import { TranslationEntry } from './en';

export const englishBatch1: TranslationEntry[] = [
  { surahId: 6, ayahNumber: 1, text: '[All] praise is [due] to Allah, who created the heavens and the earth and made the darkness and the light. Then those who disbelieve equate [others] with their Lord.' },
  { surahId: 6, ayahNumber: 2, text: 'It is He who created you from clay and then decreed a term and a specified time [known] to Him; then [still] you are in dispute.' },
  { surahId: 6, ayahNumber: 3, text: 'And He is Allah, [the only deity] in the heavens and the earth. He knows your secret and what you make public, and He knows that which you earn.' },
  { surahId: 6, ayahNumber: 4, text: 'And no sign comes to them from the signs of their Lord except that they turn away therefrom.' },
  { surahId: 6, ayahNumber: 5, text: 'For they had denied the truth when it came to them, but there is going to reach them the news of what they used to ridicule.' },
  { surahId: 6, ayahNumber: 6, text: 'Have they not seen how many generations We destroyed before them which We had established upon the earth as We have not established you? And We sent [rain from] the sky upon them in showers and made rivers flow beneath them; then We destroyed them for their sins and brought forth after them a generation of others.' },
  { surahId: 6, ayahNumber: 7, text: 'And even if We had sent down to you, [O Muhammad], a written scripture on a page and they touched it with their hands, the disbelievers would say, "This is not but obvious magic."' },
  { surahId: 6, ayahNumber: 8, text: 'And they say, "Why was there not sent down to him an angel?" But if We had sent down an angel, the matter would have been decided; then they would not be reprieved.' },
  { surahId: 6, ayahNumber: 9, text: 'And if We had made him an angel, We would have made him [appear as] a man, and We would have covered them with that in which they cover themselves.' },
  { surahId: 6, ayahNumber: 10, text: 'And already were messengers ridiculed before you, but those who mocked them were enveloped by that which they used to ridicule.' },
  { surahId: 6, ayahNumber: 11, text: 'Say, "Travel through the land; then observe how was the end of the deniers."' },
  { surahId: 6, ayahNumber: 12, text: 'Say, "To whom belongs whatever is in the heavens and earth?" Say, "To Allah." He has decreed upon Himself mercy. He will surely assemble you for the Day of Resurrection, about which there is no doubt. Those who will lose themselves [that Day] do not believe.' },
  { surahId: 6, ayahNumber: 13, text: 'And to Him belongs that which reposes by night and by day, and He is the Hearing, the Knowing.' },
  { surahId: 6, ayahNumber: 14, text: 'Say, "Is it other than Allah I should take as a protector, Creator of the heavens and the earth, while it is He who feeds and is not fed?" Say, [O Muhammad], "Indeed, I have been commanded to be the first [among you] who submit [to Allah] and [was commanded], \'Do not ever be of the polytheists.\' "' },
  { surahId: 6, ayahNumber: 15, text: 'Say, "Indeed I fear, if I should disobey my Lord, the punishment of a tremendous Day."' },
  { surahId: 6, ayahNumber: 16, text: 'He from whom it is averted that Day - [Allah] has granted him mercy. And that is the clear attainment.' },
  { surahId: 6, ayahNumber: 17, text: 'And if Allah should touch you with adversity, there is no remover of it except Him. And if He touches you with good - then He is over all things competent.' },
  { surahId: 6, ayahNumber: 18, text: 'And He is the subjugator over His servants. And He is the Wise, the Acquainted [with all].' },
  { surahId: 6, ayahNumber: 19, text: 'Say, "What thing is greatest in testimony?" Say, "Allah is witness between me and you. And this Qur\'an was revealed to me that I may warn you thereby and whomever it reaches. Do you [truly] testify that with Allah there are other deities?" Say, "I will not testify [with you]." Say, "Indeed, He is but one God, and indeed, I am free of what you associate [with Him]."' },
  { surahId: 6, ayahNumber: 20, text: 'Those to whom We have given the Scripture recognize it as they recognize their [own] sons. Those who will lose themselves [in the Hereafter] do not believe.' },
  { surahId: 6, ayahNumber: 21, text: 'And who is more unjust than one who invents about Allah a lie or denies His verses? Indeed, the wrongdoers will not succeed.' },
  { surahId: 6, ayahNumber: 22, text: 'And [mention, O Muhammad], the Day We will gather them all together; then We will say to those who associated others with Allah, "Where are your \'partners\' that you used to claim [with Him]?"' },
  { surahId: 6, ayahNumber: 23, text: 'Then there will be no [excuse upon] examination except they will say, "By Allah, our Lord, we were not those who associated."' },
  { surahId: 6, ayahNumber: 24, text: 'See how they will lie about themselves. And lost from them will be what they used to invent.' },
  { surahId: 6, ayahNumber: 25, text: 'And among them are those who listen to you, but We have placed over their hearts coverings, lest they understand it, and in their ears deafness. And if they should see every sign, they will not believe in it. Even when they come to you arguing with you, those who disbelieve say, "This is not but legends of the former peoples."' },
  { surahId: 6, ayahNumber: 26, text: 'And they prevent [others] from him and are [themselves] remote from him. And they do not destroy except themselves, but they perceive [it] not.' },
  { surahId: 6, ayahNumber: 27, text: 'If you could but see when they are made to stand before the Fire and will say, "Oh, would that we could be returned [to life on earth] and not deny the signs of our Lord and be among the believers."' },
  { surahId: 6, ayahNumber: 28, text: 'But what they concealed before has [now] appeared to them. And even if they were returned, they would return to that which they were forbidden; and indeed, they are liars.' },
  { surahId: 6, ayahNumber: 29, text: 'And they say, "There is none but our worldly life, and we will not be resurrected."' },
  { surahId: 6, ayahNumber: 30, text: 'If you could but see when they will be made to stand before their Lord. He will say, "Is this not the truth?" They will say, "Yes, by our Lord." He will [then] say, "So taste the punishment because you used to disbelieve."' },
  { surahId: 6, ayahNumber: 31, text: 'Those will have lost who deny the meeting with Allah, until when the Hour [of resurrection] comes upon them unexpectedly, they will say, "Oh, [how great is] our regret over what we neglected concerning it," while they bear their burdens on their backs. Unquestionably, evil is that which they bear.' },
  { surahId: 6, ayahNumber: 32, text: 'And the worldly life is not but amusement and diversion; but the home of the Hereafter is best for those who fear Allah, so will you not reason?' },
  { surahId: 6, ayahNumber: 33, text: 'We know that you, [O Muhammad], are saddened by what they say. And indeed, they do not call you untruthful, but it is the verses of Allah that the wrongdoers reject.' },
  { surahId: 6, ayahNumber: 34, text: 'And certainly were messengers denied before you, but they were patient over [the effects of] denial, and they were harmed until Our victory came to them. And none can alter the words of Allah. And there has certainly come to you some information about the [previous] messengers.' },
  { surahId: 6, ayahNumber: 35, text: 'And if their evasion is difficult for you, then if you are able to seek a tunnel into the earth or a stairway into the sky to bring them a sign, [then do so]. But if Allah had willed, He would have united them upon guidance. So never be of the ignorant.' },
  { surahId: 6, ayahNumber: 36, text: 'Only those who hear will respond. But the dead - Allah will resurrect them; then to Him they will be returned.' },
  { surahId: 6, ayahNumber: 37, text: 'And they say, "Why has a sign not been sent down to him from his Lord?" Say, "Indeed, Allah is Able to send down a sign, but most of them do not know."' },
  { surahId: 6, ayahNumber: 38, text: 'And there is no creature on [or within] the earth or bird that flies with its wings except [that they are] communities like you. We have not neglected in the Register a thing. Then unto their Lord they will be gathered.' },
  { surahId: 6, ayahNumber: 39, text: 'But those who deny Our verses are deaf and dumb within darknesses. Whomever Allah wills - He leaves astray; and whomever He wills - He puts him on a straight path.' },
  { surahId: 6, ayahNumber: 40, text: 'Say, "Have you considered: if there came to you the punishment of Allah or there came to you the Hour - is it other than Allah you would invoke, if you should be truthful?"' },
  { surahId: 6, ayahNumber: 41, text: 'No, it is Him [alone] you would invoke, and He would remove that for which you invoked Him if He willed, and you would forget what you associate [with Him].' },
  { surahId: 6, ayahNumber: 42, text: 'And We have already sent [messengers] to nations before you, [O Muhammad]; then We seized them with poverty and hardship that perhaps they might humble themselves [to Us].' },
  { surahId: 6, ayahNumber: 43, text: 'Then why, when Our punishment came to them, did they not humble themselves? But their hearts became hardened, and Satan made attractive to them that which they were doing.' },
  { surahId: 6, ayahNumber: 44, text: 'So when they forgot that by which they had been reminded, We opened to them the doors of every [good] thing until, when they rejoiced in that which they were given, We seized them suddenly, and they were [then] in despair.' },
  { surahId: 6, ayahNumber: 45, text: 'So the people that committed wrong were eliminated. And praise to Allah, Lord of the worlds.' },
  { surahId: 6, ayahNumber: 46, text: 'Say, "Have you considered: if Allah should take away your hearing and your sight and set a seal upon your hearts, which deity other than Allah could bring them [back] to you?" Look how we diversify the verses; then they [still] turn away.' },
  { surahId: 6, ayahNumber: 47, text: 'Say, "Have you considered: if the punishment of Allah should come to you unexpectedly or manifestly, will any be destroyed but the wrongdoing people?"' },
  { surahId: 6, ayahNumber: 48, text: 'And We send not the messengers except as bringers of good tidings and warners. So whoever believes and reforms - there will be no fear concerning them, nor will they grieve.' },
  { surahId: 6, ayahNumber: 49, text: 'But those who deny Our verses - the punishment will touch them for their defiant disobedience.' },
  { surahId: 6, ayahNumber: 50, text: 'Say, [O Muhammad], "I do not tell you that I have the depositories [containing the provision] of Allah or that I know the unseen, nor do I tell you that I am an angel. I only follow what is revealed to me." Say, "Is the blind equivalent to the seeing? Then will you not give thought?"' },
  { surahId: 6, ayahNumber: 51, text: 'And warn by the Qur\'an those who fear that they will be gathered before their Lord - for them besides Him will be no protector and no intercessor - that they might become righteous.' },
  { surahId: 6, ayahNumber: 52, text: 'And do not send away those who call upon their Lord morning and afternoon, seeking His countenance. Not upon you is anything of their account and not upon them is anything of your account. So were you to send them away, you would [then] be of the wrongdoers.' },
  { surahId: 6, ayahNumber: 53, text: 'And thus We have tried some of them through others that the disbelievers might say, "Is it these whom Allah has favored among us?" Is not Allah most knowing of those who are grateful?' },
  { surahId: 6, ayahNumber: 54, text: 'And when those come to you who believe in Our verses, say, "Peace be upon you. Your Lord has decreed upon Himself mercy: that any of you who does wrong out of ignorance and then repents after that and corrects himself - indeed, He is Forgiving and Merciful."' },
  { surahId: 6, ayahNumber: 55, text: 'And thus do We detail the verses, and [thus] the way of the criminals will become evident.' },
  { surahId: 6, ayahNumber: 56, text: 'Say, "Indeed, I have been forbidden to worship those you invoke besides Allah." Say, "I will not follow your desires, for I would then have gone astray, and I would not be of the [rightly] guided."' },
  { surahId: 6, ayahNumber: 57, text: 'Say, "Indeed, I am on clear evidence from my Lord, and you have denied it. I do not have that for which you are impatient. The decision is only for Allah. He relates the truth, and He is the best of deciders."' },
  { surahId: 6, ayahNumber: 58, text: 'Say, "If I had that for which you are impatient, the matter would have been decided between me and you, but Allah is most knowing of the wrongdoers."' },
  { surahId: 6, ayahNumber: 59, text: 'And with Him are the keys of the unseen; none knows them except Him. And He knows what is on the land and in the sea. Not a leaf falls but that He knows it. And no grain is there within the darknesses of the earth and no moist or dry [thing] but that it is [written] in a clear record.' },
  { surahId: 6, ayahNumber: 60, text: 'And it is He who takes your souls by night and knows what you have committed by day. Then He revives you therein that a specified term may be fulfilled. Then to Him will be your return; then He will inform you about what you used to do.' },
  { surahId: 6, ayahNumber: 61, text: 'And He is the subjugator over His servants, and He sends over you guardian-angels until, when death comes to one of you, Our messengers take him, and they do not fail [in their duties].' },
  { surahId: 6, ayahNumber: 62, text: 'Then they His servants are returned to Allah, their true Lord. Unquestionably, His is the judgement, and He is the swiftest of accountants.' },
  { surahId: 6, ayahNumber: 63, text: 'Say, "Who rescues you from the darknesses of the land and sea [when] you call upon Him imploring [aloud] and privately, \'If He should save us from this [crisis], we will surely be among the thankful.\' "' },
  { surahId: 6, ayahNumber: 64, text: 'Say, "It is Allah who saves you from it and from every distress; then you [still] associate others with Him."' },
  { surahId: 6, ayahNumber: 65, text: 'Say, "He is the [one] Able to send upon you affliction from above you or from beneath your feet or to confuse you [so you become] sects and make you taste the violence of one another." Look how We diversify the signs that they might understand.' },
  { surahId: 6, ayahNumber: 66, text: 'But your people have denied it while it is the truth. Say, "I am not over you a manager."' },
  { surahId: 6, ayahNumber: 67, text: 'For every happening is a finality; and you are going to know.' },
  { surahId: 6, ayahNumber: 68, text: 'And when you see those who engage in [offensive] discourse concerning Our verses, then turn away from them until they enter into another conversation. And if Satan should cause you to forget, then do not remain after the reminder with the wrongdoing people.' },
  { surahId: 6, ayahNumber: 69, text: 'And those who fear Allah are not held accountable for the disbelievers at all, but [only for] a reminder - that perhaps they will fear Him.' },
  { surahId: 6, ayahNumber: 70, text: 'And leave those who take their religion as amusement and diversion and whom the worldly life has deluded. But remind with the Qur\'an, lest a soul be given up to destruction for what it earned; it will have other than Allah no protector and no intercessor. And if it should offer every compensation, it would not be taken from it. Those are the ones who are given to destruction for what they have earned. For them will be a drink of scalding water and a painful punishment because they used to disbelieve.' },
  { surahId: 6, ayahNumber: 71, text: 'Say, "Shall we invoke instead of Allah that which neither benefits us nor harms us and be turned back on our heels after Allah has guided us? [We would then be] like one whom the devils enticed [to wander] upon the earth confused, [while] he has companions inviting him to guidance, [calling], \'Come to us.\' " Say, "Indeed, the guidance of Allah is the [only] guidance; and we have been commanded to submit to the Lord of the worlds.' },
  { surahId: 6, ayahNumber: 72, text: 'And to establish prayer and fear Him." And it is He to whom you will be gathered.' },
  { surahId: 6, ayahNumber: 73, text: 'And it is He who created the heavens and earth in truth. And the day He says, "Be," and it is, His word is the truth. And His is the dominion [on] the Day the Horn is blown. [He is] Knower of the unseen and the witnessed; and He is the Wise, the Acquainted.' },
  { surahId: 6, ayahNumber: 74, text: 'And [mention, O Muhammad], when Abraham said to his father Azar, "Do you take idols as deities? Indeed, I see you and your people to be in manifest error."' },
  { surahId: 6, ayahNumber: 75, text: 'And thus did We show Abraham the realm of the heavens and the earth that he would be among the certain [in faith]' },
  { surahId: 6, ayahNumber: 76, text: 'So when the night covered him [with darkness], he saw a star. He said, "This is my lord." But when it set, he said, "I like not those that disappear."' },
  { surahId: 6, ayahNumber: 77, text: 'And when he saw the moon rising, he said, "This is my lord." But when it set, he said, "Unless my Lord guides me, I will surely be among the people gone astray."' },
  { surahId: 6, ayahNumber: 78, text: 'And when he saw the sun rising, he said, "This is my lord; this is greater." But when it set, he said, "O my people, indeed I am free from what you associate with Allah.' },
  { surahId: 6, ayahNumber: 79, text: 'Indeed, I have turned my face toward He who created the heavens and the earth, inclining toward truth, and I am not of those who associate others with Allah."' },
  { surahId: 6, ayahNumber: 80, text: 'And his people argued with him. He said, "Do you argue with me concerning Allah while He has guided me? And I fear not what you associate with Him [and will not be harmed] unless my Lord should will something. My Lord encompasses all things in knowledge; then will you not remember?' },
  { surahId: 6, ayahNumber: 81, text: 'And how should I fear what you associate while you do not fear that you have associated with Allah that for which He has not sent down to you any authority? So which of the two parties has more right to security, if you should know?' },
  { surahId: 6, ayahNumber: 82, text: 'They who believe and do not mix their belief with injustice - those will have security, and they are [rightly] guided.' },
  { surahId: 6, ayahNumber: 83, text: 'And that was Our [conclusive] argument which We gave Abraham against his people. We raise by degrees whom We will. Indeed, your Lord is Wise and Knowing.' },
  { surahId: 6, ayahNumber: 84, text: 'And We gave to Abraham, Isaac and Jacob - all [of them] We guided. And Noah, We guided before; and among his descendants, David and Solomon and Job and Joseph and Moses and Aaron. Thus do We reward the doers of good.' },
  { surahId: 6, ayahNumber: 85, text: 'And Zechariah and John and Jesus and Elias - and all were of the righteous.' },
  { surahId: 6, ayahNumber: 86, text: 'And Ishmael and Elisha and Jonah and Lot - and all [of them] We preferred over the worlds.' },
  { surahId: 6, ayahNumber: 87, text: 'And [some] among their fathers and their descendants and their brothers - and We chose them and We guided them to a straight path.' },
  { surahId: 6, ayahNumber: 88, text: 'That is the guidance of Allah by which He guides whomever He wills of His servants. But if they had associated others with Allah, then worthless for them would be whatever they were doing.' },
  { surahId: 6, ayahNumber: 89, text: 'Those are the ones to whom We gave the Scripture and authority and prophethood. But if the disbelievers deny it, then We have entrusted it to a people who are not therein disbelievers.' },
  { surahId: 6, ayahNumber: 90, text: 'Those are the ones whom Allah has guided, so from their guidance take an example. Say, "I ask of you for this message no payment. It is not but a reminder for the worlds."' },
  { surahId: 6, ayahNumber: 91, text: 'And they did not appraise Allah with true appraisal when they said, "Allah did not reveal to a human being anything." Say, "Who revealed the Scripture that Moses brought as light and guidance to the people? You [Jews] make it into pages, disclosing [some of] it and concealing much. And you were taught that which you knew not - neither you nor your fathers." Say, "Allah [revealed it]." Then leave them in their [empty] discourse, amusing themselves.' },
  { surahId: 6, ayahNumber: 92, text: 'And this is a Book which We have sent down, blessed and confirming what was before it, that you may warn the Mother of Cities and those around it. Those who believe in the Hereafter believe in it, and they are maintaining their prayers.' },
  { surahId: 6, ayahNumber: 93, text: 'And who is more unjust than one who invents a lie about Allah or says, "It has been inspired to me," while nothing has been inspired to him, and one who says, "I will reveal [something] like what Allah revealed." And if you could but see when the wrongdoers are in the overwhelming pangs of death while the angels extend their hands, [saying], "Discharge your souls! Today you will be awarded the punishment of [extreme] humiliation for what you used to say against Allah other than the truth and [that] you were, toward His verses, being arrogant."' },
  { surahId: 6, ayahNumber: 94, text: '[It will be said to them], "And you have certainly come to Us alone as We created you the first time, and you have left whatever We bestowed upon you behind you. And We do not see with you your \'intercessors\' which you claimed that they were among you associates [of Allah]. It has [all] been severed between you, and lost from you is what you used to claim."' },
  { surahId: 6, ayahNumber: 95, text: 'Indeed, Allah is the cleaver of grain and date seeds. He brings the living out of the dead and brings the dead out of the living. That is Allah; so how are you deluded?' },
  { surahId: 6, ayahNumber: 96, text: '[He is] the cleaver of daybreak and has made the night for rest and the sun and moon for calculation. That is the determination of the Exalted in Might, the Knowing.' },
  { surahId: 6, ayahNumber: 97, text: 'And it is He who placed for you the stars that you may be guided by them through the darknesses of the land and sea. We have detailed the signs for a people who know.' },
  { surahId: 6, ayahNumber: 98, text: 'And it is He who produced you from one soul and [gave you] a place of dwelling and of storage. We have detailed the signs for a people who understand.' },
  { surahId: 6, ayahNumber: 99, text: 'And it is He who sends down rain from the sky, and We produce thereby the growth of all things. We produce from it greenery from which We produce grains arranged in layers. And from the palm trees - of its emerging fruit are clusters hanging low. And [We produce] gardens of grapevines and olives and pomegranates, similar yet varied. Look at [each of] its fruit when it yields and [at] its ripening. Indeed in that are signs for a people who believe.' },
  { surahId: 6, ayahNumber: 100, text: 'But they have attributed to Allah partners - the jinn, while He has created them - and have fabricated for Him sons and daughters. Exalted is He and high above what they describe' },
  { surahId: 6, ayahNumber: 101, text: '[He is] Originator of the heavens and the earth. How could He have a son when He does not have a companion and He created all things? And He is, of all things, Knowing.' },
  { surahId: 6, ayahNumber: 102, text: 'That is Allah, your Lord; there is no deity except Him, the Creator of all things, so worship Him. And He is Disposer of all things.' },
  { surahId: 6, ayahNumber: 103, text: 'Vision perceives Him not, but He perceives [all] vision; and He is the Subtle, the Acquainted.' },
  { surahId: 6, ayahNumber: 104, text: 'There has come to you enlightenment from your Lord. So whoever will see does so for [the benefit of] his soul, and whoever is blind [does harm] against it. And [say], "I am not a guardian over you."' },
  { surahId: 6, ayahNumber: 105, text: 'And thus do We diversify the verses so the disbelievers will say, "You have studied," and so We may make the Qur\'an clear for a people who know.' },
  { surahId: 6, ayahNumber: 106, text: 'Follow, [O Muhammad], what has been revealed to you from your Lord - there is no deity except Him - and turn away from those who associate others with Allah.' },
  { surahId: 6, ayahNumber: 107, text: 'But if Allah had willed, they would not have associated. And We have not appointed you over them as a guardian, nor are you a manager over them.' },
  { surahId: 6, ayahNumber: 108, text: 'And do not insult those they invoke other than Allah, lest they insult Allah in enmity without knowledge. Thus We have made pleasing to every community their deeds. Then to their Lord is their return, and He will inform them about what they used to do.' },
  { surahId: 6, ayahNumber: 109, text: 'And they swear by Allah their strongest oaths that if a sign came to them, they would surely believe in it. Say, "The signs are only with Allah." And what will make you perceive that even if a sign came, they would not believe.' },
  { surahId: 6, ayahNumber: 110, text: 'And We will turn away their hearts and their eyes just as they refused to believe in it the first time. And We will leave them in their transgression, wandering blindly.' },
  { surahId: 6, ayahNumber: 111, text: 'And even if We had sent down to them the angels [with the message] and the dead spoke to them [of it] and We gathered together every [created] thing in front of them, they would not believe unless Allah should will. But most of them, [of that], are ignorant.' },
  { surahId: 6, ayahNumber: 112, text: 'And thus We have made for every prophet an enemy - devils from mankind and jinn, inspiring to one another decorative speech in delusion. But if your Lord had willed, they would not have done it, so leave them and that which they invent.' },
  { surahId: 6, ayahNumber: 113, text: 'And [it is] so the hearts of those who disbelieve in the Hereafter will incline toward it and that they will be satisfied with it and that they will commit that which they are committing.' },
  { surahId: 6, ayahNumber: 114, text: '[Say], "Then is it other than Allah I should seek as judge while it is He who has revealed to you the Book explained in detail?" And those to whom We [previously] gave the Scripture know that it is sent down from your Lord in truth, so never be among the doubters.' },
  { surahId: 6, ayahNumber: 115, text: 'And the word of your Lord has been fulfilled in truth and in justice. None can alter His words, and He is the Hearing, the Knowing.' },
  { surahId: 6, ayahNumber: 116, text: 'And if you obey most of those upon the earth, they will mislead you from the way of Allah. They follow not except assumption, and they are not but falsifying.' },
  { surahId: 6, ayahNumber: 117, text: 'Indeed, your Lord is most knowing of who strays from His way, and He is most knowing of the [rightly] guided.' },
  { surahId: 6, ayahNumber: 118, text: 'So eat of that [meat] upon which the name of Allah has been mentioned, if you are believers in His verses.' },
  { surahId: 6, ayahNumber: 119, text: 'And why should you not eat of that upon which the name of Allah has been mentioned while He has explained in detail to you what He has forbidden you, excepting that to which you are compelled. And indeed do many lead [others] astray through their [own] inclinations without knowledge. Indeed, your Lord - He is most knowing of the transgressors.' },
  { surahId: 6, ayahNumber: 120, text: 'And leave what is apparent of sin and what is concealed thereof. Indeed, those who earn [blame for] sin will be recompensed for that which they used to commit.' },
  { surahId: 6, ayahNumber: 121, text: 'And do not eat of that upon which the name of Allah has not been mentioned, for indeed, it is grave disobedience. And indeed do the devils inspire their allies [among men] to dispute with you. And if you were to obey them, indeed, you would be associators [of others with Him].' },
  { surahId: 6, ayahNumber: 122, text: 'And is one who was dead and We gave him life and made for him light by which to walk among the people like one who is in darkness, never to emerge therefrom? Thus it has been made pleasing to the disbelievers that which they were doing.' },
  { surahId: 6, ayahNumber: 123, text: 'And thus We have placed within every city the greatest of its criminals to conspire therein. But they conspire not except against themselves, and they perceive [it] not.' },
  { surahId: 6, ayahNumber: 124, text: 'And when a sign comes to them, they say, "Never will we believe until we are given like that which was given to the messengers of Allah." Allah is most knowing of where He places His message. There will afflict those who committed crimes debasement before Allah and severe punishment for what they used to conspire.' },
  { surahId: 6, ayahNumber: 125, text: 'So whoever Allah wants to guide - He expands his breast to [contain] Islam; and whoever He wants to misguide - He makes his breast tight and constricted as though he were climbing into the sky. Thus does Allah place defilement upon those who do not believe.' },
  { surahId: 6, ayahNumber: 126, text: 'And this is the path of your Lord, [leading] straight. We have detailed the verses for a people who remember.' },
  { surahId: 6, ayahNumber: 127, text: 'For them will be the Home of Peace with their Lord. And He will be their protecting friend because of what they used to do.' },
  { surahId: 6, ayahNumber: 128, text: 'And [mention, O Muhammad], the Day when He will gather them together [and say], "O company of jinn, you have [misled] many of mankind." And their allies among mankind will say, "Our Lord, some of us made use of others, and we have [now] reached our term, which you appointed for us." He will say, "The Fire is your residence, wherein you will abide eternally, except for what Allah wills. Indeed, your Lord is Wise and Knowing."' },
  { surahId: 6, ayahNumber: 129, text: 'And thus will We make some of the wrongdoers allies of others for what they used to earn.' },
  { surahId: 6, ayahNumber: 130, text: '"O company of jinn and mankind, did there not come to you messengers from among you, relating to you My verses and warning you of the meeting of this Day of yours?" They will say, "We bear witness against ourselves"; and the worldly life had deluded them, and they will bear witness against themselves that they were disbelievers.' },
  { surahId: 6, ayahNumber: 131, text: 'That is because your Lord would not destroy the cities for wrongdoing while their people were unaware.' },
  { surahId: 6, ayahNumber: 132, text: 'And for all are degrees from what they have done. And your Lord is not unaware of what they do.' },
  { surahId: 6, ayahNumber: 133, text: 'And your Lord is the Free of need, the possessor of mercy. If He wills, he can do away with you and give succession after you to whomever He wills, just as He produced you from the descendants of another people.' },
  { surahId: 6, ayahNumber: 134, text: 'Indeed, what you are promised is coming, and you will not cause failure [to Allah].' },
  { surahId: 6, ayahNumber: 135, text: 'Say, "O my people, work according to your position; [for] indeed, I am working. And you are going to know who will have succession in the home. Indeed, the wrongdoers will not succeed.' },
  { surahId: 6, ayahNumber: 136, text: 'And the polytheists assign to Allah from that which He created of crops and livestock a share and say, "This is for Allah," by their claim, "and this is for our partners [associated with Him]." But what is for their "partners" does not reach Allah, while what is for Allah - this reaches their "partners." Evil is that which they rule.' },
  { surahId: 6, ayahNumber: 137, text: 'And likewise, to many of the polytheists their partners have made [to seem] pleasing the killing of their children in order to bring about their destruction and to cover them with confusion in their religion. And if Allah had willed, they would not have done so. So leave them and that which they invent.' },
  { surahId: 6, ayahNumber: 138, text: 'And they say, "These animals and crops are forbidden; no one may eat from them except whom we will," by their claim. And there are those [camels] whose backs are forbidden [by them] and those upon which the name of Allah is not mentioned - [all of this] an invention of untruth about Him. He will punish them for what they were inventing.' },
  { surahId: 6, ayahNumber: 139, text: 'And they say, "What is in the bellies of these animals is exclusively for our males and forbidden to our females. But if it is [born] dead, then all of them have shares therein." He will punish them for their description. Indeed, He is Wise and Knowing.' },
  { surahId: 6, ayahNumber: 140, text: 'Those will have lost who killed their children in foolishness without knowledge and prohibited what Allah had provided for them, inventing untruth about Allah. They have gone astray and were not [rightly] guided.' },
  { surahId: 6, ayahNumber: 141, text: 'And He it is who causes gardens to grow, [both] trellised and untrellised, and palm trees and crops of different [kinds of] food and olives and pomegranates, similar and dissimilar. Eat of [each of] its fruit when it yields and give its due [zakah] on the day of its harvest. And be not excessive. Indeed, He does not like those who commit excess.' },
  { surahId: 6, ayahNumber: 142, text: 'And of the grazing livestock are carriers [of burdens] and those [too] small. Eat of what Allah has provided for you and do not follow the footsteps of Satan. Indeed, he is to you a clear enemy.' },
  { surahId: 6, ayahNumber: 143, text: '[They are] eight mates - of the sheep, two and of the goats, two. Say, "Is it the two males He has forbidden or the two females or that which the wombs of the two females contain? Inform me with knowledge, if you should be truthful."' },
  { surahId: 6, ayahNumber: 144, text: 'And of the camels, two and of the cattle, two. Say, "Is it the two males He has forbidden or the two females or that which the wombs of the two females contain? Or were you witnesses when Allah charged you with this? Then who is more unjust than one who invents a lie about Allah to mislead the people by [something] other than knowledge? Indeed, Allah does not guide the wrongdoing people."' },
  { surahId: 6, ayahNumber: 145, text: 'Say, "I do not find within that which was revealed to me [anything] forbidden to one who would eat it unless it be a dead animal or blood spilled out or the flesh of swine - for indeed, it is impure - or it be [that slaughtered in] disobedience, dedicated to other than Allah. But whoever is forced [by necessity], neither desiring [it] nor transgressing [its limit], then indeed, your Lord is Forgiving and Merciful."' },
  { surahId: 6, ayahNumber: 146, text: 'And to those who are Jews We prohibited every animal of uncloven hoof; and of the cattle and the sheep We prohibited to them their fat, except what adheres to their backs or the entrails or what is joined with bone. [By] that We repaid them for their injustice. And indeed, We are truthful.' },
  { surahId: 6, ayahNumber: 147, text: 'So if they deny you, [O Muhammad], say, "Your Lord is the possessor of vast mercy; but His punishment cannot be repelled from the people who are criminals."' },
  { surahId: 6, ayahNumber: 148, text: 'Those who associated with Allah will say, "If Allah had willed, we would not have associated [anything] and neither would our fathers, nor would we have prohibited anything." Likewise did those before deny until they tasted Our punishment. Say, "Do you have any knowledge that you can produce for us? You follow not except assumption, and you are not but falsifying."' },
  { surahId: 6, ayahNumber: 149, text: 'Say, "With Allah is the far-reaching argument. If He had willed, He would have guided you all."' },
  { surahId: 6, ayahNumber: 150, text: 'Say, [O Muhammad], "Bring forward your witnesses who will testify that Allah has prohibited this." And if they testify, do not testify with them. And do not follow the desires of those who deny Our verses and those who do not believe in the Hereafter, while they equate [others] with their Lord.' },
  { surahId: 6, ayahNumber: 151, text: 'Say, "Come, I will recite what your Lord has prohibited to you. [He commands] that you not associate anything with Him, and to parents, good treatment, and do not kill your children out of poverty; We will provide for you and them. And do not approach immoralities - what is apparent of them and what is concealed. And do not kill the soul which Allah has forbidden [to be killed] except by [legal] right. This has He instructed you that you may use reason."' },
  { surahId: 6, ayahNumber: 152, text: 'And do not approach the orphan\'s property except in a way that is best until he reaches maturity. And give full measure and weight in justice. We do not charge any soul except [with that within] its capacity. And when you testify, be just, even if [it concerns] a near relative. And the covenant of Allah fulfill. This has He instructed you that you may remember.' },
  { surahId: 6, ayahNumber: 153, text: 'And, [moreover], this is My path, which is straight, so follow it; and do not follow [other] ways, for you will be separated from His way. This has He instructed you that you may become righteous.' },
  { surahId: 6, ayahNumber: 154, text: 'Then We gave Moses the Scripture, making complete [Our favor] upon the one who did good and as a detailed explanation of all things and as guidance and mercy that perhaps in [the matter of] the meeting with their Lord they would believe.' },
  { surahId: 6, ayahNumber: 155, text: 'And this [Qur\'an] is a Book We have revealed [which is] blessed, so follow it and fear Allah that you may receive mercy.' },
  { surahId: 6, ayahNumber: 156, text: '[We revealed it] lest you say, "The Scripture was only sent down to two groups before us, but we were of their study unaware,"' },
  { surahId: 6, ayahNumber: 157, text: 'Or lest you say, "If only the Scripture had been revealed to us, we would have been better guided than they." So there has [now] come to you a clear evidence from your Lord and a guidance and mercy. Then who is more unjust than one who denies the verses of Allah and turns away from them? We will recompense those who turn away from Our verses with the worst of punishment for their having turned away.' },
  { surahId: 6, ayahNumber: 158, text: 'Do they [then] wait for anything except that the angels should come to them or your Lord should come or that there come some of the signs of your Lord? The Day that some of the signs of your Lord will come no soul will benefit from its faith as long as it had not believed before or had earned through its faith some good. Say, "Wait. Indeed, we [also] are waiting."' },
  { surahId: 6, ayahNumber: 159, text: 'Indeed, those who have divided their religion and become sects - you, [O Muhammad], are not [associated] with them in anything. Their affair is only [left] to Allah; then He will inform them about what they used to do.' },
  { surahId: 6, ayahNumber: 160, text: 'Whoever comes [on the Day of Judgement] with a good deed will have ten times the like thereof [to his credit], and whoever comes with an evil deed will not be recompensed except the like thereof; and they will not be wronged.' },
  { surahId: 6, ayahNumber: 161, text: 'Say, "Indeed, my Lord has guided me to a straight path - a correct religion - the way of Abraham, inclining toward truth. And he was not among those who associated others with Allah."' },
  { surahId: 6, ayahNumber: 162, text: 'Say, "Indeed, my prayer, my rites of sacrifice, my living and my dying are for Allah, Lord of the worlds.' },
  { surahId: 6, ayahNumber: 163, text: 'No partner has He. And this I have been commanded, and I am the first [among you] of the Muslims."' },
  { surahId: 6, ayahNumber: 164, text: 'Say, "Is it other than Allah I should desire as a lord while He is the Lord of all things? And every soul earns not [blame] except against itself, and no bearer of burdens will bear the burden of another. Then to your Lord is your return, and He will inform you concerning that over which you used to differ."' },
  { surahId: 6, ayahNumber: 165, text: 'And it is He who has made you successors upon the earth and has raised some of you above others in degrees [of rank] that He may try you through what He has given you. Indeed, your Lord is swift in penalty; but indeed, He is Forgiving and Merciful.' },
  { surahId: 7, ayahNumber: 1, text: 'Alif, Lam, Meem, Sad.' },
  { surahId: 7, ayahNumber: 2, text: '[This is] a Book revealed to you, [O Muhammad] - so let there not be in your breast distress therefrom - that you may warn thereby and as a reminder to the believers.' },
  { surahId: 7, ayahNumber: 3, text: 'Follow, [O mankind], what has been revealed to you from your Lord and do not follow other than Him any allies. Little do you remember.' },
  { surahId: 7, ayahNumber: 4, text: 'And how many cities have We destroyed, and Our punishment came to them at night or while they were sleeping at noon.' },
  { surahId: 7, ayahNumber: 5, text: 'And their declaration when Our punishment came to them was only that they said, "Indeed, we were wrongdoers!"' },
  { surahId: 7, ayahNumber: 6, text: 'Then We will surely question those to whom [a message] was sent, and We will surely question the messengers.' },
  { surahId: 7, ayahNumber: 7, text: 'Then We will surely relate [their deeds] to them with knowledge, and We were not [at all] absent.' },
  { surahId: 7, ayahNumber: 8, text: 'And the weighing [of deeds] that Day will be the truth. So those whose scales are heavy - it is they who will be the successful.' },
  { surahId: 7, ayahNumber: 9, text: 'And those whose scales are light - they are the ones who will lose themselves for what injustice they were doing toward Our verses.' },
  { surahId: 7, ayahNumber: 10, text: 'And We have certainly established you upon the earth and made for you therein ways of livelihood. Little are you grateful.' },
  { surahId: 7, ayahNumber: 11, text: 'And We have certainly created you, [O Mankind], and given you [human] form. Then We said to the angels, "Prostrate to Adam"; so they prostrated, except for Iblees. He was not of those who prostrated.' },
  { surahId: 7, ayahNumber: 12, text: '[Allah] said, "What prevented you from prostrating when I commanded you?" [Satan] said, "I am better than him. You created me from fire and created him from clay."' },
  { surahId: 7, ayahNumber: 13, text: '[Allah] said, "Descend from Paradise, for it is not for you to be arrogant therein. So get out; indeed, you are of the debased.' },
  { surahId: 7, ayahNumber: 14, text: '[Satan] said, "Reprieve me until the Day they are resurrected."' },
  { surahId: 7, ayahNumber: 15, text: '[Allah] said, "Indeed, you are of those reprieved."' },
  { surahId: 7, ayahNumber: 16, text: '[Satan] said, "Because You have put me in error, I will surely sit in wait for them on Your straight path.' },
  { surahId: 7, ayahNumber: 17, text: 'Then I will come to them from before them and from behind them and on their right and on their left, and You will not find most of them grateful [to You]."' },
  { surahId: 7, ayahNumber: 18, text: '[Allah] said, "Get out of Paradise, reproached and expelled. Whoever follows you among them - I will surely fill Hell with you, all together."' },
  { surahId: 7, ayahNumber: 19, text: 'And "O Adam, dwell, you and your wife, in Paradise and eat from wherever you will but do not approach this tree, lest you be among the wrongdoers."' },
  { surahId: 7, ayahNumber: 20, text: 'But Satan whispered to them to make apparent to them that which was concealed from them of their private parts. He said, "Your Lord did not forbid you this tree except that you become angels or become of the immortal."' },
  { surahId: 7, ayahNumber: 21, text: 'And he swore [by Allah] to them, "Indeed, I am to you from among the sincere advisors."' },
  { surahId: 7, ayahNumber: 22, text: 'So he made them fall, through deception. And when they tasted of the tree, their private parts became apparent to them, and they began to fasten together over themselves from the leaves of Paradise. And their Lord called to them, "Did I not forbid you from that tree and tell you that Satan is to you a clear enemy?"' },
  { surahId: 7, ayahNumber: 23, text: 'They said, "Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy upon us, we will surely be among the losers."' },
  { surahId: 7, ayahNumber: 24, text: '[Allah] said, "Descend, being to one another enemies. And for you on the earth is a place of settlement and enjoyment for a time."' },
  { surahId: 7, ayahNumber: 25, text: 'He said, "Therein you will live, and therein you will die, and from it you will be brought forth."' },
  { surahId: 7, ayahNumber: 26, text: 'O children of Adam, We have bestowed upon you clothing to conceal your private parts and as adornment. But the clothing of righteousness - that is best. That is from the signs of Allah that perhaps they will remember.' },
  { surahId: 7, ayahNumber: 27, text: 'O children of Adam, let not Satan tempt you as he removed your parents from Paradise, stripping them of their clothing to show them their private parts. Indeed, he sees you, he and his tribe, from where you do not see them. Indeed, We have made the devils allies to those who do not believe.' },
  { surahId: 7, ayahNumber: 28, text: 'And when they commit an immorality, they say, "We found our fathers doing it, and Allah has ordered us to do it." Say, "Indeed, Allah does not order immorality. Do you say about Allah that which you do not know?"' },
  { surahId: 7, ayahNumber: 29, text: 'Say, [O Muhammad], "My Lord has ordered justice and that you maintain yourselves [in worship of Him] at every place [or time] of prostration, and invoke Him, sincere to Him in religion." Just as He originated you, you will return [to life] -' },
  { surahId: 7, ayahNumber: 30, text: 'A group [of you] He guided, and a group deserved [to be in] error. Indeed, they had taken the devils as allies instead of Allah while they thought that they were guided.' },
  { surahId: 7, ayahNumber: 31, text: 'O children of Adam, take your adornment at every masjid, and eat and drink, but be not excessive. Indeed, He likes not those who commit excess.' },
  { surahId: 7, ayahNumber: 32, text: 'Say, "Who has forbidden the adornment of Allah which He has produced for His servants and the good [lawful] things of provision?" Say, "They are for those who believe during the worldly life [but] exclusively for them on the Day of Resurrection." Thus do We detail the verses for a people who know.' },
  { surahId: 7, ayahNumber: 33, text: 'Say, "My Lord has only forbidden immoralities - what is apparent of them and what is concealed - and sin, and oppression without right, and that you associate with Allah that for which He has not sent down authority, and that you say about Allah that which you do not know."' },
  { surahId: 7, ayahNumber: 34, text: 'And for every nation is a [specified] term. So when their time has come, they will not remain behind an hour, nor will they precede [it].' },
  { surahId: 7, ayahNumber: 35, text: 'O children of Adam, if there come to you messengers from among you relating to you My verses, then whoever fears Allah and reforms - there will be no fear concerning them, nor will they grieve.' },
  { surahId: 7, ayahNumber: 36, text: 'But the ones who deny Our verses and are arrogant toward them - those are the companions of the Fire; they will abide therein eternally.' },
  { surahId: 7, ayahNumber: 37, text: 'And who is more unjust than one who invents about Allah a lie or denies His verses? Those will attain their portion of the decree until when Our messengers come to them to take them in death, they will say, "Where are those you used to invoke besides Allah?" They will say, "They have departed from us," and will bear witness against themselves that they were disbelievers.' },
  { surahId: 7, ayahNumber: 38, text: '[Allah] will say, "Enter among nations which had passed on before you of jinn and mankind into the Fire." Every time a nation enters, it will curse its sister until, when they have all overtaken one another therein, the last of them will say about the first of them "Our Lord, these had misled us, so give them a double punishment of the Fire. He will say, "For each is double, but you do not know."' },
  { surahId: 7, ayahNumber: 39, text: 'And the first of them will say to the last of them, "Then you had not any favor over us, so taste the punishment for what you used to earn."' },
  { surahId: 7, ayahNumber: 40, text: 'Indeed, those who deny Our verses and are arrogant toward them - the gates of Heaven will not be opened for them, nor will they enter Paradise until a camel enters into the eye of a needle. And thus do We recompense the criminals.' },
  { surahId: 7, ayahNumber: 41, text: 'They will have from Hell a bed and over them coverings [of fire]. And thus do We recompense the wrongdoers.' },
  { surahId: 7, ayahNumber: 42, text: 'But those who believed and did righteous deeds - We charge no soul except [within] its capacity. Those are the companions of Paradise; they will abide therein eternally.' },
  { surahId: 7, ayahNumber: 43, text: 'And We will have removed whatever is within their breasts of resentment, [while] flowing beneath them are rivers. And they will say, "Praise to Allah, who has guided us to this; and we would never have been guided if Allah had not guided us. Certainly the messengers of our Lord had come with the truth." And they will be called, "This is Paradise, which you have been made to inherit for what you used to do."' },
  { surahId: 7, ayahNumber: 44, text: 'And the companions of Paradise will call out to the companions of the Fire, "We have already found what our Lord promised us to be true. Have you found what your Lord promised to be true?" They will say, "Yes." Then an announcer will announce among them, "The curse of Allah shall be upon the wrongdoers."' },
  { surahId: 7, ayahNumber: 45, text: 'Who averted [people] from the way of Allah and sought to make it [seem] deviant while they were, concerning the Hereafter, disbelievers.' },
  { surahId: 7, ayahNumber: 46, text: 'And between them will be a partition, and on [its] elevations are men who recognize all by their mark. And they call out to the companions of Paradise, "Peace be upon you." They have not [yet] entered it, but they long intensely.' },
  { surahId: 7, ayahNumber: 47, text: 'And when their eyes are turned toward the companions of the Fire, they say, "Our Lord, do not place us with the wrongdoing people."' },
  { surahId: 7, ayahNumber: 48, text: 'And the companions of the Elevations will call to men [within Hell] whom they recognize by their mark, saying, "Of no avail to you was your gathering and [the fact] that you were arrogant."' },
  { surahId: 7, ayahNumber: 49, text: '[Allah will say], "Are these the ones whom you [inhabitants of Hell] swore that Allah would never offer them mercy? Enter Paradise, [O People of the Elevations]. No fear will there be concerning you, nor will you grieve."' },
  { surahId: 7, ayahNumber: 50, text: 'And the companions of the Fire will call to the companions of Paradise, "Pour upon us some water or from whatever Allah has provided you." They will say, "Indeed, Allah has forbidden them both to the disbelievers."' },
  { surahId: 7, ayahNumber: 51, text: 'Who took their religion as distraction and amusement and whom the worldly life deluded." So today We will forget them just as they forgot the meeting of this Day of theirs and for having rejected Our verses.' },
  { surahId: 7, ayahNumber: 52, text: 'And We had certainly brought them a Book which We detailed by knowledge - as guidance and mercy to a people who believe.' },
  { surahId: 7, ayahNumber: 53, text: 'Do they await except its result? The Day its result comes those who had ignored it before will say, "The messengers of our Lord had come with the truth, so are there [now] any intercessors to intercede for us or could we be sent back to do other than we used to do?" They will have lost themselves, and lost from them is what they used to invent.' },
  { surahId: 7, ayahNumber: 54, text: 'Indeed, your Lord is Allah, who created the heavens and earth in six days and then established Himself above the Throne. He covers the night with the day, [another night] chasing it rapidly; and [He created] the sun, the moon, and the stars, subjected by His command. Unquestionably, His is the creation and the command; blessed is Allah, Lord of the worlds.' },
  { surahId: 7, ayahNumber: 55, text: 'Call upon your Lord in humility and privately; indeed, He does not like transgressors.' },
  { surahId: 7, ayahNumber: 56, text: 'And cause not corruption upon the earth after its reformation. And invoke Him in fear and aspiration. Indeed, the mercy of Allah is near to the doers of good.' },
  { surahId: 7, ayahNumber: 57, text: 'And it is He who sends the winds as good tidings before His mercy until, when they have carried heavy rainclouds, We drive them to a dead land and We send down rain therein and bring forth thereby [some] of all the fruits. Thus will We bring forth the dead; perhaps you may be reminded.' },
  { surahId: 7, ayahNumber: 58, text: 'And the good land - its vegetation emerges by permission of its Lord; but that which is bad - nothing emerges except sparsely, with difficulty. Thus do We diversify the signs for a people who are grateful.' },
  { surahId: 7, ayahNumber: 59, text: 'We had certainly sent Noah to his people, and he said, "O my people, worship Allah; you have no deity other than Him. Indeed, I fear for you the punishment of a tremendous Day.' },
  { surahId: 7, ayahNumber: 60, text: 'Said the eminent among his people, "Indeed, we see you in clear error."' },
  { surahId: 7, ayahNumber: 61, text: '[Noah] said, "O my people, there is not error in me, but I am a messenger from the Lord of the worlds."' },
  { surahId: 7, ayahNumber: 62, text: 'I convey to you the messages of my Lord and advise you; and I know from Allah what you do not know.' },
  { surahId: 7, ayahNumber: 63, text: 'Then do you wonder that there has come to you a reminder from your Lord through a man from among you, that he may warn you and that you may fear Allah so you might receive mercy."' },
  { surahId: 7, ayahNumber: 64, text: 'But they denied him, so We saved him and those who were with him in the ship. And We drowned those who denied Our signs. Indeed, they were a blind people.' },
  { surahId: 7, ayahNumber: 65, text: 'And to the \'Aad [We sent] their brother Hud. He said, "O my people, worship Allah; you have no deity other than Him. Then will you not fear Him?"' },
  { surahId: 7, ayahNumber: 66, text: 'Said the eminent ones who disbelieved among his people, "Indeed, we see you in foolishness, and indeed, we think you are of the liars."' },
  { surahId: 7, ayahNumber: 67, text: '[Hud] said, "O my people, there is not foolishness in me, but I am a messenger from the Lord of the worlds."' },
  { surahId: 7, ayahNumber: 68, text: 'I convey to you the messages of my Lord, and I am to you a trustworthy adviser.' },
  { surahId: 7, ayahNumber: 69, text: 'Then do you wonder that there has come to you a reminder from your Lord through a man from among you, that he may warn you? And remember when He made you successors after the people of Noah and increased you in stature extensively. So remember the favors of Allah that you might succeed.' },
  { surahId: 7, ayahNumber: 70, text: 'They said, "Have you come to us that we should worship Allah alone and leave what our fathers have worshipped? Then bring us what you promise us, if you should be of the truthful."' },
  { surahId: 7, ayahNumber: 71, text: '[Hud] said, "Already have defilement and anger fallen upon you from your Lord. Do you dispute with me concerning [mere] names you have named them, you and your fathers, for which Allah has not sent down any authority? Then wait; indeed, I am with you among those who wait."' },
  { surahId: 7, ayahNumber: 72, text: 'So We saved him and those with him by mercy from Us. And We eliminated those who denied Our signs, and they were not [at all] believers.' },
  { surahId: 7, ayahNumber: 73, text: 'And to the Thamud [We sent] their brother Salih. He said, "O my people, worship Allah; you have no deity other than Him. There has come to you clear evidence from your Lord. This is the she-camel of Allah [sent] to you as a sign. So leave her to eat within Allah \'s land and do not touch her with harm, lest there seize you a painful punishment.' },
  { surahId: 7, ayahNumber: 74, text: 'And remember when He made you successors after the \'Aad and settled you in the land, [and] you take for yourselves palaces from its plains and carve from the mountains, homes. Then remember the favors of Allah and do not commit abuse on the earth, spreading corruption."' },
  { surahId: 7, ayahNumber: 75, text: 'Said the eminent ones who were arrogant among his people to those who were oppressed - to those who believed among them, "Do you [actually] know that Salih is sent from his Lord?" They said, "Indeed we, in that with which he was sent, are believers."' },
  { surahId: 7, ayahNumber: 76, text: 'Said those who were arrogant, "Indeed we, in that which you have believed, are disbelievers."' },
  { surahId: 7, ayahNumber: 77, text: 'So they hamstrung the she-camel and were insolent toward the command of their Lord and said, "O Salih, bring us what you promise us, if you should be of the messengers."' },
  { surahId: 7, ayahNumber: 78, text: 'So the earthquake seized them, and they became within their home [corpses] fallen prone.' },
  { surahId: 7, ayahNumber: 79, text: 'And he turned away from them and said, "O my people, I had certainly conveyed to you the message of my Lord and advised you, but you do not like advisors."' },
  { surahId: 7, ayahNumber: 80, text: 'And [We had sent] Lot when he said to his people, "Do you commit such immorality as no one has preceded you with from among the worlds?' },
  { surahId: 7, ayahNumber: 81, text: 'Indeed, you approach men with desire, instead of women. Rather, you are a transgressing people."' },
  { surahId: 7, ayahNumber: 82, text: 'But the answer of his people was only that they said, "Evict them from your city! Indeed, they are men who keep themselves pure."' },
  { surahId: 7, ayahNumber: 83, text: 'So We saved him and his family, except for his wife; she was of those who remained [with the evildoers].' },
  { surahId: 7, ayahNumber: 84, text: 'And We rained upon them a rain [of stones]. Then see how was the end of the criminals.' },
  { surahId: 7, ayahNumber: 85, text: 'And to [the people of] Madyan [We sent] their brother Shu\'ayb. He said, "O my people, worship Allah; you have no deity other than Him. There has come to you clear evidence from your Lord. So fulfill the measure and weight and do not deprive people of their due and cause not corruption upon the earth after its reformation. That is better for you, if you should be believers.' },
  { surahId: 7, ayahNumber: 86, text: 'And do not sit on every path, threatening and averting from the way of Allah those who believe in Him, seeking to make it [seem] deviant. And remember when you were few and He increased you. And see how was the end of the corrupters.' },
  { surahId: 7, ayahNumber: 87, text: 'And if there should be a group among you who has believed in that with which I have been sent and a group that has not believed, then be patient until Allah judges between us. And He is the best of judges."' },
  { surahId: 7, ayahNumber: 88, text: 'Said the eminent ones who were arrogant among his people, "We will surely evict you, O Shu\'ayb, and those who have believed with you from our city, or you must return to our religion." He said, "Even if we were unwilling?"' },
  { surahId: 7, ayahNumber: 89, text: 'We would have invented against Allah a lie if we returned to your religion after Allah had saved us from it. And it is not for us to return to it except that Allah, our Lord, should will. Our Lord has encompassed all things in knowledge. Upon Allah we have relied. Our Lord, decide between us and our people in truth, and You are the best of those who give decision."' },
  { surahId: 7, ayahNumber: 90, text: 'Said the eminent ones who disbelieved among his people, "If you should follow Shu\'ayb, indeed, you would then be losers."' },
  { surahId: 7, ayahNumber: 91, text: 'So the earthquake seized them, and they became within their home [corpses] fallen prone.' },
  { surahId: 7, ayahNumber: 92, text: 'Those who denied Shu\'ayb - it was as though they had never resided there. Those who denied Shu\'ayb - it was they who were the losers.' },
  { surahId: 7, ayahNumber: 93, text: 'And he turned away from them and said, "O my people, I had certainly conveyed to you the messages of my Lord and advised you, so how could I grieve for a disbelieving people?"' },
  { surahId: 7, ayahNumber: 94, text: 'And We sent to no city a prophet [who was denied] except that We seized its people with poverty and hardship that they might humble themselves [to Allah].' },
  { surahId: 7, ayahNumber: 95, text: 'Then We exchanged in place of the bad [condition], good, until they increased [and prospered] and said, "Our fathers [also] were touched with hardship and ease." So We seized them suddenly while they did not perceive.' },
  { surahId: 7, ayahNumber: 96, text: 'And if only the people of the cities had believed and feared Allah, We would have opened upon them blessings from the heaven and the earth; but they denied [the messengers], so We seized them for what they were earning."' },
  { surahId: 7, ayahNumber: 97, text: 'Then, did the people of the cities feel secure from Our punishment coming to them at night while they were asleep?' },
  { surahId: 7, ayahNumber: 98, text: 'Or did the people of the cities feel secure from Our punishment coming to them in the morning while they were at play?' },
  { surahId: 7, ayahNumber: 99, text: 'Then did they feel secure from the plan of Allah? But no one feels secure from the plan of Allah except the losing people.' },
  { surahId: 7, ayahNumber: 100, text: 'Has it not become clear to those who inherited the earth after its [previous] people that if We willed, We could afflict them for their sins? But We seal over their hearts so they do not hear.' },
  { surahId: 7, ayahNumber: 101, text: 'Those cities - We relate to you, [O Muhammad], some of their news. And certainly did their messengers come to them with clear proofs, but they were not to believe in that which they had denied before. Thus does Allah seal over the hearts of the disbelievers.' },
  { surahId: 7, ayahNumber: 102, text: 'And We did not find for most of them any covenant; but indeed, We found most of them defiantly disobedient.' },
  { surahId: 7, ayahNumber: 103, text: 'Then We sent after them Moses with Our signs to Pharaoh and his establishment, but they were unjust toward them. So see how was the end of the corrupters.' },
  { surahId: 7, ayahNumber: 104, text: 'And Moses said, "O Pharaoh, I am a messenger from the Lord of the worlds' },
  { surahId: 7, ayahNumber: 105, text: '[Who is] obligated not to say about Allah except the truth. I have come to you with clear evidence from your Lord, so send with me the Children of Israel."' },
  { surahId: 7, ayahNumber: 106, text: '[Pharaoh] said, "If you have come with a sign, then bring it forth, if you should be of the truthful."' },
  { surahId: 7, ayahNumber: 107, text: 'So Moses threw his staff, and suddenly it was a serpent, manifest.' },
  { surahId: 7, ayahNumber: 108, text: 'And he drew out his hand; thereupon it was white [with radiance] for the observers.' },
  { surahId: 7, ayahNumber: 109, text: 'Said the eminent among the people of Pharaoh, "Indeed, this is a learned magician' },
  { surahId: 7, ayahNumber: 110, text: 'Who wants to expel you from your land [through magic], so what do you instruct?"' },
  { surahId: 7, ayahNumber: 111, text: 'They said, "Postpone [the matter of] him and his brother and send among the cities gatherers' },
  { surahId: 7, ayahNumber: 112, text: 'Who will bring you every learned magician."' },
  { surahId: 7, ayahNumber: 113, text: 'And the magicians came to Pharaoh. They said, "Indeed for us is a reward if we are the predominant."' },
  { surahId: 7, ayahNumber: 114, text: 'He said, "Yes, and, [moreover], you will be among those made near [to me]."' },
  { surahId: 7, ayahNumber: 115, text: 'They said, "O Moses, either you throw [your staff], or we will be the ones to throw [first]."' },
  { surahId: 7, ayahNumber: 116, text: 'He said, "Throw," and when they threw, they bewitched the eyes of the people and struck terror into them, and they presented a great [feat of] magic.' },
  { surahId: 7, ayahNumber: 117, text: 'And We inspired to Moses, "Throw your staff," and at once it devoured what they were falsifying.' },
  { surahId: 7, ayahNumber: 118, text: 'So the truth was established, and abolished was what they were doing.' },
  { surahId: 7, ayahNumber: 119, text: 'And Pharaoh and his people were overcome right there and became debased.' },
  { surahId: 7, ayahNumber: 120, text: 'And the magicians fell down in prostration [to Allah].' },
  { surahId: 7, ayahNumber: 121, text: 'They said, "We have believed in the Lord of the worlds,' },
  { surahId: 7, ayahNumber: 122, text: 'The Lord of Moses and Aaron."' },
  { surahId: 7, ayahNumber: 123, text: 'Said Pharaoh, "You believed in him before I gave you permission. Indeed, this is a conspiracy which you conspired in the city to expel therefrom its people. But you are going to know.' },
  { surahId: 7, ayahNumber: 124, text: 'I will surely cut off your hands and your feet on opposite sides; then I will surely crucify you all."' },
  { surahId: 7, ayahNumber: 125, text: 'They said, "Indeed, to our Lord we will return.' },
  { surahId: 7, ayahNumber: 126, text: 'And you do not resent us except because we believed in the signs of our Lord when they came to us. Our Lord, pour upon us patience and let us die as Muslims [in submission to You]."' },
  { surahId: 7, ayahNumber: 127, text: 'And the eminent among the people of Pharaoh said," Will you leave Moses and his people to cause corruption in the land and abandon you and your gods?" [Pharaoh] said, "We will kill their sons and keep their women alive; and indeed, we are subjugators over them."' },
  { surahId: 7, ayahNumber: 128, text: 'Said Moses to his people, "Seek help through Allah and be patient. Indeed, the earth belongs to Allah. He causes to inherit it whom He wills of His servants. And the [best] outcome is for the righteous."' },
  { surahId: 7, ayahNumber: 129, text: 'They said, "We have been harmed before you came to us and after you have come to us." He said, "Perhaps your Lord will destroy your enemy and grant you succession in the land and see how you will do."' },
  { surahId: 7, ayahNumber: 130, text: 'And We certainly seized the people of Pharaoh with years of famine and a deficiency in fruits that perhaps they would be reminded.' },
  { surahId: 7, ayahNumber: 131, text: 'But when good came to them, they said, "This is ours [by right]." And if a bad [condition] struck them, they saw an evil omen in Moses and those with him. Unquestionably, their fortune is with Allah, but most of them do not know.' },
  { surahId: 7, ayahNumber: 132, text: 'And they said, "No matter what sign you bring us with which to bewitch us, we will not be believers in you."' },
  { surahId: 7, ayahNumber: 133, text: 'So We sent upon them the flood and locusts and lice and frogs and blood as distinct signs, but they were arrogant and were a criminal people.' },
  { surahId: 7, ayahNumber: 134, text: 'And when the punishment descended upon them, they said, "O Moses, invoke for us your Lord by what He has promised you. If you [can] remove the punishment from us, we will surely believe you, and we will send with you the Children of Israel."' },
  { surahId: 7, ayahNumber: 135, text: 'But when We removed the punishment from them until a term which they were to reach, then at once they broke their word.' },
  { surahId: 7, ayahNumber: 136, text: 'So We took retribution from them, and We drowned them in the sea because they denied Our signs and were heedless of them.' },
  { surahId: 7, ayahNumber: 137, text: 'And We caused the people who had been oppressed to inherit the eastern regions of the land and the western ones, which We had blessed. And the good word of your Lord was fulfilled for the Children of Israel because of what they had patiently endured. And We destroyed [all] that Pharaoh and his people were producing and what they had been building.' },
  { surahId: 7, ayahNumber: 138, text: 'And We took the Children of Israel across the sea; then they came upon a people intent in devotion to [some] idols of theirs. They said, "O Moses, make for us a god just as they have gods." He said, "Indeed, you are a people behaving ignorantly.' },
  { surahId: 7, ayahNumber: 139, text: 'Indeed, those [worshippers] - destroyed is that in which they are [engaged], and worthless is whatever they were doing."' },
  { surahId: 7, ayahNumber: 140, text: 'He said, "Is it other than Allah I should desire for you as a god while He has preferred you over the worlds?"' },
  { surahId: 7, ayahNumber: 141, text: 'And [recall, O Children of Israel], when We saved you from the people of Pharaoh, [who were] afflicting you with the worst torment - killing your sons and keeping your women alive. And in that was a great trial from your Lord.' },
  { surahId: 7, ayahNumber: 142, text: 'And We made an appointment with Moses for thirty nights and perfected them by [the addition of] ten; so the term of his Lord was completed as forty nights. And Moses said to his brother Aaron, "Take my place among my people, do right [by them], and do not follow the way of the corrupters."' },
  { surahId: 7, ayahNumber: 143, text: 'And when Moses arrived at Our appointed time and his Lord spoke to him, he said, "My Lord, show me [Yourself] that I may look at You." [Allah] said, "You will not see Me, but look at the mountain; if it should remain in place, then you will see Me." But when his Lord appeared to the mountain, He rendered it level, and Moses fell unconscious. And when he awoke, he said, "Exalted are You! I have repented to You, and I am the first of the believers."' },
  { surahId: 7, ayahNumber: 144, text: '[Allah] said, "O Moses, I have chosen you over the people with My messages and My words [to you]. So take what I have given you and be among the grateful."' },
  { surahId: 7, ayahNumber: 145, text: 'And We wrote for him on the tablets [something] of all things - instruction and explanation for all things, [saying], "Take them with determination and order your people to take the best of it. I will show you the home of the defiantly disobedient."' },
  { surahId: 7, ayahNumber: 146, text: 'I will turn away from My signs those who are arrogant upon the earth without right; and if they should see every sign, they will not believe in it. And if they see the way of consciousness, they will not adopt it as a way; but if they see the way of error, they will adopt it as a way. That is because they have denied Our signs and they were heedless of them.' },
  { surahId: 7, ayahNumber: 147, text: 'Those who denied Our signs and the meeting of the Hereafter - their deeds have become worthless. Are they recompensed except for what they used to do?' },
  { surahId: 7, ayahNumber: 148, text: 'And the people of Moses made, after [his departure], from their ornaments a calf - an image having a lowing sound. Did they not see that it could neither speak to them nor guide them to a way? They took it [for worship], and they were wrongdoers.' },
  { surahId: 7, ayahNumber: 149, text: 'And when regret overcame them and they saw that they had gone astray, they said, "If our Lord does not have mercy upon us and forgive us, we will surely be among the losers."' },
  { surahId: 7, ayahNumber: 150, text: 'And when Moses returned to his people, angry and grieved, he said, "How wretched is that by which you have replaced me after [my departure]. Were you impatient over the matter of your Lord?" And he threw down the tablets and seized his brother by [the hair of] his head, pulling him toward him. [Aaron] said, "O son of my mother, indeed the people oppressed me and were about to kill me, so let not the enemies rejoice over me and do not place me among the wrongdoing people."' },
  { surahId: 7, ayahNumber: 151, text: '[Moses] said, "My Lord, forgive me and my brother and admit us into Your mercy, for You are the most merciful of the merciful."' },
  { surahId: 7, ayahNumber: 152, text: 'Indeed, those who took the calf [for worship] will obtain anger from their Lord and humiliation in the life of this world, and thus do We recompense the inventors [of falsehood].' },
  { surahId: 7, ayahNumber: 153, text: 'But those who committed misdeeds and then repented after them and believed - indeed your Lord, thereafter, is Forgiving and Merciful.' },
  { surahId: 7, ayahNumber: 154, text: 'And when the anger subsided in Moses, he took up the tablets; and in their inscription was guidance and mercy for those who are fearful of their Lord.' },
  { surahId: 7, ayahNumber: 155, text: 'And Moses chose from his people seventy men for Our appointment. And when the earthquake seized them, he said, "My Lord, if You had willed, You could have destroyed them before and me [as well]. Would You destroy us for what the foolish among us have done? This is not but Your trial by which You send astray whom You will and guide whom You will. You are our Protector, so forgive us and have mercy upon us; and You are the best of forgivers.' },
  { surahId: 7, ayahNumber: 156, text: 'And decree for us in this world [that which is] good and [also] in the Hereafter; indeed, we have turned back to You." [Allah] said, "My punishment - I afflict with it whom I will, but My mercy encompasses all things." So I will decree it [especially] for those who fear Me and give zakah and those who believe in Our verses -' },
  { surahId: 7, ayahNumber: 157, text: 'Those who follow the Messenger, the unlettered prophet, whom they find written in what they have of the Torah and the Gospel, who enjoins upon them what is right and forbids them what is wrong and makes lawful for them the good things and prohibits for them the evil and relieves them of their burden and the shackles which were upon them. So they who have believed in him, honored him, supported him and followed the light which was sent down with him - it is those who will be the successful.' },
  { surahId: 7, ayahNumber: 158, text: 'Say, [O Muhammad], "O mankind, indeed I am the Messenger of Allah to you all, [from Him] to whom belongs the dominion of the heavens and the earth. There is no deity except Him; He gives life and causes death." So believe in Allah and His Messenger, the unlettered prophet, who believes in Allah and His words, and follow him that you may be guided.' },
  { surahId: 7, ayahNumber: 159, text: 'And among the people of Moses is a community which guides by truth and by it establishes justice.' },
  { surahId: 7, ayahNumber: 160, text: 'And We divided them into twelve descendant tribes [as distinct] nations. And We inspired to Moses when his people implored him for water, "Strike with your staff the stone," and there gushed forth from it twelve springs. Every people knew its watering place. And We shaded them with clouds and sent down upon them manna and quails, [saying], "Eat from the good things with which We have provided you." And they wronged Us not, but they were [only] wronging themselves.' },
  { surahId: 7, ayahNumber: 161, text: 'And [mention, O Muhammad], when it was said to them, "Dwell in this city and eat from it wherever you will and say, \'Relieve us of our burdens,\' and enter the gate bowing humbly; We will [then] forgive you your sins. We will increase the doers of good [in goodness and reward]."' },
  { surahId: 7, ayahNumber: 162, text: 'But those who wronged among them changed [the words] to a statement other than that which had been said to them. So We sent upon them a punishment from the sky for the wrong that they were doing.' },
  { surahId: 7, ayahNumber: 163, text: 'And ask them about the town that was by the sea - when they transgressed in [the matter of] the sabbath - when their fish came to them openly on their sabbath day, and the day they had no sabbath they did not come to them. Thus did We give them trial because they were defiantly disobedient.' },
  { surahId: 7, ayahNumber: 164, text: 'And when a community among them said, "Why do you advise [or warn] a people whom Allah is [about] to destroy or to punish with a severe punishment?" they [the advisors] said, "To be absolved before your Lord and perhaps they may fear Him."' },
  { surahId: 7, ayahNumber: 165, text: 'And when they forgot that by which they had been reminded, We saved those who had forbidden evil and seized those who wronged, with a wretched punishment, because they were defiantly disobeying.' },
  { surahId: 7, ayahNumber: 166, text: 'So when they were insolent about that which they had been forbidden, We said to them, "Be apes, despised."' },
  { surahId: 7, ayahNumber: 167, text: 'And [mention] when your Lord declared that He would surely [continue to] send upon them until the Day of Resurrection those who would afflict them with the worst torment. Indeed, your Lord is swift in penalty; but indeed, He is Forgiving and Merciful.' },
  { surahId: 7, ayahNumber: 168, text: 'And We divided them throughout the earth into nations. Of them some were righteous, and of them some were otherwise. And We tested them with good [times] and bad that perhaps they would return [to obedience].' },
  { surahId: 7, ayahNumber: 169, text: 'And there followed them successors who inherited the Scripture [while] taking the commodities of this lower life and saying, "It will be forgiven for us." And if an offer like it comes to them, they will [again] take it. Was not the covenant of the Scripture taken from them that they would not say about Allah except the truth, and they studied what was in it? And the home of the Hereafter is better for those who fear Allah, so will you not use reason?' },
  { surahId: 7, ayahNumber: 170, text: 'But those who hold fast to the Book and establish prayer - indeed, We will not allow to be lost the reward of the reformers.' },
  { surahId: 7, ayahNumber: 171, text: 'And [mention] when We raised the mountain above them as if it was a dark cloud and they were certain that it would fall upon them, [and Allah said], "Take what We have given you with determination and remember what is in it that you might fear Allah."' },
  { surahId: 7, ayahNumber: 172, text: 'And [mention] when your Lord took from the children of Adam - from their loins - their descendants and made them testify of themselves, [saying to them], "Am I not your Lord?" They said, "Yes, we have testified." [This] - lest you should say on the day of Resurrection, "Indeed, we were of this unaware."' },
  { surahId: 7, ayahNumber: 173, text: 'Or [lest] you say, "It was only that our fathers associated [others in worship] with Allah before, and we were but descendants after them. Then would You destroy us for what the falsifiers have done?"' },
  { surahId: 7, ayahNumber: 174, text: 'And thus do We [explain in] detail the verses, and perhaps they will return.' },
  { surahId: 7, ayahNumber: 175, text: 'And recite to them, [O Muhammad], the news of him to whom we gave [knowledge of] Our signs, but he detached himself from them; so Satan pursued him, and he became of the deviators.' },
  { surahId: 7, ayahNumber: 176, text: 'And if We had willed, we could have elevated him thereby, but he adhered [instead] to the earth and followed his own desire. So his example is like that of the dog: if you chase him, he pants, or if you leave him, he [still] pants. That is the example of the people who denied Our signs. So relate the stories that perhaps they will give thought.' },
  { surahId: 7, ayahNumber: 177, text: 'How evil an example [is that of] the people who denied Our signs and used to wrong themselves.' },
  { surahId: 7, ayahNumber: 178, text: 'Whoever Allah guides - he is the [rightly] guided; and whoever He sends astray - it is those who are the losers.' },
  { surahId: 7, ayahNumber: 179, text: 'And We have certainly created for Hell many of the jinn and mankind. They have hearts with which they do not understand, they have eyes with which they do not see, and they have ears with which they do not hear. Those are like livestock; rather, they are more astray. It is they who are the heedless.' },
  { surahId: 7, ayahNumber: 180, text: 'And to Allah belong the best names, so invoke Him by them. And leave [the company of] those who practice deviation concerning His names. They will be recompensed for what they have been doing.' },
  { surahId: 7, ayahNumber: 181, text: 'And among those We created is a community which guides by truth and thereby establishes justice.' },
  { surahId: 7, ayahNumber: 182, text: 'But those who deny Our signs - We will progressively lead them [to destruction] from where they do not know.' },
  { surahId: 7, ayahNumber: 183, text: 'And I will give them time. Indeed, my plan is firm.' },
  { surahId: 7, ayahNumber: 184, text: 'Then do they not give thought? There is in their companion [Muhammad] no madness. He is not but a clear warner.' },
  { surahId: 7, ayahNumber: 185, text: 'Do they not look into the realm of the heavens and the earth and everything that Allah has created and [think] that perhaps their appointed time has come near? So in what statement hereafter will they believe?' },
  { surahId: 7, ayahNumber: 186, text: 'Whoever Allah sends astray - there is no guide for him. And He leaves them in their transgression, wandering blindly.' },
  { surahId: 7, ayahNumber: 187, text: 'They ask you, [O Muhammad], about the Hour: when is its arrival? Say, "Its knowledge is only with my Lord. None will reveal its time except Him. It lays heavily upon the heavens and the earth. It will not come upon you except unexpectedly." They ask you as if you are familiar with it. Say, "Its knowledge is only with Allah, but most of the people do not know."' },
  { surahId: 7, ayahNumber: 188, text: 'Say, "I hold not for myself [the power of] benefit or harm, except what Allah has willed. And if I knew the unseen, I could have acquired much wealth, and no harm would have touched me. I am not except a warner and a bringer of good tidings to a people who believe."' },
  { surahId: 7, ayahNumber: 189, text: 'It is He who created you from one soul and created from it its mate that he might dwell in security with her. And when he covers her, she carries a light burden and continues therein. And when it becomes heavy, they both invoke Allah, their Lord, "If You should give us a good [child], we will surely be among the grateful."' },
  { surahId: 7, ayahNumber: 190, text: 'But when He gives them a good [child], they ascribe partners to Him concerning that which He has given them. Exalted is Allah above what they associate with Him.' },
  { surahId: 7, ayahNumber: 191, text: 'Do they associate with Him those who create nothing and they are [themselves] created?' },
  { surahId: 7, ayahNumber: 192, text: 'And the false deities are unable to [give] them help, nor can they help themselves.' },
  { surahId: 7, ayahNumber: 193, text: 'And if you [believers] invite them to guidance, they will not follow you. It is all the same for you whether you invite them or you are silent.' },
  { surahId: 7, ayahNumber: 194, text: 'Indeed, those you [polytheists] call upon besides Allah are servants like you. So call upon them and let them respond to you, if you should be truthful.' },
  { surahId: 7, ayahNumber: 195, text: 'Do they have feet by which they walk? Or do they have hands by which they strike? Or do they have eyes by which they see? Or do they have ears by which they hear? Say, [O Muhammad], "Call your \'partners\' and then conspire against me and give me no respite.' },
  { surahId: 7, ayahNumber: 196, text: 'Indeed, my protector is Allah, who has sent down the Book; and He is an ally to the righteous.' },
  { surahId: 7, ayahNumber: 197, text: 'And those you call upon besides Him are unable to help you, nor can they help themselves."' },
  { surahId: 7, ayahNumber: 198, text: 'And if you invite them to guidance, they do not hear; and you see them looking at you while they do not see.' },
  { surahId: 7, ayahNumber: 199, text: 'Take what is given freely, enjoin what is good, and turn away from the ignorant.' },
  { surahId: 7, ayahNumber: 200, text: 'And if an evil suggestion comes to you from Satan, then seek refuge in Allah. Indeed, He is Hearing and Knowing.' },
  { surahId: 7, ayahNumber: 201, text: 'Indeed, those who fear Allah - when an impulse touches them from Satan, they remember [Him] and at once they have insight.' },
  { surahId: 7, ayahNumber: 202, text: 'But their brothers - the devils increase them in error; then they do not stop short.' },
  { surahId: 7, ayahNumber: 203, text: 'And when you, [O Muhammad], do not bring them a sign, they say, "Why have you not contrived it?" Say, "I only follow what is revealed to me from my Lord. This [Qur\'an] is enlightenment from your Lord and guidance and mercy for a people who believe."' },
  { surahId: 7, ayahNumber: 204, text: 'So when the Qur\'an is recited, then listen to it and pay attention that you may receive mercy.' },
  { surahId: 7, ayahNumber: 205, text: 'And remember your Lord within yourself in humility and in fear without being apparent in speech - in the mornings and the evenings. And do not be among the heedless.' },
  { surahId: 7, ayahNumber: 206, text: 'Indeed, those who are near your Lord are not prevented by arrogance from His worship, and they exalt Him, and to Him they prostrate.' },
  { surahId: 8, ayahNumber: 1, text: 'They ask you, [O Muhammad], about the bounties [of war]. Say, "The [decision concerning] bounties is for Allah and the Messenger." So fear Allah and amend that which is between you and obey Allah and His Messenger, if you should be believers.' },
  { surahId: 8, ayahNumber: 2, text: 'The believers are only those who, when Allah is mentioned, their hearts become fearful, and when His verses are recited to them, it increases them in faith; and upon their Lord they rely -' },
  { surahId: 8, ayahNumber: 3, text: 'The ones who establish prayer, and from what We have provided them, they spend.' },
  { surahId: 8, ayahNumber: 4, text: 'Those are the believers, truly. For them are degrees [of high position] with their Lord and forgiveness and noble provision.' },
  { surahId: 8, ayahNumber: 5, text: '[It is] just as when your Lord brought you out of your home [for the battle of Badr] in truth, while indeed, a party among the believers were unwilling,' },
  { surahId: 8, ayahNumber: 6, text: 'Arguing with you concerning the truth after it had become clear, as if they were being driven toward death while they were looking on.' },
  { surahId: 8, ayahNumber: 7, text: '[Remember, O believers], when Allah promised you one of the two groups - that it would be yours - and you wished that the unarmed one would be yours. But Allah intended to establish the truth by His words and to eliminate the disbelievers' },
  { surahId: 8, ayahNumber: 8, text: 'That He should establish the truth and abolish falsehood, even if the criminals disliked it.' },
  { surahId: 8, ayahNumber: 9, text: '[Remember] when you asked help of your Lord, and He answered you, "Indeed, I will reinforce you with a thousand from the angels, following one another."' },
  { surahId: 8, ayahNumber: 10, text: 'And Allah made it not but good tidings and so that your hearts would be assured thereby. And victory is not but from Allah. Indeed, Allah is Exalted in Might and Wise.' },
  { surahId: 8, ayahNumber: 11, text: '[Remember] when He overwhelmed you with drowsiness [giving] security from Him and sent down upon you from the sky, rain by which to purify you and remove from you the evil [suggestions] of Satan and to make steadfast your hearts and plant firmly thereby your feet.' },
  { surahId: 8, ayahNumber: 12, text: '[Remember] when your Lord inspired to the angels, "I am with you, so strengthen those who have believed. I will cast terror into the hearts of those who disbelieved, so strike [them] upon the necks and strike from them every fingertip."' },
  { surahId: 8, ayahNumber: 13, text: 'That is because they opposed Allah and His Messenger. And whoever opposes Allah and His Messenger - indeed, Allah is severe in penalty.' },
  { surahId: 8, ayahNumber: 14, text: '"That [is yours], so taste it." And indeed for the disbelievers is the punishment of the Fire.' },
  { surahId: 8, ayahNumber: 15, text: 'O you who have believed, when you meet those who disbelieve advancing [for battle], do not turn to them your backs [in flight].' },
  { surahId: 8, ayahNumber: 16, text: 'And whoever turns his back to them on such a day, unless swerving [as a strategy] for war or joining [another] company, has certainly returned with anger [upon him] from Allah, and his refuge is Hell - and wretched is the destination.' },
  { surahId: 8, ayahNumber: 17, text: 'And you did not kill them, but it was Allah who killed them. And you threw not, [O Muhammad], when you threw, but it was Allah who threw that He might test the believers with a good test. Indeed, Allah is Hearing and Knowing.' },
  { surahId: 8, ayahNumber: 18, text: 'That [is so], and [also] that Allah will weaken the plot of the disbelievers.' },
  { surahId: 8, ayahNumber: 19, text: 'If you [disbelievers] seek the victory - the defeat has come to you. And if you desist [from hostilities], it is best for you; but if you return [to war], We will return, and never will you be availed by your [large] company at all, even if it should increase; and [that is] because Allah is with the believers.' },
  { surahId: 8, ayahNumber: 20, text: 'O you who have believed, obey Allah and His Messenger and do not turn from him while you hear [his order].' },
  { surahId: 8, ayahNumber: 21, text: 'And do not be like those who say, "We have heard," while they do not hear.' },
  { surahId: 8, ayahNumber: 22, text: 'Indeed, the worst of living creatures in the sight of Allah are the deaf and dumb who do not use reason.' },
  { surahId: 8, ayahNumber: 23, text: 'Had Allah known any good in them, He would have made them hear. And if He had made them hear, they would [still] have turned away, while they were refusing.' },
  { surahId: 8, ayahNumber: 24, text: 'O you who have believed, respond to Allah and to the Messenger when he calls you to that which gives you life. And know that Allah intervenes between a man and his heart and that to Him you will be gathered.' },
  { surahId: 8, ayahNumber: 25, text: 'And fear a trial which will not strike those who have wronged among you exclusively, and know that Allah is severe in penalty.' },
  { surahId: 8, ayahNumber: 26, text: 'And remember when you were few and oppressed in the land, fearing that people might abduct you, but He sheltered you, supported you with His victory, and provided you with good things - that you might be grateful.' },
  { surahId: 8, ayahNumber: 27, text: 'O you who have believed, do not betray Allah and the Messenger or betray your trusts while you know [the consequence].' },
  { surahId: 8, ayahNumber: 28, text: 'And know that your properties and your children are but a trial and that Allah has with Him a great reward.' },
  { surahId: 8, ayahNumber: 29, text: 'O you who have believed, if you fear Allah, He will grant you a criterion and will remove from you your misdeeds and forgive you. And Allah is the possessor of great bounty.' },
  { surahId: 8, ayahNumber: 30, text: 'And [remember, O Muhammad], when those who disbelieved plotted against you to restrain you or kill you or evict you [from Makkah]. But they plan, and Allah plans. And Allah is the best of planners.' },
  { surahId: 8, ayahNumber: 31, text: 'And when Our verses are recited to them, they say, "We have heard. If we willed, we could say [something] like this. This is not but legends of the former peoples."' },
  { surahId: 8, ayahNumber: 32, text: 'And [remember] when they said, "O Allah, if this should be the truth from You, then rain down upon us stones from the sky or bring us a painful punishment."' },
  { surahId: 8, ayahNumber: 33, text: 'But Allah would not punish them while you, [O Muhammad], are among them, and Allah would not punish them while they seek forgiveness.' },
  { surahId: 8, ayahNumber: 34, text: 'But why should Allah not punish them while they obstruct [people] from al-Masjid al- Haram and they were not [fit to be] its guardians? Its [true] guardians are not but the righteous, but most of them do not know.' },
  { surahId: 8, ayahNumber: 35, text: 'And their prayer at the House was not except whistling and handclapping. So taste the punishment for what you disbelieved.' },
  { surahId: 8, ayahNumber: 36, text: 'Indeed, those who disbelieve spend their wealth to avert [people] from the way of Allah. So they will spend it; then it will be for them a [source of] regret; then they will be overcome. And those who have disbelieved - unto Hell they will be gathered.' },
  { surahId: 8, ayahNumber: 37, text: '[This is] so that Allah may distinguish the wicked from the good and place the wicked some of them upon others and heap them all together and put them into Hell. It is those who are the losers.' },
  { surahId: 8, ayahNumber: 38, text: 'Say to those who have disbelieved [that] if they cease, what has previously occurred will be forgiven for them. But if they return [to hostility] - then the precedent of the former [rebellious] peoples has already taken place.' },
  { surahId: 8, ayahNumber: 39, text: 'And fight them until there is no fitnah and [until] the religion, all of it, is for Allah. And if they cease - then indeed, Allah is Seeing of what they do.' },
  { surahId: 8, ayahNumber: 40, text: 'But if they turn away - then know that Allah is your protector. Excellent is the protector, and Excellent is the helper.' },
  { surahId: 8, ayahNumber: 41, text: 'And know that anything you obtain of war booty - then indeed, for Allah is one fifth of it and for the Messenger and for [his] near relatives and the orphans, the needy, and the [stranded] traveler, if you have believed in Allah and in that which We sent down to Our Servant on the day of criterion - the day when the two armies met. And Allah, over all things, is competent.' },
  { surahId: 8, ayahNumber: 42, text: '[Remember] when you were on the near side of the valley, and they were on the farther side, and the caravan was lower [in position] than you. If you had made an appointment [to meet], you would have missed the appointment. But [it was] so that Allah might accomplish a matter already destined - that those who perished [through disbelief] would perish upon evidence and those who lived [in faith] would live upon evidence; and indeed, Allah is Hearing and Knowing.' },
  { surahId: 8, ayahNumber: 43, text: '[Remember, O Muhammad], when Allah showed them to you in your dream as few; and if He had shown them to you as many, you [believers] would have lost courage and would have disputed in the matter [of whether to fight], but Allah saved [you from that]. Indeed, He is Knowing of that within the breasts.' },
  { surahId: 8, ayahNumber: 44, text: 'And [remember] when He showed them to you, when you met, as few in your eyes, and He made you [appear] as few in their eyes so that Allah might accomplish a matter already destined. And to Allah are [all] matters returned.' },
  { surahId: 8, ayahNumber: 45, text: 'O you who have believed, when you encounter a company [from the enemy forces], stand firm and remember Allah much that you may be successful.' },
  { surahId: 8, ayahNumber: 46, text: 'And obey Allah and His Messenger, and do not dispute and [thus] lose courage and [then] your strength would depart; and be patient. Indeed, Allah is with the patient.' },
  { surahId: 8, ayahNumber: 47, text: 'And do not be like those who came forth from their homes insolently and to be seen by people and avert [them] from the way of Allah. And Allah is encompassing of what they do.' },
  { surahId: 8, ayahNumber: 48, text: 'And [remember] when Satan made their deeds pleasing to them and said, "No one can overcome you today from among the people, and indeed, I am your protector." But when the two armies sighted each other, he turned on his heels and said, "Indeed, I am disassociated from you. Indeed, I see what you do not see; indeed I fear Allah. And Allah is severe in penalty."' },
  { surahId: 8, ayahNumber: 49, text: '[Remember] when the hypocrites and those in whose hearts was disease said, "Their religion has deluded those [Muslims]." But whoever relies upon Allah - then indeed, Allah is Exalted in Might and Wise.' },
  { surahId: 8, ayahNumber: 50, text: 'And if you could but see when the angels take the souls of those who disbelieved... They are striking their faces and their backs and [saying], "Taste the punishment of the Burning Fire.' },
  { surahId: 8, ayahNumber: 51, text: 'That is for what your hands have put forth [of evil] and because Allah is not ever unjust to His servants."' },
  { surahId: 8, ayahNumber: 52, text: '[Theirs is] like the custom of the people of Pharaoh and of those before them. They disbelieved in the signs of Allah, so Allah seized them for their sins. Indeed, Allah is Powerful and severe in penalty.' },
  { surahId: 8, ayahNumber: 53, text: 'That is because Allah would not change a favor which He had bestowed upon a people until they change what is within themselves. And indeed, Allah is Hearing and Knowing.' },
  { surahId: 8, ayahNumber: 54, text: '[Theirs is] like the custom of the people of Pharaoh and of those before them. They denied the signs of their Lord, so We destroyed them for their sins, and We drowned the people of Pharaoh. And all [of them] were wrongdoers.' },
  { surahId: 8, ayahNumber: 55, text: 'Indeed, the worst of living creatures in the sight of Allah are those who have disbelieved, and they will not [ever] believe -' },
  { surahId: 8, ayahNumber: 56, text: 'The ones with whom you made a treaty but then they break their pledge every time, and they do not fear Allah.' },
  { surahId: 8, ayahNumber: 57, text: 'So if you, [O Muhammad], gain dominance over them in war, disperse by [means of] them those behind them that perhaps they will be reminded.' },
  { surahId: 8, ayahNumber: 58, text: 'If you [have reason to] fear from a people betrayal, throw [their treaty] back to them, [putting you] on equal terms. Indeed, Allah does not like traitors.' },
  { surahId: 8, ayahNumber: 59, text: 'And let not those who disbelieve think they will escape. Indeed, they will not cause failure [to Allah].' },
  { surahId: 8, ayahNumber: 60, text: 'And prepare against them whatever you are able of power and of steeds of war by which you may terrify the enemy of Allah and your enemy and others besides them whom you do not know [but] whom Allah knows. And whatever you spend in the cause of Allah will be fully repaid to you, and you will not be wronged.' },
  { surahId: 8, ayahNumber: 61, text: 'And if they incline to peace, then incline to it [also] and rely upon Allah. Indeed, it is He who is the Hearing, the Knowing.' },
  { surahId: 8, ayahNumber: 62, text: 'But if they intend to deceive you - then sufficient for you is Allah. It is He who supported you with His help and with the believers' },
  { surahId: 8, ayahNumber: 63, text: 'And brought together their hearts. If you had spent all that is in the earth, you could not have brought their hearts together; but Allah brought them together. Indeed, He is Exalted in Might and Wise.' },
  { surahId: 8, ayahNumber: 64, text: 'O Prophet, sufficient for you is Allah and for whoever follows you of the believers.' },
  { surahId: 8, ayahNumber: 65, text: 'O Prophet, urge the believers to battle. If there are among you twenty [who are] steadfast, they will overcome two hundred. And if there are among you one hundred [who are] steadfast, they will overcome a thousand of those who have disbelieved because they are a people who do not understand.' },
  { surahId: 8, ayahNumber: 66, text: 'Now, Allah has lightened [the hardship] for you, and He knows that among you is weakness. So if there are from you one hundred [who are] steadfast, they will overcome two hundred. And if there are among you a thousand, they will overcome two thousand by permission of Allah. And Allah is with the steadfast.' },
  { surahId: 8, ayahNumber: 67, text: 'It is not for a prophet to have captives [of war] until he inflicts a massacre [upon Allah \'s enemies] in the land. Some Muslims desire the commodities of this world, but Allah desires [for you] the Hereafter. And Allah is Exalted in Might and Wise.' },
  { surahId: 8, ayahNumber: 68, text: 'If not for a decree from Allah that preceded, you would have been touched for what you took by a great punishment.' },
  { surahId: 8, ayahNumber: 69, text: 'So consume what you have taken of war booty [as being] lawful and good, and fear Allah. Indeed, Allah is Forgiving and Merciful.' },
  { surahId: 8, ayahNumber: 70, text: 'O Prophet, say to whoever is in your hands of the captives, "If Allah knows [any] good in your hearts, He will give you [something] better than what was taken from you, and He will forgive you; and Allah is Forgiving and Merciful."' },
  { surahId: 8, ayahNumber: 71, text: 'But if they intend to betray you - then they have already betrayed Allah before, and He empowered [you] over them. And Allah is Knowing and Wise.' },
  { surahId: 8, ayahNumber: 72, text: 'Indeed, those who have believed and emigrated and fought with their wealth and lives in the cause of Allah and those who gave shelter and aided - they are allies of one another. But those who believed and did not emigrate - for you there is no guardianship of them until they emigrate. And if they seek help of you for the religion, then you must help, except against a people between yourselves and whom is a treaty. And Allah is Seeing of what you do.' },
  { surahId: 8, ayahNumber: 73, text: 'And those who disbelieved are allies of one another. If you do not do so, there will be fitnah on earth and great corruption.' },
  { surahId: 8, ayahNumber: 74, text: 'But those who have believed and emigrated and fought in the cause of Allah and those who gave shelter and aided - it is they who are the believers, truly. For them is forgiveness and noble provision.' },
  { surahId: 8, ayahNumber: 75, text: 'And those who believed after [the initial emigration] and emigrated and fought with you - they are of you. But those of [blood] relationship are more entitled [to inheritance] in the decree of Allah. Indeed, Allah is Knowing of all things.' },
  { surahId: 9, ayahNumber: 1, text: '[This is a declaration of] disassociation, from Allah and His Messenger, to those with whom you had made a treaty among the polytheists.' },
  { surahId: 9, ayahNumber: 2, text: 'So travel freely, [O disbelievers], throughout the land [during] four months but know that you cannot cause failure to Allah and that Allah will disgrace the disbelievers.' },
  { surahId: 9, ayahNumber: 3, text: 'And [it is] an announcement from Allah and His Messenger to the people on the day of the greater pilgrimage that Allah is disassociated from the disbelievers, and [so is] His Messenger. So if you repent, that is best for you; but if you turn away - then know that you will not cause failure to Allah. And give tidings to those who disbelieve of a painful punishment.' },
  { surahId: 9, ayahNumber: 4, text: 'Excepted are those with whom you made a treaty among the polytheists and then they have not been deficient toward you in anything or supported anyone against you; so complete for them their treaty until their term [has ended]. Indeed, Allah loves the righteous [who fear Him].' },
  { surahId: 9, ayahNumber: 5, text: 'And when the sacred months have passed, then kill the polytheists wherever you find them and capture them and besiege them and sit in wait for them at every place of ambush. But if they should repent, establish prayer, and give zakah, let them [go] on their way. Indeed, Allah is Forgiving and Merciful.' },
  { surahId: 9, ayahNumber: 6, text: 'And if any one of the polytheists seeks your protection, then grant him protection so that he may hear the words of Allah. Then deliver him to his place of safety. That is because they are a people who do not know.' },
  { surahId: 9, ayahNumber: 7, text: 'How can there be for the polytheists a treaty in the sight of Allah and with His Messenger, except for those with whom you made a treaty at al-Masjid al-Haram? So as long as they are upright toward you, be upright toward them. Indeed, Allah loves the righteous [who fear Him].' },
  { surahId: 9, ayahNumber: 8, text: 'How [can there be a treaty] while, if they gain dominance over you, they do not observe concerning you any pact of kinship or covenant of protection? They satisfy you with their mouths, but their hearts refuse [compliance], and most of them are defiantly disobedient.' },
  { surahId: 9, ayahNumber: 9, text: 'They have exchanged the signs of Allah for a small price and averted [people] from His way. Indeed, it was evil that they were doing.' },
  { surahId: 9, ayahNumber: 10, text: 'They do not observe toward a believer any pact of kinship or covenant of protection. And it is they who are the transgressors.' },
  { surahId: 9, ayahNumber: 11, text: 'But if they repent, establish prayer, and give zakah, then they are your brothers in religion; and We detail the verses for a people who know.' },
  { surahId: 9, ayahNumber: 12, text: 'And if they break their oaths after their treaty and defame your religion, then fight the leaders of disbelief, for indeed, there are no oaths [sacred] to them; [fight them that] they might cease.' },
  { surahId: 9, ayahNumber: 13, text: 'Would you not fight a people who broke their oaths and determined to expel the Messenger, and they had begun [the attack upon] you the first time? Do you fear them? But Allah has more right that you should fear Him, if you are [truly] believers.' },
  { surahId: 9, ayahNumber: 14, text: 'Fight them; Allah will punish them by your hands and will disgrace them and give you victory over them and satisfy the breasts of a believing people' },
  { surahId: 9, ayahNumber: 15, text: 'And remove the fury in the believers\' hearts. And Allah turns in forgiveness to whom He wills; and Allah is Knowing and Wise.' },
  { surahId: 9, ayahNumber: 16, text: 'Do you think that you will be left [as you are] while Allah has not yet made evident those among you who strive [for His cause] and do not take other than Allah, His Messenger and the believers as intimates? And Allah is Acquainted with what you do.' },
  { surahId: 9, ayahNumber: 17, text: 'It is not for the polytheists to maintain the mosques of Allah [while] witnessing against themselves with disbelief. [For] those, their deeds have become worthless, and in the Fire they will abide eternally.' },
  { surahId: 9, ayahNumber: 18, text: 'The mosques of Allah are only to be maintained by those who believe in Allah and the Last Day and establish prayer and give zakah and do not fear except Allah, for it is expected that those will be of the [rightly] guided.' },
  { surahId: 9, ayahNumber: 19, text: 'Have you made the providing of water for the pilgrim and the maintenance of al-Masjid al-Haram equal to [the deeds of] one who believes in Allah and the Last Day and strives in the cause of Allah? They are not equal in the sight of Allah. And Allah does not guide the wrongdoing people.' },
  { surahId: 9, ayahNumber: 20, text: 'The ones who have believed, emigrated and striven in the cause of Allah with their wealth and their lives are greater in rank in the sight of Allah. And it is those who are the attainers [of success].' },
  { surahId: 9, ayahNumber: 21, text: 'Their Lord gives them good tidings of mercy from Him and approval and of gardens for them wherein is enduring pleasure.' },
  { surahId: 9, ayahNumber: 22, text: '[They will be] abiding therein forever. Indeed, Allah has with Him a great reward.' },
  { surahId: 9, ayahNumber: 23, text: 'O you who have believed, do not take your fathers or your brothers as allies if they have preferred disbelief over belief. And whoever does so among you - then it is those who are the wrongdoers.' },
  { surahId: 9, ayahNumber: 24, text: 'Say, [O Muhammad], "If your fathers, your sons, your brothers, your wives, your relatives, wealth which you have obtained, commerce wherein you fear decline, and dwellings with which you are pleased are more beloved to you than Allah and His Messenger and jihad in His cause, then wait until Allah executes His command. And Allah does not guide the defiantly disobedient people."' },
  { surahId: 9, ayahNumber: 25, text: 'Allah has already given you victory in many regions and [even] on the day of Hunayn, when your great number pleased you, but it did not avail you at all, and the earth was confining for you with its vastness; then you turned back, fleeing.' },
  { surahId: 9, ayahNumber: 26, text: 'Then Allah sent down His tranquillity upon His Messenger and upon the believers and sent down soldiers angels whom you did not see and punished those who disbelieved. And that is the recompense of the disbelievers.' },
  { surahId: 9, ayahNumber: 27, text: 'Then Allah will accept repentance after that for whom He wills; and Allah is Forgiving and Merciful.' },
  { surahId: 9, ayahNumber: 28, text: 'O you who have believed, indeed the polytheists are unclean, so let them not approach al-Masjid al-Haram after this, their [final] year. And if you fear privation, Allah will enrich you from His bounty if He wills. Indeed, Allah is Knowing and Wise.' },
  { surahId: 9, ayahNumber: 29, text: 'Fight those who do not believe in Allah or in the Last Day and who do not consider unlawful what Allah and His Messenger have made unlawful and who do not adopt the religion of truth from those who were given the Scripture - [fight] until they give the jizyah willingly while they are humbled.' },
  { surahId: 9, ayahNumber: 30, text: 'The Jews say, "Ezra is the son of Allah "; and the Christians say, "The Messiah is the son of Allah." That is their statement from their mouths; they imitate the saying of those who disbelieved [before them]. May Allah destroy them; how are they deluded?' },
  { surahId: 9, ayahNumber: 31, text: 'They have taken their scholars and monks as lords besides Allah, and [also] the Messiah, the son of Mary. And they were not commanded except to worship one God; there is no deity except Him. Exalted is He above whatever they associate with Him.' },
  { surahId: 9, ayahNumber: 32, text: 'They want to extinguish the light of Allah with their mouths, but Allah refuses except to perfect His light, although the disbelievers dislike it.' },
  { surahId: 9, ayahNumber: 33, text: 'It is He who has sent His Messenger with guidance and the religion of truth to manifest it over all religion, although they who associate others with Allah dislike it.' },
  { surahId: 9, ayahNumber: 34, text: 'O you who have believed, indeed many of the scholars and the monks devour the wealth of people unjustly and avert [them] from the way of Allah. And those who hoard gold and silver and spend it not in the way of Allah - give them tidings of a painful punishment.' },
  { surahId: 9, ayahNumber: 35, text: 'The Day when it will be heated in the fire of Hell and seared therewith will be their foreheads, their flanks, and their backs, [it will be said], "This is what you hoarded for yourselves, so taste what you used to hoard."' },
  { surahId: 9, ayahNumber: 36, text: 'Indeed, the number of months with Allah is twelve [lunar] months in the register of Allah [from] the day He created the heavens and the earth; of these, four are sacred. That is the correct religion, so do not wrong yourselves during them. And fight against the disbelievers collectively as they fight against you collectively. And know that Allah is with the righteous [who fear Him].' },
  { surahId: 9, ayahNumber: 37, text: 'Indeed, the postponing [of restriction within sacred months] is an increase in disbelief by which those who have disbelieved are led [further] astray. They make it lawful one year and unlawful another year to correspond to the number made unlawful by Allah and [thus] make lawful what Allah has made unlawful. Made pleasing to them is the evil of their deeds; and Allah does not guide the disbelieving people.' },
  { surahId: 9, ayahNumber: 38, text: 'O you who have believed, what is [the matter] with you that, when you are told to go forth in the cause of Allah, you adhere heavily to the earth? Are you satisfied with the life of this world rather than the Hereafter? But what is the enjoyment of worldly life compared to the Hereafter except a [very] little.' },
  { surahId: 9, ayahNumber: 39, text: 'If you do not go forth, He will punish you with a painful punishment and will replace you with another people, and you will not harm Him at all. And Allah is over all things competent.' },
  { surahId: 9, ayahNumber: 40, text: 'If you do not aid the Prophet - Allah has already aided him when those who disbelieved had driven him out [of Makkah] as one of two, when they were in the cave and he said to his companion, "Do not grieve; indeed Allah is with us." And Allah sent down his tranquillity upon him and supported him with angels you did not see and made the word of those who disbelieved the lowest, while the word of Allah - that is the highest. And Allah is Exalted in Might and Wise.' },
  { surahId: 9, ayahNumber: 41, text: 'Go forth, whether light or heavy, and strive with your wealth and your lives in the cause of Allah. That is better for you, if you only knew.' },
  { surahId: 9, ayahNumber: 42, text: 'Had it been an easy gain and a moderate trip, the hypocrites would have followed you, but distant to them was the journey. And they will swear by Allah, "If we were able, we would have gone forth with you," destroying themselves [through false oaths], and Allah knows that indeed they are liars.' },
  { surahId: 9, ayahNumber: 43, text: 'May Allah pardon you, [O Muhammad]; why did you give them permission [to remain behind]? [You should not have] until it was evident to you who were truthful and you knew [who were] the liars.' },
  { surahId: 9, ayahNumber: 44, text: 'Those who believe in Allah and the Last Day would not ask permission of you to be excused from striving with their wealth and their lives. And Allah is Knowing of those who fear Him.' },
  { surahId: 9, ayahNumber: 45, text: 'Only those would ask permission of you who do not believe in Allah and the Last Day and whose hearts have doubted, and they, in their doubt, are hesitating.' },
  { surahId: 9, ayahNumber: 46, text: 'And if they had intended to go forth, they would have prepared for it [some] preparation. But Allah disliked their being sent, so He kept them back, and they were told, "Remain [behind] with those who remain."' },
  { surahId: 9, ayahNumber: 47, text: 'Had they gone forth with you, they would not have increased you except in confusion, and they would have been active among you, seeking [to cause] you fitnah. And among you are avid listeners to them. And Allah is Knowing of the wrongdoers.' },
  { surahId: 9, ayahNumber: 48, text: 'They had already desired dissension before and had upset matters for you until the truth came and the ordinance of Allah appeared, while they were averse.' },
  { surahId: 9, ayahNumber: 49, text: 'And among them is he who says, "Permit me [to remain at home] and do not put me to trial." Unquestionably, into trial they have fallen. And indeed, Hell will encompass the disbelievers.' },
  { surahId: 9, ayahNumber: 50, text: 'If good befalls you, it distresses them; but if disaster strikes you, they say, "We took our matter [in hand] before," and turn away while they are rejoicing.' },
  { surahId: 9, ayahNumber: 51, text: 'Say, "Never will we be struck except by what Allah has decreed for us; He is our protector." And upon Allah let the believers rely.' },
  { surahId: 9, ayahNumber: 52, text: 'Say, "Do you await for us except one of the two best things while we await for you that Allah will afflict you with punishment from Himself or at our hands? So wait; indeed we, along with you, are waiting."' },
  { surahId: 9, ayahNumber: 53, text: 'Say, "Spend willingly or unwillingly; never will it be accepted from you. Indeed, you have been a defiantly disobedient people."' },
  { surahId: 9, ayahNumber: 54, text: 'And what prevents their expenditures from being accepted from them but that they have disbelieved in Allah and in His Messenger and that they come not to prayer except while they are lazy and that they do not spend except while they are unwilling.' },
  { surahId: 9, ayahNumber: 55, text: 'So let not their wealth or their children impress you. Allah only intends to punish them through them in worldly life and that their souls should depart [at death] while they are disbelievers.' },
  { surahId: 9, ayahNumber: 56, text: 'And they swear by Allah that they are from among you while they are not from among you; but they are a people who are afraid.' },
  { surahId: 9, ayahNumber: 57, text: 'If they could find a refuge or some caves or any place to enter [and hide], they would turn to it while they run heedlessly.' },
  { surahId: 9, ayahNumber: 58, text: 'And among them are some who criticize you concerning the [distribution of] charities. If they are given from them, they approve; but if they are not given from them, at once they become angry.' },
  { surahId: 9, ayahNumber: 59, text: 'If only they had been satisfied with what Allah and His Messenger gave them and said, "Sufficient for us is Allah; Allah will give us of His bounty, and [so will] His Messenger; indeed, we are desirous toward Allah," [it would have been better for them].' },
  { surahId: 9, ayahNumber: 60, text: 'Zakah expenditures are only for the poor and for the needy and for those employed to collect [zakah] and for bringing hearts together [for Islam] and for freeing captives [or slaves] and for those in debt and for the cause of Allah and for the [stranded] traveler - an obligation [imposed] by Allah. And Allah is Knowing and Wise.' },
  { surahId: 9, ayahNumber: 61, text: 'And among them are those who abuse the Prophet and say, "He is an ear." Say, "[It is] an ear of goodness for you that believes in Allah and believes the believers and [is] a mercy to those who believe among you." And those who abuse the Messenger of Allah - for them is a painful punishment.' },
  { surahId: 9, ayahNumber: 62, text: 'They swear by Allah to you [Muslims] to satisfy you. But Allah and His Messenger are more worthy for them to satisfy, if they should be believers.' },
  { surahId: 9, ayahNumber: 63, text: 'Do they not know that whoever opposes Allah and His Messenger - that for him is the fire of Hell, wherein he will abide eternally? That is the great disgrace.' },
  { surahId: 9, ayahNumber: 64, text: 'They hypocrites are apprehensive lest a surah be revealed about them, informing them of what is in their hearts. Say, "Mock [as you wish]; indeed, Allah will expose that which you fear."' },
  { surahId: 9, ayahNumber: 65, text: 'And if you ask them, they will surely say, "We were only conversing and playing." Say, "Is it Allah and His verses and His Messenger that you were mocking?"' },
  { surahId: 9, ayahNumber: 66, text: 'Make no excuse; you have disbelieved after your belief. If We pardon one faction of you - We will punish another faction because they were criminals.' },
  { surahId: 9, ayahNumber: 67, text: 'The hypocrite men and hypocrite women are of one another. They enjoin what is wrong and forbid what is right and close their hands. They have forgotten Allah, so He has forgotten them [accordingly]. Indeed, the hypocrites - it is they who are the defiantly disobedient.' },
  { surahId: 9, ayahNumber: 68, text: 'Allah has promised the hypocrite men and hypocrite women and the disbelievers the fire of Hell, wherein they will abide eternally. It is sufficient for them. And Allah has cursed them, and for them is an enduring punishment.' },
  { surahId: 9, ayahNumber: 69, text: '[You disbelievers are] like those before you; they were stronger than you in power and more abundant in wealth and children. They enjoyed their portion [of worldly enjoyment], and you have enjoyed your portion as those before you enjoyed their portion, and you have engaged [in vanities] like that in which they engaged. [It is] those whose deeds have become worthless in this world and in the Hereafter, and it is they who are the losers.' },
  { surahId: 9, ayahNumber: 70, text: 'Has there not reached them the news of those before them - the people of Noah and [the tribes of] \'Aad and Thamud and the people of Abraham and the companions of Madyan and the towns overturned? Their messengers came to them with clear proofs. And Allah would never have wronged them, but they were wronging themselves.' },
  { surahId: 9, ayahNumber: 71, text: 'The believing men and believing women are allies of one another. They enjoin what is right and forbid what is wrong and establish prayer and give zakah and obey Allah and His Messenger. Those - Allah will have mercy upon them. Indeed, Allah is Exalted in Might and Wise.' },
  { surahId: 9, ayahNumber: 72, text: 'Allah has promised the believing men and believing women gardens beneath which rivers flow, wherein they abide eternally, and pleasant dwellings in gardens of perpetual residence; but approval from Allah is greater. It is that which is the great attainment.' },
  { surahId: 9, ayahNumber: 73, text: 'O Prophet, fight against the disbelievers and the hypocrites and be harsh upon them. And their refuge is Hell, and wretched is the destination.' },
  { surahId: 9, ayahNumber: 74, text: 'They swear by Allah that they did not say [anything against the Prophet] while they had said the word of disbelief and disbelieved after their [pretense of] Islam and planned that which they were not to attain. And they were not resentful except [for the fact] that Allah and His Messenger had enriched them of His bounty. So if they repent, it is better for them; but if they turn away, Allah will punish them with a painful punishment in this world and the Hereafter. And there will not be for them on earth any protector or helper.' },
  { surahId: 9, ayahNumber: 75, text: 'And among them are those who made a covenant with Allah, [saying], "If He should give us from His bounty, we will surely spend in charity, and we will surely be among the righteous."' },
  { surahId: 9, ayahNumber: 76, text: 'But when he gave them from His bounty, they were stingy with it and turned away while they refused.' },
  { surahId: 9, ayahNumber: 77, text: 'So He penalized them with hypocrisy in their hearts until the Day they will meet Him - because they failed Allah in what they promised Him and because they [habitually] used to lie.' },
  { surahId: 9, ayahNumber: 78, text: 'Did they not know that Allah knows their secrets and their private conversations and that Allah is the Knower of the unseen?' },
  { surahId: 9, ayahNumber: 79, text: 'Those who criticize the contributors among the believers concerning [their] charities and [criticize] the ones who find nothing [to spend] except their effort, so they ridicule them - Allah will ridicule them, and they will have a painful punishment.' },
  { surahId: 9, ayahNumber: 80, text: 'Ask forgiveness for them, [O Muhammad], or do not ask forgiveness for them. If you should ask forgiveness for them seventy times - never will Allah forgive them. That is because they disbelieved in Allah and His Messenger, and Allah does not guide the defiantly disobedient people.' },
  { surahId: 9, ayahNumber: 81, text: 'Those who remained behind rejoiced in their staying [at home] after [the departure of] the Messenger of Allah and disliked to strive with their wealth and their lives in the cause of Allah and said, "Do not go forth in the heat." Say, "The fire of Hell is more intensive in heat" - if they would but understand.' },
  { surahId: 9, ayahNumber: 82, text: 'So let them laugh a little and [then] weep much as recompense for what they used to earn.' },
  { surahId: 9, ayahNumber: 83, text: 'If Allah should return you to a faction of them [after the expedition] and then they ask your permission to go out [to battle], say, "You will not go out with me, ever, and you will never fight with me an enemy. Indeed, you were satisfied with sitting [at home] the first time, so sit [now] with those who stay behind."' },
  { surahId: 9, ayahNumber: 84, text: 'And do not pray [the funeral prayer, O Muhammad], over any of them who has died - ever - or stand at his grave. Indeed, they disbelieved in Allah and His Messenger and died while they were defiantly disobedient.' },
  { surahId: 9, ayahNumber: 85, text: 'And let not their wealth and their children impress you. Allah only intends to punish them through them in this world and that their souls should depart [at death] while they are disbelievers.' },
  { surahId: 9, ayahNumber: 86, text: 'And when a surah was revealed [enjoining them] to believe in Allah and to fight with His Messenger, those of wealth among them asked your permission [to stay back] and said, "Leave us to be with them who sit [at home]."' },
  { surahId: 9, ayahNumber: 87, text: 'They were satisfied to be with those who stay behind, and their hearts were sealed over, so they do not understand.' },
  { surahId: 9, ayahNumber: 88, text: 'But the Messenger and those who believed with him fought with their wealth and their lives. Those will have [all that is] good, and it is those who are the successful.' },
  { surahId: 9, ayahNumber: 89, text: 'Allah has prepared for them gardens beneath which rivers flow, wherein they will abide eternally. That is the great attainment.' },
  { surahId: 9, ayahNumber: 90, text: 'And those with excuses among the bedouins came to be permitted [to remain], and they who had lied to Allah and His Messenger sat [at home]. There will strike those who disbelieved among them a painful punishment.' },
  { surahId: 9, ayahNumber: 91, text: 'There is not upon the weak or upon the ill or upon those who do not find anything to spend any discomfort when they are sincere to Allah and His Messenger. There is not upon the doers of good any cause [for blame]. And Allah is Forgiving and Merciful.' },
  { surahId: 9, ayahNumber: 92, text: 'Nor [is there blame] upon those who, when they came to you that you might give them mounts, you said, "I can find nothing for you to ride upon." They turned back while their eyes overflowed with tears out of grief that they could not find something to spend [for the cause of Allah].' },
  { surahId: 9, ayahNumber: 93, text: 'The cause [for blame] is only upon those who ask permission of you while they are rich. They are satisfied to be with those who stay behind, and Allah has sealed over their hearts, so they do not know.' },
  { surahId: 9, ayahNumber: 94, text: 'They will make excuses to you when you have returned to them. Say, "Make no excuse - never will we believe you. Allah has already informed us of your news. And Allah will observe your deeds, and [so will] His Messenger; then you will be taken back to the Knower of the unseen and the witnessed, and He will inform you of what you used to do."' },
  { surahId: 9, ayahNumber: 95, text: 'They will swear by Allah to you when you return to them that you would leave them alone. So leave them alone; indeed they are evil; and their refuge is Hell as recompense for what they had been earning.' },
  { surahId: 9, ayahNumber: 96, text: 'They swear to you so that you might be satisfied with them. But if you should be satisfied with them - indeed, Allah is not satisfied with a defiantly disobedient people.' },
  { surahId: 9, ayahNumber: 97, text: 'The bedouins are stronger in disbelief and hypocrisy and more likely not to know the limits of what [laws] Allah has revealed to His Messenger. And Allah is Knowing and Wise.' },
  { surahId: 9, ayahNumber: 98, text: 'And among the bedouins are some who consider what they spend as a loss and await for you turns of misfortune. Upon them will be a misfortune of evil. And Allah is Hearing and Knowing.' },
  { surahId: 9, ayahNumber: 99, text: 'But among the bedouins are some who believe in Allah and the Last Day and consider what they spend as means of nearness to Allah and of [obtaining] invocations of the Messenger. Unquestionably, it is a means of nearness for them. Allah will admit them to His mercy. Indeed, Allah is Forgiving and Merciful.' },
  { surahId: 9, ayahNumber: 100, text: 'And the first forerunners [in the faith] among the Muhajireen and the Ansar and those who followed them with good conduct - Allah is pleased with them and they are pleased with Him, and He has prepared for them gardens beneath which rivers flow, wherein they will abide forever. That is the great attainment.' },
  { surahId: 9, ayahNumber: 101, text: 'And among those around you of the bedouins are hypocrites, and [also] from the people of Madinah. They have become accustomed to hypocrisy. You, [O Muhammad], do not know them, [but] We know them. We will punish them twice [in this world]; then they will be returned to a great punishment.' },
  { surahId: 9, ayahNumber: 102, text: 'And [there are] others who have acknowledged their sins. They had mixed a righteous deed with another that was bad. Perhaps Allah will turn to them in forgiveness. Indeed, Allah is Forgiving and Merciful.' },
  { surahId: 9, ayahNumber: 103, text: 'Take, [O, Muhammad], from their wealth a charity by which you purify them and cause them increase, and invoke [Allah \'s blessings] upon them. Indeed, your invocations are reassurance for them. And Allah is Hearing and Knowing.' },
  { surahId: 9, ayahNumber: 104, text: 'Do they not know that it is Allah who accepts repentance from His servants and receives charities and that it is Allah who is the Accepting of repentance, the Merciful?' },
  { surahId: 9, ayahNumber: 105, text: 'And say, "Do [as you will], for Allah will see your deeds, and [so, will] His Messenger and the believers. And you will be returned to the Knower of the unseen and the witnessed, and He will inform you of what you used to do."' },
  { surahId: 9, ayahNumber: 106, text: 'And [there are] others deferred until the command of Allah - whether He will punish them or whether He will forgive them. And Allah is Knowing and Wise.' },
  { surahId: 9, ayahNumber: 107, text: 'And [there are] those [hypocrites] who took for themselves a mosque for causing harm and disbelief and division among the believers and as a station for whoever had warred against Allah and His Messenger before. And they will surely swear, "We intended only the best." And Allah testifies that indeed they are liars.' },
  { surahId: 9, ayahNumber: 108, text: 'Do not stand [for prayer] within it - ever. A mosque founded on righteousness from the first day is more worthy for you to stand in. Within it are men who love to purify themselves; and Allah loves those who purify themselves.' },
  { surahId: 9, ayahNumber: 109, text: 'Then is one who laid the foundation of his building on righteousness [with fear] from Allah and [seeking] His approval better or one who laid the foundation of his building on the edge of a bank about to collapse, so it collapsed with him into the fire of Hell? And Allah does not guide the wrongdoing people.' },
  { surahId: 9, ayahNumber: 110, text: 'Their building which they built will not cease to be a [cause of] skepticism in their hearts until their hearts are stopped. And Allah is Knowing and Wise.' },
  { surahId: 9, ayahNumber: 111, text: 'Indeed, Allah has purchased from the believers their lives and their properties [in exchange] for that they will have Paradise. They fight in the cause of Allah, so they kill and are killed. [It is] a true promise [binding] upon Him in the Torah and the Gospel and the Qur\'an. And who is truer to his covenant than Allah? So rejoice in your transaction which you have contracted. And it is that which is the great attainment.' },
  { surahId: 9, ayahNumber: 112, text: '[Such believers are] the repentant, the worshippers, the praisers [of Allah], the travelers [for His cause], those who bow and prostrate [in prayer], those who enjoin what is right and forbid what is wrong, and those who observe the limits [set by] Allah. And give good tidings to the believers.' },
  { surahId: 9, ayahNumber: 113, text: 'It is not for the Prophet and those who have believed to ask forgiveness for the polytheists, even if they were relatives, after it has become clear to them that they are companions of Hellfire.' },
  { surahId: 9, ayahNumber: 114, text: 'And the request of forgiveness of Abraham for his father was only because of a promise he had made to him. But when it became apparent to Abraham that his father was an enemy to Allah, he disassociated himself from him. Indeed was Abraham compassionate and patient.' },
  { surahId: 9, ayahNumber: 115, text: 'And Allah would not let a people stray after He has guided them until He makes clear to them what they should avoid. Indeed, Allah is Knowing of all things.' },
  { surahId: 9, ayahNumber: 116, text: 'Indeed, to Allah belongs the dominion of the heavens and the earth; He gives life and causes death. And you have not besides Allah any protector or any helper.' },
  { surahId: 9, ayahNumber: 117, text: 'Allah has already forgiven the Prophet and the Muhajireen and the Ansar who followed him in the hour of difficulty after the hearts of a party of them had almost inclined [to doubt], and then He forgave them. Indeed, He was to them Kind and Merciful.' },
  { surahId: 9, ayahNumber: 118, text: 'And [He also forgave] the three who were left behind [and regretted their error] to the point that the earth closed in on them in spite of its vastness and their souls confined them and they were certain that there is no refuge from Allah except in Him. Then He turned to them so they could repent. Indeed, Allah is the Accepting of repentance, the Merciful.' },
  { surahId: 9, ayahNumber: 119, text: 'O you who have believed, fear Allah and be with those who are true.' },
  { surahId: 9, ayahNumber: 120, text: 'It was not [proper] for the people of Madinah and those surrounding them of the bedouins that they remain behind after [the departure of] the Messenger of Allah or that they prefer themselves over his self. That is because they are not afflicted by thirst or fatigue or hunger in the cause of Allah, nor do they tread on any ground that enrages the disbelievers, nor do they inflict upon an enemy any infliction but that is registered for them as a righteous deed. Indeed, Allah does not allow to be lost the reward of the doers of good.' },
  { surahId: 9, ayahNumber: 121, text: 'Nor do they spend an expenditure, small or large, or cross a valley but that it is registered for them that Allah may reward them for the best of what they were doing.' },
  { surahId: 9, ayahNumber: 122, text: 'And it is not for the believers to go forth [to battle] all at once. For there should separate from every division of them a group [remaining] to obtain understanding in the religion and warn their people when they return to them that they might be cautious.' },
  { surahId: 9, ayahNumber: 123, text: 'O you who have believed, fight those adjacent to you of the disbelievers and let them find in you harshness. And know that Allah is with the righteous.' },
  { surahId: 9, ayahNumber: 124, text: 'And whenever a surah is revealed, there are among the hypocrites those who say, "Which of you has this increased faith?" As for those who believed, it has increased them in faith, while they are rejoicing.' },
  { surahId: 9, ayahNumber: 125, text: 'But as for those in whose hearts is disease, it has [only] increased them in evil [in addition] to their evil. And they will have died while they are disbelievers.' },
  { surahId: 9, ayahNumber: 126, text: 'Do they not see that they are tried every year once or twice but then they do not repent nor do they remember?' },
  { surahId: 9, ayahNumber: 127, text: 'And whenever a surah is revealed, they look at each other, [saying], "Does anyone see you?" and then they dismiss themselves. Allah has dismissed their hearts because they are a people who do not understand.' },
  { surahId: 9, ayahNumber: 128, text: 'There has certainly come to you a Messenger from among yourselves. Grievous to him is what you suffer; [he is] concerned over you and to the believers is kind and merciful.' },
  { surahId: 9, ayahNumber: 129, text: 'But if they turn away, [O Muhammad], say, "Sufficient for me is Allah; there is no deity except Him. On Him I have relied, and He is the Lord of the Great Throne."' },
  { surahId: 10, ayahNumber: 1, text: 'Alif, Lam, Ra. These are the verses of the wise Book' },
  { surahId: 10, ayahNumber: 2, text: 'Have the people been amazed that We revealed [revelation] to a man from among them, [saying], "Warn mankind and give good tidings to those who believe that they will have a [firm] precedence of honor with their Lord"? [But] the disbelievers say, "Indeed, this is an obvious magician."' },
  { surahId: 10, ayahNumber: 3, text: 'Indeed, your Lord is Allah, who created the heavens and the earth in six days and then established Himself above the Throne, arranging the matter [of His creation]. There is no intercessor except after His permission. That is Allah, your Lord, so worship Him. Then will you not remember?' },
  { surahId: 10, ayahNumber: 4, text: 'To Him is your return all together. [It is] the promise of Allah [which is] truth. Indeed, He begins the [process of] creation and then repeats it that He may reward those who have believed and done righteous deeds, in justice. But those who disbelieved will have a drink of scalding water and a painful punishment for what they used to deny.' },
  { surahId: 10, ayahNumber: 5, text: 'It is He who made the sun a shining light and the moon a derived light and determined for it phases - that you may know the number of years and account [of time]. Allah has not created this except in truth. He details the signs for a people who know' },
  { surahId: 10, ayahNumber: 6, text: 'Indeed, in the alternation of the night and the day and [in] what Allah has created in the heavens and the earth are signs for a people who fear Allah' },
  { surahId: 10, ayahNumber: 7, text: 'Indeed, those who do not expect the meeting with Us and are satisfied with the life of this world and feel secure therein and those who are heedless of Our signs' },
  { surahId: 10, ayahNumber: 8, text: 'For those their refuge will be the Fire because of what they used to earn.' },
  { surahId: 10, ayahNumber: 9, text: 'Indeed, those who have believed and done righteous deeds - their Lord will guide them because of their faith. Beneath them rivers will flow in the Gardens of Pleasure' },
  { surahId: 10, ayahNumber: 10, text: 'Their call therein will be, "Exalted are You, O Allah," and their greeting therein will be, "Peace." And the last of their call will be, "Praise to Allah, Lord of the worlds!"' },
  { surahId: 10, ayahNumber: 11, text: 'And if Allah was to hasten for the people the evil [they invoke] as He hastens for them the good, their term would have been ended for them. But We leave the ones who do not expect the meeting with Us, in their transgression, wandering blindly' },
  { surahId: 10, ayahNumber: 12, text: 'And when affliction touches man, he calls upon Us, whether lying on his side or sitting or standing; but when We remove from him his affliction, he continues [in disobedience] as if he had never called upon Us to [remove] an affliction that touched him. Thus is made pleasing to the transgressors that which they have been doing' },
  { surahId: 10, ayahNumber: 13, text: 'And We had already destroyed generations before you when they wronged, and their messengers had come to them with clear proofs, but they were not to believe. Thus do We recompense the criminal people' },
  { surahId: 10, ayahNumber: 14, text: 'Then We made you successors in the land after them so that We may observe how you will do.' },
  { surahId: 10, ayahNumber: 15, text: 'And when Our verses are recited to them as clear evidences, those who do not expect the meeting with Us say, "Bring us a Qur\'an other than this or change it." Say, [O Muhammad], "It is not for me to change it on my own accord. I only follow what is revealed to me. Indeed I fear, if I should disobey my Lord, the punishment of a tremendous Day."' },
  { surahId: 10, ayahNumber: 16, text: 'Say, "If Allah had willed, I would not have recited it to you, nor would He have made it known to you, for I had remained among you a lifetime before it. Then will you not reason?"' },
  { surahId: 10, ayahNumber: 17, text: 'So who is more unjust than he who invents a lie about Allah or denies His signs? Indeed, the criminals will not succeed' },
  { surahId: 10, ayahNumber: 18, text: 'And they worship other than Allah that which neither harms them nor benefits them, and they say, "These are our intercessors with Allah " Say, "Do you inform Allah of something He does not know in the heavens or on the earth?" Exalted is He and high above what they associate with Him' },
  { surahId: 10, ayahNumber: 19, text: 'And mankind was not but one community [united in religion], but [then] they differed. And if not for a word that preceded from your Lord, it would have been judged between them [immediately] concerning that over which they differ.' },
  { surahId: 10, ayahNumber: 20, text: 'And they say, "Why is a sign not sent down to him from his Lord?" So say, "The unseen is only for Allah [to administer], so wait; indeed, I am with you among those who wait."' },
  { surahId: 10, ayahNumber: 21, text: 'And when We give the people a taste of mercy after adversity has touched them, at once they conspire against Our verses. Say, "Allah is swifter in strategy." Indeed, Our messengers record that which you conspire' },
  { surahId: 10, ayahNumber: 22, text: 'It is He who enables you to travel on land and sea until, when you are in ships and they sail with them by a good wind and they rejoice therein, there comes a storm wind and the waves come upon them from everywhere and they assume that they are surrounded, supplicating Allah, sincere to Him in religion, "If You should save us from this, we will surely be among the thankful."' },
  { surahId: 10, ayahNumber: 23, text: 'But when He saves them, at once they commit injustice upon the earth without right. O mankind, your injustice is only against yourselves, [being merely] the enjoyment of worldly life. Then to Us is your return, and We will inform you of what you used to do.' },
  { surahId: 10, ayahNumber: 24, text: 'The example of [this] worldly life is but like rain which We have sent down from the sky that the plants of the earth absorb - [those] from which men and livestock eat - until, when the earth has taken on its adornment and is beautified and its people suppose that they have capability over it, there comes to it Our command by night or by day, and We make it as a harvest, as if it had not flourished yesterday. Thus do We explain in detail the signs for a people who give thought.' },
  { surahId: 10, ayahNumber: 25, text: 'And Allah invites to the Home of Peace and guides whom He wills to a straight path' },
  { surahId: 10, ayahNumber: 26, text: 'For them who have done good is the best [reward] and extra. No darkness will cover their faces, nor humiliation. Those are companions of Paradise; they will abide therein eternally' },
  { surahId: 10, ayahNumber: 27, text: 'But they who have earned [blame for] evil doings - the recompense of an evil deed is its equivalent, and humiliation will cover them. They will have from Allah no protector. It will be as if their faces are covered with pieces of the night - so dark [are they]. Those are the companions of the Fire; they will abide therein eternally.' },
  { surahId: 10, ayahNumber: 28, text: 'And [mention, O Muhammad], the Day We will gather them all together - then We will say to those who associated others with Allah, "[Remain in] your place, you and your \'partners.\' " Then We will separate them, and their "partners" will say, "You did not used to worship us,' },
  { surahId: 10, ayahNumber: 29, text: 'And sufficient is Allah as a witness between us and you that we were of your worship unaware."' },
  { surahId: 10, ayahNumber: 30, text: 'There, [on that Day], every soul will be put to trial for what it did previously, and they will be returned to Allah, their master, the Truth, and lost from them is whatever they used to invent.' },
  { surahId: 10, ayahNumber: 31, text: 'Say, "Who provides for you from the heaven and the earth? Or who controls hearing and sight and who brings the living out of the dead and brings the dead out of the living and who arranges [every] matter?" They will say, "Allah," so say, "Then will you not fear Him?"' },
  { surahId: 10, ayahNumber: 32, text: 'For that is Allah, your Lord, the Truth. And what can be beyond truth except error? So how are you averted?' },
  { surahId: 10, ayahNumber: 33, text: 'Thus the word of your Lord has come into effect upon those who defiantly disobeyed - that they will not believe.' },
  { surahId: 10, ayahNumber: 34, text: 'Say, "Are there of your \'partners\' any who begins creation and then repeats it?" Say, "Allah begins creation and then repeats it, so how are you deluded?"' },
  { surahId: 10, ayahNumber: 35, text: 'Say, "Are there of your \'partners\' any who guides to the truth?" Say, "Allah guides to the truth. So is He who guides to the truth more worthy to be followed or he who guides not unless he is guided? Then what is [wrong] with you - how do you judge?"' },
  { surahId: 10, ayahNumber: 36, text: 'And most of them follow not except assumption. Indeed, assumption avails not against the truth at all. Indeed, Allah is Knowing of what they do.' },
  { surahId: 10, ayahNumber: 37, text: 'And it was not [possible] for this Qur\'an to be produced by other than Allah, but [it is] a confirmation of what was before it and a detailed explanation of the [former] Scripture, about which there is no doubt, from the Lord of the worlds.' },
  { surahId: 10, ayahNumber: 38, text: 'Or do they say [about the Prophet], "He invented it?" Say, "Then bring forth a surah like it and call upon [for assistance] whomever you can besides Allah, if you should be truthful."' },
  { surahId: 10, ayahNumber: 39, text: 'Rather, they have denied that which they encompass not in knowledge and whose interpretation has not yet come to them. Thus did those before them deny. Then observe how was the end of the wrongdoers.' },
  { surahId: 10, ayahNumber: 40, text: 'And of them are those who believe in it, and of them are those who do not believe in it. And your Lord is most knowing of the corrupters' },
  { surahId: 10, ayahNumber: 41, text: 'And if they deny you, [O Muhammad], then say, "For me are my deeds, and for you are your deeds. You are disassociated from what I do, and I am disassociated from what you do."' },
  { surahId: 10, ayahNumber: 42, text: 'And among them are those who listen to you. But can you cause the deaf to hear, although they will not use reason?' },
  { surahId: 10, ayahNumber: 43, text: 'And among them are those who look at you. But can you guide the blind although they will not [attempt to] see?' },
  { surahId: 10, ayahNumber: 44, text: 'Indeed, Allah does not wrong the people at all, but it is the people who are wronging themselves.' },
  { surahId: 10, ayahNumber: 45, text: 'And on the Day when He will gather them, [it will be] as if they had not remained [in the world] but an hour of the day, [and] they will know each other. Those will have lost who denied the meeting with Allah and were not guided' },
  { surahId: 10, ayahNumber: 46, text: 'And whether We show you some of what We promise them, [O Muhammad], or We take you in death, to Us is their return; then, [either way], Allah is a witness concerning what they are doing' },
  { surahId: 10, ayahNumber: 47, text: 'And for every nation is a messenger. So when their messenger comes, it will be judged between them in justice, and they will not be wronged' },
  { surahId: 10, ayahNumber: 48, text: 'And they say, "When is [the fulfillment of] this promise, if you should be truthful?"' },
  { surahId: 10, ayahNumber: 49, text: 'Say, "I possess not for myself any harm or benefit except what Allah should will. For every nation is a [specified] term. When their time has come, then they will not remain behind an hour, nor will they precede [it]."' },
  { surahId: 10, ayahNumber: 50, text: 'Say, "Have you considered: if His punishment should come to you by night or by day - for which [aspect] of it would the criminals be impatient?"' },
  { surahId: 10, ayahNumber: 51, text: 'Then is it that when it has [actually] occurred you will believe in it? Now? And you were [once] for it impatient' },
  { surahId: 10, ayahNumber: 52, text: 'Then it will be said to those who had wronged, "Taste the punishment of eternity; are you being recompensed except for what you used to earn?"' },
  { surahId: 10, ayahNumber: 53, text: 'And they ask information of you, [O Muhammad], "Is it true?" Say, "Yes, by my Lord. Indeed, it is truth; and you will not cause failure [to Allah]."' },
  { surahId: 10, ayahNumber: 54, text: 'And if each soul that wronged had everything on earth, it would offer it in ransom. And they will confide regret when they see the punishment; and they will be judged in justice, and they will not be wronged' },
  { surahId: 10, ayahNumber: 55, text: 'Unquestionably, to Allah belongs whatever is in the heavens and the earth. Unquestionably, the promise of Allah is truth, but most of them do not know' },
  { surahId: 10, ayahNumber: 56, text: 'He gives life and causes death, and to Him you will be returned' },
  { surahId: 10, ayahNumber: 57, text: 'O mankind, there has to come to you instruction from your Lord and healing for what is in the breasts and guidance and mercy for the believers.' },
  { surahId: 10, ayahNumber: 58, text: 'Say, "In the bounty of Allah and in His mercy - in that let them rejoice; it is better than what they accumulate."' },
  { surahId: 10, ayahNumber: 59, text: 'Say, "Have you seen what Allah has sent down to you of provision of which you have made [some] lawful and [some] unlawful?" Say, "Has Allah permitted you [to do so], or do you invent [something] about Allah?"' },
  { surahId: 10, ayahNumber: 60, text: 'And what will be the supposition of those who invent falsehood about Allah on the Day of Resurrection? Indeed, Allah is full of bounty to the people, but most of them are not grateful."' },
  { surahId: 10, ayahNumber: 61, text: 'And, [O Muhammad], you are not [engaged] in any matter or recite any of the Qur\'an and you [people] do not do any deed except that We are witness over you when you are involved in it. And not absent from your Lord is any [part] of an atom\'s weight within the earth or within the heaven or [anything] smaller than that or greater but that it is in a clear register.' },
  { surahId: 10, ayahNumber: 62, text: 'Unquestionably, [for] the allies of Allah there will be no fear concerning them, nor will they grieve' },
  { surahId: 10, ayahNumber: 63, text: 'Those who believed and were fearing Allah' },
  { surahId: 10, ayahNumber: 64, text: 'For them are good tidings in the worldly life and in the Hereafter. No change is there in the words of Allah. That is what is the great attainment.' },
  { surahId: 10, ayahNumber: 65, text: 'And let not their speech grieve you. Indeed, honor [due to power] belongs to Allah entirely. He is the Hearing, the Knowing.' },
  { surahId: 10, ayahNumber: 66, text: 'Unquestionably, to Allah belongs whoever is in the heavens and whoever is on the earth. And those who invoke other than Allah do not [actually] follow [His] "partners." They follow not except assumption, and they are not but falsifying' },
  { surahId: 10, ayahNumber: 67, text: 'It is He who made for you the night to rest therein and the day, giving sight. Indeed in that are signs for a people who listen.' },
  { surahId: 10, ayahNumber: 68, text: 'They have said, "Allah has taken a son." Exalted is He; He is the [one] Free of need. To Him belongs whatever is in the heavens and whatever is in the earth. You have no authority for this [claim]. Do you say about Allah that which you do not know?' },
  { surahId: 10, ayahNumber: 69, text: 'Say, "Indeed, those who invent falsehood about Allah will not succeed."' },
  { surahId: 10, ayahNumber: 70, text: '[For them is brief] enjoyment in this world; then to Us is their return; then We will make them taste the severe punishment because they used to disbelieve' },
  { surahId: 10, ayahNumber: 71, text: 'And recite to them the news of Noah, when he said to his people, "O my people, if my residence and my reminding of the signs of Allah has become burdensome upon you - then I have relied upon Allah. So resolve upon your plan and [call upon] your associates. Then let not your plan be obscure to you. Then carry it out upon me and do not give me respite.' },
  { surahId: 10, ayahNumber: 72, text: 'And if you turn away [from my advice] then no payment have I asked of you. My reward is only from Allah, and I have been commanded to be of the Muslims."' },
  { surahId: 10, ayahNumber: 73, text: 'And they denied him, so We saved him and those with him in the ship and made them successors, and We drowned those who denied Our signs. Then see how was the end of those who were warned.' },
  { surahId: 10, ayahNumber: 74, text: 'Then We sent after him messengers to their peoples, and they came to them with clear proofs. But they were not to believe in that which they had denied before. Thus We seal over the hearts of the transgressors' },
  { surahId: 10, ayahNumber: 75, text: 'Then We sent after them Moses and Aaron to Pharaoh and his establishment with Our signs, but they behaved arrogantly and were a criminal people' },
  { surahId: 10, ayahNumber: 76, text: 'So when there came to them the truth from Us, they said, "Indeed, this is obvious magic."' },
  { surahId: 10, ayahNumber: 77, text: 'Moses said, "Do you say [thus] about the truth when it has come to you? Is this magic? But magicians will not succeed."' },
  { surahId: 10, ayahNumber: 78, text: 'They said, "Have you come to us to turn us away from that upon which we found our fathers and so that you two may have grandeur in the land? And we are not believers in you."' },
  { surahId: 10, ayahNumber: 79, text: 'And Pharaoh said, "Bring to me every learned magician."' },
  { surahId: 10, ayahNumber: 80, text: 'So when the magicians came, Moses said to them, "Throw down whatever you will throw."' },
  { surahId: 10, ayahNumber: 81, text: 'And when they had thrown, Moses said, "What you have brought is [only] magic. Indeed, Allah will expose its worthlessness. Indeed, Allah does not amend the work of corrupters.' },
  { surahId: 10, ayahNumber: 82, text: 'And Allah will establish the truth by His words, even if the criminals dislike it."' },
  { surahId: 10, ayahNumber: 83, text: 'But no one believed Moses, except [some] youths among his people, for fear of Pharaoh and his establishment that they would persecute them. And indeed, Pharaoh was haughty within the land, and indeed, he was of the transgressors' },
  { surahId: 10, ayahNumber: 84, text: 'And Moses said, "O my people, if you have believed in Allah, then rely upon Him, if you should be Muslims."' },
  { surahId: 10, ayahNumber: 85, text: 'So they said, "Upon Allah do we rely. Our Lord, make us not [objects of] trial for the wrongdoing people' },
  { surahId: 10, ayahNumber: 86, text: 'And save us by Your mercy from the disbelieving people."' },
  { surahId: 10, ayahNumber: 87, text: 'And We inspired to Moses and his brother, "Settle your people in Egypt in houses and make your houses [facing the] qiblah and establish prayer and give good tidings to the believers."' },
  { surahId: 10, ayahNumber: 88, text: 'And Moses said, "Our Lord, indeed You have given Pharaoh and his establishment splendor and wealth in the worldly life, our Lord, that they may lead [men] astray from Your way. Our Lord, obliterate their wealth and harden their hearts so that they will not believe until they see the painful punishment."' },
  { surahId: 10, ayahNumber: 89, text: '[Allah] said, "Your supplication has been answered." So remain on a right course and follow not the way of those who do not know."' },
  { surahId: 10, ayahNumber: 90, text: 'And We took the Children of Israel across the sea, and Pharaoh and his soldiers pursued them in tyranny and enmity until, when drowning overtook him, he said, "I believe that there is no deity except that in whom the Children of Israel believe, and I am of the Muslims."' },
  { surahId: 10, ayahNumber: 91, text: 'Now? And you had disobeyed [Him] before and were of the corrupters?' },
  { surahId: 10, ayahNumber: 92, text: 'So today We will save you in body that you may be to those who succeed you a sign. And indeed, many among the people, of Our signs, are heedless' },
  { surahId: 10, ayahNumber: 93, text: 'And We had certainty settled the Children of Israel in an agreeable settlement and provided them with good things. And they did not differ until [after] knowledge had come to them. Indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ' },
  { surahId: 10, ayahNumber: 94, text: 'So if you are in doubt, [O Muhammad], about that which We have revealed to you, then ask those who have been reading the Scripture before you. The truth has certainly come to you from your Lord, so never be among the doubters.' },
  { surahId: 10, ayahNumber: 95, text: 'And never be of those who deny the signs of Allah and [thus] be among the losers.' },
  { surahId: 10, ayahNumber: 96, text: 'Indeed, those upon whom the word of your Lord has come into effect will not believe,' },
  { surahId: 10, ayahNumber: 97, text: 'Even if every sign should come to them, until they see the painful punishment.' },
  { surahId: 10, ayahNumber: 98, text: 'Then has there not been a [single] city that believed so its faith benefited it except the people of Jonah? When they believed, We removed from them the punishment of disgrace in worldly life and gave them enjoyment for a time.' },
  { surahId: 10, ayahNumber: 99, text: 'And had your Lord willed, those on earth would have believed - all of them entirely. Then, [O Muhammad], would you compel the people in order that they become believers?' },
  { surahId: 10, ayahNumber: 100, text: 'And it is not for a soul to believe except by permission of Allah, and He will place defilement upon those who will not use reason.' },
  { surahId: 10, ayahNumber: 101, text: 'Say, "Observe what is in the heavens and earth." But of no avail will be signs or warners to a people who do not believe' },
  { surahId: 10, ayahNumber: 102, text: 'So do they wait except for like [what occurred in] the days of those who passed on before them? Say, "Then wait; indeed, I am with you among those who wait."' },
  { surahId: 10, ayahNumber: 103, text: 'Then We will save our messengers and those who have believed. Thus, it is an obligation upon Us that We save the believers' },
  { surahId: 10, ayahNumber: 104, text: 'Say, [O Muhammad], "O people, if you are in doubt as to my religion - then I do not worship those which you worship besides Allah; but I worship Allah, who causes your death. And I have been commanded to be of the believers' },
  { surahId: 10, ayahNumber: 105, text: 'And [commanded], \'Direct your face toward the religion, inclining to truth, and never be of those who associate others with Allah;' },
  { surahId: 10, ayahNumber: 106, text: 'And do not invoke besides Allah that which neither benefits you nor harms you, for if you did, then indeed you would be of the wrongdoers.\'"' },
  { surahId: 10, ayahNumber: 107, text: 'And if Allah should touch you with adversity, there is no remover of it except Him; and if He intends for you good, then there is no repeller of His bounty. He causes it to reach whom He wills of His servants. And He is the Forgiving, the Merciful' },
  { surahId: 10, ayahNumber: 108, text: 'Say, "O mankind, the truth has come to you from your Lord, so whoever is guided is only guided for [the benefit of] his soul, and whoever goes astray only goes astray [in violation] against it. And I am not over you a manager."' },
  { surahId: 10, ayahNumber: 109, text: 'And follow what is revealed to you, [O Muhammad], and be patient until Allah will judge. And He is the best of judges.' },
  { surahId: 11, ayahNumber: 1, text: 'Alif, Lam, Ra. [This is] a Book whose verses are perfected and then presented in detail from [one who is] Wise and Acquainted.' },
  { surahId: 11, ayahNumber: 2, text: '[Through a messenger, saying], "Do not worship except Allah. Indeed, I am to you from Him a warner and a bringer of good tidings,"' },
  { surahId: 11, ayahNumber: 3, text: 'And [saying], "Seek forgiveness of your Lord and repent to Him, [and] He will let you enjoy a good provision for a specified term and give every doer of favor his favor. But if you turn away, then indeed, I fear for you the punishment of a great Day.' },
  { surahId: 11, ayahNumber: 4, text: 'To Allah is your return, and He is over all things competent."' },
  { surahId: 11, ayahNumber: 5, text: 'Unquestionably, they the disbelievers turn away their breasts to hide themselves from Him. Unquestionably, [even] when they cover themselves in their clothing, Allah knows what they conceal and what they declare. Indeed, He is Knowing of that within the breasts.' },
  { surahId: 11, ayahNumber: 6, text: 'And there is no creature on earth but that upon Allah is its provision, and He knows its place of dwelling and place of storage. All is in a clear register.' },
  { surahId: 11, ayahNumber: 7, text: 'And it is He who created the heavens and the earth in six days - and His Throne had been upon water - that He might test you as to which of you is best in deed. But if you say, "Indeed, you are resurrected after death," those who disbelieve will surely say, "This is not but obvious magic."' },
  { surahId: 11, ayahNumber: 8, text: 'And if We hold back from them the punishment for a limited time, they will surely say, "What detains it?" Unquestionably, on the Day it comes to them, it will not be averted from them, and they will be enveloped by what they used to ridicule.' },
  { surahId: 11, ayahNumber: 9, text: 'And if We give man a taste of mercy from Us and then We withdraw it from him, indeed, he is despairing and ungrateful.' },
  { surahId: 11, ayahNumber: 10, text: 'But if We give him a taste of favor after hardship has touched him, he will surely say, "Bad times have left me." Indeed, he is exultant and boastful -' },
  { surahId: 11, ayahNumber: 11, text: 'Except for those who are patient and do righteous deeds; those will have forgiveness and great reward.' },
  { surahId: 11, ayahNumber: 12, text: 'Then would you possibly leave [out] some of what is revealed to you, or is your breast constrained by it because they say, "Why has there not been sent down to him a treasure or come with him an angel?" But you are only a warner. And Allah is Disposer of all things.' },
  { surahId: 11, ayahNumber: 13, text: 'Or do they say, "He invented it"? Say, "Then bring ten surahs like it that have been invented and call upon [for assistance] whomever you can besides Allah, if you should be truthful."' },
  { surahId: 11, ayahNumber: 14, text: 'And if they do not respond to you - then know that the Qur\'an was revealed with the knowledge of Allah and that there is no deity except Him. Then, would you [not] be Muslims?' },
  { surahId: 11, ayahNumber: 15, text: 'Whoever desires the life of this world and its adornments - We fully repay them for their deeds therein, and they therein will not be deprived.' },
  { surahId: 11, ayahNumber: 16, text: 'Those are the ones for whom there is not in the Hereafter but the Fire. And lost is what they did therein, and worthless is what they used to do.' },
  { surahId: 11, ayahNumber: 17, text: 'So is one who [stands] upon a clear evidence from his Lord [like the aforementioned]? And a witness from Him follows it, and before it was the Scripture of Moses to lead and as mercy. Those [believers in the former revelations] believe in the Qur\'an. But whoever disbelieves in it from the [various] factions - the Fire is his promised destination. So be not in doubt about it. Indeed, it is the truth from your Lord, but most of the people do not believe.' },
  { surahId: 11, ayahNumber: 18, text: 'And who is more unjust than he who invents a lie about Allah? Those will be presented before their Lord, and the witnesses will say, "These are the ones who lied against their Lord." Unquestionably, the curse of Allah is upon the wrongdoers.' },
  { surahId: 11, ayahNumber: 19, text: 'Who averted [people] from the way of Allah and sought to make it [seem] deviant while they, concerning the Hereafter, were disbelievers.' },
  { surahId: 11, ayahNumber: 20, text: 'Those were not causing failure [to Allah] on earth, nor did they have besides Allah any protectors. For them the punishment will be multiplied. They were not able to hear, nor did they see.' },
  { surahId: 11, ayahNumber: 21, text: 'Those are the ones who will have lost themselves, and lost from them is what they used to invent.' },
  { surahId: 11, ayahNumber: 22, text: 'Assuredly, it is they in the Hereafter who will be the greatest losers.' },
  { surahId: 11, ayahNumber: 23, text: 'Indeed, they who have believed and done righteous deeds and humbled themselves to their Lord - those are the companions of Paradise; they will abide eternally therein.' },
  { surahId: 11, ayahNumber: 24, text: 'The example of the two parties is like the blind and deaf, and the seeing and hearing. Are they equal in comparison? Then, will you not remember?' },
  { surahId: 11, ayahNumber: 25, text: 'And We had certainly sent Noah to his people, [saying], "Indeed, I am to you a clear warner' },
  { surahId: 11, ayahNumber: 26, text: 'That you not worship except Allah. Indeed, I fear for you the punishment of a painful day."' },
  { surahId: 11, ayahNumber: 27, text: 'So the eminent among those who disbelieved from his people said, "We do not see you but as a man like ourselves, and we do not see you followed except by those who are the lowest of us [and] at first suggestion. And we do not see in you over us any merit; rather, we think you are liars."' },
  { surahId: 11, ayahNumber: 28, text: 'He said, "O my people have you considered: if I should be upon clear evidence from my Lord while He has given me mercy from Himself but it has been made unapparent to you, should we force it upon you while you are averse to it?' },
  { surahId: 11, ayahNumber: 29, text: 'And O my people, I ask not of you for it any wealth. My reward is not but from Allah. And I am not one to drive away those who have believed. Indeed, they will meet their Lord, but I see that you are a people behaving ignorantly.' },
  { surahId: 11, ayahNumber: 30, text: 'And O my people, who would protect me from Allah if I drove them away? Then will you not be reminded?' },
  { surahId: 11, ayahNumber: 31, text: 'And I do not tell you that I have the depositories [containing the provision] of Allah or that I know the unseen, nor do I tell you that I am an angel, nor do I say of those upon whom your eyes look down that Allah will never grant them any good. Allah is most knowing of what is within their souls. Indeed, I would then be among the wrongdoers."' },
  { surahId: 11, ayahNumber: 32, text: 'They said, "O Noah, you have disputed us and been frequent in dispute of us. So bring us what you threaten us, if you should be of the truthful."' },
  { surahId: 11, ayahNumber: 33, text: 'He said, "Allah will only bring it to you if He wills, and you will not cause [Him] failure.' },
  { surahId: 11, ayahNumber: 34, text: 'And my advice will not benefit you - although I wished to advise you - If Allah should intend to put you in error. He is your Lord, and to Him you will be returned."' },
  { surahId: 11, ayahNumber: 35, text: 'Or do they say [about Prophet Muhammad], "He invented it"? Say, "If I have invented it, then upon me is [the consequence of] my crime; but I am innocent of what [crimes] you commit."' },
  { surahId: 11, ayahNumber: 36, text: 'And it was revealed to Noah that, "No one will believe from your people except those who have already believed, so do not be distressed by what they have been doing.' },
  { surahId: 11, ayahNumber: 37, text: 'And construct the ship under Our observation and Our inspiration and do not address Me concerning those who have wronged; indeed, they are [to be] drowned."' },
  { surahId: 11, ayahNumber: 38, text: 'And he constructed the ship, and whenever an assembly of the eminent of his people passed by him, they ridiculed him. He said, "If you ridicule us, then we will ridicule you just as you ridicule.' },
  { surahId: 11, ayahNumber: 39, text: 'And you are going to know who will get a punishment that will disgrace him [on earth] and upon whom will descend an enduring punishment [in the Hereafter]."' },
  { surahId: 11, ayahNumber: 40, text: '[So it was], until when Our command came and the oven overflowed, We said, "Load upon the ship of each [creature] two mates and your family, except those about whom the word has preceded, and [include] whoever has believed." But none had believed with him, except a few.' },
  { surahId: 11, ayahNumber: 41, text: 'And [Noah] said, "Embark therein; in the name of Allah is its course and its anchorage. Indeed, my Lord is Forgiving and Merciful."' },
  { surahId: 11, ayahNumber: 42, text: 'And it sailed with them through waves like mountains, and Noah called to his son who was apart [from them], "O my son, come aboard with us and be not with the disbelievers."' },
  { surahId: 11, ayahNumber: 43, text: '[But] he said, "I will take refuge on a mountain to protect me from the water." [Noah] said, "There is no protector today from the decree of Allah, except for whom He gives mercy." And the waves came between them, and he was among the drowned.' },
  { surahId: 11, ayahNumber: 44, text: 'And it was said, "O earth, swallow your water, and O sky, withhold [your rain]." And the water subsided, and the matter was accomplished, and the ship came to rest on the [mountain of] Judiyy. And it was said, "Away with the wrongdoing people."' },
  { surahId: 11, ayahNumber: 45, text: 'And Noah called to his Lord and said, "My Lord, indeed my son is of my family; and indeed, Your promise is true; and You are the most just of judges!"' },
  { surahId: 11, ayahNumber: 46, text: 'He said, "O Noah, indeed he is not of your family; indeed, he is [one whose] work was other than righteous, so ask Me not for that about which you have no knowledge. Indeed, I advise you, lest you be among the ignorant."' },
  { surahId: 11, ayahNumber: 47, text: '[Noah] said, "My Lord, I seek refuge in You from asking that of which I have no knowledge. And unless You forgive me and have mercy upon me, I will be among the losers."' },
  { surahId: 11, ayahNumber: 48, text: 'It was said, "O Noah, disembark in security from Us and blessings upon you and upon nations [descending] from those with you. But other nations [of them] We will grant enjoyment; then there will touch them from Us a painful punishment."' },
  { surahId: 11, ayahNumber: 49, text: 'That is from the news of the unseen which We reveal to you, [O Muhammad]. You knew it not, neither you nor your people, before this. So be patient; indeed, the [best] outcome is for the righteous.' },
  { surahId: 11, ayahNumber: 50, text: 'And to \'Aad [We sent] their brother Hud. He said, "O my people, worship Allah; you have no deity other than Him. You are not but inventors [of falsehood].' },
  { surahId: 11, ayahNumber: 51, text: 'O my people, I do not ask you for it any reward. My reward is only from the one who created me. Then will you not reason?' },
  { surahId: 11, ayahNumber: 52, text: 'And O my people, ask forgiveness of your Lord and then repent to Him. He will send [rain from] the sky upon you in showers and increase you in strength [added] to your strength. And do not turn away, [being] criminals."' },
  { surahId: 11, ayahNumber: 53, text: 'They said, "O Hud, you have not brought us clear evidence, and we are not ones to leave our gods on your say-so. Nor are we believers in you.' },
  { surahId: 11, ayahNumber: 54, text: 'We only say that some of our gods have possessed you with evil." He said, "Indeed, I call Allah to witness, and witness [yourselves] that I am free from whatever you associate with Allah' },
  { surahId: 11, ayahNumber: 55, text: 'Other than Him. So plot against me all together; then do not give me respite.' },
  { surahId: 11, ayahNumber: 56, text: 'Indeed, I have relied upon Allah, my Lord and your Lord. There is no creature but that He holds its forelock. Indeed, my Lord is on a path [that is] straight."' },
  { surahId: 11, ayahNumber: 57, text: 'But if they turn away, [say], "I have already conveyed that with which I was sent to you. My Lord will give succession to a people other than you, and you will not harm Him at all. Indeed my Lord is, over all things, Guardian."' },
  { surahId: 11, ayahNumber: 58, text: 'And when Our command came, We saved Hud and those who believed with him, by mercy from Us; and We saved them from a harsh punishment.' },
  { surahId: 11, ayahNumber: 59, text: 'And that was \'Aad, who rejected the signs of their Lord and disobeyed His messengers and followed the order of every obstinate tyrant.' },
  { surahId: 11, ayahNumber: 60, text: 'And they were [therefore] followed in this world with a curse and [as well] on the Day of Resurrection. Unquestionably, \'Aad denied their Lord; then away with \'Aad, the people of Hud.' },
  { surahId: 11, ayahNumber: 61, text: 'And to Thamud [We sent] their brother Salih. He said, "O my people, worship Allah; you have no deity other than Him. He has produced you from the earth and settled you in it, so ask forgiveness of Him and then repent to Him. Indeed, my Lord is near and responsive."' },
  { surahId: 11, ayahNumber: 62, text: 'They said, "O Salih, you were among us a man of promise before this. Do you forbid us to worship what our fathers worshipped? And indeed we are, about that to which you invite us, in disquieting doubt."' },
  { surahId: 11, ayahNumber: 63, text: 'He said, "O my people, have you considered: if I should be upon clear evidence from my Lord and He has given me mercy from Himself, who would protect me from Allah if I disobeyed Him? So you would not increase me except in loss.' },
  { surahId: 11, ayahNumber: 64, text: 'And O my people, this is the she-camel of Allah - [she is] to you a sign. So let her feed upon Allah \'s earth and do not touch her with harm, or you will be taken by an impending punishment."' },
  { surahId: 11, ayahNumber: 65, text: 'But they hamstrung her, so he said, "Enjoy yourselves in your homes for three days. That is a promise not to be denied."' },
  { surahId: 11, ayahNumber: 66, text: 'So when Our command came, We saved Salih and those who believed with him, by mercy from Us, and [saved them] from the disgrace of that day. Indeed, it is your Lord who is the Powerful, the Exalted in Might.' },
  { surahId: 11, ayahNumber: 67, text: 'And the shriek seized those who had wronged, and they became within their homes [corpses] fallen prone' },
  { surahId: 11, ayahNumber: 68, text: 'As if they had never prospered therein. Unquestionably, Thamud denied their Lord; then, away with Thamud.' },
  { surahId: 11, ayahNumber: 69, text: 'And certainly did Our messengers come to Abraham with good tidings; they said, "Peace." He said, "Peace," and did not delay in bringing [them] a roasted calf.' },
  { surahId: 11, ayahNumber: 70, text: 'But when he saw their hands not reaching for it, he distrusted them and felt from them apprehension. They said, "Fear not. We have been sent to the people of Lot."' },
  { surahId: 11, ayahNumber: 71, text: 'And his Wife was standing, and she smiled. Then We gave her good tidings of Isaac and after Isaac, Jacob.' },
  { surahId: 11, ayahNumber: 72, text: 'She said, "Woe to me! Shall I give birth while I am an old woman and this, my husband, is an old man? Indeed, this is an amazing thing!"' },
  { surahId: 11, ayahNumber: 73, text: 'They said, "Are you amazed at the decree of Allah? May the mercy of Allah and His blessings be upon you, people of the house. Indeed, He is Praiseworthy and Honorable."' },
  { surahId: 11, ayahNumber: 74, text: 'And when the fright had left Abraham and the good tidings had reached him, he began to argue with Us concerning the people of Lot.' },
  { surahId: 11, ayahNumber: 75, text: 'Indeed, Abraham was forbearing, grieving and [frequently] returning [to Allah].' },
  { surahId: 11, ayahNumber: 76, text: '[The angels said], "O Abraham, give up this [plea]. Indeed, the command of your Lord has come, and indeed, there will reach them a punishment that cannot be repelled."' },
  { surahId: 11, ayahNumber: 77, text: 'And when Our messengers, [the angels], came to Lot, he was anguished for them and felt for them great discomfort and said, "This is a trying day."' },
  { surahId: 11, ayahNumber: 78, text: 'And his people came hastening to him, and before [this] they had been doing evil deeds. He said, "O my people, these are my daughters; they are purer for you. So fear Allah and do not disgrace me concerning my guests. Is there not among you a man of reason?"' },
  { surahId: 11, ayahNumber: 79, text: 'They said, "You have already known that we have not concerning your daughters any claim, and indeed, you know what we want."' },
  { surahId: 11, ayahNumber: 80, text: 'He said, "If only I had against you some power or could take refuge in a strong support."' },
  { surahId: 11, ayahNumber: 81, text: 'The angels said, "O Lot, indeed we are messengers of your Lord; [therefore], they will never reach you. So set out with your family during a portion of the night and let not any among you look back - except your wife; indeed, she will be struck by that which strikes them. Indeed, their appointment is [for] the morning. Is not the morning near?"' },
  { surahId: 11, ayahNumber: 82, text: 'So when Our command came, We made the highest part [of the city] its lowest and rained upon them stones of layered hard clay, [which were]' },
  { surahId: 11, ayahNumber: 83, text: 'Marked from your Lord. And Allah \'s punishment is not from the wrongdoers [very] far.' },
  { surahId: 11, ayahNumber: 84, text: 'And to Madyan [We sent] their brother Shu\'ayb. He said, "O my people, worship Allah; you have no deity other than Him. And do not decrease from the measure and the scale. Indeed, I see you in prosperity, but indeed, I fear for you the punishment of an all-encompassing Day.' },
  { surahId: 11, ayahNumber: 85, text: 'And O my people, give full measure and weight in justice and do not deprive the people of their due and do not commit abuse on the earth, spreading corruption.' },
  { surahId: 11, ayahNumber: 86, text: 'What remains [lawful] from Allah is best for you, if you would be believers. But I am not a guardian over you."' },
  { surahId: 11, ayahNumber: 87, text: 'They said, "O Shu\'ayb, does your prayer command you that we should leave what our fathers worship or not do with our wealth what we please? Indeed, you are the forbearing, the discerning!"' },
  { surahId: 11, ayahNumber: 88, text: 'He said, "O my people, have you considered: if I am upon clear evidence from my Lord and He has provided me with a good provision from Him...? And I do not intend to differ from you in that which I have forbidden you; I only intend reform as much as I am able. And my success is not but through Allah. Upon him I have relied, and to Him I return.' },
  { surahId: 11, ayahNumber: 89, text: 'And O my people, let not [your] dissension from me cause you to be struck by that similar to what struck the people of Noah or the people of Hud or the people of Salih. And the people of Lot are not from you far away.' },
  { surahId: 11, ayahNumber: 90, text: 'And ask forgiveness of your Lord and then repent to Him. Indeed, my Lord is Merciful and Affectionate."' },
  { surahId: 11, ayahNumber: 91, text: 'They said, "O Shu\'ayb, we do not understand much of what you say, and indeed, we consider you among us as weak. And if not for your family, we would have stoned you [to death]; and you are not to us one respected."' },
  { surahId: 11, ayahNumber: 92, text: 'He said, "O my people, is my family more respected for power by you than Allah? But you put Him behind your backs [in neglect]. Indeed, my Lord is encompassing of what you do.' },
  { surahId: 11, ayahNumber: 93, text: 'And O my people, work according to your position; indeed, I am working. You are going to know to whom will come a punishment that will disgrace him and who is a liar. So watch; indeed, I am with you a watcher, [awaiting the outcome]."' },
  { surahId: 11, ayahNumber: 94, text: 'And when Our command came, We saved Shu\'ayb and those who believed with him, by mercy from Us. And the shriek seized those who had wronged, and they became within their homes [corpses] fallen prone' },
  { surahId: 11, ayahNumber: 95, text: 'As if they had never prospered therein. Then, away with Madyan as Thamud was taken away.' },
  { surahId: 11, ayahNumber: 96, text: 'And We did certainly send Moses with Our signs and a clear authority' },
  { surahId: 11, ayahNumber: 97, text: 'To Pharaoh and his establishment, but they followed the command of Pharaoh, and the command of Pharaoh was not [at all] discerning.' },
  { surahId: 11, ayahNumber: 98, text: 'He will precede his people on the Day of Resurrection and lead them into the Fire; and wretched is the place to which they are led.' },
  { surahId: 11, ayahNumber: 99, text: 'And they were followed in this [world] with a curse and on the Day of Resurrection. And wretched is the gift which is given.' },
  { surahId: 11, ayahNumber: 100, text: 'That is from the news of the cities, which We relate to you; of them, some are [still] standing and some are [as] a harvest [mowed down].' },
  { surahId: 11, ayahNumber: 101, text: 'And We did not wrong them, but they wronged themselves. And they were not availed at all by their gods which they invoked other than Allah when there came the command of your Lord. And they did not increase them in other than ruin.' },
  { surahId: 11, ayahNumber: 102, text: 'And thus is the seizure of your Lord when He seizes the cities while they are committing wrong. Indeed, His seizure is painful and severe.' },
  { surahId: 11, ayahNumber: 103, text: 'Indeed in that is a sign for those who fear the punishment of the Hereafter. That is a Day for which the people will be collected, and that is a Day [which will be] witnessed.' },
  { surahId: 11, ayahNumber: 104, text: 'And We do not delay it except for a limited term.' },
  { surahId: 11, ayahNumber: 105, text: 'The Day it comes no soul will speak except by His permission. And among them will be the wretched and the prosperous.' },
  { surahId: 11, ayahNumber: 106, text: 'As for those who were [destined to be] wretched, they will be in the Fire. For them therein is [violent] exhaling and inhaling.' },
  { surahId: 11, ayahNumber: 107, text: '[They will be] abiding therein as long as the heavens and the earth endure, except what your Lord should will. Indeed, your Lord is an effecter of what He intends.' },
  { surahId: 11, ayahNumber: 108, text: 'And as for those who were [destined to be] prosperous, they will be in Paradise, abiding therein as long as the heavens and the earth endure, except what your Lord should will - a bestowal uninterrupted.' },
  { surahId: 11, ayahNumber: 109, text: 'So do not be in doubt, [O Muhammad], as to what these [polytheists] are worshipping. They worship not except as their fathers worshipped before. And indeed, We will give them their share undiminished.' },
  { surahId: 11, ayahNumber: 110, text: 'And We had certainly given Moses the Scripture, but it came under disagreement. And if not for a word that preceded from your Lord, it would have been judged between them. And indeed they are, concerning the Qur\'an, in disquieting doubt.' },
  { surahId: 11, ayahNumber: 111, text: 'And indeed, each [of the believers and disbelievers] - your Lord will fully compensate them for their deeds. Indeed, He is Acquainted with what they do.' },
  { surahId: 11, ayahNumber: 112, text: 'So remain on a right course as you have been commanded, [you] and those who have turned back with you [to Allah], and do not transgress. Indeed, He is Seeing of what you do.' },
  { surahId: 11, ayahNumber: 113, text: 'And do not incline toward those who do wrong, lest you be touched by the Fire, and you would not have other than Allah any protectors; then you would not be helped.' },
  { surahId: 11, ayahNumber: 114, text: 'And establish prayer at the two ends of the day and at the approach of the night. Indeed, good deeds do away with misdeeds. That is a reminder for those who remember.' },
  { surahId: 11, ayahNumber: 115, text: 'And be patient, for indeed, Allah does not allow to be lost the reward of those who do good.' },
  { surahId: 11, ayahNumber: 116, text: 'So why were there not among the generations before you those of enduring discrimination forbidding corruption on earth - except a few of those We saved from among them? But those who wronged pursued what luxury they were given therein, and they were criminals.' },
  { surahId: 11, ayahNumber: 117, text: 'And your Lord would not have destroyed the cities unjustly while their people were reformers.' },
  { surahId: 11, ayahNumber: 118, text: 'And if your Lord had willed, He could have made mankind one community; but they will not cease to differ.' },
  { surahId: 11, ayahNumber: 119, text: 'Except whom your Lord has given mercy, and for that He created them. But the word of your Lord is to be fulfilled that, "I will surely fill Hell with jinn and men all together."' },
  { surahId: 11, ayahNumber: 120, text: 'And each [story] We relate to you from the news of the messengers is that by which We make firm your heart. And there has come to you, in this, the truth and an instruction and a reminder for the believers.' },
  { surahId: 11, ayahNumber: 121, text: 'And say to those who do not believe, "Work according to your position; indeed, we are working.' },
  { surahId: 11, ayahNumber: 122, text: 'And wait, indeed, we are waiting."' },
  { surahId: 11, ayahNumber: 123, text: 'And to Allah belong the unseen [aspects] of the heavens and the earth and to Him will be returned the matter, all of it, so worship Him and rely upon Him. And your Lord is not unaware of that which you do.' },
  { surahId: 12, ayahNumber: 1, text: 'Alif, Lam, Ra. These are the verses of the clear Book.' },
  { surahId: 12, ayahNumber: 2, text: 'Indeed, We have sent it down as an Arabic Qur\'an that you might understand.' },
  { surahId: 12, ayahNumber: 3, text: 'We relate to you, [O Muhammad], the best of stories in what We have revealed to you of this Qur\'an although you were, before it, among the unaware.' },
  { surahId: 12, ayahNumber: 4, text: '[Of these stories mention] when Joseph said to his father, "O my father, indeed I have seen [in a dream] eleven stars and the sun and the moon; I saw them prostrating to me."' },
  { surahId: 12, ayahNumber: 5, text: 'He said, "O my son, do not relate your vision to your brothers or they will contrive against you a plan. Indeed Satan, to man, is a manifest enemy.' },
  { surahId: 12, ayahNumber: 6, text: 'And thus will your Lord choose you and teach you the interpretation of narratives and complete His favor upon you and upon the family of Jacob, as He completed it upon your fathers before, Abraham and Isaac. Indeed, your Lord is Knowing and Wise."' },
  { surahId: 12, ayahNumber: 7, text: 'Certainly were there in Joseph and his brothers signs for those who ask,' },
  { surahId: 12, ayahNumber: 8, text: 'When they said, "Joseph and his brother are more beloved to our father than we, while we are a clan. Indeed, our father is in clear error.' },
  { surahId: 12, ayahNumber: 9, text: 'Kill Joseph or cast him out to [another] land; the countenance of your father will [then] be only for you, and you will be after that a righteous people."' },
  { surahId: 12, ayahNumber: 10, text: 'Said a speaker among them, "Do not kill Joseph but throw him into the bottom of the well; some travelers will pick him up - if you would do [something]."' },
  { surahId: 12, ayahNumber: 11, text: 'They said, "O our father, why do you not entrust us with Joseph while indeed, we are to him sincere counselors?' },
  { surahId: 12, ayahNumber: 12, text: 'Send him with us tomorrow that he may eat well and play. And indeed, we will be his guardians.' },
  { surahId: 12, ayahNumber: 13, text: '[Jacob] said, "Indeed, it saddens me that you should take him, and I fear that a wolf would eat him while you are of him unaware."' },
  { surahId: 12, ayahNumber: 14, text: 'They said, "If a wolf should eat him while we are a [strong] clan, indeed, we would then be losers."' },
  { surahId: 12, ayahNumber: 15, text: 'So when they took him [out] and agreed to put him into the bottom of the well... But We inspired to him, "You will surely inform them [someday] about this affair of theirs while they do not perceive [your identity]."' },
  { surahId: 12, ayahNumber: 16, text: 'And they came to their father at night, weeping.' },
  { surahId: 12, ayahNumber: 17, text: 'They said, "O our father, indeed we went racing each other and left Joseph with our possessions, and a wolf ate him. But you would not believe us, even if we were truthful."' },
  { surahId: 12, ayahNumber: 18, text: 'And they brought upon his shirt false blood. [Jacob] said, "Rather, your souls have enticed you to something, so patience is most fitting. And Allah is the one sought for help against that which you describe."' },
  { surahId: 12, ayahNumber: 19, text: 'And there came a company of travelers; then they sent their water drawer, and he let down his bucket. He said, "Good news! Here is a boy." And they concealed him, [taking him] as merchandise; and Allah was knowing of what they did.' },
  { surahId: 12, ayahNumber: 20, text: 'And they sold him for a reduced price - a few dirhams - and they were, concerning him, of those content with little.' },
  { surahId: 12, ayahNumber: 21, text: 'And the one from Egypt who bought him said to his wife, "Make his residence comfortable. Perhaps he will benefit us, or we will adopt him as a son." And thus, We established Joseph in the land that We might teach him the interpretation of events. And Allah is predominant over His affair, but most of the people do not know.' },
  { surahId: 12, ayahNumber: 22, text: 'And when Joseph reached maturity, We gave him judgment and knowledge. And thus We reward the doers of good.' },
  { surahId: 12, ayahNumber: 23, text: 'And she, in whose house he was, sought to seduce him. She closed the doors and said, "Come, you." He said, "[I seek] the refuge of Allah. Indeed, he is my master, who has made good my residence. Indeed, wrongdoers will not succeed."' },
  { surahId: 12, ayahNumber: 24, text: 'And she certainly determined [to seduce] him, and he would have inclined to her had he not seen the proof of his Lord. And thus [it was] that We should avert from him evil and immorality. Indeed, he was of Our chosen servants.' },
  { surahId: 12, ayahNumber: 25, text: 'And they both raced to the door, and she tore his shirt from the back, and they found her husband at the door. She said, "What is the recompense of one who intended evil for your wife but that he be imprisoned or a painful punishment?"' },
  { surahId: 12, ayahNumber: 26, text: '[Joseph] said, "It was she who sought to seduce me." And a witness from her family testified. "If his shirt is torn from the front, then she has told the truth, and he is of the liars.' },
  { surahId: 12, ayahNumber: 27, text: 'But if his shirt is torn from the back, then she has lied, and he is of the truthful."' },
  { surahId: 12, ayahNumber: 28, text: 'So when her husband saw his shirt torn from the back, he said, "Indeed, it is of the women\'s plan. Indeed, your plan is great.' },
  { surahId: 12, ayahNumber: 29, text: 'Joseph, ignore this. And, [my wife], ask forgiveness for your sin. Indeed, you were of the sinful."' },
  { surahId: 12, ayahNumber: 30, text: 'And women in the city said, "The wife of al-\'Azeez is seeking to seduce her slave boy; he has impassioned her with love. Indeed, we see her [to be] in clear error."' },
  { surahId: 12, ayahNumber: 31, text: 'So when she heard of their scheming, she sent for them and prepared for them a banquet and gave each one of them a knife and said [to Joseph], "Come out before them." And when they saw him, they greatly admired him and cut their hands and said, "Perfect is Allah! This is not a man; this is none but a noble angel."' },
  { surahId: 12, ayahNumber: 32, text: 'She said, "That is the one about whom you blamed me. And I certainly sought to seduce him, but he firmly refused; and if he will not do what I order him, he will surely be imprisoned and will be of those debased."' },
  { surahId: 12, ayahNumber: 33, text: 'He said, "My Lord, prison is more to my liking than that to which they invite me. And if You do not avert from me their plan, I might incline toward them and [thus] be of the ignorant."' },
  { surahId: 12, ayahNumber: 34, text: 'So his Lord responded to him and averted from him their plan. Indeed, He is the Hearing, the Knowing.' },
  { surahId: 12, ayahNumber: 35, text: 'Then it appeared to them after they had seen the signs that al-\'Azeez should surely imprison him for a time.' },
  { surahId: 12, ayahNumber: 36, text: 'And there entered the prison with him two young men. One of them said, "Indeed, I have seen myself [in a dream] pressing wine." The other said, "Indeed, I have seen myself carrying upon my head [some] bread, from which the birds were eating. Inform us of its interpretation; indeed, we see you to be of those who do good."' },
  { surahId: 12, ayahNumber: 37, text: 'He said, "You will not receive food that is provided to you except that I will inform you of its interpretation before it comes to you. That is from what my Lord has taught me. Indeed, I have left the religion of a people who do not believe in Allah, and they, in the Hereafter, are disbelievers.' },
  { surahId: 12, ayahNumber: 38, text: 'And I have followed the religion of my fathers, Abraham, Isaac and Jacob. And it was not for us to associate anything with Allah. That is from the favor of Allah upon us and upon the people, but most of the people are not grateful.' },
  { surahId: 12, ayahNumber: 39, text: 'O [my] two companions of prison, are separate lords better or Allah, the One, the Prevailing?' },
  { surahId: 12, ayahNumber: 40, text: 'You worship not besides Him except [mere] names you have named them, you and your fathers, for which Allah has sent down no authority. Legislation is not but for Allah. He has commanded that you worship not except Him. That is the correct religion, but most of the people do not know.' },
  { surahId: 12, ayahNumber: 41, text: 'O two companions of prison, as for one of you, he will give drink to his master of wine; but as for the other, he will be crucified, and the birds will eat from his head. The matter has been decreed about which you both inquire."' },
  { surahId: 12, ayahNumber: 42, text: 'And he said to the one whom he knew would go free, "Mention me before your master." But Satan made him forget the mention [to] his master, and Joseph remained in prison several years.' },
  { surahId: 12, ayahNumber: 43, text: 'And [subsequently] the king said, "Indeed, I have seen [in a dream] seven fat cows being eaten by seven [that were] lean, and seven green spikes [of grain] and others [that were] dry. O eminent ones, explain to me my vision, if you should interpret visions."' },
  { surahId: 12, ayahNumber: 44, text: 'They said, "[It is but] a mixture of false dreams, and we are not learned in the interpretation of dreams."' },
  { surahId: 12, ayahNumber: 45, text: 'But the one who was freed and remembered after a time said, "I will inform you of its interpretation, so send me forth."' },
  { surahId: 12, ayahNumber: 46, text: '[He said], "Joseph, O man of truth, explain to us about seven fat cows eaten by seven [that were] lean, and seven green spikes [of grain] and others [that were] dry - that I may return to the people; perhaps they will know [about you]."' },
  { surahId: 12, ayahNumber: 47, text: '[Joseph] said, "You will plant for seven years consecutively; and what you harvest leave in its spikes, except a little from which you will eat.' },
  { surahId: 12, ayahNumber: 48, text: 'Then will come after that seven difficult [years] which will consume what you saved for them, except a little from which you will store.' },
  { surahId: 12, ayahNumber: 49, text: 'Then will come after that a year in which the people will be given rain and in which they will press [olives and grapes]."' },
  { surahId: 12, ayahNumber: 50, text: 'And the king said, "Bring him to me." But when the messenger came to him, [Joseph] said, "Return to your master and ask him what is the case of the women who cut their hands. Indeed, my Lord is Knowing of their plan."' },
  { surahId: 12, ayahNumber: 51, text: 'Said [the king to the women], "What was your condition when you sought to seduce Joseph?" They said, "Perfect is Allah! We know about him no evil." The wife of al-\'Azeez said, "Now the truth has become evident. It was I who sought to seduce him, and indeed, he is of the truthful.' },
  { surahId: 12, ayahNumber: 52, text: 'That is so al-\'Azeez will know that I did not betray him in [his] absence and that Allah does not guide the plan of betrayers.' },
  { surahId: 12, ayahNumber: 53, text: 'And I do not acquit myself. Indeed, the soul is a persistent enjoiner of evil, except those upon which my Lord has mercy. Indeed, my Lord is Forgiving and Merciful."' },
  { surahId: 12, ayahNumber: 54, text: 'And the king said, "Bring him to me; I will appoint him exclusively for myself." And when he spoke to him, he said, "Indeed, you are today established [in position] and trusted."' },
  { surahId: 12, ayahNumber: 55, text: '[Joseph] said, "Appoint me over the storehouses of the land. Indeed, I will be a knowing guardian."' },
  { surahId: 12, ayahNumber: 56, text: 'And thus We established Joseph in the land to settle therein wherever he willed. We touch with Our mercy whom We will, and We do not allow to be lost the reward of those who do good.' },
  { surahId: 12, ayahNumber: 57, text: 'And the reward of the Hereafter is better for those who believed and were fearing Allah.' },
  { surahId: 12, ayahNumber: 58, text: 'And the brothers of Joseph came [seeking food], and they entered upon him; and he recognized them, but he was to them unknown.' },
  { surahId: 12, ayahNumber: 59, text: 'And when he had furnished them with their supplies, he said, "Bring me a brother of yours from your father. Do not you see that I give full measure and that I am the best of accommodators?' },
  { surahId: 12, ayahNumber: 60, text: 'But if you do not bring him to me, no measure will there be [hereafter] for you from me, nor will you approach me."' },
  { surahId: 12, ayahNumber: 61, text: 'They said, "We will attempt to dissuade his father from [keeping] him, and indeed, we will do [it]."' },
  { surahId: 12, ayahNumber: 62, text: 'And [Joseph] said to his servants, "Put their merchandise into their saddlebags so they might recognize it when they have gone back to their people that perhaps they will [again] return."' },
  { surahId: 12, ayahNumber: 63, text: 'So when they returned to their father, they said, "O our father, [further] measure has been denied to us, so send with us our brother [that] we will be given measure. And indeed, we will be his guardians."' },
  { surahId: 12, ayahNumber: 64, text: 'He said, "Should I entrust you with him except [under coercion] as I entrusted you with his brother before? But Allah is the best guardian, and He is the most merciful of the merciful."' },
  { surahId: 12, ayahNumber: 65, text: 'And when they opened their baggage, they found their merchandise returned to them. They said, "O our father, what [more] could we desire? This is our merchandise returned to us. And we will obtain supplies for our family and protect our brother and obtain an increase of a camel\'s load; that is an easy measurement."' },
  { surahId: 12, ayahNumber: 66, text: '[Jacob] said, "Never will I send him with you until you give me a promise by Allah that you will bring him [back] to me, unless you should be surrounded by enemies." And when they had given their promise, he said, "Allah, over what we say, is Witness."' },
  { surahId: 12, ayahNumber: 67, text: 'And he said, "O my sons, do not enter from one gate but enter from different gates; and I cannot avail you against [the decree of] Allah at all. The decision is only for Allah; upon Him I have relied, and upon Him let those who would rely [indeed] rely."' },
  { surahId: 12, ayahNumber: 68, text: 'And when they entered from where their father had ordered them, it did not avail them against Allah at all except [it was] a need within the soul of Jacob, which he satisfied. And indeed, he was a possessor of knowledge because of what We had taught him, but most of the people do not know.' },
  { surahId: 12, ayahNumber: 69, text: 'And when they entered upon Joseph, he took his brother to himself; he said, "Indeed, I am your brother, so do not despair over what they used to do [to me]."' },
  { surahId: 12, ayahNumber: 70, text: 'So when he had furnished them with their supplies, he put the [gold measuring] bowl into the bag of his brother. Then an announcer called out, "O caravan, indeed you are thieves."' },
  { surahId: 12, ayahNumber: 71, text: 'They said while approaching them, "What is it you are missing?"' },
  { surahId: 12, ayahNumber: 72, text: 'They said, "We are missing the measure of the king. And for he who produces it is [the reward of] a camel\'s load, and I am responsible for it."' },
  { surahId: 12, ayahNumber: 73, text: 'They said, "By Allah, you have certainly known that we did not come to cause corruption in the land, and we have not been thieves."' },
  { surahId: 12, ayahNumber: 74, text: 'The accusers said, "Then what would be its recompense if you should be liars?"' },
  { surahId: 12, ayahNumber: 75, text: '[The brothers] said, "Its recompense is that he in whose bag it is found - he [himself] will be its recompense. Thus do we recompense the wrongdoers."' },
  { surahId: 12, ayahNumber: 76, text: 'So he began [the search] with their bags before the bag of his brother; then he extracted it from the bag of his brother. Thus did We plan for Joseph. He could not have taken his brother within the religion of the king except that Allah willed. We raise in degrees whom We will, but over every possessor of knowledge is one [more] knowing.' },
  { surahId: 12, ayahNumber: 77, text: 'They said, "If he steals - a brother of his has stolen before." But Joseph kept it within himself and did not reveal it to them. He said, "You are worse in position, and Allah is most knowing of what you describe."' },
  { surahId: 12, ayahNumber: 78, text: 'They said, "O \'Azeez, indeed he has a father [who is] an old man, so take one of us in place of him. Indeed, we see you as a doer of good."' },
  { surahId: 12, ayahNumber: 79, text: 'He said, "[I seek] the refuge of Allah [to prevent] that we take except him with whom we found our possession. Indeed, we would then be unjust."' },
  { surahId: 12, ayahNumber: 80, text: 'So when they had despaired of him, they secluded themselves in private consultation. The eldest of them said, "Do you not know that your father has taken upon you an oath by Allah and [that] before you failed in [your duty to] Joseph? So I will never leave [this] land until my father permits me or Allah decides for me, and He is the best of judges.' },
  { surahId: 12, ayahNumber: 81, text: 'Return to your father and say, "O our father, indeed your son has stolen, and we did not testify except to what we knew. And we were not witnesses of the unseen,' },
  { surahId: 12, ayahNumber: 82, text: 'And ask the city in which we were and the caravan in which we came - and indeed, we are truthful,"' },
  { surahId: 12, ayahNumber: 83, text: '[Jacob] said, "Rather, your souls have enticed you to something, so patience is most fitting. Perhaps Allah will bring them to me all together. Indeed it is He who is the Knowing, the Wise."' },
  { surahId: 12, ayahNumber: 84, text: 'And he turned away from them and said, "Oh, my sorrow over Joseph," and his eyes became white from grief, for he was [of that] a suppressor.' },
  { surahId: 12, ayahNumber: 85, text: 'They said, "By Allah, you will not cease remembering Joseph until you become fatally ill or become of those who perish."' },
  { surahId: 12, ayahNumber: 86, text: 'He said, "I only complain of my suffering and my grief to Allah, and I know from Allah that which you do not know.' },
  { surahId: 12, ayahNumber: 87, text: 'O my sons, go and find out about Joseph and his brother and despair not of relief from Allah. Indeed, no one despairs of relief from Allah except the disbelieving people."' },
  { surahId: 12, ayahNumber: 88, text: 'So when they entered upon Joseph, they said, "O \'Azeez, adversity has touched us and our family, and we have come with goods poor in quality, but give us full measure and be charitable to us. Indeed, Allah rewards the charitable."' },
  { surahId: 12, ayahNumber: 89, text: 'He said, "Do you know what you did with Joseph and his brother when you were ignorant?"' },
  { surahId: 12, ayahNumber: 90, text: 'They said, "Are you indeed Joseph?" He said "I am Joseph, and this is my brother. Allah has certainly favored us. Indeed, he who fears Allah and is patient, then indeed, Allah does not allow to be lost the reward of those who do good."' },
  { surahId: 12, ayahNumber: 91, text: 'They said, "By Allah, certainly has Allah preferred you over us, and indeed, we have been sinners."' },
  { surahId: 12, ayahNumber: 92, text: 'He said, "No blame will there be upon you today. Allah will forgive you; and He is the most merciful of the merciful."' },
  { surahId: 12, ayahNumber: 93, text: 'Take this, my shirt, and cast it over the face of my father; he will become seeing. And bring me your family, all together."' },
  { surahId: 12, ayahNumber: 94, text: 'And when the caravan departed [from Egypt], their father said, "Indeed, I find the smell of Joseph [and would say that he was alive] if you did not think me weakened in mind."' },
  { surahId: 12, ayahNumber: 95, text: 'They said, "By Allah, indeed you are in your [same] old error."' },
  { surahId: 12, ayahNumber: 96, text: 'And when the bearer of good tidings arrived, he cast it over his face, and he returned [once again] seeing. He said, "Did I not tell you that I know from Allah that which you do not know?"' },
  { surahId: 12, ayahNumber: 97, text: 'They said, "O our father, ask for us forgiveness of our sins; indeed, we have been sinners."' },
  { surahId: 12, ayahNumber: 98, text: 'He said, "I will ask forgiveness for you from my Lord. Indeed, it is He who is the Forgiving, the Merciful."' },
  { surahId: 12, ayahNumber: 99, text: 'And when they entered upon Joseph, he took his parents to himself and said, "Enter Egypt, Allah willing, safe [and secure]."' },
  { surahId: 12, ayahNumber: 100, text: 'And he raised his parents upon the throne, and they bowed to him in prostration. And he said, "O my father, this is the explanation of my vision of before. My Lord has made it reality. And He was certainly good to me when He took me out of prison and brought you [here] from bedouin life after Satan had induced [estrangement] between me and my brothers. Indeed, my Lord is Subtle in what He wills. Indeed, it is He who is the Knowing, the Wise.' },
  { surahId: 12, ayahNumber: 101, text: 'My Lord, You have given me [something] of sovereignty and taught me of the interpretation of dreams. Creator of the heavens and earth, You are my protector in this world and in the Hereafter. Cause me to die a Muslim and join me with the righteous."' },
  { surahId: 12, ayahNumber: 102, text: 'That is from the news of the unseen which We reveal, [O Muhammad], to you. And you were not with them when they put together their plan while they conspired.' },
  { surahId: 12, ayahNumber: 103, text: 'And most of the people, although you strive [for it], are not believers.' },
  { surahId: 12, ayahNumber: 104, text: 'And you do not ask of them for it any payment. It is not except a reminder to the worlds.' },
  { surahId: 12, ayahNumber: 105, text: 'And how many a sign within the heavens and earth do they pass over while they, therefrom, are turning away.' },
  { surahId: 12, ayahNumber: 106, text: 'And most of them believe not in Allah except while they associate others with Him.' },
  { surahId: 12, ayahNumber: 107, text: 'Then do they feel secure that there will not come to them an overwhelming [aspect] of the punishment of Allah or that the Hour will not come upon them suddenly while they do not perceive?' },
  { surahId: 12, ayahNumber: 108, text: 'Say, "This is my way; I invite to Allah with insight, I and those who follow me. And exalted is Allah; and I am not of those who associate others with Him."' },
  { surahId: 12, ayahNumber: 109, text: 'And We sent not before you [as messengers] except men to whom We revealed from among the people of cities. So have they not traveled through the earth and observed how was the end of those before them? And the home of the Hereafter is best for those who fear Allah; then will you not reason?' },
  { surahId: 12, ayahNumber: 110, text: '[They continued] until, when the messengers despaired and were certain that they had been denied, there came to them Our victory, and whoever We willed was saved. And Our punishment cannot be repelled from the people who are criminals.' },
  { surahId: 12, ayahNumber: 111, text: 'There was certainly in their stories a lesson for those of understanding. Never was the Qur\'an a narration invented, but a confirmation of what was before it and a detailed explanation of all things and guidance and mercy for a people who believe.' },
  { surahId: 13, ayahNumber: 1, text: 'Alif, Lam, Meem, Ra. These are the verses of the Book; and what has been revealed to you from your Lord is the truth, but most of the people do not believe.' },
  { surahId: 13, ayahNumber: 2, text: 'It is Allah who erected the heavens without pillars that you [can] see; then He established Himself above the Throne and made subject the sun and the moon, each running [its course] for a specified term. He arranges [each] matter; He details the signs that you may, of the meeting with your Lord, be certain.' },
  { surahId: 13, ayahNumber: 3, text: 'And it is He who spread the earth and placed therein firmly set mountains and rivers; and from all of the fruits He made therein two mates; He causes the night to cover the day. Indeed in that are signs for a people who give thought.' },
  { surahId: 13, ayahNumber: 4, text: 'And within the land are neighboring plots and gardens of grapevines and crops and palm trees, [growing] several from a root or otherwise, watered with one water; but We make some of them exceed others in [quality of] fruit. Indeed in that are signs for a people who reason.' },
  { surahId: 13, ayahNumber: 5, text: 'And if you are astonished, [O Muhammad] - then astonishing is their saying, "When we are dust, will we indeed be [brought] into a new creation?" Those are the ones who have disbelieved in their Lord, and those will have shackles upon their necks, and those are the companions of the Fire; they will abide therein eternally.' },
  { surahId: 13, ayahNumber: 6, text: 'They impatiently urge you to bring about evil before good, while there has already occurred before them similar punishments [to what they demand]. And indeed, your Lord is full of forgiveness for the people despite their wrongdoing, and indeed, your Lord is severe in penalty.' },
  { surahId: 13, ayahNumber: 7, text: 'And those who disbelieved say, "Why has a sign not been sent down to him from his Lord?" You are only a warner, and for every people is a guide.' },
  { surahId: 13, ayahNumber: 8, text: 'Allah knows what every female carries and what the wombs lose [prematurely] or exceed. And everything with Him is by due measure.' },
  { surahId: 13, ayahNumber: 9, text: '[He is] Knower of the unseen and the witnessed, the Grand, the Exalted.' },
  { surahId: 13, ayahNumber: 10, text: 'It is the same [to Him] concerning you whether one conceals [his] speech or one publicizes it and whether one is hidden by night or conspicuous [among others] by day.' },
  { surahId: 13, ayahNumber: 11, text: 'For each one are successive [angels] before and behind him who protect him by the decree of Allah. Indeed, Allah will not change the condition of a people until they change what is in themselves. And when Allah intends for a people ill, there is no repelling it. And there is not for them besides Him any patron.' },
  { surahId: 13, ayahNumber: 12, text: 'It is He who shows you lightening, [causing] fear and aspiration, and generates the heavy clouds.' },
  { surahId: 13, ayahNumber: 13, text: 'And the thunder exalts [Allah] with praise of Him - and the angels [as well] from fear of Him - and He sends thunderbolts and strikes therewith whom He wills while they dispute about Allah; and He is severe in assault.' },
  { surahId: 13, ayahNumber: 14, text: 'To Him [alone] is the supplication of truth. And those they call upon besides Him do not respond to them with a thing, except as one who stretches his hands toward water [from afar, calling it] to reach his mouth, but it will not reach it [thus]. And the supplication of the disbelievers is not but in error [i.e. futility].' },
  { surahId: 13, ayahNumber: 15, text: 'And to Allah prostrates whoever is within the heavens and the earth, willingly or by compulsion, and their shadows [as well] in the mornings and the afternoons.' },
  { surahId: 13, ayahNumber: 16, text: 'Say, "Who is Lord of the heavens and earth?" Say, "Allah." Say, "Have you then taken besides Him allies not possessing [even] for themselves any benefit or any harm?" Say, "Is the blind equivalent to the seeing? Or is darkness equivalent to light? Or have they attributed to Allah partners who created like His creation so that the creation [of each] seemed similar to them?" Say, "Allah is the Creator of all things, and He is the One, the Prevailing."' },
  { surahId: 13, ayahNumber: 17, text: 'He sends down from the sky, rain, and valleys flow according to their capacity, and the torrent carries a rising foam. And from that [ore] which they heat in the fire, desiring adornments and utensils, is a foam like it. Thus Allah presents [the example of] truth and falsehood. As for the foam, it vanishes, [being] cast off; but as for that which benefits the people, it remains on the earth. Thus does Allah present examples.' },
  { surahId: 13, ayahNumber: 18, text: 'For those who have responded to their Lord is the best [reward], but those who did not respond to Him - if they had all that is in the earth entirely and the like of it with it, they would [attempt to] ransom themselves thereby. Those will have the worst account, and their refuge is Hell, and wretched is the resting place.' },
  { surahId: 13, ayahNumber: 19, text: 'Then is he who knows that what has been revealed to you from your Lord is the truth like one who is blind? They will only be reminded who are people of understanding -' },
  { surahId: 13, ayahNumber: 20, text: 'Those who fulfill the covenant of Allah and do not break the contract,' },
  { surahId: 13, ayahNumber: 21, text: 'And those who join that which Allah has ordered to be joined and fear their Lord and are afraid of the evil of [their] account,' },
  { surahId: 13, ayahNumber: 22, text: 'And those who are patient, seeking the countenance of their Lord, and establish prayer and spend from what We have provided for them secretly and publicly and prevent evil with good - those will have the good consequence of [this] home -' },
  { surahId: 13, ayahNumber: 23, text: 'Gardens of perpetual residence; they will enter them with whoever were righteous among their fathers, their spouses and their descendants. And the angels will enter upon them from every gate, [saying],' },
  { surahId: 13, ayahNumber: 24, text: '"Peace be upon you for what you patiently endured. And excellent is the final home."' },
  { surahId: 13, ayahNumber: 25, text: 'But those who break the covenant of Allah after contracting it and sever that which Allah has ordered to be joined and spread corruption on earth - for them is the curse, and they will have the worst home.' },
  { surahId: 13, ayahNumber: 26, text: 'Allah extends provision for whom He wills and restricts [it]. And they rejoice in the worldly life, while the worldly life is not, compared to the Hereafter, except [brief] enjoyment.' },
  { surahId: 13, ayahNumber: 27, text: 'And those who disbelieved say, "Why has a sign not been sent down to him from his Lord?" Say, [O Muhammad], "Indeed, Allah leaves astray whom He wills and guides to Himself whoever turns back [to Him] -' },
  { surahId: 13, ayahNumber: 28, text: 'Those who have believed and whose hearts are assured by the remembrance of Allah. Unquestionably, by the remembrance of Allah hearts are assured."' },
  { surahId: 13, ayahNumber: 29, text: 'Those who have believed and done righteous deeds - a good state is theirs and a good return.' },
  { surahId: 13, ayahNumber: 30, text: 'Thus have We sent you to a community before which [other] communities have passed on so you might recite to them that which We revealed to you, while they disbelieve in the Most Merciful. Say, "He is my Lord; there is no deity except Him. Upon Him I rely, and to Him is my return."' },
  { surahId: 13, ayahNumber: 31, text: 'And if there was any qur\'an by which the mountains would be removed or the earth would be broken apart or the dead would be made to speak, [it would be this Qur\'an], but to Allah belongs the affair entirely. Then have those who believed not accepted that had Allah willed, He would have guided the people, all of them? And those who disbelieve do not cease to be struck, for what they have done, by calamity - or it will descend near their home - until there comes the promise of Allah. Indeed, Allah does not fail in [His] promise.' },
  { surahId: 13, ayahNumber: 32, text: 'And already were [other] messengers ridiculed before you, and I extended the time of those who disbelieved; then I seized them, and how [terrible] was My penalty.' },
  { surahId: 13, ayahNumber: 33, text: 'Then is He who is a maintainer of every soul, [knowing] what it has earned, [like any other]? But to Allah they have attributed partners. Say, "Name them. Or do you inform Him of that which He knows not upon the earth or of what is apparent of speech?" Rather, their [own] plan has been made attractive to those who disbelieve, and they have been averted from the way. And whomever Allah leaves astray - there will be for him no guide.' },
  { surahId: 13, ayahNumber: 34, text: 'For them will be punishment in the life of [this] world, and the punishment of the Hereafter is more severe. And they will not have from Allah any protector.' },
  { surahId: 13, ayahNumber: 35, text: 'The example of Paradise, which the righteous have been promised, is [that] beneath it rivers flow. Its fruit is lasting, and its shade. That is the consequence for the righteous, and the consequence for the disbelievers is the Fire.' },
  { surahId: 13, ayahNumber: 36, text: 'And [the believers among] those to whom We have given the [previous] Scripture rejoice at what has been revealed to you, [O Muhammad], but among the [opposing] factions are those who deny part of it. Say, "I have only been commanded to worship Allah and not associate [anything] with Him. To Him I invite, and to Him is my return."' },
  { surahId: 13, ayahNumber: 37, text: 'And thus We have revealed it as an Arabic legislation. And if you should follow their inclinations after what has come to you of knowledge, you would not have against Allah any ally or any protector.' },
  { surahId: 13, ayahNumber: 38, text: 'And We have already sent messengers before you and assigned to them wives and descendants. And it was not for a messenger to come with a sign except by permission of Allah. For every term is a decree.' },
  { surahId: 13, ayahNumber: 39, text: 'Allah eliminates what He wills or confirms, and with Him is the Mother of the Book.' },
  { surahId: 13, ayahNumber: 40, text: 'And whether We show you part of what We promise them or take you in death, upon you is only the [duty of] notification, and upon Us is the account.' },
  { surahId: 13, ayahNumber: 41, text: 'Have they not seen that We set upon the land, reducing it from its borders? And Allah decides; there is no adjuster of His decision. And He is swift in account.' },
  { surahId: 13, ayahNumber: 42, text: 'And those before them had plotted, but to Allah belongs the plan entirely. He knows what every soul earns, and the disbelievers will know for whom is the final home.' },
  { surahId: 13, ayahNumber: 43, text: 'And those who have disbelieved say, "You are not a messenger." Say, [O Muhammad], "Sufficient is Allah as Witness between me and you, and [the witness of] whoever has knowledge of the Scripture."' },
  { surahId: 14, ayahNumber: 1, text: 'Alif, Lam, Ra. [This is] a Book which We have revealed to you, [O Muhammad], that you might bring mankind out of darknesses into the light by permission of their Lord - to the path of the Exalted in Might, the Praiseworthy -' },
  { surahId: 14, ayahNumber: 2, text: 'Allah, to whom belongs whatever is in the heavens and whatever is on the earth. And woe to the disbelievers from a severe punishment' },
  { surahId: 14, ayahNumber: 3, text: 'The ones who prefer the worldly life over the Hereafter and avert [people] from the way of Allah, seeking to make it (seem) deviant. Those are in extreme error.' },
  { surahId: 14, ayahNumber: 4, text: 'And We did not send any messenger except [speaking] in the language of his people to state clearly for them, and Allah sends astray [thereby] whom He wills and guides whom He wills. And He is the Exalted in Might, the Wise.' },
  { surahId: 14, ayahNumber: 5, text: 'And We certainly sent Moses with Our signs, [saying], "Bring out your people from darknesses into the light and remind them of the days of Allah." Indeed in that are signs for everyone patient and grateful.' },
  { surahId: 14, ayahNumber: 6, text: 'And [recall, O Children of Israel], when Moses said to His people, "Remember the favor of Allah upon you when He saved you from the people of Pharaoh, who were afflicting you with the worst torment and were slaughtering your [newborn] sons and keeping your females alive. And in that was a great trial from your Lord.' },
  { surahId: 14, ayahNumber: 7, text: 'And [remember] when your Lord proclaimed, \'If you are grateful, I will surely increase you [in favor]; but if you deny, indeed, My punishment is severe.\' "' },
  { surahId: 14, ayahNumber: 8, text: 'And Moses said, "If you should disbelieve, you and whoever is on the earth entirely - indeed, Allah is Free of need and Praiseworthy."' },
  { surahId: 14, ayahNumber: 9, text: 'Has there not reached you the news of those before you - the people of Noah and \'Aad and Thamud and those after them? No one knows them but Allah. Their messengers brought them clear proofs, but they returned their hands to their mouths and said, "Indeed, we disbelieve in that with which you have been sent, and indeed we are, about that to which you invite us, in disquieting doubt."' },
  { surahId: 14, ayahNumber: 10, text: 'Their messengers said, "Can there be doubt about Allah, Creator of the heavens and earth? He invites you that He may forgive you of your sins, and He delays your death for a specified term." They said, "You are not but men like us who wish to avert us from what our fathers were worshipping. So bring us a clear authority."' },
  { surahId: 14, ayahNumber: 11, text: 'Their messengers said to them, "We are only men like you, but Allah confers favor upon whom He wills of His servants. It has never been for us to bring you evidence except by permission of Allah. And upon Allah let the believers rely.' },
  { surahId: 14, ayahNumber: 12, text: 'And why should we not rely upon Allah while He has guided us to our [good] ways. And we will surely be patient against whatever harm you should cause us. And upon Allah let those who would rely [indeed] rely."' },
  { surahId: 14, ayahNumber: 13, text: 'And those who disbelieved said to their messengers, "We will surely drive you out of our land, or you must return to our religion." So their Lord inspired to them, "We will surely destroy the wrongdoers.' },
  { surahId: 14, ayahNumber: 14, text: 'And We will surely cause you to dwell in the land after them. That is for he who fears My position and fears My threat."' },
  { surahId: 14, ayahNumber: 15, text: 'And they requested victory from Allah, and disappointed, [therefore], was every obstinate tyrant.' },
  { surahId: 14, ayahNumber: 16, text: 'Before him is Hell, and he will be given a drink of purulent water.' },
  { surahId: 14, ayahNumber: 17, text: 'He will gulp it but will hardly [be able to] swallow it. And death will come to him from everywhere, but he is not to die. And before him is a massive punishment.' },
  { surahId: 14, ayahNumber: 18, text: 'The example of those who disbelieve in their Lord is [that] their deeds are like ashes which the wind blows forcefully on a stormy day; they are unable [to keep] from what they earned a [single] thing. That is what is extreme error.' },
  { surahId: 14, ayahNumber: 19, text: 'Have you not seen that Allah created the heavens and the earth in truth? If He wills, He can do away with you and produce a new creation.' },
  { surahId: 14, ayahNumber: 20, text: 'And that is not difficult for Allah.' },
  { surahId: 14, ayahNumber: 21, text: 'And they will come out [for judgement] before Allah all together, and the weak will say to those who were arrogant, "Indeed, we were your followers, so can you avail us anything against the punishment of Allah?" They will say, "If Allah had guided us, we would have guided you. It is all the same for us whether we show intolerance or are patient: there is for us no place of escape."' },
  { surahId: 14, ayahNumber: 22, text: 'And Satan will say when the matter has been concluded, "Indeed, Allah had promised you the promise of truth. And I promised you, but I betrayed you. But I had no authority over you except that I invited you, and you responded to me. So do not blame me; but blame yourselves. I cannot be called to your aid, nor can you be called to my aid. Indeed, I deny your association of me [with Allah] before. Indeed, for the wrongdoers is a painful punishment."' },
  { surahId: 14, ayahNumber: 23, text: 'And those who believed and did righteous deeds will be admitted to gardens beneath which rivers flow, abiding eternally therein by permission of their Lord; and their greeting therein will be, "Peace!"' },
  { surahId: 14, ayahNumber: 24, text: 'Have you not considered how Allah presents an example, [making] a good word like a good tree, whose root is firmly fixed and its branches [high] in the sky?' },
  { surahId: 14, ayahNumber: 25, text: 'It produces its fruit all the time, by permission of its Lord. And Allah presents examples for the people that perhaps they will be reminded.' },
  { surahId: 14, ayahNumber: 26, text: 'And the example of a bad word is like a bad tree, uprooted from the surface of the earth, not having any stability.' },
  { surahId: 14, ayahNumber: 27, text: 'Allah keeps firm those who believe, with the firm word, in worldly life and in the Hereafter. And Allah sends astray the wrongdoers. And Allah does what He wills.' },
  { surahId: 14, ayahNumber: 28, text: 'Have you not considered those who exchanged the favor of Allah for disbelief and settled their people [in] the home of ruin?' },
  { surahId: 14, ayahNumber: 29, text: '[It is] Hell, which they will [enter to] burn, and wretched is the settlement.' },
  { surahId: 14, ayahNumber: 30, text: 'And they have attributed to Allah equals to mislead [people] from His way. Say, "Enjoy yourselves, for indeed, your destination is the Fire."' },
  { surahId: 14, ayahNumber: 31, text: '[O Muhammad], tell My servants who have believed to establish prayer and spend from what We have provided them, secretly and publicly, before a Day comes in which there will be no exchange, nor any friendships.' },
  { surahId: 14, ayahNumber: 32, text: 'It is Allah who created the heavens and the earth and sent down rain from the sky and produced thereby some fruits as provision for you and subjected for you the ships to sail through the sea by His command and subjected for you the rivers.' },
  { surahId: 14, ayahNumber: 33, text: 'And He subjected for you the sun and the moon, continuous [in orbit], and subjected for you the night and the day.' },
  { surahId: 14, ayahNumber: 34, text: 'And He gave you from all you asked of Him. And if you should count the favor of Allah, you could not enumerate them. Indeed, mankind is [generally] most unjust and ungrateful.' },
  { surahId: 14, ayahNumber: 35, text: 'And [mention, O Muhammad], when Abraham said, "My Lord, make this city [Makkah] secure and keep me and my sons away from worshipping idols.' },
  { surahId: 14, ayahNumber: 36, text: 'My Lord, indeed they have led astray many among the people. So whoever follows me - then he is of me; and whoever disobeys me - indeed, You are [yet] Forgiving and Merciful.' },
  { surahId: 14, ayahNumber: 37, text: 'Our Lord, I have settled some of my descendants in an uncultivated valley near Your sacred House, our Lord, that they may establish prayer. So make hearts among the people incline toward them and provide for them from the fruits that they might be grateful.' },
  { surahId: 14, ayahNumber: 38, text: 'Our Lord, indeed You know what we conceal and what we declare, and nothing is hidden from Allah on the earth or in the heaven.' },
  { surahId: 14, ayahNumber: 39, text: 'Praise to Allah, who has granted to me in old age Ishmael and Isaac. Indeed, my Lord is the Hearer of supplication.' },
  { surahId: 14, ayahNumber: 40, text: 'My Lord, make me an establisher of prayer, and [many] from my descendants. Our Lord, and accept my supplication.' },
  { surahId: 14, ayahNumber: 41, text: 'Our Lord, forgive me and my parents and the believers the Day the account is established."' },
  { surahId: 14, ayahNumber: 42, text: 'And never think that Allah is unaware of what the wrongdoers do. He only delays them for a Day when eyes will stare [in horror].' },
  { surahId: 14, ayahNumber: 43, text: 'Racing ahead, their heads raised up, their glance does not come back to them, and their hearts are void.' },
  { surahId: 14, ayahNumber: 44, text: 'And, [O Muhammad], warn the people of a Day when the punishment will come to them and those who did wrong will say, "Our Lord, delay us for a short term; we will answer Your call and follow the messengers." [But it will be said], "Had you not sworn, before, that for you there would be no cessation?' },
  { surahId: 14, ayahNumber: 45, text: 'And you lived among the dwellings of those who wronged themselves, and it had become clear to you how We dealt with them. And We presented for you [many] examples."' },
  { surahId: 14, ayahNumber: 46, text: 'And they had planned their plan, but with Allah is [recorded] their plan, even if their plan had been [sufficient] to do away with the mountains.' },
  { surahId: 14, ayahNumber: 47, text: 'So never think that Allah will fail in His promise to His messengers. Indeed, Allah is Exalted in Might and Owner of Retribution.' },
  { surahId: 14, ayahNumber: 48, text: '[It will be] on the Day the earth will be replaced by another earth, and the heavens [as well], and all creatures will come out before Allah, the One, the Prevailing.' },
  { surahId: 14, ayahNumber: 49, text: 'And you will see the criminals that Day bound together in shackles,' },
  { surahId: 14, ayahNumber: 50, text: 'Their garments of liquid pitch and their faces covered by the Fire.' },
  { surahId: 14, ayahNumber: 51, text: 'So that Allah will recompense every soul for what it earned. Indeed, Allah is swift in account.' },
  { surahId: 14, ayahNumber: 52, text: 'This [Qur\'an] is notification for the people that they may be warned thereby and that they may know that He is but one God and that those of understanding will be reminded.' },
  { surahId: 15, ayahNumber: 1, text: 'Alif, Lam, Ra. These are the verses of the Book and a clear Qur\'an.' },
  { surahId: 15, ayahNumber: 2, text: 'Perhaps those who disbelieve will wish that they had been Muslims.' },
  { surahId: 15, ayahNumber: 3, text: 'Let them eat and enjoy themselves and be diverted by [false] hope, for they are going to know.' },
  { surahId: 15, ayahNumber: 4, text: 'And We did not destroy any city but that for it was a known decree.' },
  { surahId: 15, ayahNumber: 5, text: 'No nation will precede its term, nor will they remain thereafter.' },
  { surahId: 15, ayahNumber: 6, text: 'And they say, "O you upon whom the message has been sent down, indeed you are mad.' },
  { surahId: 15, ayahNumber: 7, text: 'Why do you not bring us the angels, if you should be among the truthful?"' },
  { surahId: 15, ayahNumber: 8, text: 'We do not send down the angels except with truth; and the disbelievers would not then be reprieved.' },
  { surahId: 15, ayahNumber: 9, text: 'Indeed, it is We who sent down the Qur\'an and indeed, We will be its guardian.' },
  { surahId: 15, ayahNumber: 10, text: 'And We had certainly sent [messengers] before you, [O Muhammad], among the sects of the former peoples.' },
  { surahId: 15, ayahNumber: 11, text: 'And no messenger would come to them except that they ridiculed him.' },
  { surahId: 15, ayahNumber: 12, text: 'Thus do We insert denial into the hearts of the criminals.' },
  { surahId: 15, ayahNumber: 13, text: 'They will not believe in it, while there has already occurred the precedent of the former peoples.' },
  { surahId: 15, ayahNumber: 14, text: 'And [even] if We opened to them a gate from the heaven and they continued therein to ascend,' },
  { surahId: 15, ayahNumber: 15, text: 'They would say, "Our eyes have only been dazzled. Rather, we are a people affected by magic."' },
  { surahId: 15, ayahNumber: 16, text: 'And We have placed within the heaven great stars and have beautified it for the observers.' },
  { surahId: 15, ayahNumber: 17, text: 'And We have protected it from every devil expelled [from the mercy of Allah]' },
  { surahId: 15, ayahNumber: 18, text: 'Except one who steals a hearing and is pursued by a clear burning flame.' },
  { surahId: 15, ayahNumber: 19, text: 'And the earth - We have spread it and cast therein firmly set mountains and caused to grow therein [something] of every well-balanced thing.' },
  { surahId: 15, ayahNumber: 20, text: 'And We have made for you therein means of living and [for] those for whom you are not providers.' },
  { surahId: 15, ayahNumber: 21, text: 'And there is not a thing but that with Us are its depositories, and We do not send it down except according to a known measure.' },
  { surahId: 15, ayahNumber: 22, text: 'And We have sent the fertilizing winds and sent down water from the sky and given you drink from it. And you are not its retainers.' },
  { surahId: 15, ayahNumber: 23, text: 'And indeed, it is We who give life and cause death, and We are the Inheritor.' },
  { surahId: 15, ayahNumber: 24, text: 'And We have already known the preceding [generations] among you, and We have already known the later [ones to come].' },
  { surahId: 15, ayahNumber: 25, text: 'And indeed, your Lord will gather them; indeed, He is Wise and Knowing.' },
  { surahId: 15, ayahNumber: 26, text: 'And We did certainly create man out of clay from an altered black mud.' },
  { surahId: 15, ayahNumber: 27, text: 'And the jinn We created before from scorching fire.' },
  { surahId: 15, ayahNumber: 28, text: 'And [mention, O Muhammad], when your Lord said to the angels, "I will create a human being out of clay from an altered black mud.' },
  { surahId: 15, ayahNumber: 29, text: 'And when I have proportioned him and breathed into him of My [created] soul, then fall down to him in prostration."' },
  { surahId: 15, ayahNumber: 30, text: 'So the angels prostrated - all of them entirely,' },
  { surahId: 15, ayahNumber: 31, text: 'Except Iblees, he refused to be with those who prostrated.' },
  { surahId: 15, ayahNumber: 32, text: '[Allah] said, O Iblees, what is [the matter] with you that you are not with those who prostrate?"' },
  { surahId: 15, ayahNumber: 33, text: 'He said, "Never would I prostrate to a human whom You created out of clay from an altered black mud."' },
  { surahId: 15, ayahNumber: 34, text: '[Allah] said, "Then get out of it, for indeed, you are expelled.' },
  { surahId: 15, ayahNumber: 35, text: 'And indeed, upon you is the curse until the Day of Recompense."' },
  { surahId: 15, ayahNumber: 36, text: 'He said, "My Lord, then reprieve me until the Day they are resurrected."' },
  { surahId: 15, ayahNumber: 37, text: '[Allah] said, "So indeed, you are of those reprieved' },
  { surahId: 15, ayahNumber: 38, text: 'Until the Day of the time well-known."' },
  { surahId: 15, ayahNumber: 39, text: '[Iblees] said, "My Lord, because You have put me in error, I will surely make [disobedience] attractive to them on earth, and I will mislead them all' },
  { surahId: 15, ayahNumber: 40, text: 'Except, among them, Your chosen servants."' },
  { surahId: 15, ayahNumber: 41, text: '[Allah] said, "This is a path [of return] to Me [that is] straight.' },
  { surahId: 15, ayahNumber: 42, text: 'Indeed, My servants - no authority will you have over them, except those who follow you of the deviators.' },
  { surahId: 15, ayahNumber: 43, text: 'And indeed, Hell is the promised place for them all.' },
  { surahId: 15, ayahNumber: 44, text: 'It has seven gates; for every gate is of them a portion designated."' },
  { surahId: 15, ayahNumber: 45, text: 'Indeed, the righteous will be within gardens and springs.' },
  { surahId: 15, ayahNumber: 46, text: '[Having been told], "Enter it in peace, safe [and secure]."' },
  { surahId: 15, ayahNumber: 47, text: 'And We will remove whatever is in their breasts of resentment, [so they will be] brothers, on thrones facing each other.' },
  { surahId: 15, ayahNumber: 48, text: 'No fatigue will touch them therein, nor from it will they [ever] be removed.' },
  { surahId: 15, ayahNumber: 49, text: '[O Muhammad], inform My servants that it is I who am the Forgiving, the Merciful.' },
  { surahId: 15, ayahNumber: 50, text: 'And that it is My punishment which is the painful punishment.' },
  { surahId: 15, ayahNumber: 51, text: 'And inform them about the guests of Abraham,' },
  { surahId: 15, ayahNumber: 52, text: 'When they entered upon him and said, "Peace." [Abraham] said, "Indeed, we are fearful of you."' },
  { surahId: 15, ayahNumber: 53, text: '[The angels] said, "Fear not. Indeed, we give you good tidings of a learned boy."' },
  { surahId: 15, ayahNumber: 54, text: 'He said, "Have you given me good tidings although old age has come upon me? Then of what [wonder] do you inform?"' },
  { surahId: 15, ayahNumber: 55, text: 'They said, "We have given you good tidings in truth, so do not be of the despairing."' },
  { surahId: 15, ayahNumber: 56, text: 'He said, "And who despairs of the mercy of his Lord except for those astray?"' },
  { surahId: 15, ayahNumber: 57, text: '[Abraham] said, "Then what is your business [here], O messengers?"' },
  { surahId: 15, ayahNumber: 58, text: 'They said, "Indeed, we have been sent to a people of criminals,' },
  { surahId: 15, ayahNumber: 59, text: 'Except the family of Lot; indeed, we will save them all' },
  { surahId: 15, ayahNumber: 60, text: 'Except his wife." Allah decreed that she is of those who remain behind.' },
  { surahId: 15, ayahNumber: 61, text: 'And when the messengers came to the family of Lot,' },
  { surahId: 15, ayahNumber: 62, text: 'He said, "Indeed, you are people unknown."' },
  { surahId: 15, ayahNumber: 63, text: 'They said, "But we have come to you with that about which they were disputing,' },
  { surahId: 15, ayahNumber: 64, text: 'And we have come to you with truth, and indeed, we are truthful.' },
  { surahId: 15, ayahNumber: 65, text: 'So set out with your family during a portion of the night and follow behind them and let not anyone among you look back and continue on to where you are commanded."' },
  { surahId: 15, ayahNumber: 66, text: 'And We conveyed to him [the decree] of that matter: that those [sinners] would be eliminated by early morning.' },
  { surahId: 15, ayahNumber: 67, text: 'And the people of the city came rejoicing.' },
  { surahId: 15, ayahNumber: 68, text: '[Lot] said, "Indeed, these are my guests, so do not shame me.' },
  { surahId: 15, ayahNumber: 69, text: 'And fear Allah and do not disgrace me."' },
  { surahId: 15, ayahNumber: 70, text: 'They said, "Have we not forbidden you from [protecting] people?"' },
  { surahId: 15, ayahNumber: 71, text: '[Lot] said, "These are my daughters - if you would be doers [of lawful marriage]."' },
  { surahId: 15, ayahNumber: 72, text: 'By your life, [O Muhammad], indeed they were, in their intoxication, wandering blindly.' },
  { surahId: 15, ayahNumber: 73, text: 'So the shriek seized them at sunrise.' },
  { surahId: 15, ayahNumber: 74, text: 'And We made the highest part [of the city] its lowest and rained upon them stones of hard clay.' },
  { surahId: 15, ayahNumber: 75, text: 'Indeed in that are signs for those who discern.' },
  { surahId: 15, ayahNumber: 76, text: 'And indeed, those cities are [situated] on an established road.' },
  { surahId: 15, ayahNumber: 77, text: 'Indeed in that is a sign for the believers.' },
  { surahId: 15, ayahNumber: 78, text: 'And the companions of the thicket were [also] wrongdoers.' },
  { surahId: 15, ayahNumber: 79, text: 'So We took retribution from them, and indeed, both [cities] are on a clear highway.' },
  { surahId: 15, ayahNumber: 80, text: 'And certainly did the companions of Thamud deny the messengers.' },
  { surahId: 15, ayahNumber: 81, text: 'And We gave them Our signs, but from them they were turning away.' },
  { surahId: 15, ayahNumber: 82, text: 'And they used to carve from the mountains, houses, feeling secure.' },
  { surahId: 15, ayahNumber: 83, text: 'But the shriek seized them at early morning.' },
  { surahId: 15, ayahNumber: 84, text: 'So nothing availed them [from] what they used to earn.' },
  { surahId: 15, ayahNumber: 85, text: 'And We have not created the heavens and earth and that between them except in truth. And indeed, the Hour is coming; so forgive with gracious forgiveness.' },
  { surahId: 15, ayahNumber: 86, text: 'Indeed, your Lord - He is the Knowing Creator.' },
  { surahId: 15, ayahNumber: 87, text: 'And We have certainly given you, [O Muhammad], seven of the often repeated [verses] and the great Qur\'an.' },
  { surahId: 15, ayahNumber: 88, text: 'Do not extend your eyes toward that by which We have given enjoyment to [certain] categories of the disbelievers, and do not grieve over them. And lower your wing to the believers' },
  { surahId: 15, ayahNumber: 89, text: 'And say, "Indeed, I am the clear warner" -' },
  { surahId: 15, ayahNumber: 90, text: 'Just as We had revealed [scriptures] to the separators' },
  { surahId: 15, ayahNumber: 91, text: 'Who have made the Qur\'an into portions.' },
  { surahId: 15, ayahNumber: 92, text: 'So by your Lord, We will surely question them all' },
  { surahId: 15, ayahNumber: 93, text: 'About what they used to do.' },
  { surahId: 15, ayahNumber: 94, text: 'Then declare what you are commanded and turn away from the polytheists.' },
  { surahId: 15, ayahNumber: 95, text: 'Indeed, We are sufficient for you against the mockers' },
  { surahId: 15, ayahNumber: 96, text: 'Who make [equal] with Allah another deity. But they are going to know.' },
  { surahId: 15, ayahNumber: 97, text: 'And We already know that your breast is constrained by what they say.' },
  { surahId: 15, ayahNumber: 98, text: 'So exalt [Allah] with praise of your Lord and be of those who prostrate [to Him].' },
  { surahId: 15, ayahNumber: 99, text: 'And worship your Lord until there comes to you the certainty (death).' },
  { surahId: 16, ayahNumber: 1, text: 'The command of Allah is coming, so be not impatient for it. Exalted is He and high above what they associate with Him.' },
  { surahId: 16, ayahNumber: 2, text: 'He sends down the angels, with the inspiration of His command, upon whom He wills of His servants, [telling them], "Warn that there is no deity except Me; so fear Me."' },
  { surahId: 16, ayahNumber: 3, text: 'He created the heavens and earth in truth. High is He above what they associate with Him.' },
  { surahId: 16, ayahNumber: 4, text: 'He created man from a sperm-drop; then at once, he is a clear adversary.' },
  { surahId: 16, ayahNumber: 5, text: 'And the grazing livestock He has created for you; in them is warmth and [numerous] benefits, and from them you eat.' },
  { surahId: 16, ayahNumber: 6, text: 'And for you in them is [the enjoyment of] beauty when you bring them in [for the evening] and when you send them out [to pasture].' },
  { surahId: 16, ayahNumber: 7, text: 'And they carry your loads to a land you could not have reached except with difficulty to yourselves. Indeed, your Lord is Kind and Merciful.' },
  { surahId: 16, ayahNumber: 8, text: 'And [He created] the horses, mules and donkeys for you to ride and [as] adornment. And He creates that which you do not know.' },
  { surahId: 16, ayahNumber: 9, text: 'And upon Allah is the direction of the [right] way, and among the various paths are those deviating. And if He willed, He could have guided you all.' },
  { surahId: 16, ayahNumber: 10, text: 'It is He who sends down rain from the sky; from it is drink and from it is foliage in which you pasture [animals].' },
  { surahId: 16, ayahNumber: 11, text: 'He causes to grow for you thereby the crops, olives, palm trees, grapevines, and from all the fruits. Indeed in that is a sign for a people who give thought.' },
  { surahId: 16, ayahNumber: 12, text: 'And He has subjected for you the night and day and the sun and moon, and the stars are subjected by His command. Indeed in that are signs for a people who reason.' },
  { surahId: 16, ayahNumber: 13, text: 'And [He has subjected] whatever He multiplied for you on the earth of varying colors. Indeed in that is a sign for a people who remember.' },
  { surahId: 16, ayahNumber: 14, text: 'And it is He who subjected the sea for you to eat from it tender meat and to extract from it ornaments which you wear. And you see the ships plowing through it, and [He subjected it] that you may seek of His bounty; and perhaps you will be grateful.' },
  { surahId: 16, ayahNumber: 15, text: 'And He has cast into the earth firmly set mountains, lest it shift with you, and [made] rivers and roads, that you may be guided,' },
  { surahId: 16, ayahNumber: 16, text: 'And landmarks. And by the stars they are [also] guided.' },
  { surahId: 16, ayahNumber: 17, text: 'Then is He who creates like one who does not create? So will you not be reminded?' },
  { surahId: 16, ayahNumber: 18, text: 'And if you should count the favors of Allah, you could not enumerate them. Indeed, Allah is Forgiving and Merciful.' },
  { surahId: 16, ayahNumber: 19, text: 'And Allah knows what you conceal and what you declare.' },
  { surahId: 16, ayahNumber: 20, text: 'And those they invoke other than Allah create nothing, and they [themselves] are created.' },
  { surahId: 16, ayahNumber: 21, text: 'They are, [in fact], dead, not alive, and they do not perceive when they will be resurrected.' },
  { surahId: 16, ayahNumber: 22, text: 'Your god is one God. But those who do not believe in the Hereafter - their hearts are disapproving, and they are arrogant.' },
  { surahId: 16, ayahNumber: 23, text: 'Assuredly, Allah knows what they conceal and what they declare. Indeed, He does not like the arrogant.' },
  { surahId: 16, ayahNumber: 24, text: 'And when it is said to them, "What has your Lord sent down?" They say, "Legends of the former peoples,"' },
  { surahId: 16, ayahNumber: 25, text: 'That they may bear their own burdens in full on the Day of Resurrection and some of the burdens of those whom they misguide without knowledge. Unquestionably, evil is that which they bear.' },
  { surahId: 16, ayahNumber: 26, text: 'Those before them had already plotted, but Allah came at their building from the foundations, so the roof fell upon them from above them, and the punishment came to them from where they did not perceive.' },
  { surahId: 16, ayahNumber: 27, text: 'Then on the Day of Resurrection He will disgrace them and say, "Where are My \'partners\' for whom you used to oppose [the believers]?" Those who were given knowledge will say, "Indeed disgrace, this Day, and evil are upon the disbelievers" -' },
  { surahId: 16, ayahNumber: 28, text: 'The ones whom the angels take in death [while] wronging themselves, and [who] then offer submission, [saying], "We were not doing any evil." But, yes! Indeed, Allah is Knowing of what you used to do.' },
  { surahId: 16, ayahNumber: 29, text: 'So enter the gates of Hell to abide eternally therein, and how wretched is the residence of the arrogant.' },
  { surahId: 16, ayahNumber: 30, text: 'And it will be said to those who feared Allah, "What did your Lord send down?" They will say, "[That which is] good." For those who do good in this world is good; and the home of the Hereafter is better. And how excellent is the home of the righteous -' },
  { surahId: 16, ayahNumber: 31, text: 'Gardens of perpetual residence, which they will enter, beneath which rivers flow. They will have therein whatever they wish. Thus does Allah reward the righteous -' },
  { surahId: 16, ayahNumber: 32, text: 'The ones whom the angels take in death, [being] good and pure; [the angels] will say, "Peace be upon you. Enter Paradise for what you used to do."' },
  { surahId: 16, ayahNumber: 33, text: 'Do the disbelievers await [anything] except that the angels should come to them or there comes the command of your Lord? Thus did those do before them. And Allah wronged them not, but they had been wronging themselves.' },
  { surahId: 16, ayahNumber: 34, text: 'So they were struck by the evil consequences of what they did and were enveloped by what they used to ridicule.' },
  { surahId: 16, ayahNumber: 35, text: 'And those who associate others with Allah say, "If Allah had willed, we would not have worshipped anything other than Him, neither we nor our fathers, nor would we have forbidden anything through other than Him." Thus did those do before them. So is there upon the messengers except [the duty of] clear notification?' },
  { surahId: 16, ayahNumber: 36, text: 'And We certainly sent into every nation a messenger, [saying], "Worship Allah and avoid Taghut." And among them were those whom Allah guided, and among them were those upon whom error was [deservedly] decreed. So proceed through the earth and observe how was the end of the deniers.' },
  { surahId: 16, ayahNumber: 37, text: '[Even] if you should strive for their guidance, [O Muhammad], indeed, Allah does not guide those He sends astray, and they will have no helpers.' },
  { surahId: 16, ayahNumber: 38, text: 'And they swear by Allah their strongest oaths [that] Allah will not resurrect one who dies. But yes - [it is] a true promise [binding] upon Him, but most of the people do not know.' },
  { surahId: 16, ayahNumber: 39, text: '[It is] so He will make clear to them [the truth of] that wherein they differ and so those who have disbelieved may know that they were liars.' },
  { surahId: 16, ayahNumber: 40, text: 'Indeed, Our word to a thing when We intend it is but that We say to it, "Be," and it is.' },
  { surahId: 16, ayahNumber: 41, text: 'And those who emigrated for [the cause of] Allah after they had been wronged - We will surely settle them in this world in a good place; but the reward of the Hereafter is greater, if only they could know.' },
  { surahId: 16, ayahNumber: 42, text: '[They are] those who endured patiently and upon their Lord relied.' },
  { surahId: 16, ayahNumber: 43, text: 'And We sent not before you except men to whom We revealed [Our message]. So ask the people of the message if you do not know.' },
  { surahId: 16, ayahNumber: 44, text: '[We sent them] with clear proofs and written ordinances. And We revealed to you the message that you may make clear to the people what was sent down to them and that they might give thought.' },
  { surahId: 16, ayahNumber: 45, text: 'Then, do those who have planned evil deeds feel secure that Allah will not cause the earth to swallow them or that the punishment will not come upon them from where they do not perceive?' },
  { surahId: 16, ayahNumber: 46, text: 'Or that He would not seize them during their [usual] activity, and they could not cause failure?' },
  { surahId: 16, ayahNumber: 47, text: 'Or that He would not seize them gradually [in a state of dread]? But indeed, your Lord is Kind and Merciful.' },
  { surahId: 16, ayahNumber: 48, text: 'Have they not considered what things Allah has created? Their shadows incline to the right and to the left, prostrating to Allah, while they are humble.' },
  { surahId: 16, ayahNumber: 49, text: 'And to Allah prostrates whatever is in the heavens and whatever is on the earth of creatures, and the angels [as well], and they are not arrogant.' },
  { surahId: 16, ayahNumber: 50, text: 'They fear their Lord above them, and they do what they are commanded.' },
  { surahId: 16, ayahNumber: 51, text: 'And Allah has said, "Do not take for yourselves two deities. He is but one God, so fear only Me."' },
  { surahId: 16, ayahNumber: 52, text: 'And to Him belongs whatever is in the heavens and the earth, and to Him is [due] worship constantly. Then is it other than Allah that you fear?' },
  { surahId: 16, ayahNumber: 53, text: 'And whatever you have of favor - it is from Allah. Then when adversity touches you, to Him you cry for help.' },
  { surahId: 16, ayahNumber: 54, text: 'Then when He removes the adversity from you, at once a party of you associates others with their Lord' },
  { surahId: 16, ayahNumber: 55, text: 'So they will deny what We have given them. Then enjoy yourselves, for you are going to know.' },
  { surahId: 16, ayahNumber: 56, text: 'And they assign to what they do not know a portion of that which We have provided them. By Allah, you will surely be questioned about what you used to invent.' },
  { surahId: 16, ayahNumber: 57, text: 'And they attribute to Allah daughters - exalted is He - and for them is what they desire.' },
  { surahId: 16, ayahNumber: 58, text: 'And when one of them is informed of [the birth of] a female, his face becomes dark, and he suppresses grief.' },
  { surahId: 16, ayahNumber: 59, text: 'He hides himself from the people because of the ill of which he has been informed. Should he keep it in humiliation or bury it in the ground? Unquestionably, evil is what they decide.' },
  { surahId: 16, ayahNumber: 60, text: 'For those who do not believe in the Hereafter is the description of evil; and for Allah is the highest attribute. And He is Exalted in Might, the Wise.' },
  { surahId: 16, ayahNumber: 61, text: 'And if Allah were to impose blame on the people for their wrongdoing, He would not have left upon the earth any creature, but He defers them for a specified term. And when their term has come, they will not remain behind an hour, nor will they precede [it].' },
  { surahId: 16, ayahNumber: 62, text: 'And they attribute to Allah that which they dislike, and their tongues assert the lie that they will have the best [from Him]. Assuredly, they will have the Fire, and they will be [therein] neglected.' },
  { surahId: 16, ayahNumber: 63, text: 'By Allah, We did certainly send [messengers] to nations before you, but Satan made their deeds attractive to them. And he is the disbelievers\' ally today [as well], and they will have a painful punishment.' },
  { surahId: 16, ayahNumber: 64, text: 'And We have not revealed to you the Book, [O Muhammad], except for you to make clear to them that wherein they have differed and as guidance and mercy for a people who believe.' },
  { surahId: 16, ayahNumber: 65, text: 'And Allah has sent down rain from the sky and given life thereby to the earth after its lifelessness. Indeed in that is a sign for a people who listen.' },
  { surahId: 16, ayahNumber: 66, text: 'And indeed, for you in grazing livestock is a lesson. We give you drink from what is in their bellies - between excretion and blood - pure milk, palatable to drinkers.' },
  { surahId: 16, ayahNumber: 67, text: 'And from the fruits of the palm trees and grapevines you take intoxicant and good provision. Indeed in that is a sign for a people who reason.' },
  { surahId: 16, ayahNumber: 68, text: 'And your Lord inspired to the bee, "Take for yourself among the mountains, houses, and among the trees and [in] that which they construct.' },
  { surahId: 16, ayahNumber: 69, text: 'Then eat from all the fruits and follow the ways of your Lord laid down [for you]." There emerges from their bellies a drink, varying in colors, in which there is healing for people. Indeed in that is a sign for a people who give thought.' },
  { surahId: 16, ayahNumber: 70, text: 'And Allah created you; then He will take you in death. And among you is he who is reversed to the most decrepit [old] age so that he will not know, after [having had] knowledge, a thing. Indeed, Allah is Knowing and Competent.' },
  { surahId: 16, ayahNumber: 71, text: 'And Allah has favored some of you over others in provision. But those who were favored would not hand over their provision to those whom their right hands possess so they would be equal to them therein. Then is it the favor of Allah they reject?' },
  { surahId: 16, ayahNumber: 72, text: 'And Allah has made for you from yourselves mates and has made for you from your mates sons and grandchildren and has provided for you from the good things. Then in falsehood do they believe and in the favor of Allah they disbelieve?' },
  { surahId: 16, ayahNumber: 73, text: 'And they worship besides Allah that which does not possess for them [the power of] provision from the heavens and the earth at all, and [in fact], they are unable.' },
  { surahId: 16, ayahNumber: 74, text: 'So do not assert similarities to Allah. Indeed, Allah knows and you do not know.' },
  { surahId: 16, ayahNumber: 75, text: 'Allah presents an example: a slave [who is] owned and unable to do a thing and he to whom We have provided from Us good provision, so he spends from it secretly and publicly. Can they be equal? Praise to Allah! But most of them do not know.' },
  { surahId: 16, ayahNumber: 76, text: 'And Allah presents an example of two men, one of them dumb and unable to do a thing, while he is a burden to his guardian. Wherever he directs him, he brings no good. Is he equal to one who commands justice, while he is on a straight path?' },
  { surahId: 16, ayahNumber: 77, text: 'And to Allah belongs the unseen [aspects] of the heavens and the earth. And the command for the Hour is not but as a glance of the eye or even nearer. Indeed, Allah is over all things competent.' },
  { surahId: 16, ayahNumber: 78, text: 'And Allah has extracted you from the wombs of your mothers not knowing a thing, and He made for you hearing and vision and intellect that perhaps you would be grateful.' },
  { surahId: 16, ayahNumber: 79, text: 'Do they not see the birds controlled in the atmosphere of the sky? None holds them up except Allah. Indeed in that are signs for a people who believe.' },
  { surahId: 16, ayahNumber: 80, text: 'And Allah has made for you from your homes a place of rest and made for you from the hides of the animals tents which you find light on your day of travel and your day of encampment; and from their wool, fur and hair is furnishing and enjoyment for a time.' },
  { surahId: 16, ayahNumber: 81, text: 'And Allah has made for you, from that which He has created, shadows and has made for you from the mountains, shelters and has made for you garments which protect you from the heat and garments which protect you from your [enemy in] battle. Thus does He complete His favor upon you that you might submit [to Him].' },
  { surahId: 16, ayahNumber: 82, text: 'But if they turn away, [O Muhammad] - then only upon you is [responsibility for] clear notification.' },
  { surahId: 16, ayahNumber: 83, text: 'They recognize the favor of Allah; then they deny it. And most of them are disbelievers.' },
  { surahId: 16, ayahNumber: 84, text: 'And [mention] the Day when We will resurrect from every nation a witness. Then it will not be permitted to the disbelievers [to apologize or make excuses], nor will they be asked to appease [Allah].' },
  { surahId: 16, ayahNumber: 85, text: 'And when those who wronged see the punishment, it will not be lightened for them, nor will they be reprieved.' },
  { surahId: 16, ayahNumber: 86, text: 'And when those who associated others with Allah see their "partners," they will say," Our Lord, these are our partners [to You] whom we used to invoke besides You." But they will throw at them the statement, "Indeed, you are liars."' },
  { surahId: 16, ayahNumber: 87, text: 'And they will impart to Allah that Day [their] submission, and lost from them is what they used to invent.' },
  { surahId: 16, ayahNumber: 88, text: 'Those who disbelieved and averted [others] from the way of Allah - We will increase them in punishment over [their] punishment for what corruption they were causing.' },
  { surahId: 16, ayahNumber: 89, text: 'And [mention] the Day when We will resurrect among every nation a witness over them from themselves. And We will bring you, [O Muhammad], as a witness over your nation. And We have sent down to you the Book as clarification for all things and as guidance and mercy and good tidings for the Muslims.' },
  { surahId: 16, ayahNumber: 90, text: 'Indeed, Allah orders justice and good conduct and giving to relatives and forbids immorality and bad conduct and oppression. He admonishes you that perhaps you will be reminded.' },
  { surahId: 16, ayahNumber: 91, text: 'And fulfill the covenant of Allah when you have taken it, [O believers], and do not break oaths after their confirmation while you have made Allah, over you, a witness. Indeed, Allah knows what you do.' },
  { surahId: 16, ayahNumber: 92, text: 'And do not be like she who untwisted her spun thread after it was strong [by] taking your oaths as [means of] deceit between you because one community is more plentiful [in number or wealth] than another community. Allah only tries you thereby. And He will surely make clear to you on the Day of Resurrection that over which you used to differ.' },
  { surahId: 16, ayahNumber: 93, text: 'And if Allah had willed, He could have made you [of] one religion, but He causes to stray whom He wills and guides whom He wills. And you will surely be questioned about what you used to do.' },
  { surahId: 16, ayahNumber: 94, text: 'And do not take your oaths as [means of] deceit between you, lest a foot slip after it was [once] firm, and you would taste evil [in this world] for what [people] you diverted from the way of Allah, and you would have [in the Hereafter] a great punishment.' },
  { surahId: 16, ayahNumber: 95, text: 'And do not exchange the covenant of Allah for a small price. Indeed, what is with Allah is best for you, if only you could know.' },
  { surahId: 16, ayahNumber: 96, text: 'Whatever you have will end, but what Allah has is lasting. And We will surely give those who were patient their reward according to the best of what they used to do.' },
  { surahId: 16, ayahNumber: 97, text: 'Whoever does righteousness, whether male or female, while he is a believer - We will surely cause him to live a good life, and We will surely give them their reward [in the Hereafter] according to the best of what they used to do.' },
  { surahId: 16, ayahNumber: 98, text: 'So when you recite the Qur\'an, [first] seek refuge in Allah from Satan, the expelled [from His mercy].' },
  { surahId: 16, ayahNumber: 99, text: 'Indeed, there is for him no authority over those who have believed and rely upon their Lord.' },
  { surahId: 16, ayahNumber: 100, text: 'His authority is only over those who take him as an ally and those who through him associate others with Allah.' },
  { surahId: 16, ayahNumber: 101, text: 'And when We substitute a verse in place of a verse - and Allah is most knowing of what He sends down - they say, "You, [O Muhammad], are but an inventor [of lies]." But most of them do not know.' },
  { surahId: 16, ayahNumber: 102, text: 'Say, [O Muhammad], "The Pure Spirit has brought it down from your Lord in truth to make firm those who believe and as guidance and good tidings to the Muslims."' },
  { surahId: 16, ayahNumber: 103, text: 'And We certainly know that they say, "It is only a human being who teaches the Prophet." The tongue of the one they refer to is foreign, and this Qur\'an is [in] a clear Arabic language.' },
  { surahId: 16, ayahNumber: 104, text: 'Indeed, those who do not believe in the verses of Allah - Allah will not guide them, and for them is a painful punishment.' },
  { surahId: 16, ayahNumber: 105, text: 'They only invent falsehood who do not believe in the verses of Allah, and it is those who are the liars.' },
  { surahId: 16, ayahNumber: 106, text: 'Whoever disbelieves in Allah after his belief... except for one who is forced [to renounce his religion] while his heart is secure in faith. But those who [willingly] open their breasts to disbelief, upon them is wrath from Allah, and for them is a great punishment;' },
  { surahId: 16, ayahNumber: 107, text: 'That is because they preferred the worldly life over the Hereafter and that Allah does not guide the disbelieving people.' },
  { surahId: 16, ayahNumber: 108, text: 'Those are the ones over whose hearts and hearing and vision Allah has sealed, and it is those who are the heedless.' },
  { surahId: 16, ayahNumber: 109, text: 'Assuredly, it is they, in the Hereafter, who will be the losers.' },
  { surahId: 16, ayahNumber: 110, text: 'Then, indeed your Lord, to those who emigrated after they had been compelled [to renounce their religion] and thereafter fought [for the cause of Allah] and were patient - indeed, your Lord, after that, is Forgiving and Merciful' },
  { surahId: 16, ayahNumber: 111, text: 'On the Day when every soul will come disputing for itself, and every soul will be fully compensated for what it did, and they will not be wronged.' },
  { surahId: 16, ayahNumber: 112, text: 'And Allah presents an example: a city which was safe and secure, its provision coming to it in abundance from every location, but it denied the favors of Allah. So Allah made it taste the envelopment of hunger and fear for what they had been doing.' },
  { surahId: 16, ayahNumber: 113, text: 'And there had certainly come to them a Messenger from among themselves, but they denied him; so punishment overtook them while they were wrongdoers.' },
  { surahId: 16, ayahNumber: 114, text: 'Then eat of what Allah has provided for you [which is] lawful and good. And be grateful for the favor of Allah, if it is [indeed] Him that you worship.' },
  { surahId: 16, ayahNumber: 115, text: 'He has only forbidden to you dead animals, blood, the flesh of swine, and that which has been dedicated to other than Allah. But whoever is forced [by necessity], neither desiring [it] nor transgressing [its limit] - then indeed, Allah is Forgiving and Merciful.' },
  { surahId: 16, ayahNumber: 116, text: 'And do not say about what your tongues assert of untruth, "This is lawful and this is unlawful," to invent falsehood about Allah. Indeed, those who invent falsehood about Allah will not succeed.' },
  { surahId: 16, ayahNumber: 117, text: '[It is but] a brief enjoyment, and they will have a painful punishment.' },
  { surahId: 16, ayahNumber: 118, text: 'And to those who are Jews We have prohibited that which We related to you before. And We did not wrong them [thereby], but they were wronging themselves.' },
  { surahId: 16, ayahNumber: 119, text: 'Then, indeed your Lord, to those who have done wrong out of ignorance and then repent after that and correct themselves - indeed, your Lord, thereafter, is Forgiving and Merciful.' },
  { surahId: 16, ayahNumber: 120, text: 'Indeed, Abraham was a [comprehensive] leader, devoutly obedient to Allah, inclining toward truth, and he was not of those who associate others with Allah.' },
  { surahId: 16, ayahNumber: 121, text: '[He was] grateful for His favors. Allah chose him and guided him to a straight path.' },
  { surahId: 16, ayahNumber: 122, text: 'And We gave him good in this world, and indeed, in the Hereafter he will be among the righteous.' },
  { surahId: 16, ayahNumber: 123, text: 'Then We revealed to you, [O Muhammad], to follow the religion of Abraham, inclining toward truth; and he was not of those who associate with Allah.' },
  { surahId: 16, ayahNumber: 124, text: 'The sabbath was only appointed for those who differed over it. And indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ.' },
  { surahId: 16, ayahNumber: 125, text: 'Invite to the way of your Lord with wisdom and good instruction, and argue with them in a way that is best. Indeed, your Lord is most knowing of who has strayed from His way, and He is most knowing of who is [rightly] guided.' },
  { surahId: 16, ayahNumber: 126, text: 'And if you punish [an enemy, O believers], punish with an equivalent of that with which you were harmed. But if you are patient - it is better for those who are patient.' },
  { surahId: 16, ayahNumber: 127, text: 'And be patient, [O Muhammad], and your patience is not but through Allah. And do not grieve over them and do not be in distress over what they conspire.' },
  { surahId: 16, ayahNumber: 128, text: 'Indeed, Allah is with those who fear Him and those who are doers of good.' },
  { surahId: 17, ayahNumber: 1, text: 'Exalted is He who took His Servant by night from al-Masjid al-Haram to al-Masjid al-Aqsa, whose surroundings We have blessed, to show him of Our signs. Indeed, He is the Hearing, the Seeing.' },
  { surahId: 17, ayahNumber: 2, text: 'And We gave Moses the Scripture and made it a guidance for the Children of Israel that you not take other than Me as Disposer of affairs,' },
  { surahId: 17, ayahNumber: 3, text: 'O descendants of those We carried [in the ship] with Noah. Indeed, he was a grateful servant.' },
  { surahId: 17, ayahNumber: 4, text: 'And We conveyed to the Children of Israel in the Scripture that, "You will surely cause corruption on the earth twice, and you will surely reach [a degree of] great haughtiness.' },
  { surahId: 17, ayahNumber: 5, text: 'So when the [time of] promise came for the first of them, We sent against you servants of Ours - those of great military might, and they probed [even] into the homes, and it was a promise fulfilled.' },
  { surahId: 17, ayahNumber: 6, text: 'Then We gave back to you a return victory over them. And We reinforced you with wealth and sons and made you more numerous in manpower' },
  { surahId: 17, ayahNumber: 7, text: '[And said], "If you do good, you do good for yourselves; and if you do evil, [you do it] to yourselves." Then when the final promise came, [We sent your enemies] to sadden your faces and to enter the temple in Jerusalem, as they entered it the first time, and to destroy what they had taken over with [total] destruction.' },
  { surahId: 17, ayahNumber: 8, text: '[Then Allah said], "It is expected, [if you repent], that your Lord will have mercy upon you. But if you return [to sin], We will return [to punishment]. And We have made Hell, for the disbelievers, a prison-bed."' },
  { surahId: 17, ayahNumber: 9, text: 'Indeed, this Qur\'an guides to that which is most suitable and gives good tidings to the believers who do righteous deeds that they will have a great reward.' },
  { surahId: 17, ayahNumber: 10, text: 'And that those who do not believe in the Hereafter - We have prepared for them a painful punishment.' },
  { surahId: 17, ayahNumber: 11, text: 'And man supplicates for evil as he supplicates for good, and man is ever hasty.' },
  { surahId: 17, ayahNumber: 12, text: 'And We have made the night and day two signs, and We erased the sign of the night and made the sign of the day visible that you may seek bounty from your Lord and may know the number of years and the account [of time]. And everything We have set out in detail.' },
  { surahId: 17, ayahNumber: 13, text: 'And [for] every person We have imposed his fate upon his neck, and We will produce for him on the Day of Resurrection a record which he will encounter spread open.' },
  { surahId: 17, ayahNumber: 14, text: '[It will be said], "Read your record. Sufficient is yourself against you this Day as accountant."' },
  { surahId: 17, ayahNumber: 15, text: 'Whoever is guided is only guided for [the benefit of] his soul. And whoever errs only errs against it. And no bearer of burdens will bear the burden of another. And never would We punish until We sent a messenger.' },
  { surahId: 17, ayahNumber: 16, text: 'And when We intend to destroy a city, We command its affluent but they defiantly disobey therein; so the word comes into effect upon it, and We destroy it with [complete] destruction.' },
  { surahId: 17, ayahNumber: 17, text: 'And how many have We destroyed from the generations after Noah. And sufficient is your Lord, concerning the sins of His servants, as Acquainted and Seeing.' },
  { surahId: 17, ayahNumber: 18, text: 'Whoever should desire the immediate - We hasten for him from it what We will to whom We intend. Then We have made for him Hell, which he will [enter to] burn, censured and banished.' },
  { surahId: 17, ayahNumber: 19, text: 'But whoever desires the Hereafter and exerts the effort due to it while he is a believer - it is those whose effort is ever appreciated [by Allah].' },
  { surahId: 17, ayahNumber: 20, text: 'To each [category] We extend - to these and to those - from the gift of your Lord. And never has the gift of your Lord been restricted.' },
  { surahId: 17, ayahNumber: 21, text: 'Look how We have favored [in provision] some of them over others. But the Hereafter is greater in degrees [of difference] and greater in distinction.' },
  { surahId: 17, ayahNumber: 22, text: 'Do not make [as equal] with Allah another deity and [thereby] become censured and forsaken.' },
  { surahId: 17, ayahNumber: 23, text: 'And your Lord has decreed that you not worship except Him, and to parents, good treatment. Whether one or both of them reach old age [while] with you, say not to them [so much as], "uff," and do not repel them but speak to them a noble word.' },
  { surahId: 17, ayahNumber: 24, text: 'And lower to them the wing of humility out of mercy and say, "My Lord, have mercy upon them as they brought me up [when I was] small."' },
  { surahId: 17, ayahNumber: 25, text: 'Your Lord is most knowing of what is within yourselves. If you should be righteous [in intention] - then indeed He is ever, to the often returning [to Him], Forgiving.' },
  { surahId: 17, ayahNumber: 26, text: 'And give the relative his right, and [also] the poor and the traveler, and do not spend wastefully.' },
  { surahId: 17, ayahNumber: 27, text: 'Indeed, the wasteful are brothers of the devils, and ever has Satan been to his Lord ungrateful.' },
  { surahId: 17, ayahNumber: 28, text: 'And if you [must] turn away from the needy awaiting mercy from your Lord which you expect, then speak to them a gentle word.' },
  { surahId: 17, ayahNumber: 29, text: 'And do not make your hand [as] chained to your neck or extend it completely and [thereby] become blamed and insolvent.' },
  { surahId: 17, ayahNumber: 30, text: 'Indeed, your Lord extends provision for whom He wills and restricts [it]. Indeed He is ever, concerning His servants, Acquainted and Seeing.' },
  { surahId: 17, ayahNumber: 31, text: 'And do not kill your children for fear of poverty. We provide for them and for you. Indeed, their killing is ever a great sin.' },
  { surahId: 17, ayahNumber: 32, text: 'And do not approach unlawful sexual intercourse. Indeed, it is ever an immorality and is evil as a way.' },
  { surahId: 17, ayahNumber: 33, text: 'And do not kill the soul which Allah has forbidden, except by right. And whoever is killed unjustly - We have given his heir authority, but let him not exceed limits in [the matter of] taking life. Indeed, he has been supported [by the law].' },
  { surahId: 17, ayahNumber: 34, text: 'And do not approach the property of an orphan, except in the way that is best, until he reaches maturity. And fulfill [every] commitment. Indeed, the commitment is ever [that about which one will be] questioned.' },
  { surahId: 17, ayahNumber: 35, text: 'And give full measure when you measure, and weigh with an even balance. That is the best [way] and best in result.' },
  { surahId: 17, ayahNumber: 36, text: 'And do not pursue that of which you have no knowledge. Indeed, the hearing, the sight and the heart - about all those [one] will be questioned.' },
  { surahId: 17, ayahNumber: 37, text: 'And do not walk upon the earth exultantly. Indeed, you will never tear the earth [apart], and you will never reach the mountains in height.' },
  { surahId: 17, ayahNumber: 38, text: 'All that - its evil is ever, in the sight of your Lord, detested.' },
  { surahId: 17, ayahNumber: 39, text: 'That is from what your Lord has revealed to you, [O Muhammad], of wisdom. And, [O mankind], do not make [as equal] with Allah another deity, lest you be thrown into Hell, blamed and banished.' },
  { surahId: 17, ayahNumber: 40, text: 'Then, has your Lord chosen you for [having] sons and taken from among the angels daughters? Indeed, you say a grave saying.' },
  { surahId: 17, ayahNumber: 41, text: 'And We have certainly diversified [the contents] in this Qur\'an that mankind may be reminded, but it does not increase the disbelievers except in aversion.' },
  { surahId: 17, ayahNumber: 42, text: 'Say, [O Muhammad], "If there had been with Him [other] gods, as they say, then they [each] would have sought to the Owner of the Throne a way."' },
  { surahId: 17, ayahNumber: 43, text: 'Exalted is He and high above what they say by great sublimity.' },
  { surahId: 17, ayahNumber: 44, text: 'The seven heavens and the earth and whatever is in them exalt Him. And there is not a thing except that it exalts [Allah] by His praise, but you do not understand their [way of] exalting. Indeed, He is ever Forbearing and Forgiving.' },
  { surahId: 17, ayahNumber: 45, text: 'And when you recite the Qur\'an, We put between you and those who do not believe in the Hereafter a concealed partition.' },
  { surahId: 17, ayahNumber: 46, text: 'And We have placed over their hearts coverings, lest they understand it, and in their ears deafness. And when you mention your Lord alone in the Qur\'an, they turn back in aversion.' },
  { surahId: 17, ayahNumber: 47, text: 'We are most knowing of how they listen to it when they listen to you and [of] when they are in private conversation, when the wrongdoers say, "You follow not but a man affected by magic."' },
  { surahId: 17, ayahNumber: 48, text: 'Look how they strike for you comparisons; but they have strayed, so they cannot [find] a way.' },
  { surahId: 17, ayahNumber: 49, text: 'And they say, "When we are bones and crumbled particles, will we [truly] be resurrected as a new creation?"' },
  { surahId: 17, ayahNumber: 50, text: 'Say, "Be you stones or iron' },
  { surahId: 17, ayahNumber: 51, text: 'Or [any] creation of that which is great within your breasts." And they will say, "Who will restore us?" Say, "He who brought you forth the first time." Then they will nod their heads toward you and say, "When is that?" Say, "Perhaps it will be soon -' },
  { surahId: 17, ayahNumber: 52, text: 'On the Day He will call you and you will respond with praise of Him and think that you had not remained [in the world] except for a little."' },
  { surahId: 17, ayahNumber: 53, text: 'And tell My servants to say that which is best. Indeed, Satan induces [dissension] among them. Indeed Satan is ever, to mankind, a clear enemy.' },
  { surahId: 17, ayahNumber: 54, text: 'Your Lord is most knowing of you. If He wills, He will have mercy upon you; or if He wills, He will punish you. And We have not sent you, [O Muhammad], over them as a manager.' },
  { surahId: 17, ayahNumber: 55, text: 'And your Lord is most knowing of whoever is in the heavens and the earth. And We have made some of the prophets exceed others [in various ways], and to David We gave the book [of Psalms].' },
  { surahId: 17, ayahNumber: 56, text: 'Say, "Invoke those you have claimed [as gods] besides Him, for they do not possess the [ability for] removal of adversity from you or [for its] transfer [to someone else]."' },
  { surahId: 17, ayahNumber: 57, text: 'Those whom they invoke seek means of access to their Lord, [striving as to] which of them would be nearest, and they hope for His mercy and fear His punishment. Indeed, the punishment of your Lord is ever feared.' },
  { surahId: 17, ayahNumber: 58, text: 'And there is no city but that We will destroy it before the Day of Resurrection or punish it with a severe punishment. That has ever been in the Register inscribed.' },
  { surahId: 17, ayahNumber: 59, text: 'And nothing has prevented Us from sending signs except that the former peoples denied them. And We gave Thamud the she-camel as a visible sign, but they wronged her. And We send not the signs except as a warning.' },
  { surahId: 17, ayahNumber: 60, text: 'And [remember, O Muhammad], when We told you, "Indeed, your Lord has encompassed the people." And We did not make the sight which We showed you except as a trial for the people, as was the accursed tree [mentioned] in the Qur\'an. And We threaten them, but it increases them not except in great transgression.' },
  { surahId: 17, ayahNumber: 61, text: 'And [mention] when We said to the angles, "Prostrate to Adam," and they prostrated, except for Iblees. He said, "Should I prostrate to one You created from clay?"' },
  { surahId: 17, ayahNumber: 62, text: '[Iblees] said, "Do You see this one whom You have honored above me? If You delay me until the Day of Resurrection, I will surely destroy his descendants, except for a few."' },
  { surahId: 17, ayahNumber: 63, text: '[Allah] said, "Go, for whoever of them follows you, indeed Hell will be the recompense of you - an ample recompense.' },
  { surahId: 17, ayahNumber: 64, text: 'And incite [to senselessness] whoever you can among them with your voice and assault them with your horses and foot soldiers and become a partner in their wealth and their children and promise them." But Satan does not promise them except delusion.' },
  { surahId: 17, ayahNumber: 65, text: 'Indeed, over My [believing] servants there is for you no authority. And sufficient is your Lord as Disposer of affairs.' },
  { surahId: 17, ayahNumber: 66, text: 'It is your Lord who drives the ship for you through the sea that you may seek of His bounty. Indeed, He is ever, to you, Merciful.' },
  { surahId: 17, ayahNumber: 67, text: 'And when adversity touches you at sea, lost are [all] those you invoke except for Him. But when He delivers you to the land, you turn away [from Him]. And ever is man ungrateful.' },
  { surahId: 17, ayahNumber: 68, text: 'Then do you feel secure that [instead] He will not cause a part of the land to swallow you or send against you a storm of stones? Then you would not find for yourselves an advocate.' },
  { surahId: 17, ayahNumber: 69, text: 'Or do you feel secure that He will not send you back into the sea another time and send upon you a hurricane of wind and drown you for what you denied? Then you would not find for yourselves against Us an avenger.' },
  { surahId: 17, ayahNumber: 70, text: 'And We have certainly honored the children of Adam and carried them on the land and sea and provided for them of the good things and preferred them over much of what We have created, with [definite] preference.' },
  { surahId: 17, ayahNumber: 71, text: '[Mention, O Muhammad], the Day We will call forth every people with their record [of deeds]. Then whoever is given his record in his right hand - those will read their records, and injustice will not be done to them, [even] as much as a thread [inside the date seed].' },
  { surahId: 17, ayahNumber: 72, text: 'And whoever is blind in this [life] will be blind in the Hereafter and more astray in way.' },
  { surahId: 17, ayahNumber: 73, text: 'And indeed, they were about to tempt you away from that which We revealed to you in order to [make] you invent about Us something else; and then they would have taken you as a friend.' },
  { surahId: 17, ayahNumber: 74, text: 'And if We had not strengthened you, you would have almost inclined to them a little.' },
  { surahId: 17, ayahNumber: 75, text: 'Then [if you had], We would have made you taste double [punishment in] life and double [after] death. Then you would not find for yourself against Us a helper.' },
  { surahId: 17, ayahNumber: 76, text: 'And indeed, they were about to drive you from the land to evict you therefrom. And then [when they do], they will not remain [there] after you, except for a little.' },
  { surahId: 17, ayahNumber: 77, text: '[That is Our] established way for those We had sent before you of Our messengers; and you will not find in Our way any alteration.' },
  { surahId: 17, ayahNumber: 78, text: 'Establish prayer at the decline of the sun [from its meridian] until the darkness of the night and [also] the Qur\'an of dawn. Indeed, the recitation of dawn is ever witnessed.' },
  { surahId: 17, ayahNumber: 79, text: 'And from [part of] the night, pray with it as additional [worship] for you; it is expected that your Lord will resurrect you to a praised station.' },
  { surahId: 17, ayahNumber: 80, text: 'And say, "My Lord, cause me to enter a sound entrance and to exit a sound exit and grant me from Yourself a supporting authority."' },
  { surahId: 17, ayahNumber: 81, text: 'And say, "Truth has come, and falsehood has departed. Indeed is falsehood, [by nature], ever bound to depart."' },
  { surahId: 17, ayahNumber: 82, text: 'And We send down of the Qur\'an that which is healing and mercy for the believers, but it does not increase the wrongdoers except in loss.' },
  { surahId: 17, ayahNumber: 83, text: 'And when We bestow favor upon the disbeliever, he turns away and distances himself; and when evil touches him, he is ever despairing.' },
  { surahId: 17, ayahNumber: 84, text: 'Say, "Each works according to his manner, but your Lord is most knowing of who is best guided in way."' },
  { surahId: 17, ayahNumber: 85, text: 'And they ask you, [O Muhammad], about the soul. Say, "The soul is of the affair of my Lord. And mankind have not been given of knowledge except a little."' },
  { surahId: 17, ayahNumber: 86, text: 'And if We willed, We could surely do away with that which We revealed to you. Then you would not find for yourself concerning it an advocate against Us.' },
  { surahId: 17, ayahNumber: 87, text: 'Except [We have left it with you] as a mercy from your Lord. Indeed, His favor upon you has ever been great.' },
  { surahId: 17, ayahNumber: 88, text: 'Say, "If mankind and the jinn gathered in order to produce the like of this Qur\'an, they could not produce the like of it, even if they were to each other assistants."' },
  { surahId: 17, ayahNumber: 89, text: 'And We have certainly diversified for the people in this Qur\'an from every [kind] of example, but most of the people refused [anything] except disbelief.' },
  { surahId: 17, ayahNumber: 90, text: 'And they say, "We will not believe you until you break open for us from the ground a spring.' },
  { surahId: 17, ayahNumber: 91, text: 'Or [until] you have a garden of palm tress and grapes and make rivers gush forth within them in force [and abundance]' },
  { surahId: 17, ayahNumber: 92, text: 'Or you make the heaven fall upon us in fragments as you have claimed or you bring Allah and the angels before [us]' },
  { surahId: 17, ayahNumber: 93, text: 'Or you have a house of gold or you ascend into the sky. And [even then], we will not believe in your ascension until you bring down to us a book we may read." Say, "Exalted is my Lord! Was I ever but a human messenger?"' },
  { surahId: 17, ayahNumber: 94, text: 'And what prevented the people from believing when guidance came to them except that they said, "Has Allah sent a human messenger?"' },
  { surahId: 17, ayahNumber: 95, text: 'Say, "If there were upon the earth angels walking securely, We would have sent down to them from the heaven an angel [as a] messenger."' },
  { surahId: 17, ayahNumber: 96, text: 'Say, "Sufficient is Allah as Witness between me and you. Indeed he is ever, concerning His servants, Acquainted and Seeing."' },
  { surahId: 17, ayahNumber: 97, text: 'And whoever Allah guides - he is the [rightly] guided; and whoever He sends astray - you will never find for them protectors besides Him, and We will gather them on the Day of Resurrection [fallen] on their faces - blind, dumb and deaf. Their refuge is Hell; every time it subsides We increase them in blazing fire.' },
  { surahId: 17, ayahNumber: 98, text: 'That is their recompense because they disbelieved in Our verses and said, "When we are bones and crumbled particles, will we [truly] be resurrected [in] a new creation?"' },
  { surahId: 17, ayahNumber: 99, text: 'Do they not see that Allah, who created the heavens and earth, is [the one] Able to create the likes of them? And He has appointed for them a term, about which there is no doubt. But the wrongdoers refuse [anything] except disbelief.' },
  { surahId: 17, ayahNumber: 100, text: 'Say [to them], "If you possessed the depositories of the mercy of my Lord, then you would withhold out of fear of spending." And ever has man been stingy.' },
  { surahId: 17, ayahNumber: 101, text: 'And We had certainly given Moses nine evident signs, so ask the Children of Israel [about] when he came to them and Pharaoh said to him, "Indeed I think, O Moses, that you are affected by magic."' },
  { surahId: 17, ayahNumber: 102, text: '[Moses] said, "You have already known that none has sent down these [signs] except the Lord of the heavens and the earth as evidence, and indeed I think, O Pharaoh, that you are destroyed."' },
  { surahId: 17, ayahNumber: 103, text: 'So he intended to drive them from the land, but We drowned him and those with him all together.' },
  { surahId: 17, ayahNumber: 104, text: 'And We said after Pharaoh to the Children of Israel, "Dwell in the land, and when there comes the promise of the Hereafter, We will bring you forth in [one] gathering."' },
  { surahId: 17, ayahNumber: 105, text: 'And with the truth We have sent the Qur\'an down, and with the truth it has descended. And We have not sent you, [O Muhammad], except as a bringer of good tidings and a warner.' },
  { surahId: 17, ayahNumber: 106, text: 'And [it is] a Qur\'an which We have separated [by intervals] that you might recite it to the people over a prolonged period. And We have sent it down progressively.' },
  { surahId: 17, ayahNumber: 107, text: 'Say, "Believe in it or do not believe. Indeed, those who were given knowledge before it - when it is recited to them, they fall upon their faces in prostration,' },
  { surahId: 17, ayahNumber: 108, text: 'And they say, "Exalted is our Lord! Indeed, the promise of our Lord has been fulfilled."' },
  { surahId: 17, ayahNumber: 109, text: 'And they fall upon their faces weeping, and the Qur\'an increases them in humble submission.' },
  { surahId: 17, ayahNumber: 110, text: 'Say, "Call upon Allah or call upon the Most Merciful. Whichever [name] you call - to Him belong the best names." And do not recite [too] loudly in your prayer or [too] quietly but seek between that an [intermediate] way.' },
  { surahId: 17, ayahNumber: 111, text: 'And say, "Praise to Allah, who has not taken a son and has had no partner in [His] dominion and has no [need of a] protector out of weakness; and glorify Him with [great] glorification."' },
  { surahId: 18, ayahNumber: 1, text: '[All] praise is [due] to Allah, who has sent down upon His Servant the Book and has not made therein any deviance.' },
  { surahId: 18, ayahNumber: 2, text: '[He has made it] straight, to warn of severe punishment from Him and to give good tidings to the believers who do righteous deeds that they will have a good reward' },
  { surahId: 18, ayahNumber: 3, text: 'In which they will remain forever' },
  { surahId: 18, ayahNumber: 4, text: 'And to warn those who say, "Allah has taken a son."' },
  { surahId: 18, ayahNumber: 5, text: 'They have no knowledge of it, nor had their fathers. Grave is the word that comes out of their mouths; they speak not except a lie.' },
  { surahId: 18, ayahNumber: 6, text: 'Then perhaps you would kill yourself through grief over them, [O Muhammad], if they do not believe in this message, [and] out of sorrow.' },
  { surahId: 18, ayahNumber: 7, text: 'Indeed, We have made that which is on the earth adornment for it that We may test them [as to] which of them is best in deed.' },
  { surahId: 18, ayahNumber: 8, text: 'And indeed, We will make that which is upon it [into] a barren ground.' },
  { surahId: 18, ayahNumber: 9, text: 'Or have you thought that the companions of the cave and the inscription were, among Our signs, a wonder?' },
  { surahId: 18, ayahNumber: 10, text: '[Mention] when the youths retreated to the cave and said, "Our Lord, grant us from Yourself mercy and prepare for us from our affair right guidance."' },
  { surahId: 18, ayahNumber: 11, text: 'So We cast [a cover of sleep] over their ears within the cave for a number of years.' },
  { surahId: 18, ayahNumber: 12, text: 'Then We awakened them that We might show which of the two factions was most precise in calculating what [extent] they had remained in time.' },
  { surahId: 18, ayahNumber: 13, text: 'It is We who relate to you, [O Muhammad], their story in truth. Indeed, they were youths who believed in their Lord, and We increased them in guidance.' },
  { surahId: 18, ayahNumber: 14, text: 'And We made firm their hearts when they stood up and said, "Our Lord is the Lord of the heavens and the earth. Never will we invoke besides Him any deity. We would have certainly spoken, then, an excessive transgression.' },
  { surahId: 18, ayahNumber: 15, text: 'These, our people, have taken besides Him deities. Why do they not bring for [worship of] them a clear authority? And who is more unjust than one who invents about Allah a lie?"' },
  { surahId: 18, ayahNumber: 16, text: '[The youths said to one another], "And when you have withdrawn from them and that which they worship other than Allah, retreat to the cave. Your Lord will spread out for you of His mercy and will prepare for you from your affair facility."' },
  { surahId: 18, ayahNumber: 17, text: 'And [had you been present], you would see the sun when it rose, inclining away from their cave on the right, and when it set, passing away from them on the left, while they were [laying] within an open space thereof. That was from the signs of Allah. He whom Allah guides is the [rightly] guided, but he whom He leaves astray - never will you find for him a protecting guide.' },
  { surahId: 18, ayahNumber: 18, text: 'And you would think them awake, while they were asleep. And We turned them to the right and to the left, while their dog stretched his forelegs at the entrance. If you had looked at them, you would have turned from them in flight and been filled by them with terror.' },
  { surahId: 18, ayahNumber: 19, text: 'And similarly, We awakened them that they might question one another. Said a speaker from among them, "How long have you remained [here]?" They said, "We have remained a day or part of a day." They said, "Your Lord is most knowing of how long you remained. So send one of you with this silver coin of yours to the city and let him look to which is the best of food and bring you provision from it and let him be cautious. And let no one be aware of you.' },
  { surahId: 18, ayahNumber: 20, text: 'Indeed, if they come to know of you, they will stone you or return you to their religion. And never would you succeed, then - ever."' },
  { surahId: 18, ayahNumber: 21, text: 'And similarly, We caused them to be found that they [who found them] would know that the promise of Allah is truth and that of the Hour there is no doubt. [That was] when they disputed among themselves about their affair and [then] said, "Construct over them a structure. Their Lord is most knowing about them." Said those who prevailed in the matter, "We will surely take [for ourselves] over them a masjid."' },
  { surahId: 18, ayahNumber: 22, text: 'They will say there were three, the fourth of them being their dog; and they will say there were five, the sixth of them being their dog - guessing at the unseen; and they will say there were seven, and the eighth of them was their dog. Say, [O Muhammad], "My Lord is most knowing of their number. None knows them except a few. So do not argue about them except with an obvious argument and do not inquire about them among [the speculators] from anyone."' },
  { surahId: 18, ayahNumber: 23, text: 'And never say of anything, "Indeed, I will do that tomorrow,"' },
  { surahId: 18, ayahNumber: 24, text: 'Except [when adding], "If Allah wills." And remember your Lord when you forget [it] and say, "Perhaps my Lord will guide me to what is nearer than this to right conduct."' },
  { surahId: 18, ayahNumber: 25, text: 'And they remained in their cave for three hundred years and exceeded by nine.' },
  { surahId: 18, ayahNumber: 26, text: 'Say, "Allah is most knowing of how long they remained. He has [knowledge of] the unseen [aspects] of the heavens and the earth. How Seeing is He and how Hearing! They have not besides Him any protector, and He shares not His legislation with anyone."' },
  { surahId: 18, ayahNumber: 27, text: 'And recite, [O Muhammad], what has been revealed to you of the Book of your Lord. There is no changer of His words, and never will you find in other than Him a refuge.' },
  { surahId: 18, ayahNumber: 28, text: 'And keep yourself patient [by being] with those who call upon their Lord in the morning and the evening, seeking His countenance. And let not your eyes pass beyond them, desiring adornments of the worldly life, and do not obey one whose heart We have made heedless of Our remembrance and who follows his desire and whose affair is ever [in] neglect.' },
  { surahId: 18, ayahNumber: 29, text: 'And say, "The truth is from your Lord, so whoever wills - let him believe; and whoever wills - let him disbelieve." Indeed, We have prepared for the wrongdoers a fire whose walls will surround them. And if they call for relief, they will be relieved with water like murky oil, which scalds [their] faces. Wretched is the drink, and evil is the resting place.' },
  { surahId: 18, ayahNumber: 30, text: 'Indeed, those who have believed and done righteous deeds - indeed, We will not allow to be lost the reward of any who did well in deeds.' },
  { surahId: 18, ayahNumber: 31, text: 'Those will have gardens of perpetual residence; beneath them rivers will flow. They will be adorned therein with bracelets of gold and will wear green garments of fine silk and brocade, reclining therein on adorned couches. Excellent is the reward, and good is the resting place.' },
  { surahId: 18, ayahNumber: 32, text: 'And present to them an example of two men: We granted to one of them two gardens of grapevines, and We bordered them with palm trees and placed between them [fields of] crops.' },
  { surahId: 18, ayahNumber: 33, text: 'Each of the two gardens produced its fruit and did not fall short thereof in anything. And We caused to gush forth within them a river.' },
  { surahId: 18, ayahNumber: 34, text: 'And he had fruit, so he said to his companion while he was conversing with him, "I am greater than you in wealth and mightier in [numbers of] men."' },
  { surahId: 18, ayahNumber: 35, text: 'And he entered his garden while he was unjust to himself. He said, "I do not think that this will perish - ever.' },
  { surahId: 18, ayahNumber: 36, text: 'And I do not think the Hour will occur. And even if I should be brought back to my Lord, I will surely find better than this as a return."' },
  { surahId: 18, ayahNumber: 37, text: 'His companion said to him while he was conversing with him, "Have you disbelieved in He who created you from dust and then from a sperm-drop and then proportioned you [as] a man?' },
  { surahId: 18, ayahNumber: 38, text: 'But as for me, He is Allah, my Lord, and I do not associate with my Lord anyone.' },
  { surahId: 18, ayahNumber: 39, text: 'And why did you, when you entered your garden, not say, \'What Allah willed [has occurred]; there is no power except in Allah \'? Although you see me less than you in wealth and children,' },
  { surahId: 18, ayahNumber: 40, text: 'It may be that my Lord will give me [something] better than your garden and will send upon it a calamity from the sky, and it will become a smooth, dusty ground,' },
  { surahId: 18, ayahNumber: 41, text: 'Or its water will become sunken [into the earth], so you would never be able to seek it."' },
  { surahId: 18, ayahNumber: 42, text: 'And his fruits were encompassed [by ruin], so he began to turn his hands about [in dismay] over what he had spent on it, while it had collapsed upon its trellises, and said, "Oh, I wish I had not associated with my Lord anyone."' },
  { surahId: 18, ayahNumber: 43, text: 'And there was for him no company to aid him other than Allah, nor could he defend himself.' },
  { surahId: 18, ayahNumber: 44, text: 'There the authority is [completely] for Allah, the Truth. He is best in reward and best in outcome.' },
  { surahId: 18, ayahNumber: 45, text: 'And present to them the example of the life of this world, [its being] like rain which We send down from the sky, and the vegetation of the earth mingles with it and [then] it becomes dry remnants, scattered by the winds. And Allah is ever, over all things, Perfect in Ability.' },
  { surahId: 18, ayahNumber: 46, text: 'Wealth and children are [but] adornment of the worldly life. But the enduring good deeds are better to your Lord for reward and better for [one\'s] hope.' },
  { surahId: 18, ayahNumber: 47, text: 'And [warn of] the Day when We will remove the mountains and you will see the earth prominent, and We will gather them and not leave behind from them anyone.' },
  { surahId: 18, ayahNumber: 48, text: 'And they will be presented before your Lord in rows, [and He will say], "You have certainly come to Us just as We created you the first time. But you claimed that We would never make for you an appointment."' },
  { surahId: 18, ayahNumber: 49, text: 'And the record [of deeds] will be placed [open], and you will see the criminals fearful of that within it, and they will say, "Oh, woe to us! What is this book that leaves nothing small or great except that it has enumerated it?" And they will find what they did present [before them]. And your Lord does injustice to no one.' },
  { surahId: 18, ayahNumber: 50, text: 'And [mention] when We said to the angels, "Prostrate to Adam," and they prostrated, except for Iblees. He was of the jinn and departed from the command of his Lord. Then will you take him and his descendants as allies other than Me while they are enemies to you? Wretched it is for the wrongdoers as an exchange.' },
  { surahId: 18, ayahNumber: 51, text: 'I did not make them witness to the creation of the heavens and the earth or to the creation of themselves, and I would not have taken the misguiders as assistants.' },
  { surahId: 18, ayahNumber: 52, text: 'And [warn of] the Day when He will say, "Call \'My partners\' whom you claimed," and they will invoke them, but they will not respond to them. And We will put between them [a valley of] destruction.' },
  { surahId: 18, ayahNumber: 53, text: 'And the criminals will see the Fire and will be certain that they are to fall therein. And they will not find from it a way elsewhere.' },
  { surahId: 18, ayahNumber: 54, text: 'And We have certainly diversified in this Qur\'an for the people from every [kind of] example; but man has ever been, most of anything, [prone to] dispute.' },
  { surahId: 18, ayahNumber: 55, text: 'And nothing has prevented the people from believing when guidance came to them and from asking forgiveness of their Lord except that there [must] befall them the [accustomed] precedent of the former peoples or that the punishment should come [directly] before them.' },
  { surahId: 18, ayahNumber: 56, text: 'And We send not the messengers except as bringers of good tidings and warners. And those who disbelieve dispute by [using] falsehood to [attempt to] invalidate thereby the truth and have taken My verses, and that of which they are warned, in ridicule.' },
  { surahId: 18, ayahNumber: 57, text: 'And who is more unjust than one who is reminded of the verses of his Lord but turns away from them and forgets what his hands have put forth? Indeed, We have placed over their hearts coverings, lest they understand it, and in their ears deafness. And if you invite them to guidance - they will never be guided, then - ever.' },
  { surahId: 18, ayahNumber: 58, text: 'And your Lord is the Forgiving, full of mercy. If He were to impose blame upon them for what they earned, He would have hastened for them the punishment. Rather, for them is an appointment from which they will never find an escape.' },
  { surahId: 18, ayahNumber: 59, text: 'And those cities - We destroyed them when they wronged, and We made for their destruction an appointed time.' },
  { surahId: 18, ayahNumber: 60, text: 'And [mention] when Moses said to his servant, "I will not cease [traveling] until I reach the junction of the two seas or continue for a long period."' },
  { surahId: 18, ayahNumber: 61, text: 'But when they reached the junction between them, they forgot their fish, and it took its course into the sea, slipping away.' },
  { surahId: 18, ayahNumber: 62, text: 'So when they had passed beyond it, [Moses] said to his boy, "Bring us our morning meal. We have certainly suffered in this, our journey, [much] fatigue."' },
  { surahId: 18, ayahNumber: 63, text: 'He said, "Did you see when we retired to the rock? Indeed, I forgot [there] the fish. And none made me forget it except Satan - that I should mention it. And it took its course into the sea amazingly".' },
  { surahId: 18, ayahNumber: 64, text: '[Moses] said, "That is what we were seeking." So they returned, following their footprints.' },
  { surahId: 18, ayahNumber: 65, text: 'And they found a servant from among Our servants to whom we had given mercy from us and had taught him from Us a [certain] knowledge.' },
  { surahId: 18, ayahNumber: 66, text: 'Moses said to him, "May I follow you on [the condition] that you teach me from what you have been taught of sound judgement?"' },
  { surahId: 18, ayahNumber: 67, text: 'He said, "Indeed, with me you will never be able to have patience.' },
  { surahId: 18, ayahNumber: 68, text: 'And how can you have patience for what you do not encompass in knowledge?"' },
  { surahId: 18, ayahNumber: 69, text: '[Moses] said, "You will find me, if Allah wills, patient, and I will not disobey you in [any] order."' },
  { surahId: 18, ayahNumber: 70, text: 'He said, "Then if you follow me, do not ask me about anything until I make to you about it mention."' },
  { surahId: 18, ayahNumber: 71, text: 'So they set out, until when they had embarked on the ship, al-Khidh r tore it open. [Moses] said, "Have you torn it open to drown its people? You have certainly done a grave thing."' },
  { surahId: 18, ayahNumber: 72, text: '[Al-Khidh r] said, "Did I not say that with me you would never be able to have patience?"' },
  { surahId: 18, ayahNumber: 73, text: '[Moses] said, "Do not blame me for what I forgot and do not cover me in my matter with difficulty."' },
  { surahId: 18, ayahNumber: 74, text: 'So they set out, until when they met a boy, al-Khidh r killed him. [Moses] said, "Have you killed a pure soul for other than [having killed] a soul? You have certainly done a deplorable thing."' },
  { surahId: 18, ayahNumber: 75, text: '[Al-Khidh r] said, "Did I not tell you that with me you would never be able to have patience?"' },
  { surahId: 18, ayahNumber: 76, text: '[Moses] said, "If I should ask you about anything after this, then do not keep me as a companion. You have obtained from me an excuse."' },
  { surahId: 18, ayahNumber: 77, text: 'So they set out, until when they came to the people of a town, they asked its people for food, but they refused to offer them hospitality. And they found therein a wall about to collapse, so al-Khidh r restored it. [Moses] said, "If you wished, you could have taken for it a payment."' },
  { surahId: 18, ayahNumber: 78, text: '[Al-Khidh r] said, "This is parting between me and you. I will inform you of the interpretation of that about which you could not have patience.' },
  { surahId: 18, ayahNumber: 79, text: 'As for the ship, it belonged to poor people working at sea. So I intended to cause defect in it as there was after them a king who seized every [good] ship by force.' },
  { surahId: 18, ayahNumber: 80, text: 'And as for the boy, his parents were believers, and we feared that he would overburden them by transgression and disbelief.' },
  { surahId: 18, ayahNumber: 81, text: 'So we intended that their Lord should substitute for them one better than him in purity and nearer to mercy.' },
  { surahId: 18, ayahNumber: 82, text: 'And as for the wall, it belonged to two orphan boys in the city, and there was beneath it a treasure for them, and their father had been righteous. So your Lord intended that they reach maturity and extract their treasure, as a mercy from your Lord. And I did it not of my own accord. That is the interpretation of that about which you could not have patience."' },
  { surahId: 18, ayahNumber: 83, text: 'And they ask you, [O Muhammad], about Dhul-Qarnayn. Say, "I will recite to you about him a report."' },
  { surahId: 18, ayahNumber: 84, text: 'Indeed We established him upon the earth, and We gave him to everything a way.' },
  { surahId: 18, ayahNumber: 85, text: 'So he followed a way' },
  { surahId: 18, ayahNumber: 86, text: 'Until, when he reached the setting of the sun, he found it [as if] setting in a spring of dark mud, and he found near it a people. Allah said, "O Dhul-Qarnayn, either you punish [them] or else adopt among them [a way of] goodness."' },
  { surahId: 18, ayahNumber: 87, text: 'He said, "As for one who wrongs, we will punish him. Then he will be returned to his Lord, and He will punish him with a terrible punishment.' },
  { surahId: 18, ayahNumber: 88, text: 'But as for one who believes and does righteousness, he will have a reward of Paradise, and we will speak to him from our command with ease."' },
  { surahId: 18, ayahNumber: 89, text: 'Then he followed a way' },
  { surahId: 18, ayahNumber: 90, text: 'Until, when he came to the rising of the sun, he found it rising on a people for whom We had not made against it any shield.' },
  { surahId: 18, ayahNumber: 91, text: 'Thus. And We had encompassed [all] that he had in knowledge.' },
  { surahId: 18, ayahNumber: 92, text: 'Then he followed a way' },
  { surahId: 18, ayahNumber: 93, text: 'Until, when he reached [a pass] between two mountains, he found beside them a people who could hardly understand [his] speech.' },
  { surahId: 18, ayahNumber: 94, text: 'They said, "O Dhul-Qarnayn, indeed Gog and Magog are [great] corrupters in the land. So may we assign for you an expenditure that you might make between us and them a barrier?"' },
  { surahId: 18, ayahNumber: 95, text: 'He said, "That in which my Lord has established me is better [than what you offer], but assist me with strength; I will make between you and them a dam.' },
  { surahId: 18, ayahNumber: 96, text: 'Bring me sheets of iron" - until, when he had leveled [them] between the two mountain walls, he said, "Blow [with bellows]," until when he had made it [like] fire, he said, "Bring me, that I may pour over it molten copper."' },
  { surahId: 18, ayahNumber: 97, text: 'So Gog and Magog were unable to pass over it, nor were they able [to effect] in it any penetration.' },
  { surahId: 18, ayahNumber: 98, text: '[Dhul-Qarnayn] said, "This is a mercy from my Lord; but when the promise of my Lord comes, He will make it level, and ever is the promise of my Lord true."' },
  { surahId: 18, ayahNumber: 99, text: 'And We will leave them that day surging over each other, and [then] the Horn will be blown, and We will assemble them in [one] assembly.' },
  { surahId: 18, ayahNumber: 100, text: 'And We will present Hell that Day to the Disbelievers, on display -' },
  { surahId: 18, ayahNumber: 101, text: 'Those whose eyes had been within a cover [removed] from My remembrance, and they were not able to hear.' },
  { surahId: 18, ayahNumber: 102, text: 'Then do those who disbelieve think that they can take My servants instead of Me as allies? Indeed, We have prepared Hell for the disbelievers as a lodging.' },
  { surahId: 18, ayahNumber: 103, text: 'Say, [O Muhammad], "Shall we [believers] inform you of the greatest losers as to [their] deeds?' },
  { surahId: 18, ayahNumber: 104, text: '[They are] those whose effort is lost in worldly life, while they think that they are doing well in work."' },
  { surahId: 18, ayahNumber: 105, text: 'Those are the ones who disbelieve in the verses of their Lord and in [their] meeting Him, so their deeds have become worthless; and We will not assign to them on the Day of Resurrection any importance.' },
  { surahId: 18, ayahNumber: 106, text: 'That is their recompense - Hell - for what they denied and [because] they took My signs and My messengers in ridicule.' },
  { surahId: 18, ayahNumber: 107, text: 'Indeed, those who have believed and done righteous deeds - they will have the Gardens of Paradise as a lodging,' },
  { surahId: 18, ayahNumber: 108, text: 'Wherein they abide eternally. They will not desire from it any transfer.' },
  { surahId: 18, ayahNumber: 109, text: 'Say, "If the sea were ink for [writing] the words of my Lord, the sea would be exhausted before the words of my Lord were exhausted, even if We brought the like of it as a supplement."' },
  { surahId: 18, ayahNumber: 110, text: 'Say, "I am only a man like you, to whom has been revealed that your god is one God. So whoever would hope for the meeting with his Lord - let him do righteous work and not associate in the worship of his Lord anyone."' },
  { surahId: 19, ayahNumber: 1, text: 'Kaf, Ha, Ya, \'Ayn, Sad.' },
  { surahId: 19, ayahNumber: 2, text: '[This is] a mention of the mercy of your Lord to His servant Zechariah' },
  { surahId: 19, ayahNumber: 3, text: 'When he called to his Lord a private supplication.' },
  { surahId: 19, ayahNumber: 4, text: 'He said, "My Lord, indeed my bones have weakened, and my head has filled with white, and never have I been in my supplication to You, my Lord, unhappy.' },
  { surahId: 19, ayahNumber: 5, text: 'And indeed, I fear the successors after me, and my wife has been barren, so give me from Yourself an heir' },
  { surahId: 19, ayahNumber: 6, text: 'Who will inherit me and inherit from the family of Jacob. And make him, my Lord, pleasing [to You]."' },
  { surahId: 19, ayahNumber: 7, text: '[He was told], "O Zechariah, indeed We give you good tidings of a boy whose name will be John. We have not assigned to any before [this] name."' },
  { surahId: 19, ayahNumber: 8, text: 'He said, "My Lord, how will I have a boy when my wife has been barren and I have reached extreme old age?"' },
  { surahId: 19, ayahNumber: 9, text: '[An angel] said, "Thus [it will be]; your Lord says, \'It is easy for Me, for I created you before, while you were nothing.\' "' },
  { surahId: 19, ayahNumber: 10, text: '[Zechariah] said, "My Lord, make for me a sign." He said, "Your sign is that you will not speak to the people for three nights, [being] sound."' },
  { surahId: 19, ayahNumber: 11, text: 'So he came out to his people from the prayer chamber and signaled to them to exalt [Allah] in the morning and afternoon.' },
  { surahId: 19, ayahNumber: 12, text: '[Allah] said, "O John, take the Scripture with determination." And We gave him judgement [while yet] a boy' },
  { surahId: 19, ayahNumber: 13, text: 'And affection from Us and purity, and he was fearing of Allah' },
  { surahId: 19, ayahNumber: 14, text: 'And dutiful to his parents, and he was not a disobedient tyrant.' },
  { surahId: 19, ayahNumber: 15, text: 'And peace be upon him the day he was born and the day he dies and the day he is raised alive.' },
  { surahId: 19, ayahNumber: 16, text: 'And mention, [O Muhammad], in the Book [the story of] Mary, when she withdrew from her family to a place toward the east.' },
  { surahId: 19, ayahNumber: 17, text: 'And she took, in seclusion from them, a screen. Then We sent to her Our Angel, and he represented himself to her as a well-proportioned man.' },
  { surahId: 19, ayahNumber: 18, text: 'She said, "Indeed, I seek refuge in the Most Merciful from you, [so leave me], if you should be fearing of Allah."' },
  { surahId: 19, ayahNumber: 19, text: 'He said, "I am only the messenger of your Lord to give you [news of] a pure boy."' },
  { surahId: 19, ayahNumber: 20, text: 'She said, "How can I have a boy while no man has touched me and I have not been unchaste?"' },
  { surahId: 19, ayahNumber: 21, text: 'He said, "Thus [it will be]; your Lord says, \'It is easy for Me, and We will make him a sign to the people and a mercy from Us. And it is a matter [already] decreed.\' "' },
  { surahId: 19, ayahNumber: 22, text: 'So she conceived him, and she withdrew with him to a remote place.' },
  { surahId: 19, ayahNumber: 23, text: 'And the pains of childbirth drove her to the trunk of a palm tree. She said, "Oh, I wish I had died before this and was in oblivion, forgotten."' },
  { surahId: 19, ayahNumber: 24, text: 'But he called her from below her, "Do not grieve; your Lord has provided beneath you a stream.' },
  { surahId: 19, ayahNumber: 25, text: 'And shake toward you the trunk of the palm tree; it will drop upon you ripe, fresh dates.' },
  { surahId: 19, ayahNumber: 26, text: 'So eat and drink and be contented. And if you see from among humanity anyone, say, \'Indeed, I have vowed to the Most Merciful abstention, so I will not speak today to [any] man.\' "' },
  { surahId: 19, ayahNumber: 27, text: 'Then she brought him to her people, carrying him. They said, "O Mary, you have certainly done a thing unprecedented.' },
  { surahId: 19, ayahNumber: 28, text: 'O sister of Aaron, your father was not a man of evil, nor was your mother unchaste."' },
  { surahId: 19, ayahNumber: 29, text: 'So she pointed to him. They said, "How can we speak to one who is in the cradle a child?"' },
  { surahId: 19, ayahNumber: 30, text: '[Jesus] said, "Indeed, I am the servant of Allah. He has given me the Scripture and made me a prophet.' },
  { surahId: 19, ayahNumber: 31, text: 'And He has made me blessed wherever I am and has enjoined upon me prayer and zakah as long as I remain alive' },
  { surahId: 19, ayahNumber: 32, text: 'And [made me] dutiful to my mother, and He has not made me a wretched tyrant.' },
  { surahId: 19, ayahNumber: 33, text: 'And peace is on me the day I was born and the day I will die and the day I am raised alive."' },
  { surahId: 19, ayahNumber: 34, text: 'That is Jesus, the son of Mary - the word of truth about which they are in dispute.' },
  { surahId: 19, ayahNumber: 35, text: 'It is not [befitting] for Allah to take a son; exalted is He! When He decrees an affair, He only says to it, "Be," and it is.' },
  { surahId: 19, ayahNumber: 36, text: '[Jesus said], "And indeed, Allah is my Lord and your Lord, so worship Him. That is a straight path."' },
  { surahId: 19, ayahNumber: 37, text: 'Then the factions differed [concerning Jesus] from among them, so woe to those who disbelieved - from the scene of a tremendous Day.' },
  { surahId: 19, ayahNumber: 38, text: 'How [clearly] they will hear and see the Day they come to Us, but the wrongdoers today are in clear error.' },
  { surahId: 19, ayahNumber: 39, text: 'And warn them, [O Muhammad], of the Day of Regret, when the matter will be concluded; and [yet], they are in [a state of] heedlessness, and they do not believe.' },
  { surahId: 19, ayahNumber: 40, text: 'Indeed, it is We who will inherit the earth and whoever is on it, and to Us they will be returned.' },
  { surahId: 19, ayahNumber: 41, text: 'And mention in the Book [the story of] Abraham. Indeed, he was a man of truth and a prophet.' },
  { surahId: 19, ayahNumber: 42, text: '[Mention] when he said to his father, "O my father, why do you worship that which does not hear and does not see and will not benefit you at all?' },
  { surahId: 19, ayahNumber: 43, text: 'O my father, indeed there has come to me of knowledge that which has not come to you, so follow me; I will guide you to an even path.' },
  { surahId: 19, ayahNumber: 44, text: 'O my father, do not worship Satan. Indeed Satan has ever been, to the Most Merciful, disobedient.' },
  { surahId: 19, ayahNumber: 45, text: 'O my father, indeed I fear that there will touch you a punishment from the Most Merciful so you would be to Satan a companion [in Hellfire]."' },
  { surahId: 19, ayahNumber: 46, text: '[His father] said, "Have you no desire for my gods, O Abraham? If you do not desist, I will surely stone you, so avoid me a prolonged time."' },
  { surahId: 19, ayahNumber: 47, text: '[Abraham] said, "Peace will be upon you. I will ask forgiveness for you of my Lord. Indeed, He is ever gracious to me.' },
  { surahId: 19, ayahNumber: 48, text: 'And I will leave you and those you invoke other than Allah and will invoke my Lord. I expect that I will not be in invocation to my Lord unhappy."' },
  { surahId: 19, ayahNumber: 49, text: 'So when he had left them and those they worshipped other than Allah, We gave him Isaac and Jacob, and each [of them] We made a prophet.' },
  { surahId: 19, ayahNumber: 50, text: 'And We gave them of Our mercy, and we made for them a reputation of high honor.' },
  { surahId: 19, ayahNumber: 51, text: 'And mention in the Book, Moses. Indeed, he was chosen, and he was a messenger and a prophet.' },
  { surahId: 19, ayahNumber: 52, text: 'And We called him from the side of the mount at [his] right and brought him near, confiding [to him].' },
  { surahId: 19, ayahNumber: 53, text: 'And We gave him out of Our mercy his brother Aaron as a prophet.' },
  { surahId: 19, ayahNumber: 54, text: 'And mention in the Book, Ishmael. Indeed, he was true to his promise, and he was a messenger and a prophet.' },
  { surahId: 19, ayahNumber: 55, text: 'And he used to enjoin on his people prayer and zakah and was to his Lord pleasing.' },
  { surahId: 19, ayahNumber: 56, text: 'And mention in the Book, Idrees. Indeed, he was a man of truth and a prophet.' },
  { surahId: 19, ayahNumber: 57, text: 'And We raised him to a high station.' },
  { surahId: 19, ayahNumber: 58, text: 'Those were the ones upon whom Allah bestowed favor from among the prophets of the descendants of Adam and of those We carried [in the ship] with Noah, and of the descendants of Abraham and Israel, and of those whom We guided and chose. When the verses of the Most Merciful were recited to them, they fell in prostration and weeping.' },
  { surahId: 19, ayahNumber: 59, text: 'But there came after them successors who neglected prayer and pursued desires; so they are going to meet evil -' },
  { surahId: 19, ayahNumber: 60, text: 'Except those who repent, believe and do righteousness; for those will enter Paradise and will not be wronged at all.' },
  { surahId: 19, ayahNumber: 61, text: '[Therein are] gardens of perpetual residence which the Most Merciful has promised His servants in the unseen. Indeed, His promise has ever been coming.' },
  { surahId: 19, ayahNumber: 62, text: 'They will not hear therein any ill speech - only [greetings of] peace - and they will have their provision therein, morning and afternoon.' },
  { surahId: 19, ayahNumber: 63, text: 'That is Paradise, which We give as inheritance to those of Our servants who were fearing of Allah.' },
  { surahId: 19, ayahNumber: 64, text: '[Gabriel said], "And we [angels] descend not except by the order of your Lord. To Him belongs that before us and that behind us and what is in between. And never is your Lord forgetful -' },
  { surahId: 19, ayahNumber: 65, text: 'Lord of the heavens and the earth and whatever is between them - so worship Him and have patience for His worship. Do you know of any similarity to Him?"' },
  { surahId: 19, ayahNumber: 66, text: 'And the disbeliever says, "When I have died, am I going to be brought forth alive?"' },
  { surahId: 19, ayahNumber: 67, text: 'Does man not remember that We created him before, while he was nothing?' },
  { surahId: 19, ayahNumber: 68, text: 'So by your Lord, We will surely gather them and the devils; then We will bring them to be present around Hell upon their knees.' },
  { surahId: 19, ayahNumber: 69, text: 'Then We will surely extract from every sect those of them who were worst against the Most Merciful in insolence.' },
  { surahId: 19, ayahNumber: 70, text: 'Then, surely it is We who are most knowing of those most worthy of burning therein.' },
  { surahId: 19, ayahNumber: 71, text: 'And there is none of you except he will come to it. This is upon your Lord an inevitability decreed.' },
  { surahId: 19, ayahNumber: 72, text: 'Then We will save those who feared Allah and leave the wrongdoers within it, on their knees.' },
  { surahId: 19, ayahNumber: 73, text: 'And when Our verses are recited to them as clear evidences, those who disbelieve say to those who believe, "Which of [our] two parties is best in position and best in association?"' },
  { surahId: 19, ayahNumber: 74, text: 'And how many a generation have We destroyed before them who were better in possessions and [outward] appearance?' },
  { surahId: 19, ayahNumber: 75, text: 'Say, "Whoever is in error - let the Most Merciful extend for him an extension [in wealth and time] until, when they see that which they were promised - either punishment [in this world] or the Hour [of resurrection] - they will come to know who is worst in position and weaker in soldiers."' },
  { surahId: 19, ayahNumber: 76, text: 'And Allah increases those who were guided, in guidance, and the enduring good deeds are better to your Lord for reward and better for recourse.' },
  { surahId: 19, ayahNumber: 77, text: 'Then, have you seen he who disbelieved in Our verses and said, "I will surely be given wealth and children [in the next life]?"' },
  { surahId: 19, ayahNumber: 78, text: 'Has he looked into the unseen, or has he taken from the Most Merciful a promise?' },
  { surahId: 19, ayahNumber: 79, text: 'No! We will record what he says and extend for him from the punishment extensively.' },
  { surahId: 19, ayahNumber: 80, text: 'And We will inherit him [in] what he mentions, and he will come to Us alone.' },
  { surahId: 19, ayahNumber: 81, text: 'And they have taken besides Allah [false] deities that they would be for them [a source of] honor.' },
  { surahId: 19, ayahNumber: 82, text: 'No! Those "gods" will deny their worship of them and will be against them opponents [on the Day of Judgement].' },
  { surahId: 19, ayahNumber: 83, text: 'Do you not see that We have sent the devils upon the disbelievers, inciting them to [evil] with [constant] incitement?' },
  { surahId: 19, ayahNumber: 84, text: 'So be not impatient over them. We only count out to them a [limited] number.' },
  { surahId: 19, ayahNumber: 85, text: 'On the Day We will gather the righteous to the Most Merciful as a delegation' },
  { surahId: 19, ayahNumber: 86, text: 'And will drive the criminals to Hell in thirst' },
  { surahId: 19, ayahNumber: 87, text: 'None will have [power of] intercession except he who had taken from the Most Merciful a covenant.' },
  { surahId: 19, ayahNumber: 88, text: 'And they say, "The Most Merciful has taken [for Himself] a son."' },
  { surahId: 19, ayahNumber: 89, text: 'You have done an atrocious thing.' },
  { surahId: 19, ayahNumber: 90, text: 'The heavens almost rupture therefrom and the earth splits open and the mountains collapse in devastation' },
  { surahId: 19, ayahNumber: 91, text: 'That they attribute to the Most Merciful a son.' },
  { surahId: 19, ayahNumber: 92, text: 'And it is not appropriate for the Most Merciful that He should take a son.' },
  { surahId: 19, ayahNumber: 93, text: 'There is no one in the heavens and earth but that he comes to the Most Merciful as a servant.' },
  { surahId: 19, ayahNumber: 94, text: 'He has enumerated them and counted them a [full] counting.' },
  { surahId: 19, ayahNumber: 95, text: 'And all of them are coming to Him on the Day of Resurrection alone.' },
  { surahId: 19, ayahNumber: 96, text: 'Indeed, those who have believed and done righteous deeds - the Most Merciful will appoint for them affection.' },
  { surahId: 19, ayahNumber: 97, text: 'So, [O Muhammad], We have only made Qur\'an easy in the Arabic language that you may give good tidings thereby to the righteous and warn thereby a hostile people.' },
  { surahId: 19, ayahNumber: 98, text: 'And how many have We destroyed before them of generations? Do you perceive of them anyone or hear from them a sound?' },
  { surahId: 20, ayahNumber: 1, text: 'Ta, Ha.' },
  { surahId: 20, ayahNumber: 2, text: 'We have not sent down to you the Qur\'an that you be distressed' },
  { surahId: 20, ayahNumber: 3, text: 'But only as a reminder for those who fear [Allah] -' },
  { surahId: 20, ayahNumber: 4, text: 'A revelation from He who created the earth and highest heavens,' },
  { surahId: 20, ayahNumber: 5, text: 'The Most Merciful [who is] above the Throne established.' },
  { surahId: 20, ayahNumber: 6, text: 'To Him belongs what is in the heavens and what is on the earth and what is between them and what is under the soil.' },
  { surahId: 20, ayahNumber: 7, text: 'And if you speak aloud - then indeed, He knows the secret and what is [even] more hidden.' },
  { surahId: 20, ayahNumber: 8, text: 'Allah - there is no deity except Him. To Him belong the best names.' },
  { surahId: 20, ayahNumber: 9, text: 'And has the story of Moses reached you? -' },
  { surahId: 20, ayahNumber: 10, text: 'When he saw a fire and said to his family, "Stay here; indeed, I have perceived a fire; perhaps I can bring you a torch or find at the fire some guidance."' },
  { surahId: 20, ayahNumber: 11, text: 'And when he came to it, he was called, "O Moses,' },
  { surahId: 20, ayahNumber: 12, text: 'Indeed, I am your Lord, so remove your sandals. Indeed, you are in the sacred valley of Tuwa.' },
  { surahId: 20, ayahNumber: 13, text: 'And I have chosen you, so listen to what is revealed [to you].' },
  { surahId: 20, ayahNumber: 14, text: 'Indeed, I am Allah. There is no deity except Me, so worship Me and establish prayer for My remembrance.' },
  { surahId: 20, ayahNumber: 15, text: 'Indeed, the Hour is coming - I almost conceal it - so that every soul may be recompensed according to that for which it strives.' },
  { surahId: 20, ayahNumber: 16, text: 'So do not let one avert you from it who does not believe in it and follows his desire, for you [then] would perish.' },
  { surahId: 20, ayahNumber: 17, text: 'And what is that in your right hand, O Moses?"' },
  { surahId: 20, ayahNumber: 18, text: 'He said, "It is my staff; I lean upon it, and I bring down leaves for my sheep and I have therein other uses."' },
  { surahId: 20, ayahNumber: 19, text: '[Allah] said, "Throw it down, O Moses."' },
  { surahId: 20, ayahNumber: 20, text: 'So he threw it down, and thereupon it was a snake, moving swiftly.' },
  { surahId: 20, ayahNumber: 21, text: '[Allah] said, "Seize it and fear not; We will return it to its former condition.' },
  { surahId: 20, ayahNumber: 22, text: 'And draw in your hand to your side; it will come out white without disease - another sign,' },
  { surahId: 20, ayahNumber: 23, text: 'That We may show you [some] of Our greater signs.' },
  { surahId: 20, ayahNumber: 24, text: 'Go to Pharaoh. Indeed, he has transgressed."' },
  { surahId: 20, ayahNumber: 25, text: '[Moses] said, "My Lord, expand for me my breast [with assurance]' },
  { surahId: 20, ayahNumber: 26, text: 'And ease for me my task' },
  { surahId: 20, ayahNumber: 27, text: 'And untie the knot from my tongue' },
  { surahId: 20, ayahNumber: 28, text: 'That they may understand my speech.' },
  { surahId: 20, ayahNumber: 29, text: 'And appoint for me a minister from my family -' },
  { surahId: 20, ayahNumber: 30, text: 'Aaron, my brother.' },
  { surahId: 20, ayahNumber: 31, text: 'Increase through him my strength' },
  { surahId: 20, ayahNumber: 32, text: 'And let him share my task' },
  { surahId: 20, ayahNumber: 33, text: 'That we may exalt You much' },
  { surahId: 20, ayahNumber: 34, text: 'And remember You much.' },
  { surahId: 20, ayahNumber: 35, text: 'Indeed, You are of us ever Seeing."' },
  { surahId: 20, ayahNumber: 36, text: '[Allah] said, "You have been granted your request, O Moses.' },
  { surahId: 20, ayahNumber: 37, text: 'And We had already conferred favor upon you another time,' },
  { surahId: 20, ayahNumber: 38, text: 'When We inspired to your mother what We inspired,' },
  { surahId: 20, ayahNumber: 39, text: '[Saying], \'Cast him into the chest and cast it into the river, and the river will throw it onto the bank; there will take him an enemy to Me and an enemy to him.\' And I bestowed upon you love from Me that you would be brought up under My eye.' },
  { surahId: 20, ayahNumber: 40, text: '[And We favored you] when your sister went and said, \'Shall I direct you to someone who will be responsible for him?\' So We restored you to your mother that she might be content and not grieve. And you killed someone, but We saved you from retaliation and tried you with a [severe] trial. And you remained [some] years among the people of Madyan. Then you came [here] at the decreed time, O Moses.' },
  { surahId: 20, ayahNumber: 41, text: 'And I produced you for Myself.' },
  { surahId: 20, ayahNumber: 42, text: 'Go, you and your brother, with My signs and do not slacken in My remembrance.' },
  { surahId: 20, ayahNumber: 43, text: 'Go, both of you, to Pharaoh. Indeed, he has transgressed.' },
  { surahId: 20, ayahNumber: 44, text: 'And speak to him with gentle speech that perhaps he may be reminded or fear [Allah]."' },
  { surahId: 20, ayahNumber: 45, text: 'They said, "Our Lord, indeed we are afraid that he will hasten [punishment] against us or that he will transgress."' },
  { surahId: 20, ayahNumber: 46, text: '[Allah] said, "Fear not. Indeed, I am with you both; I hear and I see.' },
  { surahId: 20, ayahNumber: 47, text: 'So go to him and say, \'Indeed, we are messengers of your Lord, so send with us the Children of Israel and do not torment them. We have come to you with a sign from your Lord. And peace will be upon he who follows the guidance.' },
  { surahId: 20, ayahNumber: 48, text: 'Indeed, it has been revealed to us that the punishment will be upon whoever denies and turns away.\' "' },
  { surahId: 20, ayahNumber: 49, text: '[Pharaoh] said, "So who is the Lord of you two, O Moses?"' },
  { surahId: 20, ayahNumber: 50, text: 'He said, "Our Lord is He who gave each thing its form and then guided [it]."' },
  { surahId: 20, ayahNumber: 51, text: '[Pharaoh] said, "Then what is the case of the former generations?"' },
  { surahId: 20, ayahNumber: 52, text: '[Moses] said, "The knowledge thereof is with my Lord in a record. My Lord neither errs nor forgets."' },
  { surahId: 20, ayahNumber: 53, text: '[It is He] who has made for you the earth as a bed [spread out] and inserted therein for you roadways and sent down from the sky, rain and produced thereby categories of various plants.' },
  { surahId: 20, ayahNumber: 54, text: 'Eat [therefrom] and pasture your livestock. Indeed, in that are signs for those of intelligence.' },
  { surahId: 20, ayahNumber: 55, text: 'From the earth We created you, and into it We will return you, and from it We will extract you another time.' },
  { surahId: 20, ayahNumber: 56, text: 'And We certainly showed Pharaoh Our signs - all of them - but he denied and refused.' },
  { surahId: 20, ayahNumber: 57, text: 'He said, "Have you come to us to drive us out of our land with your magic, O Moses?' },
  { surahId: 20, ayahNumber: 58, text: 'Then we will surely bring you magic like it, so make between us and you an appointment, which we will not fail to keep and neither will you, in a place assigned."' },
  { surahId: 20, ayahNumber: 59, text: '[Moses] said, "Your appointment is on the day of the festival when the people assemble at mid-morning."' },
  { surahId: 20, ayahNumber: 60, text: 'So Pharaoh went away, put together his plan, and then came [to Moses].' },
  { surahId: 20, ayahNumber: 61, text: 'Moses said to the magicians summoned by Pharaoh, "Woe to you! Do not invent a lie against Allah or He will exterminate you with a punishment; and he has failed who invents [such falsehood]."' },
  { surahId: 20, ayahNumber: 62, text: 'So they disputed over their affair among themselves and concealed their private conversation.' },
  { surahId: 20, ayahNumber: 63, text: 'They said, "Indeed, these are two magicians who want to drive you out of your land with their magic and do away with your most exemplary way.' },
  { surahId: 20, ayahNumber: 64, text: 'So resolve upon your plan and then come [forward] in line. And he has succeeded today who overcomes."' },
  { surahId: 20, ayahNumber: 65, text: 'They said, "O Moses, either you throw or we will be the first to throw."' },
  { surahId: 20, ayahNumber: 66, text: 'He said, "Rather, you throw." And suddenly their ropes and staffs seemed to him from their magic that they were moving [like snakes].' },
  { surahId: 20, ayahNumber: 67, text: 'And he sensed within himself apprehension, did Moses.' },
  { surahId: 20, ayahNumber: 68, text: 'Allah said, "Fear not. Indeed, it is you who are superior.' },
  { surahId: 20, ayahNumber: 69, text: 'And throw what is in your right hand; it will swallow up what they have crafted. What they have crafted is but the trick of a magician, and the magician will not succeed wherever he is."' },
  { surahId: 20, ayahNumber: 70, text: 'So the magicians fell down in prostration. They said, "We have believed in the Lord of Aaron and Moses."' },
  { surahId: 20, ayahNumber: 71, text: '[Pharaoh] said, "You believed him before I gave you permission. Indeed, he is your leader who has taught you magic. So I will surely cut off your hands and your feet on opposite sides, and I will crucify you on the trunks of palm trees, and you will surely know which of us is more severe in [giving] punishment and more enduring."' },
  { surahId: 20, ayahNumber: 72, text: 'They said, "Never will we prefer you over what has come to us of clear proofs and [over] He who created us. So decree whatever you are to decree. You can only decree for this worldly life.' },
  { surahId: 20, ayahNumber: 73, text: 'Indeed, we have believed in our Lord that He may forgive us our sins and what you compelled us [to do] of magic. And Allah is better and more enduring."' },
  { surahId: 20, ayahNumber: 74, text: 'Indeed, whoever comes to his Lord as a criminal - indeed, for him is Hell; he will neither die therein nor live.' },
  { surahId: 20, ayahNumber: 75, text: 'But whoever comes to Him as a believer having done righteous deeds - for those will be the highest degrees [in position]:' },
  { surahId: 20, ayahNumber: 76, text: 'Gardens of perpetual residence beneath which rivers flow, wherein they abide eternally. And that is the reward of one who purifies himself.' },
  { surahId: 20, ayahNumber: 77, text: 'And We had inspired to Moses, "Travel by night with My servants and strike for them a dry path through the sea; you will not fear being overtaken [by Pharaoh] nor be afraid [of drowning]."' },
  { surahId: 20, ayahNumber: 78, text: 'So Pharaoh pursued them with his soldiers, and there covered them from the sea that which covered them,' },
  { surahId: 20, ayahNumber: 79, text: 'And Pharaoh led his people astray and did not guide [them].' },
  { surahId: 20, ayahNumber: 80, text: 'O Children of Israel, We delivered you from your enemy, and We made an appointment with you at the right side of the mount, and We sent down to you manna and quails,' },
  { surahId: 20, ayahNumber: 81, text: '[Saying], "Eat from the good things with which We have provided you and do not transgress [or oppress others] therein, lest My anger should descend upon you. And he upon whom My anger descends has certainly fallen."' },
  { surahId: 20, ayahNumber: 82, text: 'But indeed, I am the Perpetual Forgiver of whoever repents and believes and does righteousness and then continues in guidance.' },
  { surahId: 20, ayahNumber: 83, text: '[Allah] said, "And what made you hasten from your people, O Moses?"' },
  { surahId: 20, ayahNumber: 84, text: 'He said, "They are close upon my tracks, and I hastened to You, my Lord, that You be pleased."' },
  { surahId: 20, ayahNumber: 85, text: '[Allah] said, "But indeed, We have tried your people after you [departed], and the Samiri has led them astray."' },
  { surahId: 20, ayahNumber: 86, text: 'So Moses returned to his people, angry and grieved. He said, "O my people, did your Lord not make you a good promise? Then, was the time [of its fulfillment] too long for you, or did you wish that wrath from your Lord descend upon you, so you broke your promise [of obedience] to me?"' },
  { surahId: 20, ayahNumber: 87, text: 'They said, "We did not break our promise to you by our will, but we were made to carry burdens from the ornaments of the people [of Pharaoh], so we threw them [into the fire], and thus did the Samiri throw."' },
  { surahId: 20, ayahNumber: 88, text: 'And he extracted for them [the statue of] a calf which had a lowing sound, and they said, "This is your god and the god of Moses, but he forgot."' },
  { surahId: 20, ayahNumber: 89, text: 'Did they not see that it could not return to them any speech and that it did not possess for them any harm or benefit?' },
  { surahId: 20, ayahNumber: 90, text: 'And Aaron had already told them before [the return of Moses], "O my people, you are only being tested by it, and indeed, your Lord is the Most Merciful, so follow me and obey my order."' },
  { surahId: 20, ayahNumber: 91, text: 'They said, "We will never cease being devoted to the calf until Moses returns to us."' },
  { surahId: 20, ayahNumber: 92, text: '[Moses] said, "O Aaron, what prevented you, when you saw them going astray,' },
  { surahId: 20, ayahNumber: 93, text: 'From following me? Then have you disobeyed my order?"' },
  { surahId: 20, ayahNumber: 94, text: '[Aaron] said, "O son of my mother, do not seize [me] by my beard or by my head. Indeed, I feared that you would say, \'You caused division among the Children of Israel, and you did not observe [or await] my word.\' "' },
  { surahId: 20, ayahNumber: 95, text: '[Moses] said, "And what is your case, O Samiri?"' },
  { surahId: 20, ayahNumber: 96, text: 'He said, "I saw what they did not see, so I took a handful [of dust] from the track of the messenger and threw it, and thus did my soul entice me."' },
  { surahId: 20, ayahNumber: 97, text: '[Moses] said, "Then go. And indeed, it is [decreed] for you in [this] life to say, \'No contact.\' And indeed, you have an appointment [in the Hereafter] you will not fail to keep. And look at your \'god\' to which you remained devoted. We will surely burn it and blow it into the sea with a blast.' },
  { surahId: 20, ayahNumber: 98, text: 'Your god is only Allah, except for whom there is no deity. He has encompassed all things in knowledge."' },
  { surahId: 20, ayahNumber: 99, text: 'Thus, [O Muhammad], We relate to you from the news of what has preceded. And We have certainly given you from Us the Qur\'an.' },
  { surahId: 20, ayahNumber: 100, text: 'Whoever turns away from it - then indeed, he will bear on the Day of Resurrection a burden,' },
  { surahId: 20, ayahNumber: 101, text: '[Abiding] eternally therein, and evil it is for them on the Day of Resurrection as a load -' },
  { surahId: 20, ayahNumber: 102, text: 'The Day the Horn will be blown. And We will gather the criminals, that Day, blue-eyed.' },
  { surahId: 20, ayahNumber: 103, text: 'They will murmur among themselves, "You remained not but ten [days in the world]."' },
  { surahId: 20, ayahNumber: 104, text: 'We are most knowing of what they say when the best of them in manner will say, "You remained not but one day."' },
  { surahId: 20, ayahNumber: 105, text: 'And they ask you about the mountains, so say, "My Lord will blow them away with a blast.' },
  { surahId: 20, ayahNumber: 106, text: 'And He will leave the earth a level plain;' },
  { surahId: 20, ayahNumber: 107, text: 'You will not see therein a depression or an elevation."' },
  { surahId: 20, ayahNumber: 108, text: 'That Day, everyone will follow [the call of] the Caller [with] no deviation therefrom, and [all] voices will be stilled before the Most Merciful, so you will not hear except a whisper [of footsteps].' },
  { surahId: 20, ayahNumber: 109, text: 'That Day, no intercession will benefit except [that of] one to whom the Most Merciful has given permission and has accepted his word.' },
  { surahId: 20, ayahNumber: 110, text: 'Allah knows what is [presently] before them and what will be after them, but they do not encompass it in knowledge.' },
  { surahId: 20, ayahNumber: 111, text: 'And [all] faces will be humbled before the Ever-Living, the Sustainer of existence. And he will have failed who carries injustice.' },
  { surahId: 20, ayahNumber: 112, text: 'But he who does of righteous deeds while he is a believer - he will neither fear injustice nor deprivation.' },
  { surahId: 20, ayahNumber: 113, text: 'And thus We have sent it down as an Arabic Qur\'an and have diversified therein the warnings that perhaps they will avoid [sin] or it would cause them remembrance.' },
  { surahId: 20, ayahNumber: 114, text: 'So high [above all] is Allah, the Sovereign, the Truth. And, [O Muhammad], do not hasten with [recitation of] the Qur\'an before its revelation is completed to you, and say, "My Lord, increase me in knowledge."' },
  { surahId: 20, ayahNumber: 115, text: 'And We had already taken a promise from Adam before, but he forgot; and We found not in him determination.' },
  { surahId: 20, ayahNumber: 116, text: 'And [mention] when We said to the angels, "Prostrate to Adam," and they prostrated, except Iblees; he refused.' },
  { surahId: 20, ayahNumber: 117, text: 'So We said, "O Adam, indeed this is an enemy to you and to your wife. Then let him not remove you from Paradise so you would suffer.' },
  { surahId: 20, ayahNumber: 118, text: 'Indeed, it is [promised] for you not to be hungry therein or be unclothed.' },
  { surahId: 20, ayahNumber: 119, text: 'And indeed, you will not be thirsty therein or be hot from the sun."' },
  { surahId: 20, ayahNumber: 120, text: 'Then Satan whispered to him; he said, "O Adam, shall I direct you to the tree of eternity and possession that will not deteriorate?"' },
  { surahId: 20, ayahNumber: 121, text: 'And Adam and his wife ate of it, and their private parts became apparent to them, and they began to fasten over themselves from the leaves of Paradise. And Adam disobeyed his Lord and erred.' },
  { surahId: 20, ayahNumber: 122, text: 'Then his Lord chose him and turned to him in forgiveness and guided [him].' },
  { surahId: 20, ayahNumber: 123, text: '[Allah] said, "Descend from Paradise - all, [your descendants] being enemies to one another. And if there should come to you guidance from Me - then whoever follows My guidance will neither go astray [in the world] nor suffer [in the Hereafter].' },
  { surahId: 20, ayahNumber: 124, text: 'And whoever turns away from My remembrance - indeed, he will have a depressed life, and We will gather him on the Day of Resurrection blind."' },
  { surahId: 20, ayahNumber: 125, text: 'He will say, "My Lord, why have you raised me blind while I was [once] seeing?"' },
  { surahId: 20, ayahNumber: 126, text: '[Allah] will say, "Thus did Our signs come to you, and you forgot them; and thus will you this Day be forgotten."' },
  { surahId: 20, ayahNumber: 127, text: 'And thus do We recompense he who transgressed and did not believe in the signs of his Lord. And the punishment of the Hereafter is more severe and more enduring.' },
  { surahId: 20, ayahNumber: 128, text: 'Then, has it not become clear to them how many generations We destroyed before them as they walk among their dwellings? Indeed in that are signs for those of intelligence.' },
  { surahId: 20, ayahNumber: 129, text: 'And if not for a word that preceded from your Lord, punishment would have been an obligation [due immediately], and [if not for] a specified term [decreed].' },
  { surahId: 20, ayahNumber: 130, text: 'So be patient over what they say and exalt [Allah] with praise of your Lord before the rising of the sun and before its setting; and during periods of the night [exalt Him] and at the ends of the day, that you may be satisfied.' },
  { surahId: 20, ayahNumber: 131, text: 'And do not extend your eyes toward that by which We have given enjoyment to [some] categories of them, [its being but] the splendor of worldly life by which We test them. And the provision of your Lord is better and more enduring.' },
  { surahId: 20, ayahNumber: 132, text: 'And enjoin prayer upon your family [and people] and be steadfast therein. We ask you not for provision; We provide for you, and the [best] outcome is for [those of] righteousness.' },
  { surahId: 20, ayahNumber: 133, text: 'And they say, "Why does he not bring us a sign from his Lord?" Has there not come to them evidence of what was in the former scriptures?' },
  { surahId: 20, ayahNumber: 134, text: 'And if We had destroyed them with a punishment before him, they would have said, "Our Lord, why did You not send to us a messenger so we could have followed Your verses before we were humiliated and disgraced?"' },
  { surahId: 20, ayahNumber: 135, text: 'Say, "Each [of us] is waiting; so wait. For you will know who are the companions of the sound path and who is guided."' },
  { surahId: 21, ayahNumber: 1, text: '[The time of] their account has approached for the people, while they are in heedlessness turning away.' },
  { surahId: 21, ayahNumber: 2, text: 'No mention comes to them anew from their Lord except that they listen to it while they are at play' },
  { surahId: 21, ayahNumber: 3, text: 'With their hearts distracted. And those who do wrong conceal their private conversation, [saying], "Is this [Prophet] except a human being like you? So would you approach magic while you are aware [of it]?"' },
  { surahId: 21, ayahNumber: 4, text: 'The Prophet said, "My Lord knows whatever is said throughout the heaven and earth, and He is the Hearing, the Knowing."' },
  { surahId: 21, ayahNumber: 5, text: 'But they say, "[The revelation is but] a mixture of false dreams; rather, he has invented it; rather, he is a poet. So let him bring us a sign just as the previous [messengers] were sent [with miracles]."' },
  { surahId: 21, ayahNumber: 6, text: 'Not a [single] city which We destroyed believed before them, so will they believe?' },
  { surahId: 21, ayahNumber: 7, text: 'And We sent not before you, [O Muhammad], except men to whom We revealed [the message], so ask the people of the message if you do not know.' },
  { surahId: 21, ayahNumber: 8, text: 'And We did not make the prophets forms not eating food, nor were they immortal [on earth].' },
  { surahId: 21, ayahNumber: 9, text: 'Then We fulfilled for them the promise, and We saved them and whom We willed and destroyed the transgressors.' },
  { surahId: 21, ayahNumber: 10, text: 'We have certainly sent down to you a Book in which is your mention. Then will you not reason?' },
  { surahId: 21, ayahNumber: 11, text: 'And how many a city which was unjust have We shattered and produced after it another people.' },
  { surahId: 21, ayahNumber: 12, text: 'And when its inhabitants perceived Our punishment, at once they fled from it.' },
  { surahId: 21, ayahNumber: 13, text: '[Some angels said], "Do not flee but return to where you were given luxury and to your homes - perhaps you will be questioned."' },
  { surahId: 21, ayahNumber: 14, text: 'They said, "O woe to us! Indeed, we were wrongdoers."' },
  { surahId: 21, ayahNumber: 15, text: 'And that declaration of theirs did not cease until We made them [as] a harvest [mowed down], extinguished [like a fire].' },
  { surahId: 21, ayahNumber: 16, text: 'And We did not create the heaven and earth and that between them in play.' },
  { surahId: 21, ayahNumber: 17, text: 'Had We intended to take a diversion, We could have taken it from [what is] with Us - if [indeed] We were to do so.' },
  { surahId: 21, ayahNumber: 18, text: 'Rather, We dash the truth upon falsehood, and it destroys it, and thereupon it departs. And for you is destruction from that which you describe.' },
  { surahId: 21, ayahNumber: 19, text: 'To Him belongs whoever is in the heavens and the earth. And those near Him are not prevented by arrogance from His worship, nor do they tire.' },
  { surahId: 21, ayahNumber: 20, text: 'They exalt [Him] night and day [and] do not slacken.' },
  { surahId: 21, ayahNumber: 21, text: 'Or have men taken for themselves gods from the earth who resurrect [the dead]?' },
  { surahId: 21, ayahNumber: 22, text: 'Had there been within the heavens and earth gods besides Allah, they both would have been ruined. So exalted is Allah, Lord of the Throne, above what they describe.' },
  { surahId: 21, ayahNumber: 23, text: 'He is not questioned about what He does, but they will be questioned.' },
  { surahId: 21, ayahNumber: 24, text: 'Or have they taken gods besides Him? Say, [O Muhammad], "Produce your proof. This [Qur\'an] is the message for those with me and the message of those before me." But most of them do not know the truth, so they are turning away.' },
  { surahId: 21, ayahNumber: 25, text: 'And We sent not before you any messenger except that We revealed to him that, "There is no deity except Me, so worship Me."' },
  { surahId: 21, ayahNumber: 26, text: 'And they say, "The Most Merciful has taken a son." Exalted is He! Rather, they are [but] honored servants.' },
  { surahId: 21, ayahNumber: 27, text: 'They cannot precede Him in word, and they act by His command.' },
  { surahId: 21, ayahNumber: 28, text: 'He knows what is [presently] before them and what will be after them, and they cannot intercede except on behalf of one whom He approves. And they, from fear of Him, are apprehensive.' },
  { surahId: 21, ayahNumber: 29, text: 'And whoever of them should say, "Indeed, I am a god besides Him"- that one We would recompense with Hell. Thus do We recompense the wrongdoers.' },
  { surahId: 21, ayahNumber: 30, text: 'Have those who disbelieved not considered that the heavens and the earth were a joined entity, and We separated them and made from water every living thing? Then will they not believe?' },
  { surahId: 21, ayahNumber: 31, text: 'And We placed within the earth firmly set mountains, lest it should shift with them, and We made therein [mountain] passes [as] roads that they might be guided.' },
  { surahId: 21, ayahNumber: 32, text: 'And We made the sky a protected ceiling, but they, from its signs, are turning away.' },
  { surahId: 21, ayahNumber: 33, text: 'And it is He who created the night and the day and the sun and the moon; all [heavenly bodies] in an orbit are swimming.' },
  { surahId: 21, ayahNumber: 34, text: 'And We did not grant to any man before you eternity [on earth]; so if you die - would they be eternal?' },
  { surahId: 21, ayahNumber: 35, text: 'Every soul will taste death. And We test you with evil and with good as trial; and to Us you will be returned.' },
  { surahId: 21, ayahNumber: 36, text: 'And when those who disbelieve see you, [O Muhammad], they take you not except in ridicule, [saying], "Is this the one who insults your gods?" And they are, at the mention of the Most Merciful, disbelievers.' },
  { surahId: 21, ayahNumber: 37, text: 'Man was created of haste. I will show you My signs, so do not impatiently urge Me.' },
  { surahId: 21, ayahNumber: 38, text: 'And they say, "When is this promise, if you should be truthful?"' },
  { surahId: 21, ayahNumber: 39, text: 'If those who disbelieved but knew the time when they will not avert the Fire from their faces or from their backs and they will not be aided...' },
  { surahId: 21, ayahNumber: 40, text: 'Rather, it will come to them unexpectedly and bewilder them, and they will not be able to repel it, nor will they be reprieved.' },
  { surahId: 21, ayahNumber: 41, text: 'And already were messengers ridiculed before you, but those who mocked them were enveloped by what they used to ridicule.' },
  { surahId: 21, ayahNumber: 42, text: 'Say, "Who can protect you at night or by day from the Most Merciful?" But they are, from the remembrance of their Lord, turning away.' },
  { surahId: 21, ayahNumber: 43, text: 'Or do they have gods to defend them other than Us? They are unable [even] to help themselves, nor can they be protected from Us.' },
  { surahId: 21, ayahNumber: 44, text: 'But, [on the contrary], We have provided good things for these [disbelievers] and their fathers until life was prolonged for them. Then do they not see that We set upon the land, reducing it from its borders? So it is they who will overcome?' },
  { surahId: 21, ayahNumber: 45, text: 'Say, "I only warn you by revelation." But the deaf do not hear the call when they are warned.' },
  { surahId: 21, ayahNumber: 46, text: 'And if [as much as] a whiff of the punishment of your Lord should touch them, they would surely say, "O woe to us! Indeed, we have been wrongdoers."' },
  { surahId: 21, ayahNumber: 47, text: 'And We place the scales of justice for the Day of Resurrection, so no soul will be treated unjustly at all. And if there is [even] the weight of a mustard seed, We will bring it forth. And sufficient are We as accountant.' },
  { surahId: 21, ayahNumber: 48, text: 'And We had already given Moses and Aaron the criterion and a light and a reminder for the righteous' },
  { surahId: 21, ayahNumber: 49, text: 'Who fear their Lord unseen, while they are of the Hour apprehensive.' },
  { surahId: 21, ayahNumber: 50, text: 'And this [Qur\'an] is a blessed message which We have sent down. Then are you with it unacquainted?' },
  { surahId: 21, ayahNumber: 51, text: 'And We had certainly given Abraham his sound judgement before, and We were of him well-Knowing' },
  { surahId: 21, ayahNumber: 52, text: 'When he said to his father and his people, "What are these statues to which you are devoted?"' },
  { surahId: 21, ayahNumber: 53, text: 'They said, "We found our fathers worshippers of them."' },
  { surahId: 21, ayahNumber: 54, text: 'He said, "You were certainly, you and your fathers, in manifest error."' },
  { surahId: 21, ayahNumber: 55, text: 'They said, "Have you come to us with truth, or are you of those who jest?"' },
  { surahId: 21, ayahNumber: 56, text: 'He said, "[No], rather, your Lord is the Lord of the heavens and the earth who created them, and I, to that, am of those who testify.' },
  { surahId: 21, ayahNumber: 57, text: 'And [I swear] by Allah, I will surely plan against your idols after you have turned and gone away."' },
  { surahId: 21, ayahNumber: 58, text: 'So he made them into fragments, except a large one among them, that they might return to it [and question].' },
  { surahId: 21, ayahNumber: 59, text: 'They said, "Who has done this to our gods? Indeed, he is of the wrongdoers."' },
  { surahId: 21, ayahNumber: 60, text: 'They said, "We heard a young man mention them who is called Abraham."' },
  { surahId: 21, ayahNumber: 61, text: 'They said, "Then bring him before the eyes of the people that they may testify."' },
  { surahId: 21, ayahNumber: 62, text: 'They said, "Have you done this to our gods, O Abraham?"' },
  { surahId: 21, ayahNumber: 63, text: 'He said, "Rather, this - the largest of them - did it, so ask them, if they should [be able to] speak."' },
  { surahId: 21, ayahNumber: 64, text: 'So they returned to [blaming] themselves and said [to each other], "Indeed, you are the wrongdoers."' },
  { surahId: 21, ayahNumber: 65, text: 'Then they reversed themselves, [saying], "You have already known that these do not speak!"' },
  { surahId: 21, ayahNumber: 66, text: 'He said, "Then do you worship instead of Allah that which does not benefit you at all or harm you?' },
  { surahId: 21, ayahNumber: 67, text: 'Uff to you and to what you worship instead of Allah. Then will you not use reason?"' },
  { surahId: 21, ayahNumber: 68, text: 'They said, "Burn him and support your gods - if you are to act."' },
  { surahId: 21, ayahNumber: 69, text: 'Allah said, "O fire, be coolness and safety upon Abraham."' },
  { surahId: 21, ayahNumber: 70, text: 'And they intended for him harm, but We made them the greatest losers.' },
  { surahId: 21, ayahNumber: 71, text: 'And We delivered him and Lot to the land which We had blessed for the worlds.' },
  { surahId: 21, ayahNumber: 72, text: 'And We gave him Isaac and Jacob in addition, and all [of them] We made righteous.' },
  { surahId: 21, ayahNumber: 73, text: 'And We made them leaders guiding by Our command. And We inspired to them the doing of good deeds, establishment of prayer, and giving of zakah; and they were worshippers of Us.' },
  { surahId: 21, ayahNumber: 74, text: 'And to Lot We gave judgement and knowledge, and We saved him from the city that was committing wicked deeds. Indeed, they were a people of evil, defiantly disobedient.' },
  { surahId: 21, ayahNumber: 75, text: 'And We admitted him into Our mercy. Indeed, he was of the righteous.' },
  { surahId: 21, ayahNumber: 76, text: 'And [mention] Noah, when he called [to Allah] before [that time], so We responded to him and saved him and his family from the great flood.' },
  { surahId: 21, ayahNumber: 77, text: 'And We saved him from the people who denied Our signs. Indeed, they were a people of evil, so We drowned them, all together.' },
  { surahId: 21, ayahNumber: 78, text: 'And [mention] David and Solomon, when they judged concerning the field - when the sheep of a people overran it [at night], and We were witness to their judgement.' },
  { surahId: 21, ayahNumber: 79, text: 'And We gave understanding of the case to Solomon, and to each [of them] We gave judgement and knowledge. And We subjected the mountains to exalt [Us], along with David and [also] the birds. And We were doing [that].' },
  { surahId: 21, ayahNumber: 80, text: 'And We taught him the fashioning of coats of armor to protect you from your [enemy in] battle. So will you then be grateful?' },
  { surahId: 21, ayahNumber: 81, text: 'And to Solomon [We subjected] the wind, blowing forcefully, proceeding by his command toward the land which We had blessed. And We are ever, of all things, Knowing.' },
  { surahId: 21, ayahNumber: 82, text: 'And of the devils were those who dived for him and did work other than that. And We were of them a guardian.' },
  { surahId: 21, ayahNumber: 83, text: 'And [mention] Job, when he called to his Lord, "Indeed, adversity has touched me, and you are the Most Merciful of the merciful."' },
  { surahId: 21, ayahNumber: 84, text: 'So We responded to him and removed what afflicted him of adversity. And We gave him [back] his family and the like thereof with them as mercy from Us and a reminder for the worshippers [of Allah].' },
  { surahId: 21, ayahNumber: 85, text: 'And [mention] Ishmael and Idrees and Dhul-Kifl; all were of the patient.' },
  { surahId: 21, ayahNumber: 86, text: 'And We admitted them into Our mercy. Indeed, they were of the righteous.' },
  { surahId: 21, ayahNumber: 87, text: 'And [mention] the man of the fish, when he went off in anger and thought that We would not decree [anything] upon him. And he called out within the darknesses, "There is no deity except You; exalted are You. Indeed, I have been of the wrongdoers."' },
  { surahId: 21, ayahNumber: 88, text: 'So We responded to him and saved him from the distress. And thus do We save the believers.' },
  { surahId: 21, ayahNumber: 89, text: 'And [mention] Zechariah, when he called to his Lord, "My Lord, do not leave me alone [with no heir], while you are the best of inheritors."' },
  { surahId: 21, ayahNumber: 90, text: 'So We responded to him, and We gave to him John, and amended for him his wife. Indeed, they used to hasten to good deeds and supplicate Us in hope and fear, and they were to Us humbly submissive.' },
  { surahId: 21, ayahNumber: 91, text: 'And [mention] the one who guarded her chastity, so We blew into her [garment] through Our angel [Gabriel], and We made her and her son a sign for the worlds.' },
  { surahId: 21, ayahNumber: 92, text: 'Indeed this, your religion, is one religion, and I am your Lord, so worship Me.' },
  { surahId: 21, ayahNumber: 93, text: 'And [yet] they divided their affair among themselves, [but] all to Us will return.' },
  { surahId: 21, ayahNumber: 94, text: 'So whoever does righteous deeds while he is a believer - no denial will there be for his effort, and indeed We, of it, are recorders.' },
  { surahId: 21, ayahNumber: 95, text: 'And there is prohibition upon [the people of] a city which We have destroyed that they will [ever] return' },
  { surahId: 21, ayahNumber: 96, text: 'Until when [the dam of] Gog and Magog has been opened and they, from every elevation, descend' },
  { surahId: 21, ayahNumber: 97, text: 'And [when] the true promise has approached; then suddenly the eyes of those who disbelieved will be staring [in horror, while they say], "O woe to us; we had been unmindful of this; rather, we were wrongdoers."' },
  { surahId: 21, ayahNumber: 98, text: 'Indeed, you [disbelievers] and what you worship other than Allah are the firewood of Hell. You will be coming to [enter] it.' },
  { surahId: 21, ayahNumber: 99, text: 'Had these [false deities] been [actual] gods, they would not have come to it, but all are eternal therein.' },
  { surahId: 21, ayahNumber: 100, text: 'For them therein is heavy sighing, and they therein will not hear.' },
  { surahId: 21, ayahNumber: 101, text: 'Indeed, those for whom the best [reward] has preceded from Us - they are from it far removed.' },
  { surahId: 21, ayahNumber: 102, text: 'They will not hear its sound, while they are, in that which their souls desire, abiding eternally.' },
  { surahId: 21, ayahNumber: 103, text: 'They will not be grieved by the greatest terror, and the angels will meet them, [saying], "This is your Day which you have been promised" -' },
  { surahId: 21, ayahNumber: 104, text: 'The Day when We will fold the heaven like the folding of a [written] sheet for the records. As We began the first creation, We will repeat it. [That is] a promise binding upon Us. Indeed, We will do it.' },
  { surahId: 21, ayahNumber: 105, text: 'And We have already written in the book [of Psalms] after the [previous] mention that the land [of Paradise] is inherited by My righteous servants.' },
  { surahId: 21, ayahNumber: 106, text: 'Indeed, in this [Qur\'an] is notification for a worshipping people.' },
  { surahId: 21, ayahNumber: 107, text: 'And We have not sent you, [O Muhammad], except as a mercy to the worlds.' },
  { surahId: 21, ayahNumber: 108, text: 'Say, "It is only revealed to me that your god is but one God; so will you be Muslims [in submission to Him]?"' },
  { surahId: 21, ayahNumber: 109, text: 'But if they turn away, then say, "I have announced to [all of] you equally. And I know not whether near or far is that which you are promised.' },
  { surahId: 21, ayahNumber: 110, text: 'Indeed, He knows what is declared of speech, and He knows what you conceal.' },
  { surahId: 21, ayahNumber: 111, text: 'And I know not; perhaps it is a trial for you and enjoyment for a time."' },
  { surahId: 21, ayahNumber: 112, text: '[The Prophet] has said, "My Lord, judge [between us] in truth. And our Lord is the Most Merciful, the one whose help is sought against that which you describe."' },
  { surahId: 22, ayahNumber: 1, text: 'O mankind, fear your Lord. Indeed, the convulsion of the [final] Hour is a terrible thing.' },
  { surahId: 22, ayahNumber: 2, text: 'On the Day you see it every nursing mother will be distracted from that [child] she was nursing, and every pregnant woman will abort her pregnancy, and you will see the people [appearing] intoxicated while they are not intoxicated; but the punishment of Allah is severe.' },
  { surahId: 22, ayahNumber: 3, text: 'And of the people is he who disputes about Allah without knowledge and follows every rebellious devil.' },
  { surahId: 22, ayahNumber: 4, text: 'It has been decreed for every devil that whoever turns to him - he will misguide him and will lead him to the punishment of the Blaze.' },
  { surahId: 22, ayahNumber: 5, text: 'O People, if you should be in doubt about the Resurrection, then [consider that] indeed, We created you from dust, then from a sperm-drop, then from a clinging clot, and then from a lump of flesh, formed and unformed - that We may show you. And We settle in the wombs whom We will for a specified term, then We bring you out as a child, and then [We develop you] that you may reach your [time of] maturity. And among you is he who is taken in [early] death, and among you is he who is returned to the most decrepit [old] age so that he knows, after [once having] knowledge, nothing. And you see the earth barren, but when We send down upon it rain, it quivers and swells and grows [something] of every beautiful kind.' },
  { surahId: 22, ayahNumber: 6, text: 'That is because Allah is the Truth and because He gives life to the dead and because He is over all things competent' },
  { surahId: 22, ayahNumber: 7, text: 'And [that they may know] that the Hour is coming - no doubt about it - and that Allah will resurrect those in the graves.' },
  { surahId: 22, ayahNumber: 8, text: 'And of the people is he who disputes about Allah without knowledge or guidance or an enlightening book [from Him],' },
  { surahId: 22, ayahNumber: 9, text: 'Twisting his neck [in arrogance] to mislead [people] from the way of Allah. For him in the world is disgrace, and We will make him taste on the Day of Resurrection the punishment of the Burning Fire [while it is said],' },
  { surahId: 22, ayahNumber: 10, text: '"That is for what your hands have put forth and because Allah is not ever unjust to [His] servants."' },
  { surahId: 22, ayahNumber: 11, text: 'And of the people is he who worships Allah on an edge. If he is touched by good, he is reassured by it; but if he is struck by trial, he turns on his face [to the other direction]. He has lost [this] world and the Hereafter. That is what is the manifest loss.' },
  { surahId: 22, ayahNumber: 12, text: 'He invokes instead of Allah that which neither harms him nor benefits him. That is what is the extreme error.' },
  { surahId: 22, ayahNumber: 13, text: 'He invokes one whose harm is closer than his benefit - how wretched the protector and how wretched the associate.' },
  { surahId: 22, ayahNumber: 14, text: 'Indeed, Allah will admit those who believe and do righteous deeds to gardens beneath which rivers flow. Indeed, Allah does what He intends.' },
  { surahId: 22, ayahNumber: 15, text: 'Whoever should think that Allah will not support [Prophet Muhammad] in this world and the Hereafter - let him extend a rope to the ceiling, then cut off [his breath], and let him see: will his effort remove that which enrages [him]?' },
  { surahId: 22, ayahNumber: 16, text: 'And thus have We sent the Qur\'an down as verses of clear evidence and because Allah guides whom He intends.' },
  { surahId: 22, ayahNumber: 17, text: 'Indeed, those who have believed and those who were Jews and the Sabeans and the Christians and the Magians and those who associated with Allah - Allah will judge between them on the Day of Resurrection. Indeed Allah is, over all things, Witness.' },
  { surahId: 22, ayahNumber: 18, text: 'Do you not see that to Allah prostrates whoever is in the heavens and whoever is on the earth and the sun, the moon, the stars, the mountains, the trees, the moving creatures and many of the people? But upon many the punishment has been justified. And he whom Allah humiliates - for him there is no bestower of honor. Indeed, Allah does what He wills.' },
  { surahId: 22, ayahNumber: 19, text: 'These are two adversaries who have disputed over their Lord. But those who disbelieved will have cut out for them garments of fire. Poured upon their heads will be scalding water' },
  { surahId: 22, ayahNumber: 20, text: 'By which is melted that within their bellies and [their] skins.' },
  { surahId: 22, ayahNumber: 21, text: 'And for [striking] them are maces of iron.' },
  { surahId: 22, ayahNumber: 22, text: 'Every time they want to get out of Hellfire from anguish, they will be returned to it, and [it will be said], "Taste the punishment of the Burning Fire!"' },
  { surahId: 22, ayahNumber: 23, text: 'Indeed, Allah will admit those who believe and do righteous deeds to gardens beneath which rivers flow. They will be adorned therein with bracelets of gold and pearl, and their garments therein will be silk.' },
  { surahId: 22, ayahNumber: 24, text: 'And they had been guided [in worldly life] to good speech, and they were guided to the path of the Praiseworthy.' },
  { surahId: 22, ayahNumber: 25, text: 'Indeed, those who have disbelieved and avert [people] from the way of Allah and [from] al-Masjid al-Haram, which We made for the people - equal are the resident therein and one from outside; and [also] whoever intends [a deed] therein of deviation [in religion] or wrongdoing - We will make him taste of a painful punishment.' },
  { surahId: 22, ayahNumber: 26, text: 'And [mention, O Muhammad], when We designated for Abraham the site of the House, [saying], "Do not associate anything with Me and purify My House for those who perform Tawaf and those who stand [in prayer] and those who bow and prostrate.' },
  { surahId: 22, ayahNumber: 27, text: 'And proclaim to the people the Hajj [pilgrimage]; they will come to you on foot and on every lean camel; they will come from every distant pass -' },
  { surahId: 22, ayahNumber: 28, text: 'That they may witness benefits for themselves and mention the name of Allah on known days over what He has provided for them of [sacrificial] animals. So eat of them and feed the miserable and poor.' },
  { surahId: 22, ayahNumber: 29, text: 'Then let them end their untidiness and fulfill their vows and perform Tawaf around the ancient House."' },
  { surahId: 22, ayahNumber: 30, text: 'That [has been commanded], and whoever honors the sacred ordinances of Allah - it is best for him in the sight of his Lord. And permitted to you are the grazing livestock, except what is recited to you. So avoid the uncleanliness of idols and avoid false statement,' },
  { surahId: 22, ayahNumber: 31, text: 'Inclining [only] to Allah, not associating [anything] with Him. And he who associates with Allah - it is as though he had fallen from the sky and was snatched by the birds or the wind carried him down into a remote place.' },
  { surahId: 22, ayahNumber: 32, text: 'That [is so]. And whoever honors the symbols of Allah - indeed, it is from the piety of hearts.' },
  { surahId: 22, ayahNumber: 33, text: 'For you the animals marked for sacrifice are benefits for a specified term; then their place of sacrifice is at the ancient House.' },
  { surahId: 22, ayahNumber: 34, text: 'And for all religion We have appointed a rite [of sacrifice] that they may mention the name of Allah over what He has provided for them of [sacrificial] animals. For your god is one God, so to Him submit. And, [O Muhammad], give good tidings to the humble [before their Lord]' },
  { surahId: 22, ayahNumber: 35, text: 'Who, when Allah is mentioned, their hearts are fearful, and [to] the patient over what has afflicted them, and the establishers of prayer and those who spend from what We have provided them.' },
  { surahId: 22, ayahNumber: 36, text: 'And the camels and cattle We have appointed for you as among the symbols of Allah; for you therein is good. So mention the name of Allah upon them when lined up [for sacrifice]; and when they are [lifeless] on their sides, then eat from them and feed the needy and the beggar. Thus have We subjected them to you that you may be grateful.' },
  { surahId: 22, ayahNumber: 37, text: 'Their meat will not reach Allah, nor will their blood, but what reaches Him is piety from you. Thus have We subjected them to you that you may glorify Allah for that [to] which He has guided you; and give good tidings to the doers of good.' },
  { surahId: 22, ayahNumber: 38, text: 'Indeed, Allah defends those who have believed. Indeed, Allah does not like everyone treacherous and ungrateful.' },
  { surahId: 22, ayahNumber: 39, text: 'Permission [to fight] has been given to those who are being fought, because they were wronged. And indeed, Allah is competent to give them victory.' },
  { surahId: 22, ayahNumber: 40, text: '[They are] those who have been evicted from their homes without right - only because they say, "Our Lord is Allah." And were it not that Allah checks the people, some by means of others, there would have been demolished monasteries, churches, synagogues, and mosques in which the name of Allah is much mentioned. And Allah will surely support those who support Him. Indeed, Allah is Powerful and Exalted in Might.' },
  { surahId: 22, ayahNumber: 41, text: '[And they are] those who, if We give them authority in the land, establish prayer and give zakah and enjoin what is right and forbid what is wrong. And to Allah belongs the outcome of [all] matters.' },
  { surahId: 22, ayahNumber: 42, text: 'And if they deny you, [O Muhammad] - so, before them, did the people of Noah and \'Aad and Thamud deny [their prophets],' },
  { surahId: 22, ayahNumber: 43, text: 'And the people of Abraham and the people of Lot' },
  { surahId: 22, ayahNumber: 44, text: 'And the inhabitants of Madyan. And Moses was denied, so I prolonged enjoyment for the disbelievers; then I seized them, and how [terrible] was My reproach.' },
  { surahId: 22, ayahNumber: 45, text: 'And how many a city did We destroy while it was committing wrong - so it is [now] fallen into ruin - and [how many] an abandoned well and [how many] a lofty palace.' },
  { surahId: 22, ayahNumber: 46, text: 'So have they not traveled through the earth and have hearts by which to reason and ears by which to hear? For indeed, it is not eyes that are blinded, but blinded are the hearts which are within the breasts.' },
  { surahId: 22, ayahNumber: 47, text: 'And they urge you to hasten the punishment. But Allah will never fail in His promise. And indeed, a day with your Lord is like a thousand years of those which you count.' },
  { surahId: 22, ayahNumber: 48, text: 'And for how many a city did I prolong enjoyment while it was committing wrong. Then I seized it, and to Me is the [final] destination.' },
  { surahId: 22, ayahNumber: 49, text: 'Say, "O people, I am only to you a clear warner."' },
  { surahId: 22, ayahNumber: 50, text: 'And those who have believed and done righteous deeds - for them is forgiveness and noble provision.' },
  { surahId: 22, ayahNumber: 51, text: 'But the ones who strove against Our verses, [seeking] to cause failure - those are the companions of Hellfire.' },
  { surahId: 22, ayahNumber: 52, text: 'And We did not send before you any messenger or prophet except that when he spoke [or recited], Satan threw into it [some misunderstanding]. But Allah abolishes that which Satan throws in; then Allah makes precise His verses. And Allah is Knowing and Wise.' },
  { surahId: 22, ayahNumber: 53, text: '[That is] so He may make what Satan throws in a trial for those within whose hearts is disease and those hard of heart. And indeed, the wrongdoers are in extreme dissension.' },
  { surahId: 22, ayahNumber: 54, text: 'And so those who were given knowledge may know that it is the truth from your Lord and [therefore] believe in it, and their hearts humbly submit to it. And indeed is Allah the Guide of those who have believed to a straight path.' },
  { surahId: 22, ayahNumber: 55, text: 'But those who disbelieve will not cease to be in doubt of it until the Hour comes upon them unexpectedly or there comes to them the punishment of a barren Day.' },
  { surahId: 22, ayahNumber: 56, text: '[All] sovereignty that Day is for Allah; He will judge between them. So they who believed and did righteous deeds will be in the Gardens of Pleasure.' },
  { surahId: 22, ayahNumber: 57, text: 'And they who disbelieved and denied Our signs - for those there will be a humiliating punishment.' },
  { surahId: 22, ayahNumber: 58, text: 'And those who emigrated for the cause of Allah and then were killed or died - Allah will surely provide for them a good provision. And indeed, it is Allah who is the best of providers.' },
  { surahId: 22, ayahNumber: 59, text: 'He will surely cause them to enter an entrance with which they will be pleased, and indeed, Allah is Knowing and Forbearing.' },
  { surahId: 22, ayahNumber: 60, text: 'That [is so]. And whoever responds [to injustice] with the equivalent of that with which he was harmed and then is tyrannized - Allah will surely aid him. Indeed, Allah is Pardoning and Forgiving.' },
  { surahId: 22, ayahNumber: 61, text: 'That is because Allah causes the night to enter the day and causes the day to enter the night and because Allah is Hearing and Seeing.' },
  { surahId: 22, ayahNumber: 62, text: 'That is because Allah is the Truth, and that which they call upon other than Him is falsehood, and because Allah is the Most High, the Grand.' },
  { surahId: 22, ayahNumber: 63, text: 'Do you not see that Allah has sent down rain from the sky and the earth becomes green? Indeed, Allah is Subtle and Acquainted.' },
  { surahId: 22, ayahNumber: 64, text: 'To Him belongs what is in the heavens and what is on the earth. And indeed, Allah is the Free of need, the Praiseworthy.' },
  { surahId: 22, ayahNumber: 65, text: 'Do you not see that Allah has subjected to you whatever is on the earth and the ships which run through the sea by His command? And He restrains the sky from falling upon the earth, unless by His permission. Indeed Allah, to the people, is Kind and Merciful.' },
  { surahId: 22, ayahNumber: 66, text: 'And He is the one who gave you life; then He causes you to die and then will [again] give you life. Indeed, mankind is ungrateful.' },
  { surahId: 22, ayahNumber: 67, text: 'For every religion We have appointed rites which they perform. So, [O Muhammad], let the disbelievers not contend with you over the matter but invite them to your Lord. Indeed, you are upon straight guidance.' },
  { surahId: 22, ayahNumber: 68, text: 'And if they dispute with you, then say, "Allah is most knowing of what you do.' },
  { surahId: 22, ayahNumber: 69, text: 'Allah will judge between you on the Day of Resurrection concerning that over which you used to differ."' },
  { surahId: 22, ayahNumber: 70, text: 'Do you not know that Allah knows what is in the heaven and earth? Indeed, that is in a Record. Indeed that, for Allah, is easy.' },
  { surahId: 22, ayahNumber: 71, text: 'And they worship besides Allah that for which He has not sent down authority and that of which they have no knowledge. And there will not be for the wrongdoers any helper.' },
  { surahId: 22, ayahNumber: 72, text: 'And when Our verses are recited to them as clear evidences, you recognize in the faces of those who disbelieve disapproval. They are almost on the verge of assaulting those who recite to them Our verses. Say, "Then shall I inform you of [what is] worse than that? [It is] the Fire which Allah has promised those who disbelieve, and wretched is the destination."' },
  { surahId: 22, ayahNumber: 73, text: 'O people, an example is presented, so listen to it. Indeed, those you invoke besides Allah will never create [as much as] a fly, even if they gathered together for that purpose. And if the fly should steal away from them a [tiny] thing, they could not recover it from him. Weak are the pursuer and pursued.' },
  { surahId: 22, ayahNumber: 74, text: 'They have not appraised Allah with true appraisal. Indeed, Allah is Powerful and Exalted in Might.' },
  { surahId: 22, ayahNumber: 75, text: 'Allah chooses from the angels messengers and from the people. Indeed, Allah is Hearing and Seeing.' },
  { surahId: 22, ayahNumber: 76, text: 'He knows what is [presently] before them and what will be after them. And to Allah will be returned [all] matters.' },
  { surahId: 22, ayahNumber: 77, text: 'O you who have believed, bow and prostrate and worship your Lord and do good - that you may succeed.' },
  { surahId: 22, ayahNumber: 78, text: 'And strive for Allah with the striving due to Him. He has chosen you and has not placed upon you in the religion any difficulty. [It is] the religion of your father, Abraham. Allah named you "Muslims" before [in former scriptures] and in this [revelation] that the Messenger may be a witness over you and you may be witnesses over the people. So establish prayer and give zakah and hold fast to Allah. He is your protector; and excellent is the protector, and excellent is the helper.' },
  { surahId: 23, ayahNumber: 1, text: 'Certainly will the believers have succeeded:' },
  { surahId: 23, ayahNumber: 2, text: 'They who are during their prayer humbly submissive' },
  { surahId: 23, ayahNumber: 3, text: 'And they who turn away from ill speech' },
  { surahId: 23, ayahNumber: 4, text: 'And they who are observant of zakah' },
  { surahId: 23, ayahNumber: 5, text: 'And they who guard their private parts' },
  { surahId: 23, ayahNumber: 6, text: 'Except from their wives or those their right hands possess, for indeed, they will not be blamed -' },
  { surahId: 23, ayahNumber: 7, text: 'But whoever seeks beyond that, then those are the transgressors -' },
  { surahId: 23, ayahNumber: 8, text: 'And they who are to their trusts and their promises attentive' },
  { surahId: 23, ayahNumber: 9, text: 'And they who carefully maintain their prayers -' },
  { surahId: 23, ayahNumber: 10, text: 'Those are the inheritors' },
  { surahId: 23, ayahNumber: 11, text: 'Who will inherit al-Firdaus. They will abide therein eternally.' },
  { surahId: 23, ayahNumber: 12, text: 'And certainly did We create man from an extract of clay.' },
  { surahId: 23, ayahNumber: 13, text: 'Then We placed him as a sperm-drop in a firm lodging.' },
  { surahId: 23, ayahNumber: 14, text: 'Then We made the sperm-drop into a clinging clot, and We made the clot into a lump [of flesh], and We made [from] the lump, bones, and We covered the bones with flesh; then We developed him into another creation. So blessed is Allah, the best of creators.' },
  { surahId: 23, ayahNumber: 15, text: 'Then indeed, after that you are to die.' },
  { surahId: 23, ayahNumber: 16, text: 'Then indeed you, on the Day of Resurrection, will be resurrected.' },
  { surahId: 23, ayahNumber: 17, text: 'And We have created above you seven layered heavens, and never have We been of [Our] creation unaware.' },
  { surahId: 23, ayahNumber: 18, text: 'And We have sent down rain from the sky in a measured amount and settled it in the earth. And indeed, We are Able to take it away.' },
  { surahId: 23, ayahNumber: 19, text: 'And We brought forth for you thereby gardens of palm trees and grapevines in which for you are abundant fruits and from which you eat.' },
  { surahId: 23, ayahNumber: 20, text: 'And [We brought forth] a tree issuing from Mount Sinai which produces oil and food for those who eat.' },
  { surahId: 23, ayahNumber: 21, text: 'And indeed, for you in livestock is a lesson. We give you drink from that which is in their bellies, and for you in them are numerous benefits, and from them you eat.' },
  { surahId: 23, ayahNumber: 22, text: 'And upon them and on ships you are carried.' },
  { surahId: 23, ayahNumber: 23, text: 'And We had certainly sent Noah to his people, and he said, "O my people, worship Allah; you have no deity other than Him; then will you not fear Him?"' },
  { surahId: 23, ayahNumber: 24, text: 'But the eminent among those who disbelieved from his people said, "This is not but a man like yourselves who wishes to take precedence over you; and if Allah had willed [to send a messenger], He would have sent down angels. We have not heard of this among our forefathers.' },
  { surahId: 23, ayahNumber: 25, text: 'He is not but a man possessed with madness, so wait concerning him for a time."' },
  { surahId: 23, ayahNumber: 26, text: '[Noah] said, "My Lord, support me because they have denied me."' },
  { surahId: 23, ayahNumber: 27, text: 'So We inspired to him, "Construct the ship under Our observation, and Our inspiration, and when Our command comes and the oven overflows, put into the ship from each [creature] two mates and your family, except those for whom the decree [of destruction] has proceeded. And do not address Me concerning those who have wronged; indeed, they are to be drowned.' },
  { surahId: 23, ayahNumber: 28, text: 'And when you have boarded the ship, you and those with you, then say, \'Praise to Allah who has saved us from the wrongdoing people.\'' },
  { surahId: 23, ayahNumber: 29, text: 'And say, \'My Lord, let me land at a blessed landing place, and You are the best to accommodate [us].\' "' },
  { surahId: 23, ayahNumber: 30, text: 'Indeed in that are signs, and indeed, We are ever testing [Our servants].' },
  { surahId: 23, ayahNumber: 31, text: 'Then We produced after them a generation of others.' },
  { surahId: 23, ayahNumber: 32, text: 'And We sent among them a messenger from themselves, [saying], "Worship Allah; you have no deity other than Him; then will you not fear Him?"' },
  { surahId: 23, ayahNumber: 33, text: 'And the eminent among his people who disbelieved and denied the meeting of the Hereafter while We had given them luxury in the worldly life said, "This is not but a man like yourselves. He eats of that from which you eat and drinks of what you drink.' },
  { surahId: 23, ayahNumber: 34, text: 'And if you should obey a man like yourselves, indeed, you would then be losers.' },
  { surahId: 23, ayahNumber: 35, text: 'Does he promise you that when you have died and become dust and bones that you will be brought forth [once more]?' },
  { surahId: 23, ayahNumber: 36, text: 'How far, how far, is that which you are promised.' },
  { surahId: 23, ayahNumber: 37, text: 'Life is not but our worldly life - we die and live, but we will not be resurrected.' },
  { surahId: 23, ayahNumber: 38, text: 'He is not but a man who has invented a lie about Allah, and we will not believe him."' },
  { surahId: 23, ayahNumber: 39, text: 'He said, "My Lord, support me because they have denied me."' },
  { surahId: 23, ayahNumber: 40, text: '[Allah] said, "After a little, they will surely become regretful."' },
  { surahId: 23, ayahNumber: 41, text: 'So the shriek seized them in truth, and We made them as [plant] stubble. Then away with the wrongdoing people.' },
  { surahId: 23, ayahNumber: 42, text: 'Then We produced after them other generations.' },
  { surahId: 23, ayahNumber: 43, text: 'No nation will precede its time [of termination], nor will they remain [thereafter].' },
  { surahId: 23, ayahNumber: 44, text: 'Then We sent Our messengers in succession. Every time there came to a nation its messenger, they denied him, so We made them follow one another [to destruction], and We made them narrations. So away with a people who do not believe.' },
  { surahId: 23, ayahNumber: 45, text: 'Then We sent Moses and his brother Aaron with Our signs and a clear authority' },
  { surahId: 23, ayahNumber: 46, text: 'To Pharaoh and his establishment, but they were arrogant and were a haughty people.' },
  { surahId: 23, ayahNumber: 47, text: 'They said, "Should we believe two men like ourselves while their people are for us in servitude?"' },
  { surahId: 23, ayahNumber: 48, text: 'So they denied them and were of those destroyed.' },
  { surahId: 23, ayahNumber: 49, text: 'And We certainly gave Moses the Scripture that perhaps they would be guided.' },
  { surahId: 23, ayahNumber: 50, text: 'And We made the son of Mary and his mother a sign and sheltered them within a high ground having level [areas] and flowing water.' },
  { surahId: 23, ayahNumber: 51, text: '[Allah said], "O messengers, eat from the good foods and work righteousness. Indeed, I, of what you do, am Knowing.' },
  { surahId: 23, ayahNumber: 52, text: 'And indeed this, your religion, is one religion, and I am your Lord, so fear Me."' },
  { surahId: 23, ayahNumber: 53, text: 'But the people divided their religion among them into sects - each faction, in what it has, rejoicing.' },
  { surahId: 23, ayahNumber: 54, text: 'So leave them in their confusion for a time.' },
  { surahId: 23, ayahNumber: 55, text: 'Do they think that what We extend to them of wealth and children' },
  { surahId: 23, ayahNumber: 56, text: 'Is [because] We hasten for them good things? Rather, they do not perceive.' },
  { surahId: 23, ayahNumber: 57, text: 'Indeed, they who are apprehensive from fear of their Lord' },
  { surahId: 23, ayahNumber: 58, text: 'And they who believe in the signs of their Lord' },
  { surahId: 23, ayahNumber: 59, text: 'And they who do not associate anything with their Lord' },
  { surahId: 23, ayahNumber: 60, text: 'And they who give what they give while their hearts are fearful because they will be returning to their Lord -' },
  { surahId: 23, ayahNumber: 61, text: 'It is those who hasten to good deeds, and they outstrip [others] therein.' },
  { surahId: 23, ayahNumber: 62, text: 'And We charge no soul except [with that within] its capacity, and with Us is a record which speaks with truth; and they will not be wronged.' },
  { surahId: 23, ayahNumber: 63, text: 'But their hearts are covered with confusion over this, and they have [evil] deeds besides disbelief which they are doing,' },
  { surahId: 23, ayahNumber: 64, text: 'Until when We seize their affluent ones with punishment, at once they are crying [to Allah] for help.' },
  { surahId: 23, ayahNumber: 65, text: 'Do not cry out today. Indeed, by Us you will not be helped.' },
  { surahId: 23, ayahNumber: 66, text: 'My verses had already been recited to you, but you were turning back on your heels' },
  { surahId: 23, ayahNumber: 67, text: 'In arrogance regarding it, conversing by night, speaking evil.' },
  { surahId: 23, ayahNumber: 68, text: 'Then have they not reflected over the Qur\'an, or has there come to them that which had not come to their forefathers?' },
  { surahId: 23, ayahNumber: 69, text: 'Or did they not know their Messenger, so they are toward him disacknowledging?' },
  { surahId: 23, ayahNumber: 70, text: 'Or do they say, "In him is madness?" Rather, he brought them the truth, but most of them, to the truth, are averse.' },
  { surahId: 23, ayahNumber: 71, text: 'But if the Truth had followed their inclinations, the heavens and the earth and whoever is in them would have been ruined. Rather, We have brought them their message, but they, from their message, are turning away.' },
  { surahId: 23, ayahNumber: 72, text: 'Or do you, [O Muhammad], ask them for payment? But the reward of your Lord is best, and He is the best of providers.' },
  { surahId: 23, ayahNumber: 73, text: 'And indeed, you invite them to a straight path.' },
  { surahId: 23, ayahNumber: 74, text: 'But indeed, those who do not believe in the Hereafter are deviating from the path.' },
  { surahId: 23, ayahNumber: 75, text: 'And even if We gave them mercy and removed what was upon them of affliction, they would persist in their transgression, wandering blindly.' },
  { surahId: 23, ayahNumber: 76, text: 'And We had gripped them with suffering [as a warning], but they did not yield to their Lord, nor did they humbly supplicate, [and will continue thus]' },
  { surahId: 23, ayahNumber: 77, text: 'Until when We have opened before them a door of severe punishment, immediately they will be therein in despair.' },
  { surahId: 23, ayahNumber: 78, text: 'And it is He who produced for you hearing and vision and hearts; little are you grateful.' },
  { surahId: 23, ayahNumber: 79, text: 'And it is He who has multiplied you throughout the earth, and to Him you will be gathered.' },
  { surahId: 23, ayahNumber: 80, text: 'And it is He who gives life and causes death, and His is the alternation of the night and the day. Then will you not reason?' },
  { surahId: 23, ayahNumber: 81, text: 'Rather, they say like what the former peoples said.' },
  { surahId: 23, ayahNumber: 82, text: 'They said, "When we have died and become dust and bones, are we indeed to be resurrected?' },
  { surahId: 23, ayahNumber: 83, text: 'We have been promised this, we and our forefathers, before; this is not but legends of the former peoples."' },
  { surahId: 23, ayahNumber: 84, text: 'Say, [O Muhammad], "To whom belongs the earth and whoever is in it, if you should know?"' },
  { surahId: 23, ayahNumber: 85, text: 'They will say, "To Allah." Say, "Then will you not remember?"' },
  { surahId: 23, ayahNumber: 86, text: 'Say, "Who is Lord of the seven heavens and Lord of the Great Throne?"' },
  { surahId: 23, ayahNumber: 87, text: 'They will say, "[They belong] to Allah." Say, "Then will you not fear Him?"' },
  { surahId: 23, ayahNumber: 88, text: 'Say, "In whose hand is the realm of all things - and He protects while none can protect against Him - if you should know?"' },
  { surahId: 23, ayahNumber: 89, text: 'They will say, "[All belongs] to Allah." Say, "Then how are you deluded?"' },
  { surahId: 23, ayahNumber: 90, text: 'Rather, We have brought them the truth, and indeed they are liars.' },
  { surahId: 23, ayahNumber: 91, text: 'Allah has not taken any son, nor has there ever been with Him any deity. [If there had been], then each deity would have taken what it created, and some of them would have sought to overcome others. Exalted is Allah above what they describe [concerning Him].' },
  { surahId: 23, ayahNumber: 92, text: '[He is] Knower of the unseen and the witnessed, so high is He above what they associate [with Him].' },
  { surahId: 23, ayahNumber: 93, text: 'Say, [O Muhammad], "My Lord, if You should show me that which they are promised,' },
  { surahId: 23, ayahNumber: 94, text: 'My Lord, then do not place me among the wrongdoing people."' },
  { surahId: 23, ayahNumber: 95, text: 'And indeed, We are able to show you what We have promised them.' },
  { surahId: 23, ayahNumber: 96, text: 'Repel, by [means of] what is best, [their] evil. We are most knowing of what they describe.' },
  { surahId: 23, ayahNumber: 97, text: 'And say, "My Lord, I seek refuge in You from the incitements of the devils,' },
  { surahId: 23, ayahNumber: 98, text: 'And I seek refuge in You, my Lord, lest they be present with me."' },
  { surahId: 23, ayahNumber: 99, text: '[For such is the state of the disbelievers], until, when death comes to one of them, he says, "My Lord, send me back' },
  { surahId: 23, ayahNumber: 100, text: 'That I might do righteousness in that which I left behind." No! It is only a word he is saying; and behind them is a barrier until the Day they are resurrected.' },
  { surahId: 23, ayahNumber: 101, text: 'So when the Horn is blown, no relationship will there be among them that Day, nor will they ask about one another.' },
  { surahId: 23, ayahNumber: 102, text: 'And those whose scales are heavy [with good deeds] - it is they who are the successful.' },
  { surahId: 23, ayahNumber: 103, text: 'But those whose scales are light - those are the ones who have lost their souls, [being] in Hell, abiding eternally.' },
  { surahId: 23, ayahNumber: 104, text: 'The Fire will sear their faces, and they therein will have taut smiles.' },
  { surahId: 23, ayahNumber: 105, text: '[It will be said]. "Were not My verses recited to you and you used to deny them?"' },
  { surahId: 23, ayahNumber: 106, text: 'They will say, "Our Lord, our wretchedness overcame us, and we were a people astray.' },
  { surahId: 23, ayahNumber: 107, text: 'Our Lord, remove us from it, and if we were to return [to evil], we would indeed be wrongdoers."' },
  { surahId: 23, ayahNumber: 108, text: 'He will say, "Remain despised therein and do not speak to Me.' },
  { surahId: 23, ayahNumber: 109, text: 'Indeed, there was a party of My servants who said, \'Our Lord, we have believed, so forgive us and have mercy upon us, and You are the best of the merciful.\'' },
  { surahId: 23, ayahNumber: 110, text: 'But you took them in mockery to the point that they made you forget My remembrance, and you used to laugh at them.' },
  { surahId: 23, ayahNumber: 111, text: 'Indeed, I have rewarded them this Day for their patient endurance - that they are the attainers [of success]."' },
  { surahId: 23, ayahNumber: 112, text: '[Allah] will say, "How long did you remain on earth in number of years?"' },
  { surahId: 23, ayahNumber: 113, text: 'They will say, "We remained a day or part of a day; ask those who enumerate."' },
  { surahId: 23, ayahNumber: 114, text: 'He will say, "You stayed not but a little - if only you had known.' },
  { surahId: 23, ayahNumber: 115, text: 'Then did you think that We created you uselessly and that to Us you would not be returned?"' },
  { surahId: 23, ayahNumber: 116, text: 'So exalted is Allah, the Sovereign, the Truth; there is no deity except Him, Lord of the Noble Throne.' },
  { surahId: 23, ayahNumber: 117, text: 'And whoever invokes besides Allah another deity for which he has no proof - then his account is only with his Lord. Indeed, the disbelievers will not succeed.' },
  { surahId: 23, ayahNumber: 118, text: 'And, [O Muhammad], say, "My Lord, forgive and have mercy, and You are the best of the merciful."' },
  { surahId: 24, ayahNumber: 1, text: '[This is] a surah which We have sent down and made [that within it] obligatory and revealed therein verses of clear evidence that you might remember.' },
  { surahId: 24, ayahNumber: 2, text: 'The [unmarried] woman or [unmarried] man found guilty of sexual intercourse - lash each one of them with a hundred lashes, and do not be taken by pity for them in the religion of Allah, if you should believe in Allah and the Last Day. And let a group of the believers witness their punishment.' },
  { surahId: 24, ayahNumber: 3, text: 'The fornicator does not marry except a [female] fornicator or polytheist, and none marries her except a fornicator or a polytheist, and that has been made unlawful to the believers.' },
  { surahId: 24, ayahNumber: 4, text: 'And those who accuse chaste women and then do not produce four witnesses - lash them with eighty lashes and do not accept from them testimony ever after. And those are the defiantly disobedient,' },
  { surahId: 24, ayahNumber: 5, text: 'Except for those who repent thereafter and reform, for indeed, Allah is Forgiving and Merciful.' },
  { surahId: 24, ayahNumber: 6, text: 'And those who accuse their wives [of adultery] and have no witnesses except themselves - then the witness of one of them [shall be] four testimonies [swearing] by Allah that indeed, he is of the truthful.' },
  { surahId: 24, ayahNumber: 7, text: 'And the fifth [oath will be] that the curse of Allah be upon him if he should be among the liars.' },
  { surahId: 24, ayahNumber: 8, text: 'But it will prevent punishment from her if she gives four testimonies [swearing] by Allah that indeed, he is of the liars.' },
  { surahId: 24, ayahNumber: 9, text: 'And the fifth [oath will be] that the wrath of Allah be upon her if he was of the truthful.' },
  { surahId: 24, ayahNumber: 10, text: 'And if not for the favor of Allah upon you and His mercy... and because Allah is Accepting of repentance and Wise.' },
  { surahId: 24, ayahNumber: 11, text: 'Indeed, those who came with falsehood are a group among you. Do not think it bad for you; rather it is good for you. For every person among them is what [punishment] he has earned from the sin, and he who took upon himself the greater portion thereof - for him is a great punishment.' },
  { surahId: 24, ayahNumber: 12, text: 'Why, when you heard it, did not the believing men and believing women think good of one another and say, "This is an obvious falsehood"?' },
  { surahId: 24, ayahNumber: 13, text: 'Why did they [who slandered] not produce for it four witnesses? And when they do not produce the witnesses, then it is they, in the sight of Allah, who are the liars.' },
  { surahId: 24, ayahNumber: 14, text: 'And if it had not been for the favor of Allah upon you and His mercy in this world and the Hereafter, you would have been touched for that [lie] in which you were involved by a great punishment' },
  { surahId: 24, ayahNumber: 15, text: 'When you received it with your tongues and said with your mouths that of which you had no knowledge and thought it was insignificant while it was, in the sight of Allah, tremendous.' },
  { surahId: 24, ayahNumber: 16, text: 'And why, when you heard it, did you not say, "It is not for us to speak of this. Exalted are You, [O Allah]; this is a great slander"?' },
  { surahId: 24, ayahNumber: 17, text: 'Allah warns you against returning to the likes of this [conduct], ever, if you should be believers.' },
  { surahId: 24, ayahNumber: 18, text: 'And Allah makes clear to you the verses, and Allah is Knowing and Wise.' },
  { surahId: 24, ayahNumber: 19, text: 'Indeed, those who like that immorality should be spread [or publicized] among those who have believed will have a painful punishment in this world and the Hereafter. And Allah knows and you do not know.' },
  { surahId: 24, ayahNumber: 20, text: 'And if it had not been for the favor of Allah upon you and His mercy... and because Allah is Kind and Merciful.' },
  { surahId: 24, ayahNumber: 21, text: 'O you who have believed, do not follow the footsteps of Satan. And whoever follows the footsteps of Satan - indeed, he enjoins immorality and wrongdoing. And if not for the favor of Allah upon you and His mercy, not one of you would have been pure, ever, but Allah purifies whom He wills, and Allah is Hearing and Knowing.' },
  { surahId: 24, ayahNumber: 22, text: 'And let not those of virtue among you and wealth swear not to give [aid] to their relatives and the needy and the emigrants for the cause of Allah, and let them pardon and overlook. Would you not like that Allah should forgive you? And Allah is Forgiving and Merciful.' },
  { surahId: 24, ayahNumber: 23, text: 'Indeed, those who [falsely] accuse chaste, unaware and believing women are cursed in this world and the Hereafter; and they will have a great punishment' },
  { surahId: 24, ayahNumber: 24, text: 'On a Day when their tongues, their hands and their feet will bear witness against them as to what they used to do.' },
  { surahId: 24, ayahNumber: 25, text: 'That Day, Allah will pay them in full their deserved recompense, and they will know that it is Allah who is the perfect in justice.' },
  { surahId: 24, ayahNumber: 26, text: 'Evil words are for evil men, and evil men are [subjected] to evil words. And good words are for good men, and good men are [an object] of good words. Those [good people] are declared innocent of what the slanderers say. For them is forgiveness and noble provision.' },
  { surahId: 24, ayahNumber: 27, text: 'O you who have believed, do not enter houses other than your own houses until you ascertain welcome and greet their inhabitants. That is best for you; perhaps you will be reminded.' },
  { surahId: 24, ayahNumber: 28, text: 'And if you do not find anyone therein, do not enter them until permission has been given you. And if it is said to you, "Go back," then go back; it is purer for you. And Allah is Knowing of what you do.' },
  { surahId: 24, ayahNumber: 29, text: 'There is no blame upon you for entering houses not inhabited in which there is convenience for you. And Allah knows what you reveal and what you conceal.' },
  { surahId: 24, ayahNumber: 30, text: 'Tell the believing men to reduce [some] of their vision and guard their private parts. That is purer for them. Indeed, Allah is Acquainted with what they do.' },
  { surahId: 24, ayahNumber: 31, text: 'And tell the believing women to reduce [some] of their vision and guard their private parts and not expose their adornment except that which [necessarily] appears thereof and to wrap [a portion of] their headcovers over their chests and not expose their adornment except to their husbands, their fathers, their husbands\' fathers, their sons, their husbands\' sons, their brothers, their brothers\' sons, their sisters\' sons, their women, that which their right hands possess, or those male attendants having no physical desire, or children who are not yet aware of the private aspects of women. And let them not stamp their feet to make known what they conceal of their adornment. And turn to Allah in repentance, all of you, O believers, that you might succeed.' },
  { surahId: 24, ayahNumber: 32, text: 'And marry the unmarried among you and the righteous among your male slaves and female slaves. If they should be poor, Allah will enrich them from His bounty, and Allah is all-Encompassing and Knowing.' },
  { surahId: 24, ayahNumber: 33, text: 'But let them who find not [the means for] marriage abstain [from sexual relations] until Allah enriches them from His bounty. And those who seek a contract [for eventual emancipation] from among whom your right hands possess - then make a contract with them if you know there is within them goodness and give them from the wealth of Allah which He has given you. And do not compel your slave girls to prostitution, if they desire chastity, to seek [thereby] the temporary interests of worldly life. And if someone should compel them, then indeed, Allah is [to them], after their compulsion, Forgiving and Merciful.' },
  { surahId: 24, ayahNumber: 34, text: 'And We have certainly sent down to you distinct verses and examples from those who passed on before you and an admonition for those who fear Allah.' },
  { surahId: 24, ayahNumber: 35, text: 'Allah is the Light of the heavens and the earth. The example of His light is like a niche within which is a lamp, the lamp is within glass, the glass as if it were a pearly [white] star lit from [the oil of] a blessed olive tree, neither of the east nor of the west, whose oil would almost glow even if untouched by fire. Light upon light. Allah guides to His light whom He wills. And Allah presents examples for the people, and Allah is Knowing of all things.' },
  { surahId: 24, ayahNumber: 36, text: '[Such niches are] in mosques which Allah has ordered to be raised and that His name be mentioned therein; exalting Him within them in the morning and the evenings' },
  { surahId: 24, ayahNumber: 37, text: '[Are] men whom neither commerce nor sale distracts from the remembrance of Allah and performance of prayer and giving of zakah. They fear a Day in which the hearts and eyes will [fearfully] turn about -' },
  { surahId: 24, ayahNumber: 38, text: 'That Allah may reward them [according to] the best of what they did and increase them from His bounty. And Allah gives provision to whom He wills without account.' },
  { surahId: 24, ayahNumber: 39, text: 'But those who disbelieved - their deeds are like a mirage in a lowland which a thirsty one thinks is water until, when he comes to it, he finds it is nothing but finds Allah before Him, and He will pay him in full his due; and Allah is swift in account.' },
  { surahId: 24, ayahNumber: 40, text: 'Or [they are] like darknesses within an unfathomable sea which is covered by waves, upon which are waves, over which are clouds - darknesses, some of them upon others. When one puts out his hand [therein], he can hardly see it. And he to whom Allah has not granted light - for him there is no light.' },
  { surahId: 24, ayahNumber: 41, text: 'Do you not see that Allah is exalted by whomever is within the heavens and the earth and [by] the birds with wings spread [in flight]? Each [of them] has known his [means of] prayer and exalting [Him], and Allah is Knowing of what they do.' },
  { surahId: 24, ayahNumber: 42, text: 'And to Allah belongs the dominion of the heavens and the earth, and to Allah is the destination.' },
  { surahId: 24, ayahNumber: 43, text: 'Do you not see that Allah drives clouds? Then He brings them together, then He makes them into a mass, and you see the rain emerge from within it. And He sends down from the sky, mountains [of clouds] within which is hail, and He strikes with it whom He wills and averts it from whom He wills. The flash of its lightening almost takes away the eyesight.' },
  { surahId: 24, ayahNumber: 44, text: 'Allah alternates the night and the day. Indeed in that is a lesson for those who have vision.' },
  { surahId: 24, ayahNumber: 45, text: 'Allah has created every [living] creature from water. And of them are those that move on their bellies, and of them are those that walk on two legs, and of them are those that walk on four. Allah creates what He wills. Indeed, Allah is over all things competent.' },
  { surahId: 24, ayahNumber: 46, text: 'We have certainly sent down distinct verses. And Allah guides whom He wills to a straight path.' },
  { surahId: 24, ayahNumber: 47, text: 'But the hypocrites say, "We have believed in Allah and in the Messenger, and we obey"; then a party of them turns away after that. And those are not believers.' },
  { surahId: 24, ayahNumber: 48, text: 'And when they are called to [the words of] Allah and His Messenger to judge between them, at once a party of them turns aside [in refusal].' },
  { surahId: 24, ayahNumber: 49, text: 'But if the right is theirs, they come to him in prompt obedience.' },
  { surahId: 24, ayahNumber: 50, text: 'Is there disease in their hearts? Or have they doubted? Or do they fear that Allah will be unjust to them, or His Messenger? Rather, it is they who are the wrongdoers.' },
  { surahId: 24, ayahNumber: 51, text: 'The only statement of the [true] believers when they are called to Allah and His Messenger to judge between them is that they say, "We hear and we obey." And those are the successful.' },
  { surahId: 24, ayahNumber: 52, text: 'And whoever obeys Allah and His Messenger and fears Allah and is conscious of Him - it is those who are the attainers.' },
  { surahId: 24, ayahNumber: 53, text: 'And they swear by Allah their strongest oaths that if you ordered them, they would go forth [in Allah \'s cause]. Say, "Do not swear. [Such] obedience is known. Indeed, Allah is Acquainted with that which you do."' },
  { surahId: 24, ayahNumber: 54, text: 'Say, "Obey Allah and obey the Messenger; but if you turn away - then upon him is only that [duty] with which he has been charged, and upon you is that with which you have been charged. And if you obey him, you will be [rightly] guided. And there is not upon the Messenger except the [responsibility for] clear notification."' },
  { surahId: 24, ayahNumber: 55, text: 'Allah has promised those who have believed among you and done righteous deeds that He will surely grant them succession [to authority] upon the earth just as He granted it to those before them and that He will surely establish for them [therein] their religion which He has preferred for them and that He will surely substitute for them, after their fear, security, [for] they worship Me, not associating anything with Me. But whoever disbelieves after that - then those are the defiantly disobedient.' },
  { surahId: 24, ayahNumber: 56, text: 'And establish prayer and give zakah and obey the Messenger - that you may receive mercy.' },
  { surahId: 24, ayahNumber: 57, text: 'Never think that the disbelievers are causing failure [to Allah] upon the earth. Their refuge will be the Fire - and how wretched the destination.' },
  { surahId: 24, ayahNumber: 58, text: 'O you who have believed, let those whom your right hands possess and those who have not [yet] reached puberty among you ask permission of you [before entering] at three times: before the dawn prayer and when you put aside your clothing [for rest] at noon and after the night prayer. [These are] three times of privacy for you. There is no blame upon you nor upon them beyond these [periods], for they continually circulate among you - some of you, among others. Thus does Allah make clear to you the verses; and Allah is Knowing and Wise.' },
  { surahId: 24, ayahNumber: 59, text: 'And when the children among you reach puberty, let them ask permission [at all times] as those before them have done. Thus does Allah make clear to you His verses; and Allah is Knowing and Wise.' },
  { surahId: 24, ayahNumber: 60, text: 'And women of post-menstrual age who have no desire for marriage - there is no blame upon them for putting aside their outer garments [but] not displaying adornment. But to modestly refrain [from that] is better for them. And Allah is Hearing and Knowing.' },
  { surahId: 24, ayahNumber: 61, text: 'There is not upon the blind [any] constraint nor upon the lame constraint nor upon the ill constraint nor upon yourselves when you eat from your [own] houses or the houses of your fathers or the houses of your mothers or the houses of your brothers or the houses of your sisters or the houses of your father\'s brothers or the houses of your father\'s sisters or the houses of your mother\'s brothers or the houses of your mother\'s sisters or [from houses] whose keys you possess or [from the house] of your friend. There is no blame upon you whether you eat together or separately. But when you enter houses, give greetings of peace upon each other - a greeting from Allah, blessed and good. Thus does Allah make clear to you the verses [of ordinance] that you may understand.' },
  { surahId: 24, ayahNumber: 62, text: 'The believers are only those who believe in Allah and His Messenger and, when they are [meeting] with him for a matter of common interest, do not depart until they have asked his permission. Indeed, those who ask your permission, [O Muhammad] - those are the ones who believe in Allah and His Messenger. So when they ask your permission for something of their affairs, then give permission to whom you will among them and ask forgiveness for them of Allah. Indeed, Allah is Forgiving and Merciful.' },
  { surahId: 24, ayahNumber: 63, text: 'Do not make [your] calling of the Messenger among yourselves as the call of one of you to another. Already Allah knows those of you who slip away, concealed by others. So let those beware who dissent from the Prophet\'s order, lest fitnah strike them or a painful punishment.' },
  { surahId: 24, ayahNumber: 64, text: 'Unquestionably, to Allah belongs whatever is in the heavens and earth. Already He knows that upon which you [stand] and [knows] the Day when they will be returned to Him and He will inform them of what they have done. And Allah is Knowing of all things.' },
  { surahId: 25, ayahNumber: 1, text: 'Blessed is He who sent down the Criterion upon His Servant that he may be to the worlds a warner -' },
  { surahId: 25, ayahNumber: 2, text: 'He to whom belongs the dominion of the heavens and the earth and who has not taken a son and has not had a partner in dominion and has created each thing and determined it with [precise] determination.' },
  { surahId: 25, ayahNumber: 3, text: 'But they have taken besides Him gods which create nothing, while they are created, and possess not for themselves any harm or benefit and possess not [power to cause] death or life or resurrection.' },
  { surahId: 25, ayahNumber: 4, text: 'And those who disbelieve say, "This [Qur\'an] is not except a falsehood he invented, and another people assisted him in it." But they have committed an injustice and a lie.' },
  { surahId: 25, ayahNumber: 5, text: 'And they say, "Legends of the former peoples which he has written down, and they are dictated to him morning and afternoon."' },
  { surahId: 25, ayahNumber: 6, text: 'Say, [O Muhammad], "It has been revealed by He who knows [every] secret within the heavens and the earth. Indeed, He is ever Forgiving and Merciful."' },
  { surahId: 25, ayahNumber: 7, text: 'And they say, "What is this messenger that eats food and walks in the markets? Why was there not sent down to him an angel so he would be with him a warner?' },
  { surahId: 25, ayahNumber: 8, text: 'Or [why is not] a treasure presented to him [from heaven], or does he [not] have a garden from which he eats?" And the wrongdoers say, "You follow not but a man affected by magic."' },
  { surahId: 25, ayahNumber: 9, text: 'Look how they strike for you comparisons; but they have strayed, so they cannot [find] a way.' },
  { surahId: 25, ayahNumber: 10, text: 'Blessed is He who, if He willed, could have made for you [something] better than that - gardens beneath which rivers flow - and could make for you palaces.' },
  { surahId: 25, ayahNumber: 11, text: 'But they have denied the Hour, and We have prepared for those who deny the Hour a Blaze.' },
  { surahId: 25, ayahNumber: 12, text: 'When the Hellfire sees them from a distant place, they will hear its fury and roaring.' },
  { surahId: 25, ayahNumber: 13, text: 'And when they are thrown into a narrow place therein bound in chains, they will cry out thereupon for destruction.' },
  { surahId: 25, ayahNumber: 14, text: '[They will be told], "Do not cry this Day for one destruction but cry for much destruction."' },
  { surahId: 25, ayahNumber: 15, text: 'Say, "Is that better or the Garden of Eternity which is promised to the righteous? It will be for them a reward and destination.' },
  { surahId: 25, ayahNumber: 16, text: 'For them therein is whatever they wish, [while] abiding eternally. It is ever upon your Lord a promise [worthy to be] requested.' },
  { surahId: 25, ayahNumber: 17, text: 'And [mention] the Day He will gather them and that which they worship besides Allah and will say, "Did you mislead these, My servants, or did they [themselves] stray from the way?"' },
  { surahId: 25, ayahNumber: 18, text: 'They will say, "Exalted are You! It was not for us to take besides You any allies. But You provided comforts for them and their fathers until they forgot the message and became a people ruined."' },
  { surahId: 25, ayahNumber: 19, text: 'So they will deny you, [disbelievers], in what you say, and you cannot avert [punishment] or [find] help. And whoever commits injustice among you - We will make him taste a great punishment.' },
  { surahId: 25, ayahNumber: 20, text: 'And We did not send before you, [O Muhammad], any of the messengers except that they ate food and walked in the markets. And We have made some of you [people] as trial for others - will you have patience? And ever is your Lord, Seeing.' },
  { surahId: 25, ayahNumber: 21, text: 'And those who do not expect the meeting with Us say, "Why were not angels sent down to us, or [why] do we [not] see our Lord?" They have certainly become arrogant within themselves and [become] insolent with great insolence.' },
  { surahId: 25, ayahNumber: 22, text: 'The day they see the angels - no good tidings will there be that day for the criminals, and [the angels] will say, "Prevented and inaccessible."' },
  { surahId: 25, ayahNumber: 23, text: 'And We will regard what they have done of deeds and make them as dust dispersed.' },
  { surahId: 25, ayahNumber: 24, text: 'The companions of Paradise, that Day, are [in] a better settlement and better resting place.' },
  { surahId: 25, ayahNumber: 25, text: 'And [mention] the Day when the heaven will split open with [emerging] clouds, and the angels will be sent down in successive descent.' },
  { surahId: 25, ayahNumber: 26, text: 'True sovereignty, that Day, is for the Most Merciful. And it will be upon the disbelievers a difficult Day.' },
  { surahId: 25, ayahNumber: 27, text: 'And the Day the wrongdoer will bite on his hands [in regret] he will say, "Oh, I wish I had taken with the Messenger a way.' },
  { surahId: 25, ayahNumber: 28, text: 'Oh, woe to me! I wish I had not taken that one as a friend.' },
  { surahId: 25, ayahNumber: 29, text: 'He led me away from the remembrance after it had come to me. And ever is Satan, to man, a deserter."' },
  { surahId: 25, ayahNumber: 30, text: 'And the Messenger has said, "O my Lord, indeed my people have taken this Qur\'an as [a thing] abandoned."' },
  { surahId: 25, ayahNumber: 31, text: 'And thus have We made for every prophet an enemy from among the criminals. But sufficient is your Lord as a guide and a helper.' },
  { surahId: 25, ayahNumber: 32, text: 'And those who disbelieve say, "Why was the Qur\'an not revealed to him all at once?" Thus [it is] that We may strengthen thereby your heart. And We have spaced it distinctly.' },
  { surahId: 25, ayahNumber: 33, text: 'And they do not come to you with an argument except that We bring you the truth and the best explanation.' },
  { surahId: 25, ayahNumber: 34, text: 'The ones who are gathered on their faces to Hell - those are the worst in position and farthest astray in [their] way.' },
  { surahId: 25, ayahNumber: 35, text: 'And We had certainly given Moses the Scripture and appointed with him his brother Aaron as an assistant.' },
  { surahId: 25, ayahNumber: 36, text: 'And We said, "Go both of you to the people who have denied Our signs." Then We destroyed them with [complete] destruction.' },
  { surahId: 25, ayahNumber: 37, text: 'And the people of Noah - when they denied the messengers, We drowned them, and We made them for mankind a sign. And We have prepared for the wrongdoers a painful punishment.' },
  { surahId: 25, ayahNumber: 38, text: 'And [We destroyed] \'Aad and Thamud and the companions of the well and many generations between them.' },
  { surahId: 25, ayahNumber: 39, text: 'And for each We presented examples [as warnings], and each We destroyed with [total] destruction.' },
  { surahId: 25, ayahNumber: 40, text: 'And they have already come upon the town which was showered with a rain of evil. So have they not seen it? But they are not expecting resurrection.' },
  { surahId: 25, ayahNumber: 41, text: 'And when they see you, [O Muhammad], they take you not except in ridicule, [saying], "Is this the one whom Allah has sent as a messenger?' },
  { surahId: 25, ayahNumber: 42, text: 'He almost would have misled us from our gods had we not been steadfast in [worship of] them." But they are going to know, when they see the punishment, who is farthest astray in [his] way.' },
  { surahId: 25, ayahNumber: 43, text: 'Have you seen the one who takes as his god his own desire? Then would you be responsible for him?' },
  { surahId: 25, ayahNumber: 44, text: 'Or do you think that most of them hear or reason? They are not except like livestock. Rather, they are [even] more astray in [their] way.' },
  { surahId: 25, ayahNumber: 45, text: 'Have you not considered your Lord - how He extends the shadow, and if He willed, He could have made it stationary? Then We made the sun for it an indication.' },
  { surahId: 25, ayahNumber: 46, text: 'Then We hold it in hand for a brief grasp.' },
  { surahId: 25, ayahNumber: 47, text: 'And it is He who has made the night for you as clothing and sleep [a means for] rest and has made the day a resurrection.' },
  { surahId: 25, ayahNumber: 48, text: 'And it is He who sends the winds as good tidings before His mercy, and We send down from the sky pure water' },
  { surahId: 25, ayahNumber: 49, text: 'That We may bring to life thereby a dead land and give it as drink to those We created of numerous livestock and men.' },
  { surahId: 25, ayahNumber: 50, text: 'And We have certainly distributed it among them that they might be reminded, but most of the people refuse except disbelief.' },
  { surahId: 25, ayahNumber: 51, text: 'And if We had willed, We could have sent into every city a warner.' },
  { surahId: 25, ayahNumber: 52, text: 'So do not obey the disbelievers, and strive against them with the Qur\'an a great striving.' },
  { surahId: 25, ayahNumber: 53, text: 'And it is He who has released [simultaneously] the two seas, one fresh and sweet and one salty and bitter, and He placed between them a barrier and prohibiting partition.' },
  { surahId: 25, ayahNumber: 54, text: 'And it is He who has created from water a human being and made him [a relative by] lineage and marriage. And ever is your Lord competent [concerning creation].' },
  { surahId: 25, ayahNumber: 55, text: 'But they worship rather than Allah that which does not benefit them or harm them, and the disbeliever is ever, against his Lord, an assistant [to Satan].' },
  { surahId: 25, ayahNumber: 56, text: 'And We have not sent you, [O Muhammad], except as a bringer of good tidings and a warner.' },
  { surahId: 25, ayahNumber: 57, text: 'Say, "I do not ask of you for it any payment - only that whoever wills might take to his Lord a way."' },
  { surahId: 25, ayahNumber: 58, text: 'And rely upon the Ever-Living who does not die, and exalt [Allah] with His praise. And sufficient is He to be, with the sins of His servants, Acquainted -' },
  { surahId: 25, ayahNumber: 59, text: 'He who created the heavens and the earth and what is between them in six days and then established Himself above the Throne - the Most Merciful, so ask about Him one well informed.' },
  { surahId: 25, ayahNumber: 60, text: 'And when it is said to them, "Prostrate to the Most Merciful," they say, "And what is the Most Merciful? Should we prostrate to that which you order us?" And it increases them in aversion.' },
  { surahId: 25, ayahNumber: 61, text: 'Blessed is He who has placed in the sky great stars and placed therein a [burning] lamp and luminous moon.' },
  { surahId: 25, ayahNumber: 62, text: 'And it is He who has made the night and the day in succession for whoever desires to remember or desires gratitude.' },
  { surahId: 25, ayahNumber: 63, text: 'And the servants of the Most Merciful are those who walk upon the earth easily, and when the ignorant address them [harshly], they say [words of] peace,' },
  { surahId: 25, ayahNumber: 64, text: 'And those who spend [part of] the night to their Lord prostrating and standing [in prayer]' },
  { surahId: 25, ayahNumber: 65, text: 'And those who say, "Our Lord, avert from us the punishment of Hell. Indeed, its punishment is ever adhering;' },
  { surahId: 25, ayahNumber: 66, text: 'Indeed, it is evil as a settlement and residence."' },
  { surahId: 25, ayahNumber: 67, text: 'And [they are] those who, when they spend, do so not excessively or sparingly but are ever, between that, [justly] moderate' },
  { surahId: 25, ayahNumber: 68, text: 'And those who do not invoke with Allah another deity or kill the soul which Allah has forbidden [to be killed], except by right, and do not commit unlawful sexual intercourse. And whoever should do that will meet a penalty.' },
  { surahId: 25, ayahNumber: 69, text: 'Multiplied for him is the punishment on the Day of Resurrection, and he will abide therein humiliated -' },
  { surahId: 25, ayahNumber: 70, text: 'Except for those who repent, believe and do righteous work. For them Allah will replace their evil deeds with good. And ever is Allah Forgiving and Merciful.' },
  { surahId: 25, ayahNumber: 71, text: 'And he who repents and does righteousness does indeed turn to Allah with [accepted] repentance.' },
  { surahId: 25, ayahNumber: 72, text: 'And [they are] those who do not testify to falsehood, and when they pass near ill speech, they pass by with dignity.' },
  { surahId: 25, ayahNumber: 73, text: 'And those who, when reminded of the verses of their Lord, do not fall upon them deaf and blind.' },
  { surahId: 25, ayahNumber: 74, text: 'And those who say, "Our Lord, grant us from among our wives and offspring comfort to our eyes and make us an example for the righteous."' },
  { surahId: 25, ayahNumber: 75, text: 'Those will be awarded the Chamber for what they patiently endured, and they will be received therein with greetings and [words of] peace.' },
  { surahId: 25, ayahNumber: 76, text: 'Abiding eternally therein. Good is the settlement and residence.' },
  { surahId: 25, ayahNumber: 77, text: 'Say, "What would my Lord care for you if not for your supplication?" For you [disbelievers] have denied, so your denial is going to be adherent.' },
  { surahId: 26, ayahNumber: 1, text: 'Ta, Seen, Meem.' },
  { surahId: 26, ayahNumber: 2, text: 'These are the verses of the clear Book.' },
  { surahId: 26, ayahNumber: 3, text: 'Perhaps, [O Muhammad], you would kill yourself with grief that they will not be believers.' },
  { surahId: 26, ayahNumber: 4, text: 'If We willed, We could send down to them from the sky a sign for which their necks would remain humbled.' },
  { surahId: 26, ayahNumber: 5, text: 'And no revelation comes to them anew from the Most Merciful except that they turn away from it.' },
  { surahId: 26, ayahNumber: 6, text: 'For they have already denied, but there will come to them the news of that which they used to ridicule.' },
  { surahId: 26, ayahNumber: 7, text: 'Did they not look at the earth - how much We have produced therein from every noble kind?' },
  { surahId: 26, ayahNumber: 8, text: 'Indeed in that is a sign, but most of them were not to be believers.' },
  { surahId: 26, ayahNumber: 9, text: 'And indeed, your Lord - He is the Exalted in Might, the Merciful.' },
  { surahId: 26, ayahNumber: 10, text: 'And [mention] when your Lord called Moses, [saying], "Go to the wrongdoing people -' },
  { surahId: 26, ayahNumber: 11, text: 'The people of Pharaoh. Will they not fear Allah?"' },
  { surahId: 26, ayahNumber: 12, text: 'He said, "My Lord, indeed I fear that they will deny me' },
  { surahId: 26, ayahNumber: 13, text: 'And that my breast will tighten and my tongue will not be fluent, so send for Aaron.' },
  { surahId: 26, ayahNumber: 14, text: 'And they have upon me a [claim due to] sin, so I fear that they will kill me."' },
  { surahId: 26, ayahNumber: 15, text: '[Allah] said, "No. Go both of you with Our signs; indeed, We are with you, listening.' },
  { surahId: 26, ayahNumber: 16, text: 'Go to Pharaoh and say, \'We are the messengers of the Lord of the worlds,' },
  { surahId: 26, ayahNumber: 17, text: '[Commanded to say], "Send with us the Children of Israel."\'"' },
  { surahId: 26, ayahNumber: 18, text: '[Pharaoh] said, "Did we not raise you among us as a child, and you remained among us for years of your life?' },
  { surahId: 26, ayahNumber: 19, text: 'And [then] you did your deed which you did, and you were of the ungrateful."' },
  { surahId: 26, ayahNumber: 20, text: '[Moses] said, "I did it, then, while I was of those astray.' },
  { surahId: 26, ayahNumber: 21, text: 'So I fled from you when I feared you. Then my Lord granted me wisdom and prophethood and appointed me [as one] of the messengers.' },
  { surahId: 26, ayahNumber: 22, text: 'And is this a favor of which you remind me - that you have enslaved the Children of Israel?"' },
  { surahId: 26, ayahNumber: 23, text: 'Said Pharaoh, "And what is the Lord of the worlds?"' },
  { surahId: 26, ayahNumber: 24, text: '[Moses] said, "The Lord of the heavens and earth and that between them, if you should be convinced."' },
  { surahId: 26, ayahNumber: 25, text: '[Pharaoh] said to those around him, "Do you not hear?"' },
  { surahId: 26, ayahNumber: 26, text: '[Moses] said, "Your Lord and the Lord of your first forefathers."' },
  { surahId: 26, ayahNumber: 27, text: '[Pharaoh] said, "Indeed, your \'messenger\' who has been sent to you is mad."' },
  { surahId: 26, ayahNumber: 28, text: '[Moses] said, "Lord of the east and the west and that between them, if you were to reason."' },
  { surahId: 26, ayahNumber: 29, text: '[Pharaoh] said, "If you take a god other than me, I will surely place you among those imprisoned."' },
  { surahId: 26, ayahNumber: 30, text: '[Moses] said, "Even if I brought you proof manifest?"' },
  { surahId: 26, ayahNumber: 31, text: '[Pharaoh] said, "Then bring it, if you should be of the truthful."' },
  { surahId: 26, ayahNumber: 32, text: 'So [Moses] threw his staff, and suddenly it was a serpent manifest.' },
  { surahId: 26, ayahNumber: 33, text: 'And he drew out his hand; thereupon it was white for the observers.' },
  { surahId: 26, ayahNumber: 34, text: '[Pharaoh] said to the eminent ones around him, "Indeed, this is a learned magician.' },
  { surahId: 26, ayahNumber: 35, text: 'He wants to drive you out of your land by his magic, so what do you advise?"' },
  { surahId: 26, ayahNumber: 36, text: 'They said, "Postpone [the matter of] him and his brother and send among the cities gatherers' },
  { surahId: 26, ayahNumber: 37, text: 'Who will bring you every learned, skilled magician."' },
  { surahId: 26, ayahNumber: 38, text: 'So the magicians were assembled for the appointment of a well-known day.' },
  { surahId: 26, ayahNumber: 39, text: 'And it was said to the people, "Will you congregate' },
  { surahId: 26, ayahNumber: 40, text: 'That we might follow the magicians if they are the predominant?"' },
  { surahId: 26, ayahNumber: 41, text: 'And when the magicians arrived, they said to Pharaoh, "Is there indeed for us a reward if we are the predominant?"' },
  { surahId: 26, ayahNumber: 42, text: 'He said, "Yes, and indeed, you will then be of those near [to me]."' },
  { surahId: 26, ayahNumber: 43, text: 'Moses said to them, "Throw whatever you will throw."' },
  { surahId: 26, ayahNumber: 44, text: 'So they threw their ropes and their staffs and said, "By the might of Pharaoh, indeed it is we who are predominant."' },
  { surahId: 26, ayahNumber: 45, text: 'Then Moses threw his staff, and at once it devoured what they falsified.' },
  { surahId: 26, ayahNumber: 46, text: 'So the magicians fell down in prostration [to Allah].' },
  { surahId: 26, ayahNumber: 47, text: 'They said, "We have believed in the Lord of the worlds,' },
  { surahId: 26, ayahNumber: 48, text: 'The Lord of Moses and Aaron."' },
  { surahId: 26, ayahNumber: 49, text: '[Pharaoh] said, "You believed Moses before I gave you permission. Indeed, he is your leader who has taught you magic, but you are going to know. I will surely cut off your hands and your feet on opposite sides, and I will surely crucify you all."' },
  { surahId: 26, ayahNumber: 50, text: 'They said, "No harm. Indeed, to our Lord we will return.' },
  { surahId: 26, ayahNumber: 51, text: 'Indeed, we aspire that our Lord will forgive us our sins because we were the first of the believers."' },
  { surahId: 26, ayahNumber: 52, text: 'And We inspired to Moses, "Travel by night with My servants; indeed, you will be pursued."' },
  { surahId: 26, ayahNumber: 53, text: 'Then Pharaoh sent among the cities gatherers' },
  { surahId: 26, ayahNumber: 54, text: '[And said], "Indeed, those are but a small band,' },
  { surahId: 26, ayahNumber: 55, text: 'And indeed, they are enraging us,' },
  { surahId: 26, ayahNumber: 56, text: 'And indeed, we are a cautious society... "' },
  { surahId: 26, ayahNumber: 57, text: 'So We removed them from gardens and springs' },
  { surahId: 26, ayahNumber: 58, text: 'And treasures and honorable station -' },
  { surahId: 26, ayahNumber: 59, text: 'Thus. And We caused to inherit it the Children of Israel.' },
  { surahId: 26, ayahNumber: 60, text: 'So they pursued them at sunrise.' },
  { surahId: 26, ayahNumber: 61, text: 'And when the two companies saw one another, the companions of Moses said, "Indeed, we are to be overtaken!"' },
  { surahId: 26, ayahNumber: 62, text: '[Moses] said, "No! Indeed, with me is my Lord; He will guide me."' },
  { surahId: 26, ayahNumber: 63, text: 'Then We inspired to Moses, "Strike with your staff the sea," and it parted, and each portion was like a great towering mountain.' },
  { surahId: 26, ayahNumber: 64, text: 'And We advanced thereto the pursuers.' },
  { surahId: 26, ayahNumber: 65, text: 'And We saved Moses and those with him, all together.' },
  { surahId: 26, ayahNumber: 66, text: 'Then We drowned the others.' },
  { surahId: 26, ayahNumber: 67, text: 'Indeed in that is a sign, but most of them were not to be believers.' },
  { surahId: 26, ayahNumber: 68, text: 'And indeed, your Lord - He is the Exalted in Might, the Merciful.' },
  { surahId: 26, ayahNumber: 69, text: 'And recite to them the news of Abraham,' },
  { surahId: 26, ayahNumber: 70, text: 'When he said to his father and his people, "What do you worship?"' },
  { surahId: 26, ayahNumber: 71, text: 'They said, "We worship idols and remain to them devoted."' },
  { surahId: 26, ayahNumber: 72, text: 'He said, "Do they hear you when you supplicate?' },
  { surahId: 26, ayahNumber: 73, text: 'Or do they benefit you, or do they harm?"' },
  { surahId: 26, ayahNumber: 74, text: 'They said, "But we found our fathers doing thus."' },
  { surahId: 26, ayahNumber: 75, text: 'He said, "Then do you see what you have been worshipping,' },
  { surahId: 26, ayahNumber: 76, text: 'You and your ancient forefathers?' },
  { surahId: 26, ayahNumber: 77, text: 'Indeed, they are enemies to me, except the Lord of the worlds,' },
  { surahId: 26, ayahNumber: 78, text: 'Who created me, and He [it is who] guides me.' },
  { surahId: 26, ayahNumber: 79, text: 'And it is He who feeds me and gives me drink.' },
  { surahId: 26, ayahNumber: 80, text: 'And when I am ill, it is He who cures me' },
  { surahId: 26, ayahNumber: 81, text: 'And who will cause me to die and then bring me to life' },
  { surahId: 26, ayahNumber: 82, text: 'And who I aspire that He will forgive me my sin on the Day of Recompense."' },
  { surahId: 26, ayahNumber: 83, text: '[And he said], "My Lord, grant me authority and join me with the righteous.' },
  { surahId: 26, ayahNumber: 84, text: 'And grant me a reputation of honor among later generations.' },
  { surahId: 26, ayahNumber: 85, text: 'And place me among the inheritors of the Garden of Pleasure.' },
  { surahId: 26, ayahNumber: 86, text: 'And forgive my father. Indeed, he has been of those astray.' },
  { surahId: 26, ayahNumber: 87, text: 'And do not disgrace me on the Day they are [all] resurrected -' },
  { surahId: 26, ayahNumber: 88, text: 'The Day when there will not benefit [anyone] wealth or children' },
  { surahId: 26, ayahNumber: 89, text: 'But only one who comes to Allah with a sound heart."' },
  { surahId: 26, ayahNumber: 90, text: 'And Paradise will be brought near [that Day] to the righteous.' },
  { surahId: 26, ayahNumber: 91, text: 'And Hellfire will be brought forth for the deviators,' },
  { surahId: 26, ayahNumber: 92, text: 'And it will be said to them, "Where are those you used to worship' },
  { surahId: 26, ayahNumber: 93, text: 'Other than Allah? Can they help you or help themselves?"' },
  { surahId: 26, ayahNumber: 94, text: 'So they will be overturned into Hellfire, they and the deviators' },
  { surahId: 26, ayahNumber: 95, text: 'And the soldiers of Iblees, all together.' },
  { surahId: 26, ayahNumber: 96, text: 'They will say while they dispute therein,' },
  { surahId: 26, ayahNumber: 97, text: '"By Allah, we were indeed in manifest error' },
  { surahId: 26, ayahNumber: 98, text: 'When we equated you with the Lord of the worlds.' },
  { surahId: 26, ayahNumber: 99, text: 'And no one misguided us except the criminals.' },
  { surahId: 26, ayahNumber: 100, text: 'So now we have no intercessors' },
  { surahId: 26, ayahNumber: 101, text: 'And not a devoted friend.' },
  { surahId: 26, ayahNumber: 102, text: 'Then if we only had a return [to the world] and could be of the believers... "' },
  { surahId: 26, ayahNumber: 103, text: 'Indeed in that is a sign, but most of them were not to be believers.' },
  { surahId: 26, ayahNumber: 104, text: 'And indeed, your Lord - He is the Exalted in Might, the Merciful.' },
  { surahId: 26, ayahNumber: 105, text: 'The people of Noah denied the messengers' },
  { surahId: 26, ayahNumber: 106, text: 'When their brother Noah said to them, "Will you not fear Allah?' },
  { surahId: 26, ayahNumber: 107, text: 'Indeed, I am to you a trustworthy messenger.' },
  { surahId: 26, ayahNumber: 108, text: 'So fear Allah and obey me.' },
  { surahId: 26, ayahNumber: 109, text: 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.' },
  { surahId: 26, ayahNumber: 110, text: 'So fear Allah and obey me."' },
  { surahId: 26, ayahNumber: 111, text: 'They said, "Should we believe you while you are followed by the lowest [class of people]?"' },
  { surahId: 26, ayahNumber: 112, text: 'He said, "And what is my knowledge of what they used to do?' },
  { surahId: 26, ayahNumber: 113, text: 'Their account is only upon my Lord, if you [could] perceive.' },
  { surahId: 26, ayahNumber: 114, text: 'And I am not one to drive away the believers.' },
  { surahId: 26, ayahNumber: 115, text: 'I am only a clear warner."' },
  { surahId: 26, ayahNumber: 116, text: 'They said, "If you do not desist, O Noah, you will surely be of those who are stoned."' },
  { surahId: 26, ayahNumber: 117, text: 'He said, "My Lord, indeed my people have denied me.' },
  { surahId: 26, ayahNumber: 118, text: 'Then judge between me and them with decisive judgement and save me and those with me of the believers."' },
  { surahId: 26, ayahNumber: 119, text: 'So We saved him and those with him in the laden ship.' },
  { surahId: 26, ayahNumber: 120, text: 'Then We drowned thereafter the remaining ones.' },
  { surahId: 26, ayahNumber: 121, text: 'Indeed in that is a sign, but most of them were not to be believers.' },
  { surahId: 26, ayahNumber: 122, text: 'And indeed, your Lord - He is the Exalted in Might, the Merciful.' },
  { surahId: 26, ayahNumber: 123, text: '\'Aad denied the messengers' },
  { surahId: 26, ayahNumber: 124, text: 'When their brother Hud said to them, "Will you not fear Allah?' },
  { surahId: 26, ayahNumber: 125, text: 'Indeed, I am to you a trustworthy messenger.' },
  { surahId: 26, ayahNumber: 126, text: 'So fear Allah and obey me.' },
  { surahId: 26, ayahNumber: 127, text: 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.' },
  { surahId: 26, ayahNumber: 128, text: 'Do you construct on every elevation a sign, amusing yourselves,' },
  { surahId: 26, ayahNumber: 129, text: 'And take for yourselves palaces and fortresses that you might abide eternally?' },
  { surahId: 26, ayahNumber: 130, text: 'And when you strike, you strike as tyrants.' },
  { surahId: 26, ayahNumber: 131, text: 'So fear Allah and obey me.' },
  { surahId: 26, ayahNumber: 132, text: 'And fear He who provided you with that which you know,' },
  { surahId: 26, ayahNumber: 133, text: 'Provided you with grazing livestock and children' },
  { surahId: 26, ayahNumber: 134, text: 'And gardens and springs.' },
  { surahId: 26, ayahNumber: 135, text: 'Indeed, I fear for you the punishment of a terrible day."' },
  { surahId: 26, ayahNumber: 136, text: 'They said, "It is all the same to us whether you advise or are not of the advisors.' },
  { surahId: 26, ayahNumber: 137, text: 'This is not but the custom of the former peoples,' },
  { surahId: 26, ayahNumber: 138, text: 'And we are not to be punished."' },
  { surahId: 26, ayahNumber: 139, text: 'And they denied him, so We destroyed them. Indeed in that is a sign, but most of them were not to be believers.' },
  { surahId: 26, ayahNumber: 140, text: 'And indeed, your Lord - He is the Exalted in Might, the Merciful.' },
  { surahId: 26, ayahNumber: 141, text: 'Thamud denied the messengers' },
  { surahId: 26, ayahNumber: 142, text: 'When their brother Salih said to them, "Will you not fear Allah?' },
  { surahId: 26, ayahNumber: 143, text: 'Indeed, I am to you a trustworthy messenger.' },
  { surahId: 26, ayahNumber: 144, text: 'So fear Allah and obey me.' },
  { surahId: 26, ayahNumber: 145, text: 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.' },
  { surahId: 26, ayahNumber: 146, text: 'Will you be left in what is here, secure [from death],' },
  { surahId: 26, ayahNumber: 147, text: 'Within gardens and springs' },
  { surahId: 26, ayahNumber: 148, text: 'And fields of crops and palm trees with softened fruit?' },
  { surahId: 26, ayahNumber: 149, text: 'And you carve out of the mountains, homes, with skill.' },
  { surahId: 26, ayahNumber: 150, text: 'So fear Allah and obey me.' },
  { surahId: 26, ayahNumber: 151, text: 'And do not obey the order of the transgressors,' },
  { surahId: 26, ayahNumber: 152, text: 'Who cause corruption in the land and do not amend."' },
  { surahId: 26, ayahNumber: 153, text: 'They said, "You are only of those affected by magic.' },
  { surahId: 26, ayahNumber: 154, text: 'You are but a man like ourselves, so bring a sign, if you should be of the truthful."' },
  { surahId: 26, ayahNumber: 155, text: 'He said, "This is a she-camel. For her is a [time of] drink, and for you is a [time of] drink, [each] on a known day.' },
  { surahId: 26, ayahNumber: 156, text: 'And do not touch her with harm, lest you be seized by the punishment of a terrible day."' },
  { surahId: 26, ayahNumber: 157, text: 'But they hamstrung her and so became regretful.' },
  { surahId: 26, ayahNumber: 158, text: 'And the punishment seized them. Indeed in that is a sign, but most of them were not to be believers.' },
  { surahId: 26, ayahNumber: 159, text: 'And indeed, your Lord - He is the Exalted in Might, the Merciful.' },
  { surahId: 26, ayahNumber: 160, text: 'The people of Lot denied the messengers' },
  { surahId: 26, ayahNumber: 161, text: 'When their brother Lot said to them, "Will you not fear Allah?' },
  { surahId: 26, ayahNumber: 162, text: 'Indeed, I am to you a trustworthy messenger.' },
  { surahId: 26, ayahNumber: 163, text: 'So fear Allah and obey me.' },
  { surahId: 26, ayahNumber: 164, text: 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.' },
  { surahId: 26, ayahNumber: 165, text: 'Do you approach males among the worlds' },
  { surahId: 26, ayahNumber: 166, text: 'And leave what your Lord has created for you as mates? But you are a people transgressing."' },
  { surahId: 26, ayahNumber: 167, text: 'They said, "If you do not desist, O Lot, you will surely be of those evicted."' },
  { surahId: 26, ayahNumber: 168, text: 'He said, "Indeed, I am, toward your deed, of those who detest [it].' },
  { surahId: 26, ayahNumber: 169, text: 'My Lord, save me and my family from [the consequence of] what they do."' },
  { surahId: 26, ayahNumber: 170, text: 'So We saved him and his family, all,' },
  { surahId: 26, ayahNumber: 171, text: 'Except an old woman among those who remained behind.' },
  { surahId: 26, ayahNumber: 172, text: 'Then We destroyed the others.' },
  { surahId: 26, ayahNumber: 173, text: 'And We rained upon them a rain [of stones], and evil was the rain of those who were warned.' },
  { surahId: 26, ayahNumber: 174, text: 'Indeed in that is a sign, but most of them were not to be believers.' },
  { surahId: 26, ayahNumber: 175, text: 'And indeed, your Lord - He is the Exalted in Might, the Merciful.' },
  { surahId: 26, ayahNumber: 176, text: 'The companions of the thicket denied the messengers' },
  { surahId: 26, ayahNumber: 177, text: 'When Shu\'ayb said to them, "Will you not fear Allah?' },
  { surahId: 26, ayahNumber: 178, text: 'Indeed, I am to you a trustworthy messenger.' },
  { surahId: 26, ayahNumber: 179, text: 'So fear Allah and obey me.' },
  { surahId: 26, ayahNumber: 180, text: 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.' },
  { surahId: 26, ayahNumber: 181, text: 'Give full measure and do not be of those who cause loss.' },
  { surahId: 26, ayahNumber: 182, text: 'And weigh with an even balance.' },
  { surahId: 26, ayahNumber: 183, text: 'And do not deprive people of their due and do not commit abuse on earth, spreading corruption.' },
  { surahId: 26, ayahNumber: 184, text: 'And fear He who created you and the former creation."' },
  { surahId: 26, ayahNumber: 185, text: 'They said, "You are only of those affected by magic.' },
  { surahId: 26, ayahNumber: 186, text: 'You are but a man like ourselves, and indeed, we think you are among the liars.' },
  { surahId: 26, ayahNumber: 187, text: 'So cause to fall upon us fragments of the sky, if you should be of the truthful."' },
  { surahId: 26, ayahNumber: 188, text: 'He said, "My Lord is most knowing of what you do."' },
  { surahId: 26, ayahNumber: 189, text: 'And they denied him, so the punishment of the day of the black cloud seized them. Indeed, it was the punishment of a terrible day.' },
  { surahId: 26, ayahNumber: 190, text: 'Indeed in that is a sign, but most of them were not to be believers.' },
  { surahId: 26, ayahNumber: 191, text: 'And indeed, your Lord - He is the Exalted in Might, the Merciful.' },
  { surahId: 26, ayahNumber: 192, text: 'And indeed, the Qur\'an is the revelation of the Lord of the worlds.' },
  { surahId: 26, ayahNumber: 193, text: 'The Trustworthy Spirit has brought it down' },
  { surahId: 26, ayahNumber: 194, text: 'Upon your heart, [O Muhammad] - that you may be of the warners -' },
  { surahId: 26, ayahNumber: 195, text: 'In a clear Arabic language.' },
  { surahId: 26, ayahNumber: 196, text: 'And indeed, it is [mentioned] in the scriptures of former peoples.' },
  { surahId: 26, ayahNumber: 197, text: 'And has it not been a sign to them that it is recognized by the scholars of the Children of Israel?' },
  { surahId: 26, ayahNumber: 198, text: 'And even if We had revealed it to one among the foreigners' },
  { surahId: 26, ayahNumber: 199, text: 'And he had recited it to them [perfectly], they would [still] not have been believers in it.' },
  { surahId: 26, ayahNumber: 200, text: 'Thus have We inserted disbelief into the hearts of the criminals.' },
  { surahId: 26, ayahNumber: 201, text: 'They will not believe in it until they see the painful punishment.' },
  { surahId: 26, ayahNumber: 202, text: 'And it will come to them suddenly while they perceive [it] not.' },
  { surahId: 26, ayahNumber: 203, text: 'And they will say, "May we be reprieved?"' },
  { surahId: 26, ayahNumber: 204, text: 'So for Our punishment are they impatient?' },
  { surahId: 26, ayahNumber: 205, text: 'Then have you considered if We gave them enjoyment for years' },
  { surahId: 26, ayahNumber: 206, text: 'And then there came to them that which they were promised?' },
  { surahId: 26, ayahNumber: 207, text: 'They would not be availed by the enjoyment with which they were provided.' },
  { surahId: 26, ayahNumber: 208, text: 'And We did not destroy any city except that it had warners' },
  { surahId: 26, ayahNumber: 209, text: 'As a reminder; and never have We been unjust.' },
  { surahId: 26, ayahNumber: 210, text: 'And the devils have not brought the revelation down.' },
  { surahId: 26, ayahNumber: 211, text: 'It is not allowable for them, nor would they be able.' },
  { surahId: 26, ayahNumber: 212, text: 'Indeed they, from [its] hearing, are removed.' },
  { surahId: 26, ayahNumber: 213, text: 'So do not invoke with Allah another deity and [thus] be among the punished.' },
  { surahId: 26, ayahNumber: 214, text: 'And warn, [O Muhammad], your closest kindred.' },
  { surahId: 26, ayahNumber: 215, text: 'And lower your wing to those who follow you of the believers.' },
  { surahId: 26, ayahNumber: 216, text: 'And if they disobey you, then say, "Indeed, I am disassociated from what you are doing."' },
  { surahId: 26, ayahNumber: 217, text: 'And rely upon the Exalted in Might, the Merciful,' },
  { surahId: 26, ayahNumber: 218, text: 'Who sees you when you arise' },
  { surahId: 26, ayahNumber: 219, text: 'And your movement among those who prostrate.' },
  { surahId: 26, ayahNumber: 220, text: 'Indeed, He is the Hearing, the Knowing.' },
  { surahId: 26, ayahNumber: 221, text: 'Shall I inform you upon whom the devils descend?' },
  { surahId: 26, ayahNumber: 222, text: 'They descend upon every sinful liar.' },
  { surahId: 26, ayahNumber: 223, text: 'They pass on what is heard, and most of them are liars.' },
  { surahId: 26, ayahNumber: 224, text: 'And the poets - [only] the deviators follow them;' },
  { surahId: 26, ayahNumber: 225, text: 'Do you not see that in every valley they roam' },
  { surahId: 26, ayahNumber: 226, text: 'And that they say what they do not do? -' },
  { surahId: 26, ayahNumber: 227, text: 'Except those [poets] who believe and do righteous deeds and remember Allah often and defend [the Muslims] after they were wronged. And those who have wronged are going to know to what [kind of] return they will be returned.' },
  { surahId: 27, ayahNumber: 1, text: 'Ta, Seen. These are the verses of the Qur\'an and a clear Book' },
  { surahId: 27, ayahNumber: 2, text: 'As guidance and good tidings for the believers' },
  { surahId: 27, ayahNumber: 3, text: 'Who establish prayer and give zakah, and of the Hereafter they are certain [in faith].' },
  { surahId: 27, ayahNumber: 4, text: 'Indeed, for those who do not believe in the Hereafter, We have made pleasing to them their deeds, so they wander blindly.' },
  { surahId: 27, ayahNumber: 5, text: 'Those are the ones for whom there will be the worst of punishment, and in the Hereafter they are the greatest losers.' },
  { surahId: 27, ayahNumber: 6, text: 'And indeed, [O Muhammad], you receive the Qur\'an from one Wise and Knowing.' },
  { surahId: 27, ayahNumber: 7, text: '[Mention] when Moses said to his family, "Indeed, I have perceived a fire. I will bring you from there information or will bring you a burning torch that you may warm yourselves."' },
  { surahId: 27, ayahNumber: 8, text: 'But when he came to it, he was called, "Blessed is whoever is at the fire and whoever is around it. And exalted is Allah, Lord of the worlds.' },
  { surahId: 27, ayahNumber: 9, text: 'O Moses, indeed it is I - Allah, the Exalted in Might, the Wise."' },
  { surahId: 27, ayahNumber: 10, text: 'And [he was told], "Throw down your staff." But when he saw it writhing as if it were a snake, he turned in flight and did not return. [Allah said], "O Moses, fear not. Indeed, in My presence the messengers do not fear.' },
  { surahId: 27, ayahNumber: 11, text: 'Otherwise, he who wrongs, then substitutes good after evil - indeed, I am Forgiving and Merciful.' },
  { surahId: 27, ayahNumber: 12, text: 'And put your hand into the opening of your garment [at the breast]; it will come out white without disease. [These are] among the nine signs [you will take] to Pharaoh and his people. Indeed, they have been a people defiantly disobedient."' },
  { surahId: 27, ayahNumber: 13, text: 'But when there came to them Our visible signs, they said, "This is obvious magic."' },
  { surahId: 27, ayahNumber: 14, text: 'And they rejected them, while their [inner] selves were convinced thereof, out of injustice and haughtiness. So see how was the end of the corrupters.' },
  { surahId: 27, ayahNumber: 15, text: 'And We had certainly given to David and Solomon knowledge, and they said, "Praise [is due] to Allah, who has favored us over many of His believing servants."' },
  { surahId: 27, ayahNumber: 16, text: 'And Solomon inherited David. He said, "O people, we have been taught the language of birds, and we have been given from all things. Indeed, this is evident bounty."' },
  { surahId: 27, ayahNumber: 17, text: 'And gathered for Solomon were his soldiers of the jinn and men and birds, and they were [marching] in rows.' },
  { surahId: 27, ayahNumber: 18, text: 'Until, when they came upon the valley of the ants, an ant said, "O ants, enter your dwellings that you not be crushed by Solomon and his soldiers while they perceive not."' },
  { surahId: 27, ayahNumber: 19, text: 'So [Solomon] smiled, amused at her speech, and said, "My Lord, enable me to be grateful for Your favor which You have bestowed upon me and upon my parents and to do righteousness of which You approve. And admit me by Your mercy into [the ranks of] Your righteous servants."' },
  { surahId: 27, ayahNumber: 20, text: 'And he took attendance of the birds and said, "Why do I not see the hoopoe - or is he among the absent?' },
  { surahId: 27, ayahNumber: 21, text: 'I will surely punish him with a severe punishment or slaughter him unless he brings me clear authorization."' },
  { surahId: 27, ayahNumber: 22, text: 'But the hoopoe stayed not long and said, "I have encompassed [in knowledge] that which you have not encompassed, and I have come to you from Sheba with certain news.' },
  { surahId: 27, ayahNumber: 23, text: 'Indeed, I found [there] a woman ruling them, and she has been given of all things, and she has a great throne.' },
  { surahId: 27, ayahNumber: 24, text: 'I found her and her people prostrating to the sun instead of Allah, and Satan has made their deeds pleasing to them and averted them from [His] way, so they are not guided,' },
  { surahId: 27, ayahNumber: 25, text: '[And] so they do not prostrate to Allah, who brings forth what is hidden within the heavens and the earth and knows what you conceal and what you declare -' },
  { surahId: 27, ayahNumber: 26, text: 'Allah - there is no deity except Him, Lord of the Great Throne."' },
  { surahId: 27, ayahNumber: 27, text: '[Solomon] said, "We will see whether you were truthful or were of the liars.' },
  { surahId: 27, ayahNumber: 28, text: 'Take this letter of mine and deliver it to them. Then leave them and see what [answer] they will return."' },
  { surahId: 27, ayahNumber: 29, text: 'She said, "O eminent ones, indeed, to me has been delivered a noble letter.' },
  { surahId: 27, ayahNumber: 30, text: 'Indeed, it is from Solomon, and indeed, it reads: \'In the name of Allah, the Entirely Merciful, the Especially Merciful,' },
  { surahId: 27, ayahNumber: 31, text: 'Be not haughty with me but come to me in submission [as Muslims].\' "' },
  { surahId: 27, ayahNumber: 32, text: 'She said, "O eminent ones, advise me in my affair. I would not decide a matter until you witness [for] me."' },
  { surahId: 27, ayahNumber: 33, text: 'They said, "We are men of strength and of great military might, but the command is yours, so see what you will command."' },
  { surahId: 27, ayahNumber: 34, text: 'She said, "Indeed kings - when they enter a city, they ruin it and render the honored of its people humbled. And thus do they do.' },
  { surahId: 27, ayahNumber: 35, text: 'But indeed, I will send to them a gift and see with what [reply] the messengers will return."' },
  { surahId: 27, ayahNumber: 36, text: 'So when they came to Solomon, he said, "Do you provide me with wealth? But what Allah has given me is better than what He has given you. Rather, it is you who rejoice in your gift.' },
  { surahId: 27, ayahNumber: 37, text: 'Return to them, for we will surely come to them with soldiers that they will be powerless to encounter, and we will surely expel them therefrom in humiliation, and they will be debased."' },
  { surahId: 27, ayahNumber: 38, text: '[Solomon] said, "O assembly [of jinn], which of you will bring me her throne before they come to me in submission?"' },
  { surahId: 27, ayahNumber: 39, text: 'A powerful one from among the jinn said, "I will bring it to you before you rise from your place, and indeed, I am for this [task] strong and trustworthy."' },
  { surahId: 27, ayahNumber: 40, text: 'Said one who had knowledge from the Scripture, "I will bring it to you before your glance returns to you." And when [Solomon] saw it placed before him, he said, "This is from the favor of my Lord to test me whether I will be grateful or ungrateful. And whoever is grateful - his gratitude is only for [the benefit of] himself. And whoever is ungrateful - then indeed, my Lord is Free of need and Generous."' },
  { surahId: 27, ayahNumber: 41, text: 'He said, "Disguise for her her throne; we will see whether she will be guided [to truth] or will be of those who is not guided."' },
  { surahId: 27, ayahNumber: 42, text: 'So when she arrived, it was said [to her], "Is your throne like this?" She said, "[It is] as though it was it." [Solomon said], "And we were given knowledge before her, and we have been Muslims [in submission to Allah].' },
  { surahId: 27, ayahNumber: 43, text: 'And that which she was worshipping other than Allah had averted her [from submission to Him]. Indeed, she was from a disbelieving people."' },
  { surahId: 27, ayahNumber: 44, text: 'She was told, "Enter the palace." But when she saw it, she thought it was a body of water and uncovered her shins [to wade through]. He said, "Indeed, it is a palace [whose floor is] made smooth with glass." She said, "My Lord, indeed I have wronged myself, and I submit with Solomon to Allah, Lord of the worlds."' },
  { surahId: 27, ayahNumber: 45, text: 'And We had certainly sent to Thamud their brother Salih, [saying], "Worship Allah," and at once they were two parties conflicting.' },
  { surahId: 27, ayahNumber: 46, text: 'He said, "O my people, why are you impatient for evil instead of good? Why do you not seek forgiveness of Allah that you may receive mercy?"' },
  { surahId: 27, ayahNumber: 47, text: 'They said, "We consider you a bad omen, you and those with you." He said, "Your omen is with Allah. Rather, you are a people being tested."' },
  { surahId: 27, ayahNumber: 48, text: 'And there were in the city nine family heads causing corruption in the land and not amending [its affairs].' },
  { surahId: 27, ayahNumber: 49, text: 'They said, "Take a mutual oath by Allah that we will kill him by night, he and his family. Then we will say to his executor, \'We did not witness the destruction of his family, and indeed, we are truthful.\' "' },
  { surahId: 27, ayahNumber: 50, text: 'And they planned a plan, and We planned a plan, while they perceived not.' },
  { surahId: 27, ayahNumber: 51, text: 'Then look how was the outcome of their plan - that We destroyed them and their people, all.' },
  { surahId: 27, ayahNumber: 52, text: 'So those are their houses, desolate because of the wrong they had done. Indeed in that is a sign for people who know.' },
  { surahId: 27, ayahNumber: 53, text: 'And We saved those who believed and used to fear Allah.' },
  { surahId: 27, ayahNumber: 54, text: 'And [mention] Lot, when he said to his people, "Do you commit immorality while you are seeing?' },
  { surahId: 27, ayahNumber: 55, text: 'Do you indeed approach men with desire instead of women? Rather, you are a people behaving ignorantly."' },
  { surahId: 27, ayahNumber: 56, text: 'But the answer of his people was not except that they said, "Expel the family of Lot from your city. Indeed, they are people who keep themselves pure."' },
  { surahId: 27, ayahNumber: 57, text: 'So We saved him and his family, except for his wife; We destined her to be of those who remained behind.' },
  { surahId: 27, ayahNumber: 58, text: 'And We rained upon them a rain [of stones], and evil was the rain of those who were warned.' },
  { surahId: 27, ayahNumber: 59, text: 'Say, [O Muhammad], "Praise be to Allah, and peace upon His servants whom He has chosen. Is Allah better or what they associate with Him?"' },
  { surahId: 27, ayahNumber: 60, text: '[More precisely], is He [not best] who created the heavens and the earth and sent down for you rain from the sky, causing to grow thereby gardens of joyful beauty which you could not [otherwise] have grown the trees thereof? Is there a deity with Allah? [No], but they are a people who ascribe equals [to Him].' },
  { surahId: 27, ayahNumber: 61, text: 'Is He [not best] who made the earth a stable ground and placed within it rivers and made for it firmly set mountains and placed between the two seas a barrier? Is there a deity with Allah? [No], but most of them do not know.' },
  { surahId: 27, ayahNumber: 62, text: 'Is He [not best] who responds to the desperate one when he calls upon Him and removes evil and makes you inheritors of the earth? Is there a deity with Allah? Little do you remember.' },
  { surahId: 27, ayahNumber: 63, text: 'Is He [not best] who guides you through the darknesses of the land and sea and who sends the winds as good tidings before His mercy? Is there a deity with Allah? High is Allah above whatever they associate with Him.' },
  { surahId: 27, ayahNumber: 64, text: 'Is He [not best] who begins creation and then repeats it and who provides for you from the heaven and earth? Is there a deity with Allah? Say, "Produce your proof, if you should be truthful."' },
  { surahId: 27, ayahNumber: 65, text: 'Say, "None in the heavens and earth knows the unseen except Allah, and they do not perceive when they will be resurrected."' },
  { surahId: 27, ayahNumber: 66, text: 'Rather, their knowledge is arrested concerning the Hereafter. Rather, they are in doubt about it. Rather, they are, concerning it, blind.' },
  { surahId: 27, ayahNumber: 67, text: 'And those who disbelieve say, "When we have become dust as well as our forefathers, will we indeed be brought out [of the graves]?' },
  { surahId: 27, ayahNumber: 68, text: 'We have been promised this, we and our forefathers, before. This is not but legends of the former peoples."' },
  { surahId: 27, ayahNumber: 69, text: 'Say, [O Muhammad], "Travel through the land and observe how was the end of the criminals."' },
  { surahId: 27, ayahNumber: 70, text: 'And grieve not over them or be in distress from what they conspire.' },
  { surahId: 27, ayahNumber: 71, text: 'And they say, "When is [the fulfillment of] this promise, if you should be truthful?"' },
  { surahId: 27, ayahNumber: 72, text: 'Say, "Perhaps it is close behind you - some of that for which you are impatient.' },
  { surahId: 27, ayahNumber: 73, text: 'And indeed, your Lord is full of bounty for the people, but most of them do not show gratitude."' },
  { surahId: 27, ayahNumber: 74, text: 'And indeed, your Lord knows what their breasts conceal and what they declare.' },
  { surahId: 27, ayahNumber: 75, text: 'And there is nothing concealed within the heaven and the earth except that it is in a clear Register.' },
  { surahId: 27, ayahNumber: 76, text: 'Indeed, this Qur\'an relates to the Children of Israel most of that over which they disagree.' },
  { surahId: 27, ayahNumber: 77, text: 'And indeed, it is guidance and mercy for the believers.' },
  { surahId: 27, ayahNumber: 78, text: 'Indeed, your Lord will judge between them by His [wise] judgement. And He is the Exalted in Might, the Knowing.' },
  { surahId: 27, ayahNumber: 79, text: 'So rely upon Allah; indeed, you are upon the clear truth.' },
  { surahId: 27, ayahNumber: 80, text: 'Indeed, you will not make the dead hear, nor will you make the deaf hear the call when they have turned their backs retreating.' },
  { surahId: 27, ayahNumber: 81, text: 'And you cannot guide the blind away from their error. You will only make hear those who believe in Our verses so they are Muslims [submitting to Allah].' },
  { surahId: 27, ayahNumber: 82, text: 'And when the word befalls them, We will bring forth for them a creature from the earth speaking to them, [saying] that the people were, of Our verses, not certain [in faith].' },
  { surahId: 27, ayahNumber: 83, text: 'And [warn of] the Day when We will gather from every nation a company of those who deny Our signs, and they will be [driven] in rows' },
  { surahId: 27, ayahNumber: 84, text: 'Until, when they arrive [at the place of Judgement], He will say, "Did you deny My signs while you encompassed them not in knowledge, or what [was it that] you were doing?"' },
  { surahId: 27, ayahNumber: 85, text: 'And the decree will befall them for the wrong they did, and they will not [be able to] speak.' },
  { surahId: 27, ayahNumber: 86, text: 'Do they not see that We made the night that they may rest therein and the day giving sight? Indeed in that are signs for a people who believe.' },
  { surahId: 27, ayahNumber: 87, text: 'And [warn of] the Day the Horn will be blown, and whoever is in the heavens and whoever is on the earth will be terrified except whom Allah wills. And all will come to Him humbled.' },
  { surahId: 27, ayahNumber: 88, text: 'And you see the mountains, thinking them rigid, while they will pass as the passing of clouds. [It is] the work of Allah, who perfected all things. Indeed, He is Acquainted with that which you do.' },
  { surahId: 27, ayahNumber: 89, text: 'Whoever comes [at Judgement] with a good deed will have better than it, and they, from the terror of that Day, will be safe.' },
  { surahId: 27, ayahNumber: 90, text: 'And whoever comes with an evil deed - their faces will be overturned into the Fire, [and it will be said], "Are you recompensed except for what you used to do?"' },
  { surahId: 27, ayahNumber: 91, text: '[Say, O Muhammad], "I have only been commanded to worship the Lord of this city, who made it sacred and to whom [belongs] all things. And I am commanded to be of the Muslims [those who submit to Allah]' },
  { surahId: 27, ayahNumber: 92, text: 'And to recite the Qur\'an." And whoever is guided is only guided for [the benefit of] himself; and whoever strays - say, "I am only [one] of the warners."' },
  { surahId: 27, ayahNumber: 93, text: 'And say, "[All] praise is [due] to Allah. He will show you His signs, and you will recognize them. And your Lord is not unaware of what you do."' },
  { surahId: 28, ayahNumber: 1, text: 'Ta, Seen, Meem.' },
  { surahId: 28, ayahNumber: 2, text: 'These are the verses of the clear Book.' },
  { surahId: 28, ayahNumber: 3, text: 'We recite to you from the news of Moses and Pharaoh in truth for a people who believe.' },
  { surahId: 28, ayahNumber: 4, text: 'Indeed, Pharaoh exalted himself in the land and made its people into factions, oppressing a sector among them, slaughtering their [newborn] sons and keeping their females alive. Indeed, he was of the corrupters.' },
  { surahId: 28, ayahNumber: 5, text: 'And We wanted to confer favor upon those who were oppressed in the land and make them leaders and make them inheritors' },
  { surahId: 28, ayahNumber: 6, text: 'And establish them in the land and show Pharaoh and [his minister] Haman and their soldiers through them that which they had feared.' },
  { surahId: 28, ayahNumber: 7, text: 'And We inspired to the mother of Moses, "Suckle him; but when you fear for him, cast him into the river and do not fear and do not grieve. Indeed, We will return him to you and will make him [one] of the messengers."' },
  { surahId: 28, ayahNumber: 8, text: 'And the family of Pharaoh picked him up [out of the river] so that he would become to them an enemy and a [cause of] grief. Indeed, Pharaoh and Haman and their soldiers were deliberate sinners.' },
  { surahId: 28, ayahNumber: 9, text: 'And the wife of Pharaoh said, "[He will be] a comfort of the eye for me and for you. Do not kill him; perhaps he may benefit us, or we may adopt him as a son." And they perceived not.' },
  { surahId: 28, ayahNumber: 10, text: 'And the heart of Moses\' mother became empty [of all else]. She was about to disclose [the matter concerning] him had We not bound fast her heart that she would be of the believers.' },
  { surahId: 28, ayahNumber: 11, text: 'And she said to his sister, "Follow him"; so she watched him from a distance while they perceived not.' },
  { surahId: 28, ayahNumber: 12, text: 'And We had prevented from him [all] wet nurses before, so she said, "Shall I direct you to a household that will be responsible for him for you while they are to him [for his upbringing] sincere?"' },
  { surahId: 28, ayahNumber: 13, text: 'So We restored him to his mother that she might be content and not grieve and that she would know that the promise of Allah is true. But most of the people do not know.' },
  { surahId: 28, ayahNumber: 14, text: 'And when he attained his full strength and was [mentally] mature, We bestowed upon him judgement and knowledge. And thus do We reward the doers of good.' },
  { surahId: 28, ayahNumber: 15, text: 'And he entered the city at a time of inattention by its people and found therein two men fighting: one from his faction and one from among his enemy. And the one from his faction called for help to him against the one from his enemy, so Moses struck him and [unintentionally] killed him. [Moses] said, "This is from the work of Satan. Indeed, he is a manifest, misleading enemy."' },
  { surahId: 28, ayahNumber: 16, text: 'He said, "My Lord, indeed I have wronged myself, so forgive me," and He forgave him. Indeed, He is the Forgiving, the Merciful.' },
  { surahId: 28, ayahNumber: 17, text: 'He said, "My Lord, for the favor You bestowed upon me, I will never be an assistant to the criminals."' },
  { surahId: 28, ayahNumber: 18, text: 'And he became inside the city fearful and anticipating [exposure], when suddenly the one who sought his help the previous day cried out to him [once again]. Moses said to him, "Indeed, you are an evident, [persistent] deviator."' },
  { surahId: 28, ayahNumber: 19, text: 'And when he wanted to strike the one who was an enemy to both of them, he said, "O Moses, do you intend to kill me as you killed someone yesterday? You only want to be a tyrant in the land and do not want to be of the amenders."' },
  { surahId: 28, ayahNumber: 20, text: 'And a man came from the farthest end of the city, running. He said, "O Moses, indeed the eminent ones are conferring over you [intending] to kill you, so leave [the city]; indeed, I am to you of the sincere advisors."' },
  { surahId: 28, ayahNumber: 21, text: 'So he left it, fearful and anticipating [apprehension]. He said, "My Lord, save me from the wrongdoing people."' },
  { surahId: 28, ayahNumber: 22, text: 'And when he directed himself toward Madyan, he said, "Perhaps my Lord will guide me to the sound way."' },
  { surahId: 28, ayahNumber: 23, text: 'And when he came to the well of Madyan, he found there a crowd of people watering [their flocks], and he found aside from them two women driving back [their flocks]. He said, "What is your circumstance?" They said, "We do not water until the shepherds dispatch [their flocks]; and our father is an old man."' },
  { surahId: 28, ayahNumber: 24, text: 'So he watered [their flocks] for them; then he went back to the shade and said, "My Lord, indeed I am, for whatever good You would send down to me, in need."' },
  { surahId: 28, ayahNumber: 25, text: 'Then one of the two women came to him walking with shyness. She said, "Indeed, my father invites you that he may reward you for having watered for us." So when he came to him and related to him the story, he said, "Fear not. You have escaped from the wrongdoing people."' },
  { surahId: 28, ayahNumber: 26, text: 'One of the women said, "O my father, hire him. Indeed, the best one you can hire is the strong and the trustworthy."' },
  { surahId: 28, ayahNumber: 27, text: 'He said, "Indeed, I wish to wed you one of these, my two daughters, on [the condition] that you serve me for eight years; but if you complete ten, it will be [as a favor] from you. And I do not wish to put you in difficulty. You will find me, if Allah wills, from among the righteous."' },
  { surahId: 28, ayahNumber: 28, text: '[Moses] said, "That is [established] between me and you. Whichever of the two terms I complete - there is no injustice to me, and Allah, over what we say, is Witness."' },
  { surahId: 28, ayahNumber: 29, text: 'And when Moses had completed the term and was traveling with his family, he perceived from the direction of the mount a fire. He said to his family, "Stay here; indeed, I have perceived a fire. Perhaps I will bring you from there [some] information or burning wood from the fire that you may warm yourselves."' },
  { surahId: 28, ayahNumber: 30, text: 'But when he came to it, he was called from the right side of the valley in a blessed spot - from the tree, "O Moses, indeed I am Allah, Lord of the worlds."' },
  { surahId: 28, ayahNumber: 31, text: 'And [he was told], "Throw down your staff." But when he saw it writhing as if it was a snake, he turned in flight and did not return. [Allah said], "O Moses, approach and fear not. Indeed, you are of the secure.' },
  { surahId: 28, ayahNumber: 32, text: 'Insert your hand into the opening of your garment; it will come out white, without disease. And draw in your arm close to you [as prevention] from fear, for those are two proofs from your Lord to Pharaoh and his establishment. Indeed, they have been a people defiantly disobedient."' },
  { surahId: 28, ayahNumber: 33, text: 'He said, "My Lord, indeed, I killed from among them someone, and I fear they will kill me.' },
  { surahId: 28, ayahNumber: 34, text: 'And my brother Aaron is more fluent than me in tongue, so send him with me as support, verifying me. Indeed, I fear that they will deny me."' },
  { surahId: 28, ayahNumber: 35, text: '[Allah] said, "We will strengthen your arm through your brother and grant you both supremacy so they will not reach you. [It will be] through Our signs; you and those who follow you will be the predominant."' },
  { surahId: 28, ayahNumber: 36, text: 'But when Moses came to them with Our signs as clear evidences, they said, "This is not except invented magic, and we have not heard of this [religion] among our forefathers."' },
  { surahId: 28, ayahNumber: 37, text: 'And Moses said, "My Lord is more knowing [than we or you] of who has come with guidance from Him and to whom will be succession in the home. Indeed, wrongdoers do not succeed."' },
  { surahId: 28, ayahNumber: 38, text: 'And Pharaoh said, "O eminent ones, I have not known you to have a god other than me. Then ignite for me, O Haman, [a fire] upon the clay and make for me a tower that I may look at the God of Moses. And indeed, I do think he is among the liars."' },
  { surahId: 28, ayahNumber: 39, text: 'And he was arrogant, he and his soldiers, in the land, without right, and they thought that they would not be returned to Us.' },
  { surahId: 28, ayahNumber: 40, text: 'So We took him and his soldiers and threw them into the sea. So see how was the end of the wrongdoers.' },
  { surahId: 28, ayahNumber: 41, text: 'And We made them leaders inviting to the Fire, and on the Day of Resurrection they will not be helped.' },
  { surahId: 28, ayahNumber: 42, text: 'And We caused to overtake them in this world a curse, and on the Day of Resurrection they will be of the despised.' },
  { surahId: 28, ayahNumber: 43, text: 'And We gave Moses the Scripture, after We had destroyed the former generations, as enlightenment for the people and guidance and mercy that they might be reminded.' },
  { surahId: 28, ayahNumber: 44, text: 'And you, [O Muhammad], were not on the western side [of the mount] when We revealed to Moses the command, and you were not among the witnesses [to that].' },
  { surahId: 28, ayahNumber: 45, text: 'But We produced [many] generations [after Moses], and prolonged was their duration. And you were not a resident among the people of Madyan, reciting to them Our verses, but We were senders [of this message].' },
  { surahId: 28, ayahNumber: 46, text: 'And you were not at the side of the mount when We called [Moses] but [were sent] as a mercy from your Lord to warn a people to whom no warner had come before you that they might be reminded.' },
  { surahId: 28, ayahNumber: 47, text: 'And if not that a disaster should strike them for what their hands put forth [of sins] and they would say, "Our Lord, why did You not send us a messenger so we could have followed Your verses and been among the believers?"...' },
  { surahId: 28, ayahNumber: 48, text: 'But when the truth came to them from Us, they said, "Why was he not given like that which was given to Moses?" Did they not disbelieve in that which was given to Moses before? They said, "[They are but] two works of magic supporting each other, and indeed we are, in both, disbelievers."' },
  { surahId: 28, ayahNumber: 49, text: 'Say, "Then bring a scripture from Allah which is more guiding than either of them that I may follow it, if you should be truthful."' },
  { surahId: 28, ayahNumber: 50, text: 'But if they do not respond to you - then know that they only follow their [own] desires. And who is more astray than one who follows his desire without guidance from Allah? Indeed, Allah does not guide the wrongdoing people.' },
  { surahId: 28, ayahNumber: 51, text: 'And We have [repeatedly] conveyed to them the Qur\'an that they might be reminded.' },
  { surahId: 28, ayahNumber: 52, text: 'Those to whom We gave the Scripture before it - they are believers in it.' },
  { surahId: 28, ayahNumber: 53, text: 'And when it is recited to them, they say, "We have believed in it; indeed, it is the truth from our Lord. Indeed we were, [even] before it, Muslims [submitting to Allah]."' },
  { surahId: 28, ayahNumber: 54, text: 'Those will be given their reward twice for what they patiently endured and [because] they avert evil through good, and from what We have provided them they spend.' },
  { surahId: 28, ayahNumber: 55, text: 'And when they hear ill speech, they turn away from it and say, "For us are our deeds, and for you are your deeds. Peace will be upon you; we seek not the ignorant."' },
  { surahId: 28, ayahNumber: 56, text: 'Indeed, [O Muhammad], you do not guide whom you like, but Allah guides whom He wills. And He is most knowing of the [rightly] guided.' },
  { surahId: 28, ayahNumber: 57, text: 'And they say, "If we were to follow the guidance with you, we would be swept from our land." Have we not established for them a safe sanctuary to which are brought the fruits of all things as provision from Us? But most of them do not know.' },
  { surahId: 28, ayahNumber: 58, text: 'And how many a city have We destroyed that was insolent in its [way of] living, and those are their dwellings which have not been inhabited after them except briefly. And it is We who were the inheritors.' },
  { surahId: 28, ayahNumber: 59, text: 'And never would your Lord have destroyed the cities until He had sent to their mother a messenger reciting to them Our verses. And We would not destroy the cities except while their people were wrongdoers.' },
  { surahId: 28, ayahNumber: 60, text: 'And whatever thing you [people] have been given - it is [only for] the enjoyment of worldly life and its adornment. And what is with Allah is better and more lasting; so will you not use reason?' },
  { surahId: 28, ayahNumber: 61, text: 'Then is he whom We have promised a good promise which he will obtain like he for whom We provided enjoyment of worldly life [but] then he is, on the Day of Resurrection, among those presented [for punishment in Hell]?' },
  { surahId: 28, ayahNumber: 62, text: 'And [warn of] the Day He will call them and say, "Where are My \'partners\' which you used to claim?"' },
  { surahId: 28, ayahNumber: 63, text: 'Those upon whom the word will have come into effect will say, "Our Lord, these are the ones we led to error. We led them to error just as we were in error. We declare our disassociation [from them] to You. They did not used to worship us."' },
  { surahId: 28, ayahNumber: 64, text: 'And it will be said, "Invoke your \'partners\' " and they will invoke them; but they will not respond to them, and they will see the punishment. If only they had followed guidance!' },
  { surahId: 28, ayahNumber: 65, text: 'And [mention] the Day He will call them and say, "What did you answer the messengers?"' },
  { surahId: 28, ayahNumber: 66, text: 'But the information will be unapparent to them that Day, so they will not [be able to] ask one another.' },
  { surahId: 28, ayahNumber: 67, text: 'But as for one who had repented, believed, and done righteousness, it is promised by Allah that he will be among the successful.' },
  { surahId: 28, ayahNumber: 68, text: 'And your Lord creates what He wills and chooses; not for them was the choice. Exalted is Allah and high above what they associate with Him.' },
  { surahId: 28, ayahNumber: 69, text: 'And your Lord knows what their breasts conceal and what they declare.' },
  { surahId: 28, ayahNumber: 70, text: 'And He is Allah; there is no deity except Him. To Him is [due all] praise in the first [life] and the Hereafter. And His is the [final] decision, and to Him you will be returned.' },
  { surahId: 28, ayahNumber: 71, text: 'Say, "Have you considered: if Allah should make for you the night continuous until the Day of Resurrection, what deity other than Allah could bring you light? Then will you not hear?"' },
  { surahId: 28, ayahNumber: 72, text: 'Say, "Have you considered: if Allah should make for you the day continuous until the Day of Resurrection, what deity other than Allah could bring you a night in which you may rest? Then will you not see?"' },
  { surahId: 28, ayahNumber: 73, text: 'And out of His mercy He made for you the night and the day that you may rest therein and [by day] seek from His bounty and [that] perhaps you will be grateful.' },
  { surahId: 28, ayahNumber: 74, text: 'And [warn of] the Day He will call them and say, "Where are my \'partners\' which you used to claim?"' },
  { surahId: 28, ayahNumber: 75, text: 'And We will extract from every nation a witness and say, "Produce your proof," and they will know that the truth belongs to Allah, and lost from them is that which they used to invent.' },
  { surahId: 28, ayahNumber: 76, text: 'Indeed, Qarun was from the people of Moses, but he tyrannized them. And We gave him of treasures whose keys would burden a band of strong men; thereupon his people said to him, "Do not exult. Indeed, Allah does not like the exultant.' },
  { surahId: 28, ayahNumber: 77, text: 'But seek, through that which Allah has given you, the home of the Hereafter; and [yet], do not forget your share of the world. And do good as Allah has done good to you. And desire not corruption in the land. Indeed, Allah does not like corrupters."' },
  { surahId: 28, ayahNumber: 78, text: 'He said, "I was only given it because of knowledge I have." Did he not know that Allah had destroyed before him of generations those who were greater than him in power and greater in accumulation [of wealth]? But the criminals, about their sins, will not be asked.' },
  { surahId: 28, ayahNumber: 79, text: 'So he came out before his people in his adornment. Those who desired the worldly life said, "Oh, would that we had like what was given to Qarun. Indeed, he is one of great fortune."' },
  { surahId: 28, ayahNumber: 80, text: 'But those who had been given knowledge said, "Woe to you! The reward of Allah is better for he who believes and does righteousness. And none are granted it except the patient."' },
  { surahId: 28, ayahNumber: 81, text: 'And We caused the earth to swallow him and his home. And there was for him no company to aid him other than Allah, nor was he of those who [could] defend themselves.' },
  { surahId: 28, ayahNumber: 82, text: 'And those who had wished for his position the previous day began to say, "Oh, how Allah extends provision to whom He wills of His servants and restricts it! If not that Allah had conferred favor on us, He would have caused it to swallow us. Oh, how the disbelievers do not succeed!"' },
  { surahId: 28, ayahNumber: 83, text: 'That home of the Hereafter We assign to those who do not desire exaltedness upon the earth or corruption. And the [best] outcome is for the righteous.' },
  { surahId: 28, ayahNumber: 84, text: 'Whoever comes [on the Day of Judgement] with a good deed will have better than it; and whoever comes with an evil deed - then those who did evil deeds will not be recompensed except [as much as] what they used to do.' },
  { surahId: 28, ayahNumber: 85, text: 'Indeed, [O Muhammad], He who imposed upon you the Qur\'an will take you back to a place of return. Say, "My Lord is most knowing of who brings guidance and who is in clear error."' },
  { surahId: 28, ayahNumber: 86, text: 'And you were not expecting that the Book would be conveyed to you, but [it is] a mercy from your Lord. So do not be an assistant to the disbelievers.' },
  { surahId: 28, ayahNumber: 87, text: 'And never let them avert you from the verses of Allah after they have been revealed to you. And invite [people] to your Lord. And never be of those who associate others with Allah.' },
  { surahId: 28, ayahNumber: 88, text: 'And do not invoke with Allah another deity. There is no deity except Him. Everything will be destroyed except His Face. His is the judgement, and to Him you will be returned.' },
  { surahId: 29, ayahNumber: 1, text: 'Alif, Lam, Meem' },
  { surahId: 29, ayahNumber: 2, text: 'Do the people think that they will be left to say, "We believe" and they will not be tried?' },
  { surahId: 29, ayahNumber: 3, text: 'But We have certainly tried those before them, and Allah will surely make evident those who are truthful, and He will surely make evident the liars.' },
  { surahId: 29, ayahNumber: 4, text: 'Or do those who do evil deeds think they can outrun Us? Evil is what they judge.' },
  { surahId: 29, ayahNumber: 5, text: 'Whoever should hope for the meeting with Allah - indeed, the term decreed by Allah is coming. And He is the Hearing, the Knowing.' },
  { surahId: 29, ayahNumber: 6, text: 'And whoever strives only strives for [the benefit of] himself. Indeed, Allah is free from need of the worlds.' },
  { surahId: 29, ayahNumber: 7, text: 'And those who believe and do righteous deeds - We will surely remove from them their misdeeds and will surely reward them according to the best of what they used to do.' },
  { surahId: 29, ayahNumber: 8, text: 'And We have enjoined upon man goodness to parents. But if they endeavor to make you associate with Me that of which you have no knowledge, do not obey them. To Me is your return, and I will inform you about what you used to do.' },
  { surahId: 29, ayahNumber: 9, text: 'And those who believe and do righteous deeds - We will surely admit them among the righteous [into Paradise].' },
  { surahId: 29, ayahNumber: 10, text: 'And of the people are some who say, "We believe in Allah," but when one [of them] is harmed for [the cause of] Allah, they consider the trial of the people as [if it were] the punishment of Allah. But if victory comes from your Lord, they say, "Indeed, We were with you." Is not Allah most knowing of what is within the breasts of all creatures?' },
  { surahId: 29, ayahNumber: 11, text: 'And Allah will surely make evident those who believe, and He will surely make evident the hypocrites.' },
  { surahId: 29, ayahNumber: 12, text: 'And those who disbelieve say to those who believe, "Follow our way, and we will carry your sins." But they will not carry anything of their sins. Indeed, they are liars.' },
  { surahId: 29, ayahNumber: 13, text: 'But they will surely carry their [own] burdens and [other] burdens along with their burdens, and they will surely be questioned on the Day of Resurrection about what they used to invent.' },
  { surahId: 29, ayahNumber: 14, text: 'And We certainly sent Noah to his people, and he remained among them a thousand years minus fifty years, and the flood seized them while they were wrongdoers.' },
  { surahId: 29, ayahNumber: 15, text: 'But We saved him and the companions of the ship, and We made it a sign for the worlds.' },
  { surahId: 29, ayahNumber: 16, text: 'And [We sent] Abraham, when he said to his people, "Worship Allah and fear Him. That is best for you, if you should know.' },
  { surahId: 29, ayahNumber: 17, text: 'You only worship, besides Allah, idols, and you produce a falsehood. Indeed, those you worship besides Allah do not possess for you [the power of] provision. So seek from Allah provision and worship Him and be grateful to Him. To Him you will be returned."' },
  { surahId: 29, ayahNumber: 18, text: 'And if you [people] deny [the message] - already nations before you have denied. And there is not upon the Messenger except [the duty of] clear notification.' },
  { surahId: 29, ayahNumber: 19, text: 'Have they not considered how Allah begins creation and then repeats it? Indeed that, for Allah, is easy.' },
  { surahId: 29, ayahNumber: 20, text: 'Say, [O Muhammad], "Travel through the land and observe how He began creation. Then Allah will produce the final creation. Indeed Allah, over all things, is competent."' },
  { surahId: 29, ayahNumber: 21, text: 'He punishes whom He wills and has mercy upon whom He wills, and to Him you will be returned.' },
  { surahId: 29, ayahNumber: 22, text: 'And you will not cause failure [to Allah] upon the earth or in the heaven. And you have not other than Allah any protector or any helper.' },
  { surahId: 29, ayahNumber: 23, text: 'And the ones who disbelieve in the signs of Allah and the meeting with Him - those have despaired of My mercy, and they will have a painful punishment.' },
  { surahId: 29, ayahNumber: 24, text: 'And the answer of Abraham\'s people was not but that they said, "Kill him or burn him," but Allah saved him from the fire. Indeed in that are signs for a people who believe.' },
  { surahId: 29, ayahNumber: 25, text: 'And [Abraham] said, "You have only taken, other than Allah, idols as [a bond of] affection among you in worldly life. Then on the Day of Resurrection you will deny one another and curse one another, and your refuge will be the Fire, and you will not have any helpers."' },
  { surahId: 29, ayahNumber: 26, text: 'And Lot believed him. [Abraham] said, "Indeed, I will emigrate to [the service of] my Lord. Indeed, He is the Exalted in Might, the Wise."' },
  { surahId: 29, ayahNumber: 27, text: 'And We gave to Him Isaac and Jacob and placed in his descendants prophethood and scripture. And We gave him his reward in this world, and indeed, he is in the Hereafter among the righteous.' },
  { surahId: 29, ayahNumber: 28, text: 'And [mention] Lot, when he said to his people, "Indeed, you commit such immorality as no one has preceded you with from among the worlds.' },
  { surahId: 29, ayahNumber: 29, text: 'Indeed, you approach men and obstruct the road and commit in your meetings [every] evil." And the answer of his people was not but they said, "Bring us the punishment of Allah, if you should be of the truthful."' },
  { surahId: 29, ayahNumber: 30, text: 'He said, "My Lord, support me against the corrupting people."' },
  { surahId: 29, ayahNumber: 31, text: 'And when Our messengers came to Abraham with the good tidings, they said, "Indeed, we will destroy the people of that Lot\'s city. Indeed, its people have been wrongdoers."' },
  { surahId: 29, ayahNumber: 32, text: '[Abraham] said, "Indeed, within it is Lot." They said, "We are more knowing of who is within it. We will surely save him and his family, except his wife. She is to be of those who remain behind."' },
  { surahId: 29, ayahNumber: 33, text: 'And when Our messengers came to Lot, he was distressed for them and felt for them great discomfort. They said, "Fear not, nor grieve. Indeed, we will save you and your family, except your wife; she is to be of those who remain behind.' },
  { surahId: 29, ayahNumber: 34, text: 'Indeed, we will bring down on the people of this city punishment from the sky because they have been defiantly disobedient."' },
  { surahId: 29, ayahNumber: 35, text: 'And We have certainly left of it a sign as clear evidence for a people who use reason.' },
  { surahId: 29, ayahNumber: 36, text: 'And to Madyan [We sent] their brother Shu\'ayb, and he said, "O my people, worship Allah and expect the Last Day and do not commit abuse on the earth, spreading corruption."' },
  { surahId: 29, ayahNumber: 37, text: 'But they denied him, so the earthquake seized them, and they became within their home [corpses] fallen prone.' },
  { surahId: 29, ayahNumber: 38, text: 'And [We destroyed] \'Aad and Thamud, and it has become clear to you from their [ruined] dwellings. And Satan had made pleasing to them their deeds and averted them from the path, and they were endowed with perception.' },
  { surahId: 29, ayahNumber: 39, text: 'And [We destroyed] Qarun and Pharaoh and Haman. And Moses had already come to them with clear evidences, and they were arrogant in the land, but they were not outrunners [of Our punishment].' },
  { surahId: 29, ayahNumber: 40, text: 'So each We seized for his sin; and among them were those upon whom We sent a storm of stones, and among them were those who were seized by the blast [from the sky], and among them were those whom We caused the earth to swallow, and among them were those whom We drowned. And Allah would not have wronged them, but it was they who were wronging themselves.' },
  { surahId: 29, ayahNumber: 41, text: 'The example of those who take allies other than Allah is like that of the spider who takes a home. And indeed, the weakest of homes is the home of the spider, if they only knew.' },
  { surahId: 29, ayahNumber: 42, text: 'Indeed, Allah knows whatever thing they call upon other than Him. And He is the Exalted in Might, the Wise.' },
  { surahId: 29, ayahNumber: 43, text: 'And these examples We present to the people, but none will understand them except those of knowledge.' },
  { surahId: 29, ayahNumber: 44, text: 'Allah created the heavens and the earth in truth. Indeed in that is a sign for the believers.' },
  { surahId: 29, ayahNumber: 45, text: 'Recite, [O Muhammad], what has been revealed to you of the Book and establish prayer. Indeed, prayer prohibits immorality and wrongdoing, and the remembrance of Allah is greater. And Allah knows that which you do.' },
  { surahId: 29, ayahNumber: 46, text: 'And do not argue with the People of the Scripture except in a way that is best, except for those who commit injustice among them, and say, "We believe in that which has been revealed to us and revealed to you. And our God and your God is one; and we are Muslims [in submission] to Him."' },
  { surahId: 29, ayahNumber: 47, text: 'And thus We have sent down to you the Qur\'an. And those to whom We [previously] gave the Scripture believe in it. And among these [people of Makkah] are those who believe in it. And none reject Our verses except the disbelievers.' },
  { surahId: 29, ayahNumber: 48, text: 'And you did not recite before it any scripture, nor did you inscribe one with your right hand. Otherwise the falsifiers would have had [cause for] doubt.' },
  { surahId: 29, ayahNumber: 49, text: 'Rather, the Qur\'an is distinct verses [preserved] within the breasts of those who have been given knowledge. And none reject Our verses except the wrongdoers.' },
  { surahId: 29, ayahNumber: 50, text: 'But they say, "Why are not signs sent down to him from his Lord?" Say, "The signs are only with Allah, and I am only a clear warner."' },
  { surahId: 29, ayahNumber: 51, text: 'And is it not sufficient for them that We revealed to you the Book which is recited to them? Indeed in that is a mercy and reminder for a people who believe.' },
  { surahId: 29, ayahNumber: 52, text: 'Say, "Sufficient is Allah between me and you as Witness. He knows what is in the heavens and earth. And they who have believed in falsehood and disbelieved in Allah - it is those who are the losers."' },
  { surahId: 29, ayahNumber: 53, text: 'And they urge you to hasten the punishment. And if not for [the decree of] a specified term, punishment would have reached them. But it will surely come to them suddenly while they perceive not.' },
  { surahId: 29, ayahNumber: 54, text: 'They urge you to hasten the punishment. And indeed, Hell will be encompassing of the disbelievers' },
  { surahId: 29, ayahNumber: 55, text: 'On the Day the punishment will cover them from above them and from below their feet and it is said, "Taste [the result of] what you used to do."' },
  { surahId: 29, ayahNumber: 56, text: 'O My servants who have believed, indeed My earth is spacious, so worship only Me.' },
  { surahId: 29, ayahNumber: 57, text: 'Every soul will taste death. Then to Us will you be returned.' },
  { surahId: 29, ayahNumber: 58, text: 'And those who have believed and done righteous deeds - We will surely assign to them of Paradise [elevated] chambers beneath which rivers flow, wherein they abide eternally. Excellent is the reward of the [righteous] workers' },
  { surahId: 29, ayahNumber: 59, text: 'Who have been patient and upon their Lord rely.' },
  { surahId: 29, ayahNumber: 60, text: 'And how many a creature carries not its [own] provision. Allah provides for it and for you. And He is the Hearing, the Knowing.' },
  { surahId: 29, ayahNumber: 61, text: 'If you asked them, "Who created the heavens and earth and subjected the sun and the moon?" they would surely say, "Allah." Then how are they deluded?' },
  { surahId: 29, ayahNumber: 62, text: 'Allah extends provision for whom He wills of His servants and restricts for him. Indeed Allah is, of all things, Knowing.' },
  { surahId: 29, ayahNumber: 63, text: 'And if you asked them, "Who sends down rain from the sky and gives life thereby to the earth after its lifelessness?" they would surely say " Allah." Say, "Praise to Allah "; but most of them do not reason.' },
  { surahId: 29, ayahNumber: 64, text: 'And this worldly life is not but diversion and amusement. And indeed, the home of the Hereafter - that is the [eternal] life, if only they knew.' },
  { surahId: 29, ayahNumber: 65, text: 'And when they board a ship, they supplicate Allah, sincere to Him in religion. But when He delivers them to the land, at once they associate others with Him' },
  { surahId: 29, ayahNumber: 66, text: 'So that they will deny what We have granted them, and they will enjoy themselves. But they are going to know.' },
  { surahId: 29, ayahNumber: 67, text: 'Have they not seen that We made [Makkah] a safe sanctuary, while people are being taken away all around them? Then in falsehood do they believe, and in the favor of Allah they disbelieve?' },
  { surahId: 29, ayahNumber: 68, text: 'And who is more unjust than one who invents a lie about Allah or denies the truth when it has come to him? Is there not in Hell a [sufficient] residence for the disbelievers?' },
  { surahId: 29, ayahNumber: 69, text: 'And those who strive for Us - We will surely guide them to Our ways. And indeed, Allah is with the doers of good.' },
  { surahId: 30, ayahNumber: 1, text: 'Alif, Lam, Meem.' },
  { surahId: 30, ayahNumber: 2, text: 'The Byzantines have been defeated' },
  { surahId: 30, ayahNumber: 3, text: 'In the nearest land. But they, after their defeat, will overcome.' },
  { surahId: 30, ayahNumber: 4, text: 'Within three to nine years. To Allah belongs the command before and after. And that day the believers will rejoice' },
  { surahId: 30, ayahNumber: 5, text: 'In the victory of Allah. He gives victory to whom He wills, and He is the Exalted in Might, the Merciful.' },
  { surahId: 30, ayahNumber: 6, text: '[It is] the promise of Allah. Allah does not fail in His promise, but most of the people do not know.' },
  { surahId: 30, ayahNumber: 7, text: 'They know what is apparent of the worldly life, but they, of the Hereafter, are unaware.' },
  { surahId: 30, ayahNumber: 8, text: 'Do they not contemplate within themselves? Allah has not created the heavens and the earth and what is between them except in truth and for a specified term. And indeed, many of the people, in [the matter of] the meeting with their Lord, are disbelievers.' },
  { surahId: 30, ayahNumber: 9, text: 'Have they not traveled through the earth and observed how was the end of those before them? They were greater than them in power, and they plowed the earth and built it up more than they have built it up, and their messengers came to them with clear evidences. And Allah would not ever have wronged them, but they were wronging themselves.' },
  { surahId: 30, ayahNumber: 10, text: 'Then the end of those who did evil was the worst [consequence] because they denied the signs of Allah and used to ridicule them.' },
  { surahId: 30, ayahNumber: 11, text: 'Allah begins creation; then He will repeat it; then to Him you will be returned.' },
  { surahId: 30, ayahNumber: 12, text: 'And the Day the Hour appears the criminals will be in despair.' },
  { surahId: 30, ayahNumber: 13, text: 'And there will not be for them among their [alleged] partners any intercessors, and they will [then] be disbelievers in their partners.' },
  { surahId: 30, ayahNumber: 14, text: 'And the Day the Hour appears - that Day they will become separated.' },
  { surahId: 30, ayahNumber: 15, text: 'And as for those who had believed and done righteous deeds, they will be in a garden [of Paradise], delighted.' },
  { surahId: 30, ayahNumber: 16, text: 'But as for those who disbelieved and denied Our verses and the meeting of the Hereafter, those will be brought into the punishment [to remain].' },
  { surahId: 30, ayahNumber: 17, text: 'So exalted is Allah when you reach the evening and when you reach the morning.' },
  { surahId: 30, ayahNumber: 18, text: 'And to Him is [due all] praise throughout the heavens and the earth. And [exalted is He] at night and when you are at noon.' },
  { surahId: 30, ayahNumber: 19, text: 'He brings the living out of the dead and brings the dead out of the living and brings to life the earth after its lifelessness. And thus will you be brought out.' },
  { surahId: 30, ayahNumber: 20, text: 'And of His signs is that He created you from dust; then, suddenly you were human beings dispersing [throughout the earth].' },
  { surahId: 30, ayahNumber: 21, text: 'And of His signs is that He created for you from yourselves mates that you may find tranquillity in them; and He placed between you affection and mercy. Indeed in that are signs for a people who give thought.' },
  { surahId: 30, ayahNumber: 22, text: 'And of His signs is the creation of the heavens and the earth and the diversity of your languages and your colors. Indeed in that are signs for those of knowledge.' },
  { surahId: 30, ayahNumber: 23, text: 'And of His signs is your sleep by night and day and your seeking of His bounty. Indeed in that are signs for a people who listen.' },
  { surahId: 30, ayahNumber: 24, text: 'And of His signs is [that] He shows you the lightning [causing] fear and aspiration, and He sends down rain from the sky by which He brings to life the earth after its lifelessness. Indeed in that are signs for a people who use reason.' },
  { surahId: 30, ayahNumber: 25, text: 'And of His signs is that the heaven and earth remain by His command. Then when He calls you with a [single] call from the earth, immediately you will come forth.' },
  { surahId: 30, ayahNumber: 26, text: 'And to Him belongs whoever is in the heavens and earth. All are to Him devoutly obedient.' },
  { surahId: 30, ayahNumber: 27, text: 'And it is He who begins creation; then He repeats it, and that is [even] easier for Him. To Him belongs the highest attribute in the heavens and earth. And He is the Exalted in Might, the Wise.' },
  { surahId: 30, ayahNumber: 28, text: 'He presents to you an example from yourselves. Do you have among those whom your right hands possess any partners in what We have provided for you so that you are equal therein [and] would fear them as your fear of one another [within a partnership]? Thus do We detail the verses for a people who use reason.' },
  { surahId: 30, ayahNumber: 29, text: 'But those who wrong follow their [own] desires without knowledge. Then who can guide one whom Allah has sent astray? And for them there are no helpers.' },
  { surahId: 30, ayahNumber: 30, text: 'So direct your face toward the religion, inclining to truth. [Adhere to] the fitrah of Allah upon which He has created [all] people. No change should there be in the creation of Allah. That is the correct religion, but most of the people do not know.' },
  { surahId: 30, ayahNumber: 31, text: '[Adhere to it], turning in repentance to Him, and fear Him and establish prayer and do not be of those who associate others with Allah' },
  { surahId: 30, ayahNumber: 32, text: '[Or] of those who have divided their religion and become sects, every faction rejoicing in what it has.' },
  { surahId: 30, ayahNumber: 33, text: 'And when adversity touches the people, they call upon their Lord, turning in repentance to Him. Then when He lets them taste mercy from Him, at once a party of them associate others with their Lord,' },
  { surahId: 30, ayahNumber: 34, text: 'So that they will deny what We have granted them. Then enjoy yourselves, for you are going to know.' },
  { surahId: 30, ayahNumber: 35, text: 'Or have We sent down to them an authority, and it speaks of what they were associating with Him?' },
  { surahId: 30, ayahNumber: 36, text: 'And when We let the people taste mercy, they rejoice therein, but if evil afflicts them for what their hands have put forth, immediately they despair.' },
  { surahId: 30, ayahNumber: 37, text: 'Do they not see that Allah extends provision for whom He wills and restricts [it]? Indeed, in that are signs for a people who believe.' },
  { surahId: 30, ayahNumber: 38, text: 'So give the relative his right, as well as the needy and the traveler. That is best for those who desire the countenance of Allah, and it is they who will be the successful.' },
  { surahId: 30, ayahNumber: 39, text: 'And whatever you give for interest to increase within the wealth of people will not increase with Allah. But what you give in zakah, desiring the countenance of Allah - those are the multipliers.' },
  { surahId: 30, ayahNumber: 40, text: 'Allah is the one who created you, then provided for you, then will cause you to die, and then will give you life. Are there any of your "partners" who does anything of that? Exalted is He and high above what they associate with Him.' },
  { surahId: 30, ayahNumber: 41, text: 'Corruption has appeared throughout the land and sea by [reason of] what the hands of people have earned so He may let them taste part of [the consequence of] what they have done that perhaps they will return [to righteousness].' },
  { surahId: 30, ayahNumber: 42, text: 'Say, [O Muhammad], "Travel through the land and observe how was the end of those before. Most of them were associators [of others with Allah].' },
  { surahId: 30, ayahNumber: 43, text: 'So direct your face toward the correct religion before a Day comes from Allah of which there is no repelling. That Day, they will be divided.' },
  { surahId: 30, ayahNumber: 44, text: 'Whoever disbelieves - upon him is [the consequence of] his disbelief. And whoever does righteousness - they are for themselves preparing,' },
  { surahId: 30, ayahNumber: 45, text: 'That He may reward those who have believed and done righteous deeds out of His bounty. Indeed, He does not like the disbelievers.' },
  { surahId: 30, ayahNumber: 46, text: 'And of His signs is that He sends the winds as bringers of good tidings and to let you taste His mercy and so the ships may sail at His command and so you may seek of His bounty, and perhaps you will be grateful.' },
  { surahId: 30, ayahNumber: 47, text: 'And We have already sent messengers before you to their peoples, and they came to them with clear evidences; then We took retribution from those who committed crimes, and incumbent upon Us was support of the believers.' },
  { surahId: 30, ayahNumber: 48, text: 'It is Allah who sends the winds, and they stir the clouds and spread them in the sky however He wills, and He makes them fragments so you see the rain emerge from within them. And when He causes it to fall upon whom He wills of His servants, immediately they rejoice' },
  { surahId: 30, ayahNumber: 49, text: 'Although they were, before it was sent down upon them - before that, in despair.' },
  { surahId: 30, ayahNumber: 50, text: 'So observe the effects of the mercy of Allah - how He gives life to the earth after its lifelessness. Indeed, that [same one] will give life to the dead, and He is over all things competent.' },
  { surahId: 30, ayahNumber: 51, text: 'But if We should send a [bad] wind and they saw [their crops] turned yellow, they would remain thereafter disbelievers.' },
  { surahId: 30, ayahNumber: 52, text: 'So indeed, you will not make the dead hear, nor will you make the deaf hear the call when they turn their backs, retreating.' },
  { surahId: 30, ayahNumber: 53, text: 'And you cannot guide the blind away from their error. You will only make hear those who believe in Our verses so they are Muslims [in submission to Allah].' },
  { surahId: 30, ayahNumber: 54, text: 'Allah is the one who created you from weakness, then made after weakness strength, then made after strength weakness and white hair. He creates what He wills, and He is the Knowing, the Competent.' },
  { surahId: 30, ayahNumber: 55, text: 'And the Day the Hour appears the criminals will swear they had remained but an hour. Thus they were deluded.' },
  { surahId: 30, ayahNumber: 56, text: 'But those who were given knowledge and faith will say, "You remained the extent of Allah \'s decree until the Day of Resurrection, and this is the Day of Resurrection, but you did not used to know."' },
  { surahId: 30, ayahNumber: 57, text: 'So that Day, their excuse will not benefit those who wronged, nor will they be asked to appease [Allah].' },
  { surahId: 30, ayahNumber: 58, text: 'And We have certainly presented to the people in this Qur\'an from every [kind of] example. But, [O Muhammad], if you should bring them a sign, the disbelievers will surely say, "You [believers] are but falsifiers."' },
  { surahId: 30, ayahNumber: 59, text: 'Thus does Allah seal the hearts of those who do not know.' },
  { surahId: 30, ayahNumber: 60, text: 'So be patient. Indeed, the promise of Allah is truth. And let them not disquiet you who are not certain [in faith].' },
  { surahId: 31, ayahNumber: 1, text: 'Alif, Lam, Meem.' },
  { surahId: 31, ayahNumber: 2, text: 'These are verses of the wise Book,' },
  { surahId: 31, ayahNumber: 3, text: 'As guidance and mercy for the doers of good' },
  { surahId: 31, ayahNumber: 4, text: 'Who establish prayer and give zakah, and they, of the Hereafter, are certain [in faith].' },
  { surahId: 31, ayahNumber: 5, text: 'Those are on [right] guidance from their Lord, and it is those who are the successful.' },
  { surahId: 31, ayahNumber: 6, text: 'And of the people is he who buys the amusement of speech to mislead [others] from the way of Allah without knowledge and who takes it in ridicule. Those will have a humiliating punishment.' },
  { surahId: 31, ayahNumber: 7, text: 'And when our verses are recited to him, he turns away arrogantly as if he had not heard them, as if there was in his ears deafness. So give him tidings of a painful punishment.' },
  { surahId: 31, ayahNumber: 8, text: 'Indeed, those who believe and do righteous deeds - for them are the Gardens of Pleasure.' },
  { surahId: 31, ayahNumber: 9, text: 'Wherein they abide eternally; [it is] the promise of Allah [which is] truth. And He is the Exalted in Might, the Wise.' },
  { surahId: 31, ayahNumber: 10, text: 'He created the heavens without pillars that you see and has cast into the earth firmly set mountains, lest it should shift with you, and dispersed therein from every creature. And We sent down rain from the sky and made grow therein [plants] of every noble kind.' },
  { surahId: 31, ayahNumber: 11, text: 'This is the creation of Allah. So show Me what those other than Him have created. Rather, the wrongdoers are in clear error.' },
  { surahId: 31, ayahNumber: 12, text: 'And We had certainly given Luqman wisdom [and said], "Be grateful to Allah." And whoever is grateful is grateful for [the benefit of] himself. And whoever denies [His favor] - then indeed, Allah is Free of need and Praiseworthy.' },
  { surahId: 31, ayahNumber: 13, text: 'And [mention, O Muhammad], when Luqman said to his son while he was instructing him, "O my son, do not associate [anything] with Allah. Indeed, association [with him] is great injustice."' },
  { surahId: 31, ayahNumber: 14, text: 'And We have enjoined upon man [care] for his parents. His mother carried him, [increasing her] in weakness upon weakness, and his weaning is in two years. Be grateful to Me and to your parents; to Me is the [final] destination.' },
  { surahId: 31, ayahNumber: 15, text: 'But if they endeavor to make you associate with Me that of which you have no knowledge, do not obey them but accompany them in [this] world with appropriate kindness and follow the way of those who turn back to Me [in repentance]. Then to Me will be your return, and I will inform you about what you used to do.' },
  { surahId: 31, ayahNumber: 16, text: '[And Luqman said], "O my son, indeed if wrong should be the weight of a mustard seed and should be within a rock or [anywhere] in the heavens or in the earth, Allah will bring it forth. Indeed, Allah is Subtle and Acquainted.' },
  { surahId: 31, ayahNumber: 17, text: 'O my son, establish prayer, enjoin what is right, forbid what is wrong, and be patient over what befalls you. Indeed, [all] that is of the matters [requiring] determination.' },
  { surahId: 31, ayahNumber: 18, text: 'And do not turn your cheek [in contempt] toward people and do not walk through the earth exultantly. Indeed, Allah does not like everyone self-deluded and boastful.' },
  { surahId: 31, ayahNumber: 19, text: 'And be moderate in your pace and lower your voice; indeed, the most disagreeable of sounds is the voice of donkeys."' },
  { surahId: 31, ayahNumber: 20, text: 'Do you not see that Allah has made subject to you whatever is in the heavens and whatever is in the earth and amply bestowed upon you His favors, [both] apparent and unapparent? But of the people is he who disputes about Allah without knowledge or guidance or an enlightening Book [from Him].' },
  { surahId: 31, ayahNumber: 21, text: 'And when it is said to them, "Follow what Allah has revealed," they say, "Rather, we will follow that upon which we found our fathers." Even if Satan was inviting them to the punishment of the Blaze?' },
  { surahId: 31, ayahNumber: 22, text: 'And whoever submits his face to Allah while he is a doer of good - then he has grasped the most trustworthy handhold. And to Allah will be the outcome of [all] matters.' },
  { surahId: 31, ayahNumber: 23, text: 'And whoever has disbelieved - let not his disbelief grieve you. To Us is their return, and We will inform them of what they did. Indeed, Allah is Knowing of that within the breasts.' },
  { surahId: 31, ayahNumber: 24, text: 'We grant them enjoyment for a little; then We will force them to a massive punishment.' },
  { surahId: 31, ayahNumber: 25, text: 'And if you asked them, "Who created the heavens and earth?" they would surely say, "Allah." Say, "[All] praise is [due] to Allah "; but most of them do not know.' },
  { surahId: 31, ayahNumber: 26, text: 'To Allah belongs whatever is in the heavens and earth. Indeed, Allah is the Free of need, the Praiseworthy.' },
  { surahId: 31, ayahNumber: 27, text: 'And if whatever trees upon the earth were pens and the sea [was ink], replenished thereafter by seven [more] seas, the words of Allah would not be exhausted. Indeed, Allah is Exalted in Might and Wise.' },
  { surahId: 31, ayahNumber: 28, text: 'Your creation and your resurrection will not be but as that of a single soul. Indeed, Allah is Hearing and Seeing.' },
  { surahId: 31, ayahNumber: 29, text: 'Do you not see that Allah causes the night to enter the day and causes the day to enter the night and has subjected the sun and the moon, each running [its course] for a specified term, and that Allah, with whatever you do, is Acquainted?' },
  { surahId: 31, ayahNumber: 30, text: 'That is because Allah is the Truth, and that what they call upon other than Him is falsehood, and because Allah is the Most High, the Grand.' },
  { surahId: 31, ayahNumber: 31, text: 'Do you not see that ships sail through the sea by the favor of Allah that He may show you of His signs? Indeed in that are signs for everyone patient and grateful.' },
  { surahId: 31, ayahNumber: 32, text: 'And when waves come over them like canopies, they supplicate Allah, sincere to Him in religion. But when He delivers them to the land, there are [some] of them who are moderate [in faith]. And none rejects Our signs except everyone treacherous and ungrateful.' },
  { surahId: 31, ayahNumber: 33, text: 'O mankind, fear your Lord and fear a Day when no father will avail his son, nor will a son avail his father at all. Indeed, the promise of Allah is truth, so let not the worldly life delude you and be not deceived about Allah by the Deceiver.' },
  { surahId: 31, ayahNumber: 34, text: 'Indeed, Allah [alone] has knowledge of the Hour and sends down the rain and knows what is in the wombs. And no soul perceives what it will earn tomorrow, and no soul perceives in what land it will die. Indeed, Allah is Knowing and Acquainted.' },
  { surahId: 32, ayahNumber: 1, text: 'Alif, Lam, Meem.' },
  { surahId: 32, ayahNumber: 2, text: '[This is] the revelation of the Book about which there is no doubt from the Lord of the worlds.' },
  { surahId: 32, ayahNumber: 3, text: 'Or do they say, "He invented it"? Rather, it is the truth from your Lord, [O Muhammad], that you may warn a people to whom no warner has come before you [so] perhaps they will be guided.' },
  { surahId: 32, ayahNumber: 4, text: 'It is Allah who created the heavens and the earth and whatever is between them in six days; then He established Himself above the Throne. You have not besides Him any protector or any intercessor; so will you not be reminded?' },
  { surahId: 32, ayahNumber: 5, text: 'He arranges [each] matter from the heaven to the earth; then it will ascend to Him in a Day, the extent of which is a thousand years of those which you count.' },
  { surahId: 32, ayahNumber: 6, text: 'That is the Knower of the unseen and the witnessed, the Exalted in Might, the Merciful,' },
  { surahId: 32, ayahNumber: 7, text: 'Who perfected everything which He created and began the creation of man from clay.' },
  { surahId: 32, ayahNumber: 8, text: 'Then He made his posterity out of the extract of a liquid disdained.' },
  { surahId: 32, ayahNumber: 9, text: 'Then He proportioned him and breathed into him from His [created] soul and made for you hearing and vision and hearts; little are you grateful.' },
  { surahId: 32, ayahNumber: 10, text: 'And they say, "When we are lost within the earth, will we indeed be [recreated] in a new creation?" Rather, they are, in [the matter of] the meeting with their Lord, disbelievers.' },
  { surahId: 32, ayahNumber: 11, text: 'Say, "The angel of death will take you who has been entrusted with you. Then to your Lord you will be returned."' },
  { surahId: 32, ayahNumber: 12, text: 'If you could but see when the criminals are hanging their heads before their Lord, [saying], "Our Lord, we have seen and heard, so return us [to the world]; we will work righteousness. Indeed, we are [now] certain."' },
  { surahId: 32, ayahNumber: 13, text: 'And if We had willed, We could have given every soul its guidance, but the word from Me will come into effect [that] "I will surely fill Hell with jinn and people all together.' },
  { surahId: 32, ayahNumber: 14, text: 'So taste [punishment] because you forgot the meeting of this, your Day; indeed, We have [accordingly] forgotten you. And taste the punishment of eternity for what you used to do."' },
  { surahId: 32, ayahNumber: 15, text: 'Only those believe in Our verses who, when they are reminded by them, fall down in prostration and exalt [Allah] with praise of their Lord, and they are not arrogant.' },
  { surahId: 32, ayahNumber: 16, text: 'They arise from [their] beds; they supplicate their Lord in fear and aspiration, and from what We have provided them, they spend.' },
  { surahId: 32, ayahNumber: 17, text: 'And no soul knows what has been hidden for them of comfort for eyes as reward for what they used to do.' },
  { surahId: 32, ayahNumber: 18, text: 'Then is one who was a believer like one who was defiantly disobedient? They are not equal.' },
  { surahId: 32, ayahNumber: 19, text: 'As for those who believed and did righteous deeds, for them will be the Gardens of Refuge as accommodation for what they used to do.' },
  { surahId: 32, ayahNumber: 20, text: 'But as for those who defiantly disobeyed, their refuge is the Fire. Every time they wish to emerge from it, they will be returned to it while it is said to them, "Taste the punishment of the Fire which you used to deny."' },
  { surahId: 32, ayahNumber: 21, text: 'And we will surely let them taste the nearer punishment short of the greater punishment that perhaps they will repent.' },
  { surahId: 32, ayahNumber: 22, text: 'And who is more unjust than one who is reminded of the verses of his Lord; then he turns away from them? Indeed We, from the criminals, will take retribution.' },
  { surahId: 32, ayahNumber: 23, text: 'And We certainly gave Moses the Scripture, so do not be in doubt over his meeting. And we made the Torah guidance for the Children of Israel.' },
  { surahId: 32, ayahNumber: 24, text: 'And We made from among them leaders guiding by Our command when they were patient and [when] they were certain of Our signs.' },
  { surahId: 32, ayahNumber: 25, text: 'Indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ.' },
  { surahId: 32, ayahNumber: 26, text: 'Has it not become clear to them how many generations We destroyed before them, [as] they walk among their dwellings? Indeed in that are signs; then do they not hear?' },
  { surahId: 32, ayahNumber: 27, text: 'Have they not seen that We drive the water [in clouds] to barren land and bring forth thereby crops from which their livestock eat and [they] themselves? Then do they not see?' },
  { surahId: 32, ayahNumber: 28, text: 'And they say, "When will be this conquest, if you should be truthful?"' },
  { surahId: 32, ayahNumber: 29, text: 'Say, [O Muhammad], "On the Day of Conquest the belief of those who had disbelieved will not benefit them, nor will they be reprieved."' },
  { surahId: 32, ayahNumber: 30, text: 'So turn away from them and wait. Indeed, they are waiting.' },
  { surahId: 33, ayahNumber: 1, text: 'O Prophet, fear Allah and do not obey the disbelievers and the hypocrites. Indeed, Allah is ever Knowing and Wise.' },
  { surahId: 33, ayahNumber: 2, text: 'And follow that which is revealed to you from your Lord. Indeed Allah is ever, with what you do, Acquainted.' },
  { surahId: 33, ayahNumber: 3, text: 'And rely upon Allah; and sufficient is Allah as Disposer of affairs.' },
  { surahId: 33, ayahNumber: 4, text: 'Allah has not made for a man two hearts in his interior. And He has not made your wives whom you declare unlawful your mothers. And he has not made your adopted sons your [true] sons. That is [merely] your saying by your mouths, but Allah says the truth, and He guides to the [right] way.' },
  { surahId: 33, ayahNumber: 5, text: 'Call them by [the names of] their fathers; it is more just in the sight of Allah. But if you do not know their fathers - then they are [still] your brothers in religion and those entrusted to you. And there is no blame upon you for that in which you have erred but [only for] what your hearts intended. And ever is Allah Forgiving and Merciful.' },
  { surahId: 33, ayahNumber: 6, text: 'The Prophet is more worthy of the believers than themselves, and his wives are [in the position of] their mothers. And those of [blood] relationship are more entitled [to inheritance] in the decree of Allah than the [other] believers and the emigrants, except that you may do to your close associates a kindness [through bequest]. That was in the Book inscribed.' },
  { surahId: 33, ayahNumber: 7, text: 'And [mention, O Muhammad], when We took from the prophets their covenant and from you and from Noah and Abraham and Moses and Jesus, the son of Mary; and We took from them a solemn covenant.' },
  { surahId: 33, ayahNumber: 8, text: 'That He may question the truthful about their truth. And He has prepared for the disbelievers a painful punishment.' },
  { surahId: 33, ayahNumber: 9, text: 'O you who have believed, remember the favor of Allah upon you when armies came to [attack] you and We sent upon them a wind and armies [of angels] you did not see. And ever is Allah, of what you do, Seeing.' },
  { surahId: 33, ayahNumber: 10, text: '[Remember] when they came at you from above you and from below you, and when eyes shifted [in fear], and hearts reached the throats and you assumed about Allah [various] assumptions.' },
  { surahId: 33, ayahNumber: 11, text: 'There the believers were tested and shaken with a severe shaking.' },
  { surahId: 33, ayahNumber: 12, text: 'And [remember] when the hypocrites and those in whose hearts is disease said, "Allah and His Messenger did not promise us except delusion,"' },
  { surahId: 33, ayahNumber: 13, text: 'And when a faction of them said, "O people of Yathrib, there is no stability for you [here], so return [home]." And a party of them asked permission of the Prophet, saying, "Indeed, our houses are unprotected," while they were not exposed. They did not intend except to flee.' },
  { surahId: 33, ayahNumber: 14, text: 'And if they had been entered upon from all its [surrounding] regions and fitnah had been demanded of them, they would have done it and not hesitated over it except briefly.' },
  { surahId: 33, ayahNumber: 15, text: 'And they had already promised Allah before not to turn their backs and flee. And ever is the promise to Allah [that about which one will be] questioned.' },
  { surahId: 33, ayahNumber: 16, text: 'Say, [O Muhammad], "Never will fleeing benefit you if you should flee from death or killing; and then [if you did], you would not be given enjoyment [of life] except for a little."' },
  { surahId: 33, ayahNumber: 17, text: 'Say, "Who is it that can protect you from Allah if He intends for you an ill or intends for you a mercy?" And they will not find for themselves besides Allah any protector or any helper.' },
  { surahId: 33, ayahNumber: 18, text: 'Already Allah knows the hinderers among you and those [hypocrites] who say to their brothers, "Come to us," and do not go to battle, except for a few,' },
  { surahId: 33, ayahNumber: 19, text: 'Indisposed toward you. And when fear comes, you see them looking at you, their eyes revolving like one being overcome by death. But when fear departs, they lash you with sharp tongues, indisposed toward [any] good. Those have not believed, so Allah has rendered their deeds worthless, and ever is that, for Allah, easy.' },
  { surahId: 33, ayahNumber: 20, text: 'They think the companies have not [yet] withdrawn. And if the companies should come [again], they would wish they were in the desert among the bedouins, inquiring [from afar] about your news. And if they should be among you, they would not fight except for a little.' },
  { surahId: 33, ayahNumber: 21, text: 'There has certainly been for you in the Messenger of Allah an excellent pattern for anyone whose hope is in Allah and the Last Day and [who] remembers Allah often.' },
  { surahId: 33, ayahNumber: 22, text: 'And when the believers saw the companies, they said, "This is what Allah and His Messenger had promised us, and Allah and His Messenger spoke the truth." And it increased them only in faith and acceptance.' },
  { surahId: 33, ayahNumber: 23, text: 'Among the believers are men true to what they promised Allah. Among them is he who has fulfilled his vow [to the death], and among them is he who awaits [his chance]. And they did not alter [the terms of their commitment] by any alteration -' },
  { surahId: 33, ayahNumber: 24, text: 'That Allah may reward the truthful for their truth and punish the hypocrites if He wills or accept their repentance. Indeed, Allah is ever Forgiving and Merciful.' },
  { surahId: 33, ayahNumber: 25, text: 'And Allah repelled those who disbelieved, in their rage, not having obtained any good. And sufficient was Allah for the believers in battle, and ever is Allah Powerful and Exalted in Might.' },
  { surahId: 33, ayahNumber: 26, text: 'And He brought down those who supported them among the People of the Scripture from their fortresses and cast terror into their hearts [so that] a party you killed, and you took captive a party.' },
  { surahId: 33, ayahNumber: 27, text: 'And He caused you to inherit their land and their homes and their properties and a land which you have not trodden. And ever is Allah, over all things, competent.' },
  { surahId: 33, ayahNumber: 28, text: 'O Prophet, say to your wives, "If you should desire the worldly life and its adornment, then come, I will provide for you and give you a gracious release.' },
  { surahId: 33, ayahNumber: 29, text: 'But if you should desire Allah and His Messenger and the home of the Hereafter - then indeed, Allah has prepared for the doers of good among you a great reward."' },
  { surahId: 33, ayahNumber: 30, text: 'O wives of the Prophet, whoever of you should commit a clear immorality - for her the punishment would be doubled two fold, and ever is that, for Allah, easy.' },
  { surahId: 33, ayahNumber: 31, text: 'And whoever of you devoutly obeys Allah and His Messenger and does righteousness - We will give her her reward twice; and We have prepared for her a noble provision.' },
  { surahId: 33, ayahNumber: 32, text: 'O wives of the Prophet, you are not like anyone among women. If you fear Allah, then do not be soft in speech [to men], lest he in whose heart is disease should covet, but speak with appropriate speech.' },
  { surahId: 33, ayahNumber: 33, text: 'And abide in your houses and do not display yourselves as [was] the display of the former times of ignorance. And establish prayer and give zakah and obey Allah and His Messenger. Allah intends only to remove from you the impurity [of sin], O people of the [Prophet\'s] household, and to purify you with [extensive] purification.' },
  { surahId: 33, ayahNumber: 34, text: 'And remember what is recited in your houses of the verses of Allah and wisdom. Indeed, Allah is ever Subtle and Acquainted [with all things].' },
  { surahId: 33, ayahNumber: 35, text: 'Indeed, the Muslim men and Muslim women, the believing men and believing women, the obedient men and obedient women, the truthful men and truthful women, the patient men and patient women, the humble men and humble women, the charitable men and charitable women, the fasting men and fasting women, the men who guard their private parts and the women who do so, and the men who remember Allah often and the women who do so - for them Allah has prepared forgiveness and a great reward.' },
  { surahId: 33, ayahNumber: 36, text: 'It is not for a believing man or a believing woman, when Allah and His Messenger have decided a matter, that they should [thereafter] have any choice about their affair. And whoever disobeys Allah and His Messenger has certainly strayed into clear error.' },
  { surahId: 33, ayahNumber: 37, text: 'And [remember, O Muhammad], when you said to the one on whom Allah bestowed favor and you bestowed favor, "Keep your wife and fear Allah," while you concealed within yourself that which Allah is to disclose. And you feared the people, while Allah has more right that you fear Him. So when Zayd had no longer any need for her, We married her to you in order that there not be upon the believers any discomfort concerning the wives of their adopted sons when they no longer have need of them. And ever is the command of Allah accomplished.' },
  { surahId: 33, ayahNumber: 38, text: 'There is not to be upon the Prophet any discomfort concerning that which Allah has imposed upon him. [This is] the established way of Allah with those [prophets] who have passed on before. And ever is the command of Allah a destiny decreed.' },
  { surahId: 33, ayahNumber: 39, text: '[Allah praises] those who convey the messages of Allah and fear Him and do not fear anyone but Allah. And sufficient is Allah as Accountant.' },
  { surahId: 33, ayahNumber: 40, text: 'Muhammad is not the father of [any] one of your men, but [he is] the Messenger of Allah and last of the prophets. And ever is Allah, of all things, Knowing.' },
  { surahId: 33, ayahNumber: 41, text: 'O you who have believed, remember Allah with much remembrance' },
  { surahId: 33, ayahNumber: 42, text: 'And exalt Him morning and afternoon.' },
  { surahId: 33, ayahNumber: 43, text: 'It is He who confers blessing upon you, and His angels [ask Him to do so] that He may bring you out from darknesses into the light. And ever is He, to the believers, Merciful.' },
  { surahId: 33, ayahNumber: 44, text: 'Their greeting the Day they meet Him will be, "Peace." And He has prepared for them a noble reward.' },
  { surahId: 33, ayahNumber: 45, text: 'O Prophet, indeed We have sent you as a witness and a bringer of good tidings and a warner.' },
  { surahId: 33, ayahNumber: 46, text: 'And one who invites to Allah, by His permission, and an illuminating lamp.' },
  { surahId: 33, ayahNumber: 47, text: 'And give good tidings to the believers that they will have from Allah great bounty.' },
  { surahId: 33, ayahNumber: 48, text: 'And do not obey the disbelievers and the hypocrites but do not harm them, and rely upon Allah. And sufficient is Allah as Disposer of affairs.' },
  { surahId: 33, ayahNumber: 49, text: 'O You who have believed, when you marry believing women and then divorce them before you have touched them, then there is not for you any waiting period to count concerning them. So provide for them and give them a gracious release.' },
  { surahId: 33, ayahNumber: 50, text: 'O Prophet, indeed We have made lawful to you your wives to whom you have given their due compensation and those your right hand possesses from what Allah has returned to you [of captives] and the daughters of your paternal uncles and the daughters of your paternal aunts and the daughters of your maternal uncles and the daughters of your maternal aunts who emigrated with you and a believing woman if she gives herself to the Prophet [and] if the Prophet wishes to marry her, [this is] only for you, excluding the [other] believers. We certainly know what We have made obligatory upon them concerning their wives and those their right hands possess, [but this is for you] in order that there will be upon you no discomfort. And ever is Allah Forgiving and Merciful.' },
  { surahId: 33, ayahNumber: 51, text: 'You, [O Muhammad], may put aside whom you will of them or take to yourself whom you will. And any that you desire of those [wives] from whom you had [temporarily] separated - there is no blame upon you [in returning her]. That is more suitable that they should be content and not grieve and that they should be satisfied with what you have given them - all of them. And Allah knows what is in your hearts. And ever is Allah Knowing and Forbearing.' },
  { surahId: 33, ayahNumber: 52, text: 'Not lawful to you, [O Muhammad], are [any additional] women after [this], nor [is it] for you to exchange them for [other] wives, even if their beauty were to please you, except what your right hand possesses. And ever is Allah, over all things, an Observer.' },
  { surahId: 33, ayahNumber: 53, text: 'O you who have believed, do not enter the houses of the Prophet except when you are permitted for a meal, without awaiting its readiness. But when you are invited, then enter; and when you have eaten, disperse without seeking to remain for conversation. Indeed, that [behavior] was troubling the Prophet, and he is shy of [dismissing] you. But Allah is not shy of the truth. And when you ask [his wives] for something, ask them from behind a partition. That is purer for your hearts and their hearts. And it is not [conceivable or lawful] for you to harm the Messenger of Allah or to marry his wives after him, ever. Indeed, that would be in the sight of Allah an enormity.' },
  { surahId: 33, ayahNumber: 54, text: 'Whether you reveal a thing or conceal it, indeed Allah is ever, of all things, Knowing.' },
  { surahId: 33, ayahNumber: 55, text: 'There is no blame upon women concerning their fathers or their sons or their brothers or their brothers\' sons or their sisters\' sons or their women or those their right hands possess. And fear Allah. Indeed Allah is ever, over all things, Witness.' },
  { surahId: 33, ayahNumber: 56, text: 'Indeed, Allah confers blessing upon the Prophet, and His angels [ask Him to do so]. O you who have believed, ask [Allah to confer] blessing upon him and ask [Allah to grant him] peace.' },
  { surahId: 33, ayahNumber: 57, text: 'Indeed, those who abuse Allah and His Messenger - Allah has cursed them in this world and the Hereafter and prepared for them a humiliating punishment.' },
  { surahId: 33, ayahNumber: 58, text: 'And those who harm believing men and believing women for [something] other than what they have earned have certainly born upon themselves a slander and manifest sin.' },
  { surahId: 33, ayahNumber: 59, text: 'O Prophet, tell your wives and your daughters and the women of the believers to bring down over themselves [part] of their outer garments. That is more suitable that they will be known and not be abused. And ever is Allah Forgiving and Merciful.' },
  { surahId: 33, ayahNumber: 60, text: 'If the hypocrites and those in whose hearts is disease and those who spread rumors in al-Madinah do not cease, We will surely incite you against them; then they will not remain your neighbors therein except for a little.' },
  { surahId: 33, ayahNumber: 61, text: 'Accursed wherever they are found, [being] seized and massacred completely.' },
  { surahId: 33, ayahNumber: 62, text: '[This is] the established way of Allah with those who passed on before; and you will not find in the way of Allah any change.' },
  { surahId: 33, ayahNumber: 63, text: 'People ask you concerning the Hour. Say," Knowledge of it is only with Allah. And what may make you perceive? Perhaps the Hour is near."' },
  { surahId: 33, ayahNumber: 64, text: 'Indeed, Allah has cursed the disbelievers and prepared for them a Blaze.' },
  { surahId: 33, ayahNumber: 65, text: 'Abiding therein forever, they will not find a protector or a helper.' },
  { surahId: 33, ayahNumber: 66, text: 'The Day their faces will be turned about in the Fire, they will say, "How we wish we had obeyed Allah and obeyed the Messenger."' },
  { surahId: 33, ayahNumber: 67, text: 'And they will say, "Our Lord, indeed we obeyed our masters and our dignitaries, and they led us astray from the [right] way.' },
  { surahId: 33, ayahNumber: 68, text: 'Our Lord, give them double the punishment and curse them with a great curse."' },
  { surahId: 33, ayahNumber: 69, text: 'O you who have believed, be not like those who abused Moses; then Allah cleared him of what they said. And he, in the sight of Allah, was distinguished.' },
  { surahId: 33, ayahNumber: 70, text: 'O you who have believed, fear Allah and speak words of appropriate justice.' },
  { surahId: 33, ayahNumber: 71, text: 'He will [then] amend for you your deeds and forgive you your sins. And whoever obeys Allah and His Messenger has certainly attained a great attainment.' },
  { surahId: 33, ayahNumber: 72, text: 'Indeed, we offered the Trust to the heavens and the earth and the mountains, and they declined to bear it and feared it; but man [undertook to] bear it. Indeed, he was unjust and ignorant.' },
  { surahId: 33, ayahNumber: 73, text: '[It was] so that Allah may punish the hypocrite men and hypocrite women and the men and women who associate others with Him and that Allah may accept repentance from the believing men and believing women. And ever is Allah Forgiving and Merciful.' },
  { surahId: 34, ayahNumber: 1, text: '[All] praise is [due] to Allah, to whom belongs whatever is in the heavens and whatever is in the earth, and to Him belongs [all] praise in the Hereafter. And He is the Wise, the Acquainted.' },
  { surahId: 34, ayahNumber: 2, text: 'He knows what penetrates into the earth and what emerges from it and what descends from the heaven and what ascends therein. And He is the Merciful, the Forgiving.' },
  { surahId: 34, ayahNumber: 3, text: 'But those who disbelieve say, "The Hour will not come to us." Say, "Yes, by my Lord, it will surely come to you. [Allah is] the Knower of the unseen." Not absent from Him is an atom\'s weight within the heavens or within the earth or [what is] smaller than that or greater, except that it is in a clear register -' },
  { surahId: 34, ayahNumber: 4, text: 'That He may reward those who believe and do righteous deeds. Those will have forgiveness and noble provision.' },
  { surahId: 34, ayahNumber: 5, text: 'But those who strive against Our verses [seeking] to cause failure - for them will be a painful punishment of foul nature.' },
  { surahId: 34, ayahNumber: 6, text: 'And those who have been given knowledge see that what is revealed to you from your Lord is the truth, and it guides to the path of the Exalted in Might, the Praiseworthy.' },
  { surahId: 34, ayahNumber: 7, text: 'But those who disbelieve say, "Shall we direct you to a man who will inform you [that] when you have disintegrated in complete disintegration, you will [then] be [recreated] in a new creation?' },
  { surahId: 34, ayahNumber: 8, text: 'Has he invented about Allah a lie or is there in him madness?" Rather, they who do not believe in the Hereafter will be in the punishment and [are in] extreme error.' },
  { surahId: 34, ayahNumber: 9, text: 'Then, do they not look at what is before them and what is behind them of the heaven and earth? If We should will, We could cause the earth to swallow them or [could] let fall upon them fragments from the sky. Indeed in that is a sign for every servant turning back [to Allah].' },
  { surahId: 34, ayahNumber: 10, text: 'And We certainly gave David from Us bounty. [We said], "O mountains, repeat [Our] praises with him, and the birds [as well]." And We made pliable for him iron,' },
  { surahId: 34, ayahNumber: 11, text: '[Commanding him], "Make full coats of mail and calculate [precisely] the links, and work [all of you] righteousness. Indeed I, of what you do, am Seeing."' },
  { surahId: 34, ayahNumber: 12, text: 'And to Solomon [We subjected] the wind - its morning [journey was that of] a month - and its afternoon [journey was that of] a month, and We made flow for him a spring of [liquid] copper. And among the jinn were those who worked for him by the permission of his Lord. And whoever deviated among them from Our command - We will make him taste of the punishment of the Blaze.' },
  { surahId: 34, ayahNumber: 13, text: 'They made for him what he willed of elevated chambers, statues, bowls like reservoirs, and stationary kettles. [We said], "Work, O family of David, in gratitude." And few of My servants are grateful.' },
  { surahId: 34, ayahNumber: 14, text: 'And when We decreed for Solomon death, nothing indicated to the jinn his death except a creature of the earth eating his staff. But when he fell, it became clear to the jinn that if they had known the unseen, they would not have remained in humiliating punishment.' },
  { surahId: 34, ayahNumber: 15, text: 'There was for [the tribe of] Saba\' in their dwelling place a sign: two [fields of] gardens on the right and on the left. [They were told], "Eat from the provisions of your Lord and be grateful to Him. A good land [have you], and a forgiving Lord."' },
  { surahId: 34, ayahNumber: 16, text: 'But they turned away [refusing], so We sent upon them the flood of the dam, and We replaced their two [fields of] gardens with gardens of bitter fruit, tamarisks and something of sparse lote trees.' },
  { surahId: 34, ayahNumber: 17, text: '[By] that We repaid them because they disbelieved. And do We [thus] repay except the ungrateful?' },
  { surahId: 34, ayahNumber: 18, text: 'And We placed between them and the cities which We had blessed [many] visible cities. And We determined between them the [distances of] journey, [saying], "Travel between them by night or day in safety."' },
  { surahId: 34, ayahNumber: 19, text: 'But [insolently] they said, "Our Lord, lengthen the distance between our journeys," and wronged themselves, so We made them narrations and dispersed them in total dispersion. Indeed in that are signs for everyone patient and grateful.' },
  { surahId: 34, ayahNumber: 20, text: 'And Iblees had already confirmed through them his assumption, so they followed him, except for a party of believers.' },
  { surahId: 34, ayahNumber: 21, text: 'And he had over them no authority except [it was decreed] that We might make evident who believes in the Hereafter from who is thereof in doubt. And your Lord, over all things, is Guardian.' },
  { surahId: 34, ayahNumber: 22, text: 'Say, [O Muhammad], "Invoke those you claim [as deities] besides Allah." They do not possess an atom\'s weight [of ability] in the heavens or on the earth, and they do not have therein any partnership [with Him], nor is there for Him from among them any assistant.' },
  { surahId: 34, ayahNumber: 23, text: 'And intercession does not benefit with Him except for one whom He permits. [And those wait] until, when terror is removed from their hearts, they will say [to one another], "What has your Lord said?" They will say, "The truth." And He is the Most High, the Grand.' },
  { surahId: 34, ayahNumber: 24, text: 'Say, "Who provides for you from the heavens and the earth?" Say, "Allah. And indeed, we or you are either upon guidance or in clear error."' },
  { surahId: 34, ayahNumber: 25, text: 'Say, "You will not be asked about what we committed, and we will not be asked about what you do."' },
  { surahId: 34, ayahNumber: 26, text: 'Say, "Our Lord will bring us together; then He will judge between us in truth. And He is the Knowing Judge."' },
  { surahId: 34, ayahNumber: 27, text: 'Say, "Show me those whom you have attached to Him as partners. No! Rather, He [alone] is Allah, the Exalted in Might, the Wise."' },
  { surahId: 34, ayahNumber: 28, text: 'And We have not sent you except comprehensively to mankind as a bringer of good tidings and a warner. But most of the people do not know.' },
  { surahId: 34, ayahNumber: 29, text: 'And they say, "When is this promise, if you should be truthful?"' },
  { surahId: 34, ayahNumber: 30, text: 'Say, "For you is the appointment of a Day [when] you will not remain thereafter an hour, nor will you precede [it]."' },
  { surahId: 34, ayahNumber: 31, text: 'And those who disbelieve say, "We will never believe in this Qur\'an nor in that before it." But if you could see when the wrongdoers are made to stand before their Lord, refuting each other\'s words... Those who were oppressed will say to those who were arrogant, "If not for you, we would have been believers."' },
  { surahId: 34, ayahNumber: 32, text: 'Those who were arrogant will say to those who were oppressed, "Did we avert you from guidance after it had come to you? Rather, you were criminals."' },
  { surahId: 34, ayahNumber: 33, text: 'Those who were oppressed will say to those who were arrogant, "Rather, [it was your] conspiracy of night and day when you were ordering us to disbelieve in Allah and attribute to Him equals." But they will [all] confide regret when they see the punishment; and We will put shackles on the necks of those who disbelieved. Will they be recompensed except for what they used to do?' },
  { surahId: 34, ayahNumber: 34, text: 'And We did not send into a city any warner except that its affluent said, "Indeed we, in that with which you were sent, are disbelievers."' },
  { surahId: 34, ayahNumber: 35, text: 'And they said, "We are more [than the believers] in wealth and children, and we are not to be punished."' },
  { surahId: 34, ayahNumber: 36, text: 'Say, "Indeed, my Lord extends provision for whom He wills and restricts [it], but most of the people do not know."' },
  { surahId: 34, ayahNumber: 37, text: 'And it is not your wealth or your children that bring you nearer to Us in position, but it is [by being] one who has believed and done righteousness. For them there will be the double reward for what they did, and they will be in the upper chambers [of Paradise], safe [and secure].' },
  { surahId: 34, ayahNumber: 38, text: 'And the ones who strive against Our verses to cause [them] failure - those will be brought into the punishment [to remain].' },
  { surahId: 34, ayahNumber: 39, text: 'Say, "Indeed, my Lord extends provision for whom He wills of His servants and restricts [it] for him. But whatever thing you spend [in His cause] - He will compensate it; and He is the best of providers."' },
  { surahId: 34, ayahNumber: 40, text: 'And [mention] the Day when He will gather them all and then say to the angels, "Did these [people] used to worship you?"' },
  { surahId: 34, ayahNumber: 41, text: 'They will say, "Exalted are You! You, [O Allah], are our benefactor not them. Rather, they used to worship the jinn; most of them were believers in them."' },
  { surahId: 34, ayahNumber: 42, text: 'But today you do not hold for one another [the power of] benefit or harm, and We will say to those who wronged, "Taste the punishment of the Fire, which you used to deny."' },
  { surahId: 34, ayahNumber: 43, text: 'And when our verses are recited to them as clear evidences, they say, "This is not but a man who wishes to avert you from that which your fathers were worshipping." And they say, "This is not except a lie invented." And those who disbelieve say of the truth when it has come to them, "This is not but obvious magic."' },
  { surahId: 34, ayahNumber: 44, text: 'And We had not given them any scriptures which they could study, and We had not sent to them before you, [O Muhammad], any warner.' },
  { surahId: 34, ayahNumber: 45, text: 'And those before them denied, and the people of Makkah have not attained a tenth of what We had given them. But the former peoples denied My messengers, so how [terrible] was My reproach.' },
  { surahId: 34, ayahNumber: 46, text: 'Say, "I only advise you of one [thing] - that you stand for Allah, [seeking truth] in pairs and individually, and then give thought." There is not in your companion any madness. He is only a warner to you before a severe punishment.' },
  { surahId: 34, ayahNumber: 47, text: 'Say, "Whatever payment I might have asked of you - it is yours. My payment is only from Allah, and He is, over all things, Witness."' },
  { surahId: 34, ayahNumber: 48, text: 'Say, "Indeed, my Lord projects the truth. Knower of the unseen."' },
  { surahId: 34, ayahNumber: 49, text: 'Say, "The truth has come, and falsehood can neither begin [anything] nor repeat [it]."' },
  { surahId: 34, ayahNumber: 50, text: 'Say, "If I should err, I would only err against myself. But if I am guided, it is by what my Lord reveals to me. Indeed, He is Hearing and near."' },
  { surahId: 34, ayahNumber: 51, text: 'And if you could see when they are terrified but there is no escape, and they will be seized from a place nearby.' },
  { surahId: 34, ayahNumber: 52, text: 'And they will [then] say, "We believe in it!" But how for them will be the taking [of faith] from a place far away?' },
  { surahId: 34, ayahNumber: 53, text: 'And they had already disbelieved in it before and would assault the unseen from a place far away.' },
  { surahId: 34, ayahNumber: 54, text: 'And prevention will be placed between them and what they desire, as was done with their kind before. Indeed, they were in disquieting denial.' },
  { surahId: 35, ayahNumber: 1, text: '[All] praise is [due] to Allah, Creator of the heavens and the earth, [who] made the angels messengers having wings, two or three or four. He increases in creation what He wills. Indeed, Allah is over all things competent.' },
  { surahId: 35, ayahNumber: 2, text: 'Whatever Allah grants to people of mercy - none can withhold it; and whatever He withholds - none can release it thereafter. And He is the Exalted in Might, the Wise.' },
  { surahId: 35, ayahNumber: 3, text: 'O mankind, remember the favor of Allah upon you. Is there any creator other than Allah who provides for you from the heaven and earth? There is no deity except Him, so how are you deluded?' },
  { surahId: 35, ayahNumber: 4, text: 'And if they deny you, [O Muhammad] - already were messengers denied before you. And to Allah are returned [all] matters.' },
  { surahId: 35, ayahNumber: 5, text: 'O mankind, indeed the promise of Allah is truth, so let not the worldly life delude you and be not deceived about Allah by the Deceiver.' },
  { surahId: 35, ayahNumber: 6, text: 'Indeed, Satan is an enemy to you; so take him as an enemy. He only invites his party to be among the companions of the Blaze.' },
  { surahId: 35, ayahNumber: 7, text: 'Those who disbelieve will have a severe punishment, and those who believe and do righteous deeds will have forgiveness and great reward.' },
  { surahId: 35, ayahNumber: 8, text: 'Then is one to whom the evil of his deed has been made attractive so he considers it good [like one rightly guided]? For indeed, Allah sends astray whom He wills and guides whom He wills. So do not let yourself perish over them in regret. Indeed, Allah is Knowing of what they do.' },
  { surahId: 35, ayahNumber: 9, text: 'And it is Allah who sends the winds, and they stir the clouds, and We drive them to a dead land and give life thereby to the earth after its lifelessness. Thus is the resurrection.' },
  { surahId: 35, ayahNumber: 10, text: 'Whoever desires honor [through power] - then to Allah belongs all honor. To Him ascends good speech, and righteous work raises it. But they who plot evil deeds will have a severe punishment, and the plotting of those - it will perish.' },
  { surahId: 35, ayahNumber: 11, text: 'And Allah created you from dust, then from a sperm-drop; then He made you mates. And no female conceives nor does she give birth except with His knowledge. And no aged person is granted [additional] life nor is his lifespan lessened but that it is in a register. Indeed, that for Allah is easy.' },
  { surahId: 35, ayahNumber: 12, text: 'And not alike are the two bodies of water. One is fresh and sweet, palatable for drinking, and one is salty and bitter. And from each you eat tender meat and extract ornaments which you wear, and you see the ships plowing through [them] that you might seek of His bounty; and perhaps you will be grateful.' },
  { surahId: 35, ayahNumber: 13, text: 'He causes the night to enter the day, and He causes the day to enter the night and has subjected the sun and the moon - each running [its course] for a specified term. That is Allah, your Lord; to Him belongs sovereignty. And those whom you invoke other than Him do not possess [as much as] the membrane of a date seed.' },
  { surahId: 35, ayahNumber: 14, text: 'If you invoke them, they do not hear your supplication; and if they heard, they would not respond to you. And on the Day of Resurrection they will deny your association. And none can inform you like [one] Acquainted [with all matters].' },
  { surahId: 35, ayahNumber: 15, text: 'O mankind, you are those in need of Allah, while Allah is the Free of need, the Praiseworthy.' },
  { surahId: 35, ayahNumber: 16, text: 'If He wills, He can do away with you and bring forth a new creation.' },
  { surahId: 35, ayahNumber: 17, text: 'And that is for Allah not difficult.' },
  { surahId: 35, ayahNumber: 18, text: 'And no bearer of burdens will bear the burden of another. And if a heavily laden soul calls [another] to [carry some of] its load, nothing of it will be carried, even if he should be a close relative. You can only warn those who fear their Lord unseen and have established prayer. And whoever purifies himself only purifies himself for [the benefit of] his soul. And to Allah is the [final] destination.' },
  { surahId: 35, ayahNumber: 19, text: 'Not equal are the blind and the seeing,' },
  { surahId: 35, ayahNumber: 20, text: 'Nor are the darknesses and the light,' },
  { surahId: 35, ayahNumber: 21, text: 'Nor are the shade and the heat,' },
  { surahId: 35, ayahNumber: 22, text: 'And not equal are the living and the dead. Indeed, Allah causes to hear whom He wills, but you cannot make hear those in the graves.' },
  { surahId: 35, ayahNumber: 23, text: 'You, [O Muhammad], are not but a warner.' },
  { surahId: 35, ayahNumber: 24, text: 'Indeed, We have sent you with the truth as a bringer of good tidings and a warner. And there was no nation but that there had passed within it a warner.' },
  { surahId: 35, ayahNumber: 25, text: 'And if they deny you - then already have those before them denied. Their messengers came to them with clear proofs and written ordinances and with the enlightening Scripture.' },
  { surahId: 35, ayahNumber: 26, text: 'Then I seized the ones who disbelieved, and how [terrible] was My reproach.' },
  { surahId: 35, ayahNumber: 27, text: 'Do you not see that Allah sends down rain from the sky, and We produce thereby fruits of varying colors? And in the mountains are tracts, white and red of varying shades and [some] extremely black.' },
  { surahId: 35, ayahNumber: 28, text: 'And among people and moving creatures and grazing livestock are various colors similarly. Only those fear Allah, from among His servants, who have knowledge. Indeed, Allah is Exalted in Might and Forgiving.' },
  { surahId: 35, ayahNumber: 29, text: 'Indeed, those who recite the Book of Allah and establish prayer and spend [in His cause] out of what We have provided them, secretly and publicly, [can] expect a profit that will never perish -' },
  { surahId: 35, ayahNumber: 30, text: 'That He may give them in full their rewards and increase for them of His bounty. Indeed, He is Forgiving and Appreciative.' },
  { surahId: 35, ayahNumber: 31, text: 'And that which We have revealed to you, [O Muhammad], of the Book is the truth, confirming what was before it. Indeed, Allah, of His servants, is Acquainted and Seeing.' },
  { surahId: 35, ayahNumber: 32, text: 'Then we caused to inherit the Book those We have chosen of Our servants; and among them is he who wrongs himself, and among them is he who is moderate, and among them is he who is foremost in good deeds by permission of Allah. That [inheritance] is what is the great bounty.' },
  { surahId: 35, ayahNumber: 33, text: '[For them are] gardens of perpetual residence which they will enter. They will be adorned therein with bracelets of gold and pearls, and their garments therein will be silk.' },
  { surahId: 35, ayahNumber: 34, text: 'And they will say, "Praise to Allah, who has removed from us [all] sorrow. Indeed, our Lord is Forgiving and Appreciative -' },
  { surahId: 35, ayahNumber: 35, text: 'He who has settled us in the home of duration out of His bounty. There touches us not in it any fatigue, and there touches us not in it weariness [of mind]."' },
  { surahId: 35, ayahNumber: 36, text: 'And for those who disbelieve will be the fire of Hell. [Death] is not decreed for them so they may die, nor will its torment be lightened for them. Thus do we recompense every ungrateful one.' },
  { surahId: 35, ayahNumber: 37, text: 'And they will cry out therein, "Our Lord, remove us; we will do righteousness - other than what we were doing!" But did We not grant you life enough for whoever would remember therein to remember, and the warner had come to you? So taste [the punishment], for there is not for the wrongdoers any helper.' },
  { surahId: 35, ayahNumber: 38, text: 'Indeed, Allah is Knower of the unseen [aspects] of the heavens and earth. Indeed, He is Knowing of that within the breasts.' },
  { surahId: 35, ayahNumber: 39, text: 'It is He who has made you successors upon the earth. And whoever disbelieves - upon him will be [the consequence of] his disbelief. And the disbelief of the disbelievers does not increase them in the sight of their Lord except in hatred; and the disbelief of the disbelievers does not increase them except in loss.' },
  { surahId: 35, ayahNumber: 40, text: 'Say, "Have you considered your \'partners\' whom you invoke besides Allah? Show me what they have created from the earth, or have they partnership [with Him] in the heavens? Or have We given them a book so they are [standing] on evidence therefrom? [No], rather, the wrongdoers do not promise each other except delusion."' },
  { surahId: 35, ayahNumber: 41, text: 'Indeed, Allah holds the heavens and the earth, lest they cease. And if they should cease, no one could hold them [in place] after Him. Indeed, He is Forbearing and Forgiving.' },
  { surahId: 35, ayahNumber: 42, text: 'And they swore by Allah their strongest oaths that if a warner came to them, they would be more guided than [any] one of the [previous] nations. But when a warner came to them, it did not increase them except in aversion.' },
  { surahId: 35, ayahNumber: 43, text: '[Due to] arrogance in the land and plotting of evil; but the evil plot does not encompass except its own people. Then do they await except the way of the former peoples? But you will never find in the way of Allah any change, and you will never find in the way of Allah any alteration.' },
  { surahId: 35, ayahNumber: 44, text: 'Have they not traveled through the land and observed how was the end of those before them? And they were greater than them in power. But Allah is not to be caused failure by anything in the heavens or on the earth. Indeed, He is ever Knowing and Competent.' },
  { surahId: 35, ayahNumber: 45, text: 'And if Allah were to impose blame on the people for what they have earned, He would not leave upon the earth any creature. But He defers them for a specified term. And when their time comes, then indeed Allah has ever been, of His servants, Seeing.' },
  { surahId: 36, ayahNumber: 1, text: 'Ya, Seen.' },
  { surahId: 36, ayahNumber: 2, text: 'By the wise Qur\'an.' },
  { surahId: 36, ayahNumber: 3, text: 'Indeed you, [O Muhammad], are from among the messengers,' },
  { surahId: 36, ayahNumber: 4, text: 'On a straight path.' },
  { surahId: 36, ayahNumber: 5, text: '[This is] a revelation of the Exalted in Might, the Merciful,' },
  { surahId: 36, ayahNumber: 6, text: 'That you may warn a people whose forefathers were not warned, so they are unaware.' },
  { surahId: 36, ayahNumber: 7, text: 'Already the word has come into effect upon most of them, so they do not believe.' },
  { surahId: 36, ayahNumber: 8, text: 'Indeed, We have put shackles on their necks, and they are to their chins, so they are with heads [kept] aloft.' },
  { surahId: 36, ayahNumber: 9, text: 'And We have put before them a barrier and behind them a barrier and covered them, so they do not see.' },
  { surahId: 36, ayahNumber: 10, text: 'And it is all the same for them whether you warn them or do not warn them - they will not believe.' },
  { surahId: 36, ayahNumber: 11, text: 'You can only warn one who follows the message and fears the Most Merciful unseen. So give him good tidings of forgiveness and noble reward.' },
  { surahId: 36, ayahNumber: 12, text: 'Indeed, it is We who bring the dead to life and record what they have put forth and what they left behind, and all things We have enumerated in a clear register.' },
  { surahId: 36, ayahNumber: 13, text: 'And present to them an example: the people of the city, when the messengers came to it -' },
  { surahId: 36, ayahNumber: 14, text: 'When We sent to them two but they denied them, so We strengthened them with a third, and they said, "Indeed, we are messengers to you."' },
  { surahId: 36, ayahNumber: 15, text: 'They said, "You are not but human beings like us, and the Most Merciful has not revealed a thing. You are only telling lies."' },
  { surahId: 36, ayahNumber: 16, text: 'They said, "Our Lord knows that we are messengers to you,' },
  { surahId: 36, ayahNumber: 17, text: 'And we are not responsible except for clear notification."' },
  { surahId: 36, ayahNumber: 18, text: 'They said, "Indeed, we consider you a bad omen. If you do not desist, we will surely stone you, and there will surely touch you, from us, a painful punishment."' },
  { surahId: 36, ayahNumber: 19, text: 'They said, "Your omen is with yourselves. Is it because you were reminded? Rather, you are a transgressing people."' },
  { surahId: 36, ayahNumber: 20, text: 'And there came from the farthest end of the city a man, running. He said, "O my people, follow the messengers.' },
  { surahId: 36, ayahNumber: 21, text: 'Follow those who do not ask of you [any] payment, and they are [rightly] guided.' },
  { surahId: 36, ayahNumber: 22, text: 'And why should I not worship He who created me and to whom you will be returned?' },
  { surahId: 36, ayahNumber: 23, text: 'Should I take other than Him [false] deities [while], if the Most Merciful intends for me some adversity, their intercession will not avail me at all, nor can they save me?' },
  { surahId: 36, ayahNumber: 24, text: 'Indeed, I would then be in manifest error.' },
  { surahId: 36, ayahNumber: 25, text: 'Indeed, I have believed in your Lord, so listen to me."' },
  { surahId: 36, ayahNumber: 26, text: 'It was said, "Enter Paradise." He said, "I wish my people could know' },
  { surahId: 36, ayahNumber: 27, text: 'Of how my Lord has forgiven me and placed me among the honored."' },
  { surahId: 36, ayahNumber: 28, text: 'And We did not send down upon his people after him any soldiers from the heaven, nor would We have done so.' },
  { surahId: 36, ayahNumber: 29, text: 'It was not but one shout, and immediately they were extinguished.' },
  { surahId: 36, ayahNumber: 30, text: 'How regretful for the servants. There did not come to them any messenger except that they used to ridicule him.' },
  { surahId: 36, ayahNumber: 31, text: 'Have they not considered how many generations We destroyed before them - that they to them will not return?' },
  { surahId: 36, ayahNumber: 32, text: 'And indeed, all of them will yet be brought present before Us.' },
  { surahId: 36, ayahNumber: 33, text: 'And a sign for them is the dead earth. We have brought it to life and brought forth from it grain, and from it they eat.' },
  { surahId: 36, ayahNumber: 34, text: 'And We placed therein gardens of palm trees and grapevines and caused to burst forth therefrom some springs -' },
  { surahId: 36, ayahNumber: 35, text: 'That they may eat of His fruit. And their hands have not produced it, so will they not be grateful?' },
  { surahId: 36, ayahNumber: 36, text: 'Exalted is He who created all pairs - from what the earth grows and from themselves and from that which they do not know.' },
  { surahId: 36, ayahNumber: 37, text: 'And a sign for them is the night. We remove from it [the light of] day, so they are [left] in darkness.' },
  { surahId: 36, ayahNumber: 38, text: 'And the sun runs [on course] toward its stopping point. That is the determination of the Exalted in Might, the Knowing.' },
  { surahId: 36, ayahNumber: 39, text: 'And the moon - We have determined for it phases, until it returns [appearing] like the old date stalk.' },
  { surahId: 36, ayahNumber: 40, text: 'It is not allowable for the sun to reach the moon, nor does the night overtake the day, but each, in an orbit, is swimming.' },
  { surahId: 36, ayahNumber: 41, text: 'And a sign for them is that We carried their forefathers in a laden ship.' },
  { surahId: 36, ayahNumber: 42, text: 'And We created for them from the likes of it that which they ride.' },
  { surahId: 36, ayahNumber: 43, text: 'And if We should will, We could drown them; then no one responding to a cry would there be for them, nor would they be saved' },
  { surahId: 36, ayahNumber: 44, text: 'Except as a mercy from Us and provision for a time.' },
  { surahId: 36, ayahNumber: 45, text: 'But when it is said to them, "Beware of what is before you and what is behind you; perhaps you will receive mercy... "' },
  { surahId: 36, ayahNumber: 46, text: 'And no sign comes to them from the signs of their Lord except that they are from it turning away.' },
  { surahId: 36, ayahNumber: 47, text: 'And when it is said to them, "Spend from that which Allah has provided for you," those who disbelieve say to those who believe, "Should we feed one whom, if Allah had willed, He would have fed? You are not but in clear error."' },
  { surahId: 36, ayahNumber: 48, text: 'And they say, "When is this promise, if you should be truthful?"' },
  { surahId: 36, ayahNumber: 49, text: 'They do not await except one blast which will seize them while they are disputing.' },
  { surahId: 36, ayahNumber: 50, text: 'And they will not be able [to give] any instruction, nor to their people can they return.' },
  { surahId: 36, ayahNumber: 51, text: 'And the Horn will be blown; and at once from the graves to their Lord they will hasten.' },
  { surahId: 36, ayahNumber: 52, text: 'They will say, "O woe to us! Who has raised us up from our sleeping place?" [The reply will be], "This is what the Most Merciful had promised, and the messengers told the truth."' },
  { surahId: 36, ayahNumber: 53, text: 'It will not be but one blast, and at once they are all brought present before Us.' },
  { surahId: 36, ayahNumber: 54, text: 'So today no soul will be wronged at all, and you will not be recompensed except for what you used to do.' },
  { surahId: 36, ayahNumber: 55, text: 'Indeed the companions of Paradise, that Day, will be amused in [joyful] occupation -' },
  { surahId: 36, ayahNumber: 56, text: 'They and their spouses - in shade, reclining on adorned couches.' },
  { surahId: 36, ayahNumber: 57, text: 'For them therein is fruit, and for them is whatever they request [or wish]' },
  { surahId: 36, ayahNumber: 58, text: '[And] "Peace," a word from a Merciful Lord.' },
  { surahId: 36, ayahNumber: 59, text: '[Then He will say], "But stand apart today, you criminals.' },
  { surahId: 36, ayahNumber: 60, text: 'Did I not enjoin upon you, O children of Adam, that you not worship Satan - [for] indeed, he is to you a clear enemy -' },
  { surahId: 36, ayahNumber: 61, text: 'And that you worship [only] Me? This is a straight path.' },
  { surahId: 36, ayahNumber: 62, text: 'And he had already led astray from among you much of creation, so did you not use reason?' },
  { surahId: 36, ayahNumber: 63, text: 'This is the Hellfire which you were promised.' },
  { surahId: 36, ayahNumber: 64, text: '[Enter to] burn therein today for what you used to deny."' },
  { surahId: 36, ayahNumber: 65, text: 'That Day, We will seal over their mouths, and their hands will speak to Us, and their feet will testify about what they used to earn.' },
  { surahId: 36, ayahNumber: 66, text: 'And if We willed, We could have obliterated their eyes, and they would race to [find] the path, and how could they see?' },
  { surahId: 36, ayahNumber: 67, text: 'And if We willed, We could have deformed them, [paralyzing them] in their places so they would not be able to proceed, nor could they return.' },
  { surahId: 36, ayahNumber: 68, text: 'And he to whom We grant long life We reverse in creation; so will they not understand?' },
  { surahId: 36, ayahNumber: 69, text: 'And We did not give Prophet Muhammad, knowledge of poetry, nor is it befitting for him. It is not but a message and a clear Qur\'an' },
  { surahId: 36, ayahNumber: 70, text: 'To warn whoever is alive and justify the word against the disbelievers.' },
  { surahId: 36, ayahNumber: 71, text: 'Do they not see that We have created for them from what Our hands have made, grazing livestock, and [then] they are their owners?' },
  { surahId: 36, ayahNumber: 72, text: 'And We have tamed them for them, so some of them they ride, and some of them they eat.' },
  { surahId: 36, ayahNumber: 73, text: 'And for them therein are [other] benefits and drinks, so will they not be grateful?' },
  { surahId: 36, ayahNumber: 74, text: 'But they have taken besides Allah [false] deities that perhaps they would be helped.' },
  { surahId: 36, ayahNumber: 75, text: 'They are not able to help them, and they [themselves] are for them soldiers in attendance.' },
  { surahId: 36, ayahNumber: 76, text: 'So let not their speech grieve you. Indeed, We know what they conceal and what they declare.' },
  { surahId: 36, ayahNumber: 77, text: 'Does man not consider that We created him from a [mere] sperm-drop - then at once he is a clear adversary?' },
  { surahId: 36, ayahNumber: 78, text: 'And he presents for Us an example and forgets his [own] creation. He says, "Who will give life to bones while they are disintegrated?"' },
  { surahId: 36, ayahNumber: 79, text: 'Say, "He will give them life who produced them the first time; and He is, of all creation, Knowing."' },
  { surahId: 36, ayahNumber: 80, text: '[It is] He who made for you from the green tree, fire, and then from it you ignite.' },
  { surahId: 36, ayahNumber: 81, text: 'Is not He who created the heavens and the earth Able to create the likes of them? Yes, [it is so]; and He is the Knowing Creator.' },
  { surahId: 36, ayahNumber: 82, text: 'His command is only when He intends a thing that He says to it, "Be," and it is.' },
  { surahId: 36, ayahNumber: 83, text: 'So exalted is He in whose hand is the realm of all things, and to Him you will be returned.' },
  { surahId: 37, ayahNumber: 1, text: 'By those [angels] lined up in rows' },
  { surahId: 37, ayahNumber: 2, text: 'And those who drive [the clouds]' },
  { surahId: 37, ayahNumber: 3, text: 'And those who recite the message,' },
  { surahId: 37, ayahNumber: 4, text: 'Indeed, your God is One,' },
  { surahId: 37, ayahNumber: 5, text: 'Lord of the heavens and the earth and that between them and Lord of the sunrises.' },
  { surahId: 37, ayahNumber: 6, text: 'Indeed, We have adorned the nearest heaven with an adornment of stars' },
  { surahId: 37, ayahNumber: 7, text: 'And as protection against every rebellious devil' },
  { surahId: 37, ayahNumber: 8, text: '[So] they may not listen to the exalted assembly [of angels] and are pelted from every side,' },
  { surahId: 37, ayahNumber: 9, text: 'Repelled; and for them is a constant punishment,' },
  { surahId: 37, ayahNumber: 10, text: 'Except one who snatches [some words] by theft, but they are pursued by a burning flame, piercing [in brightness].' },
  { surahId: 37, ayahNumber: 11, text: 'Then inquire of them, [O Muhammad], "Are they a stronger [or more difficult] creation or those [others] We have created?" Indeed, We created men from sticky clay.' },
  { surahId: 37, ayahNumber: 12, text: 'But you wonder, while they mock,' },
  { surahId: 37, ayahNumber: 13, text: 'And when they are reminded, they remember not.' },
  { surahId: 37, ayahNumber: 14, text: 'And when they see a sign, they ridicule' },
  { surahId: 37, ayahNumber: 15, text: 'And say, "This is not but obvious magic.' },
  { surahId: 37, ayahNumber: 16, text: 'When we have died and become dust and bones, are we indeed to be resurrected?' },
  { surahId: 37, ayahNumber: 17, text: 'And our forefathers [as well]?"' },
  { surahId: 37, ayahNumber: 18, text: 'Say, "Yes, and you will be [rendered] contemptible."' },
  { surahId: 37, ayahNumber: 19, text: 'It will be only one shout, and at once they will be observing.' },
  { surahId: 37, ayahNumber: 20, text: 'They will say, "O woe to us! This is the Day of Recompense."' },
  { surahId: 37, ayahNumber: 21, text: '[They will be told], "This is the Day of Judgement which you used to deny."' },
  { surahId: 37, ayahNumber: 22, text: '[The angels will be ordered], "Gather those who committed wrong, their kinds, and what they used to worship' },
  { surahId: 37, ayahNumber: 23, text: 'Other than Allah, and guide them to the path of Hellfire' },
  { surahId: 37, ayahNumber: 24, text: 'And stop them; indeed, they are to be questioned."' },
  { surahId: 37, ayahNumber: 25, text: '[They will be asked], "What is [wrong] with you? Why do you not help each other?"' },
  { surahId: 37, ayahNumber: 26, text: 'But they, that Day, are in surrender.' },
  { surahId: 37, ayahNumber: 27, text: 'And they will approach one another blaming each other.' },
  { surahId: 37, ayahNumber: 28, text: 'They will say, "Indeed, you used to come at us from the right."' },
  { surahId: 37, ayahNumber: 29, text: 'The oppressors will say, "Rather, you [yourselves] were not believers,' },
  { surahId: 37, ayahNumber: 30, text: 'And we had over you no authority, but you were a transgressing people.' },
  { surahId: 37, ayahNumber: 31, text: 'So the word of our Lord has come into effect upon us; indeed, we will taste [punishment].' },
  { surahId: 37, ayahNumber: 32, text: 'And we led you to deviation; indeed, we were deviators."' },
  { surahId: 37, ayahNumber: 33, text: 'So indeed they, that Day, will be sharing in the punishment.' },
  { surahId: 37, ayahNumber: 34, text: 'Indeed, that is how We deal with the criminals.' },
  { surahId: 37, ayahNumber: 35, text: 'Indeed they, when it was said to them, "There is no deity but Allah," were arrogant' },
  { surahId: 37, ayahNumber: 36, text: 'And were saying, "Are we to leave our gods for a mad poet?"' },
  { surahId: 37, ayahNumber: 37, text: 'Rather, the Prophet has come with the truth and confirmed the [previous] messengers.' },
  { surahId: 37, ayahNumber: 38, text: 'Indeed, you [disbelievers] will be tasters of the painful punishment,' },
  { surahId: 37, ayahNumber: 39, text: 'And you will not be recompensed except for what you used to do -' },
  { surahId: 37, ayahNumber: 40, text: 'But not the chosen servants of Allah.' },
  { surahId: 37, ayahNumber: 41, text: 'Those will have a provision determined -' },
  { surahId: 37, ayahNumber: 42, text: 'Fruits; and they will be honored' },
  { surahId: 37, ayahNumber: 43, text: 'In gardens of pleasure' },
  { surahId: 37, ayahNumber: 44, text: 'On thrones facing one another.' },
  { surahId: 37, ayahNumber: 45, text: 'There will be circulated among them a cup [of wine] from a flowing spring,' },
  { surahId: 37, ayahNumber: 46, text: 'White and delicious to the drinkers;' },
  { surahId: 37, ayahNumber: 47, text: 'No bad effect is there in it, nor from it will they be intoxicated.' },
  { surahId: 37, ayahNumber: 48, text: 'And with them will be women limiting [their] glances, with large, [beautiful] eyes,' },
  { surahId: 37, ayahNumber: 49, text: 'As if they were [delicate] eggs, well-protected.' },
  { surahId: 37, ayahNumber: 50, text: 'And they will approach one another, inquiring of each other.' },
  { surahId: 37, ayahNumber: 51, text: 'A speaker among them will say, "Indeed, I had a companion [on earth]' },
  { surahId: 37, ayahNumber: 52, text: 'Who would say, \'Are you indeed of those who believe' },
  { surahId: 37, ayahNumber: 53, text: 'That when we have died and become dust and bones, we will indeed be recompensed?\'"' },
  { surahId: 37, ayahNumber: 54, text: 'He will say, "Would you [care to] look?"' },
  { surahId: 37, ayahNumber: 55, text: 'And he will look and see him in the midst of the Hellfire.' },
  { surahId: 37, ayahNumber: 56, text: 'He will say, "By Allah, you almost ruined me.' },
  { surahId: 37, ayahNumber: 57, text: 'If not for the favor of my Lord, I would have been of those brought in [to Hell].' },
  { surahId: 37, ayahNumber: 58, text: 'Then, are we not to die' },
  { surahId: 37, ayahNumber: 59, text: 'Except for our first death, and we will not be punished?"' },
  { surahId: 37, ayahNumber: 60, text: 'Indeed, this is the great attainment.' },
  { surahId: 37, ayahNumber: 61, text: 'For the like of this let the workers [on earth] work.' },
  { surahId: 37, ayahNumber: 62, text: 'Is Paradise a better accommodation or the tree of zaqqum?' },
  { surahId: 37, ayahNumber: 63, text: 'Indeed, We have made it a torment for the wrongdoers.' },
  { surahId: 37, ayahNumber: 64, text: 'Indeed, it is a tree issuing from the bottom of the Hellfire,' },
  { surahId: 37, ayahNumber: 65, text: 'Its emerging fruit as if it was heads of the devils.' },
  { surahId: 37, ayahNumber: 66, text: 'And indeed, they will eat from it and fill with it their bellies.' },
  { surahId: 37, ayahNumber: 67, text: 'Then indeed, they will have after it a mixture of scalding water.' },
  { surahId: 37, ayahNumber: 68, text: 'Then indeed, their return will be to the Hellfire.' },
  { surahId: 37, ayahNumber: 69, text: 'Indeed they found their fathers astray.' },
  { surahId: 37, ayahNumber: 70, text: 'So they hastened [to follow] in their footsteps.' },
  { surahId: 37, ayahNumber: 71, text: 'And there had already strayed before them most of the former peoples,' },
  { surahId: 37, ayahNumber: 72, text: 'And We had already sent among them warners.' },
  { surahId: 37, ayahNumber: 73, text: 'Then look how was the end of those who were warned -' },
  { surahId: 37, ayahNumber: 74, text: 'But not the chosen servants of Allah.' },
  { surahId: 37, ayahNumber: 75, text: 'And Noah had certainly called Us, and [We are] the best of responders.' },
  { surahId: 37, ayahNumber: 76, text: 'And We saved him and his family from the great affliction.' },
  { surahId: 37, ayahNumber: 77, text: 'And We made his descendants those remaining [on the earth]' },
  { surahId: 37, ayahNumber: 78, text: 'And left for him [favorable mention] among later generations:' },
  { surahId: 37, ayahNumber: 79, text: '"Peace upon Noah among the worlds."' },
  { surahId: 37, ayahNumber: 80, text: 'Indeed, We thus reward the doers of good.' },
  { surahId: 37, ayahNumber: 81, text: 'Indeed, he was of Our believing servants.' },
  { surahId: 37, ayahNumber: 82, text: 'Then We drowned the disbelievers.' },
  { surahId: 37, ayahNumber: 83, text: 'And indeed, among his kind was Abraham,' },
  { surahId: 37, ayahNumber: 84, text: 'When he came to his Lord with a sound heart' },
  { surahId: 37, ayahNumber: 85, text: '[And] when he said to his father and his people, "What do you worship?' },
  { surahId: 37, ayahNumber: 86, text: 'Is it falsehood [as] gods other than Allah you desire?' },
  { surahId: 37, ayahNumber: 87, text: 'Then what is your thought about the Lord of the worlds?"' },
  { surahId: 37, ayahNumber: 88, text: 'And he cast a look at the stars' },
  { surahId: 37, ayahNumber: 89, text: 'And said, "Indeed, I am [about to be] ill."' },
  { surahId: 37, ayahNumber: 90, text: 'So they turned away from him, departing.' },
  { surahId: 37, ayahNumber: 91, text: 'Then he turned to their gods and said, "Do you not eat?' },
  { surahId: 37, ayahNumber: 92, text: 'What is [wrong] with you that you do not speak?"' },
  { surahId: 37, ayahNumber: 93, text: 'And he turned upon them a blow with [his] right hand.' },
  { surahId: 37, ayahNumber: 94, text: 'Then the people came toward him, hastening.' },
  { surahId: 37, ayahNumber: 95, text: 'He said, "Do you worship that which you [yourselves] carve,' },
  { surahId: 37, ayahNumber: 96, text: 'While Allah created you and that which you do?"' },
  { surahId: 37, ayahNumber: 97, text: 'They said, "Construct for him a furnace and throw him into the burning fire."' },
  { surahId: 37, ayahNumber: 98, text: 'And they intended for him a plan, but We made them the most debased.' },
  { surahId: 37, ayahNumber: 99, text: 'And [then] he said, "Indeed, I will go to [where I am ordered by] my Lord; He will guide me.' },
  { surahId: 37, ayahNumber: 100, text: 'My Lord, grant me [a child] from among the righteous."' },
  { surahId: 37, ayahNumber: 101, text: 'So We gave him good tidings of a forbearing boy.' },
  { surahId: 37, ayahNumber: 102, text: 'And when he reached with him [the age of] exertion, he said, "O my son, indeed I have seen in a dream that I [must] sacrifice you, so see what you think." He said, "O my father, do as you are commanded. You will find me, if Allah wills, of the steadfast."' },
  { surahId: 37, ayahNumber: 103, text: 'And when they had both submitted and he put him down upon his forehead,' },
  { surahId: 37, ayahNumber: 104, text: 'We called to him, "O Abraham,' },
  { surahId: 37, ayahNumber: 105, text: 'You have fulfilled the vision." Indeed, We thus reward the doers of good.' },
  { surahId: 37, ayahNumber: 106, text: 'Indeed, this was the clear trial.' },
  { surahId: 37, ayahNumber: 107, text: 'And We ransomed him with a great sacrifice,' },
  { surahId: 37, ayahNumber: 108, text: 'And We left for him [favorable mention] among later generations:' },
  { surahId: 37, ayahNumber: 109, text: '"Peace upon Abraham."' },
  { surahId: 37, ayahNumber: 110, text: 'Indeed, We thus reward the doers of good.' },
  { surahId: 37, ayahNumber: 111, text: 'Indeed, he was of Our believing servants.' },
  { surahId: 37, ayahNumber: 112, text: 'And We gave him good tidings of Isaac, a prophet from among the righteous.' },
  { surahId: 37, ayahNumber: 113, text: 'And We blessed him and Isaac. But among their descendants is the doer of good and the clearly unjust to himself.' },
  { surahId: 37, ayahNumber: 114, text: 'And We did certainly confer favor upon Moses and Aaron.' },
  { surahId: 37, ayahNumber: 115, text: 'And We saved them and their people from the great affliction,' },
  { surahId: 37, ayahNumber: 116, text: 'And We supported them so it was they who overcame.' },
  { surahId: 37, ayahNumber: 117, text: 'And We gave them the explicit Scripture,' },
  { surahId: 37, ayahNumber: 118, text: 'And We guided them on the straight path.' },
  { surahId: 37, ayahNumber: 119, text: 'And We left for them [favorable mention] among later generations:' },
  { surahId: 37, ayahNumber: 120, text: '"Peace upon Moses and Aaron."' },
  { surahId: 37, ayahNumber: 121, text: 'Indeed, We thus reward the doers of good.' },
  { surahId: 37, ayahNumber: 122, text: 'Indeed, they were of Our believing servants.' },
  { surahId: 37, ayahNumber: 123, text: 'And indeed, Elias was from among the messengers,' },
  { surahId: 37, ayahNumber: 124, text: 'When he said to his people, "Will you not fear Allah?' },
  { surahId: 37, ayahNumber: 125, text: 'Do you call upon Ba\'l and leave the best of creators -' },
  { surahId: 37, ayahNumber: 126, text: 'Allah, your Lord and the Lord of your first forefathers?"' },
  { surahId: 37, ayahNumber: 127, text: 'And they denied him, so indeed, they will be brought [for punishment],' },
  { surahId: 37, ayahNumber: 128, text: 'Except the chosen servants of Allah.' },
  { surahId: 37, ayahNumber: 129, text: 'And We left for him [favorable mention] among later generations:' },
  { surahId: 37, ayahNumber: 130, text: '"Peace upon Elias."' },
  { surahId: 37, ayahNumber: 131, text: 'Indeed, We thus reward the doers of good.' },
  { surahId: 37, ayahNumber: 132, text: 'Indeed, he was of Our believing servants.' },
  { surahId: 37, ayahNumber: 133, text: 'And indeed, Lot was among the messengers.' },
  { surahId: 37, ayahNumber: 134, text: '[So mention] when We saved him and his family, all,' },
  { surahId: 37, ayahNumber: 135, text: 'Except his wife among those who remained [with the evildoers].' },
  { surahId: 37, ayahNumber: 136, text: 'Then We destroyed the others.' },
  { surahId: 37, ayahNumber: 137, text: 'And indeed, you pass by them in the morning' },
  { surahId: 37, ayahNumber: 138, text: 'And at night. Then will you not use reason?' },
  { surahId: 37, ayahNumber: 139, text: 'And indeed, Jonah was among the messengers.' },
  { surahId: 37, ayahNumber: 140, text: '[Mention] when he ran away to the laden ship.' },
  { surahId: 37, ayahNumber: 141, text: 'And he drew lots and was among the losers.' },
  { surahId: 37, ayahNumber: 142, text: 'Then the fish swallowed him, while he was blameworthy.' },
  { surahId: 37, ayahNumber: 143, text: 'And had he not been of those who exalt Allah,' },
  { surahId: 37, ayahNumber: 144, text: 'He would have remained inside its belly until the Day they are resurrected.' },
  { surahId: 37, ayahNumber: 145, text: 'But We threw him onto the open shore while he was ill.' },
  { surahId: 37, ayahNumber: 146, text: 'And We caused to grow over him a gourd vine.' },
  { surahId: 37, ayahNumber: 147, text: 'And We sent him to [his people of] a hundred thousand or more.' },
  { surahId: 37, ayahNumber: 148, text: 'And they believed, so We gave them enjoyment [of life] for a time.' },
  { surahId: 37, ayahNumber: 149, text: 'So inquire of them, [O Muhammad], "Does your Lord have daughters while they have sons?' },
  { surahId: 37, ayahNumber: 150, text: 'Or did We create the angels as females while they were witnesses?"' },
  { surahId: 37, ayahNumber: 151, text: 'Unquestionably, it is out of their [invented] falsehood that they say,' },
  { surahId: 37, ayahNumber: 152, text: '" Allah has begotten," and indeed, they are liars.' },
  { surahId: 37, ayahNumber: 153, text: 'Has He chosen daughters over sons?' },
  { surahId: 37, ayahNumber: 154, text: 'What is [wrong] with you? How do you make judgement?' },
  { surahId: 37, ayahNumber: 155, text: 'Then will you not be reminded?' },
  { surahId: 37, ayahNumber: 156, text: 'Or do you have a clear authority?' },
  { surahId: 37, ayahNumber: 157, text: 'Then produce your scripture, if you should be truthful.' },
  { surahId: 37, ayahNumber: 158, text: 'And they have claimed between Him and the jinn a lineage, but the jinn have already known that they [who made such claims] will be brought to [punishment].' },
  { surahId: 37, ayahNumber: 159, text: 'Exalted is Allah above what they describe,' },
  { surahId: 37, ayahNumber: 160, text: 'Except the chosen servants of Allah [who do not share in that sin].' },
  { surahId: 37, ayahNumber: 161, text: 'So indeed, you [disbelievers] and whatever you worship,' },
  { surahId: 37, ayahNumber: 162, text: 'You cannot tempt [anyone] away from Him' },
  { surahId: 37, ayahNumber: 163, text: 'Except he who is to [enter and] burn in the Hellfire.' },
  { surahId: 37, ayahNumber: 164, text: '[The angels say], "There is not among us any except that he has a known position.' },
  { surahId: 37, ayahNumber: 165, text: 'And indeed, we are those who line up [for prayer].' },
  { surahId: 37, ayahNumber: 166, text: 'And indeed, we are those who exalt Allah."' },
  { surahId: 37, ayahNumber: 167, text: 'And indeed, the disbelievers used to say,' },
  { surahId: 37, ayahNumber: 168, text: '"If we had a message from [those of] the former peoples,' },
  { surahId: 37, ayahNumber: 169, text: 'We would have been the chosen servants of Allah."' },
  { surahId: 37, ayahNumber: 170, text: 'But they disbelieved in it, so they are going to know.' },
  { surahId: 37, ayahNumber: 171, text: 'And Our word has already preceded for Our servants, the messengers,' },
  { surahId: 37, ayahNumber: 172, text: '[That] indeed, they would be those given victory' },
  { surahId: 37, ayahNumber: 173, text: 'And [that] indeed, Our soldiers will be those who overcome.' },
  { surahId: 37, ayahNumber: 174, text: 'So, [O Muhammad], leave them for a time.' },
  { surahId: 37, ayahNumber: 175, text: 'And see [what will befall] them, for they are going to see.' },
  { surahId: 37, ayahNumber: 176, text: 'Then for Our punishment are they impatient?' },
  { surahId: 37, ayahNumber: 177, text: 'But when it descends in their territory, then evil is the morning of those who were warned.' },
  { surahId: 37, ayahNumber: 178, text: 'And leave them for a time.' },
  { surahId: 37, ayahNumber: 179, text: 'And see, for they are going to see.' },
  { surahId: 37, ayahNumber: 180, text: 'Exalted is your Lord, the Lord of might, above what they describe.' },
  { surahId: 37, ayahNumber: 181, text: 'And peace upon the messengers.' },
  { surahId: 37, ayahNumber: 182, text: 'And praise to Allah, Lord of the worlds.' },
  { surahId: 38, ayahNumber: 1, text: 'Sad. By the Qur\'an containing reminder...' },
  { surahId: 38, ayahNumber: 2, text: 'But those who disbelieve are in pride and dissension.' },
  { surahId: 38, ayahNumber: 3, text: 'How many a generation have We destroyed before them, and they [then] called out; but it was not a time for escape.' },
  { surahId: 38, ayahNumber: 4, text: 'And they wonder that there has come to them a warner from among themselves. And the disbelievers say, "This is a magician and a liar.' },
  { surahId: 38, ayahNumber: 5, text: 'Has he made the gods [only] one God? Indeed, this is a curious thing."' },
  { surahId: 38, ayahNumber: 6, text: 'And the eminent among them went forth, [saying], "Continue, and be patient over [the defense of] your gods. Indeed, this is a thing intended.' },
  { surahId: 38, ayahNumber: 7, text: 'We have not heard of this in the latest religion. This is not but a fabrication.' },
  { surahId: 38, ayahNumber: 8, text: 'Has the message been revealed to him out of [all of] us?" Rather, they are in doubt about My message. Rather, they have not yet tasted My punishment.' },
  { surahId: 38, ayahNumber: 9, text: 'Or do they have the depositories of the mercy of your Lord, the Exalted in Might, the Bestower?' },
  { surahId: 38, ayahNumber: 10, text: 'Or is theirs the dominion of the heavens and the earth and what is between them? Then let them ascend through [any] ways of access.' },
  { surahId: 38, ayahNumber: 11, text: '[They are but] soldiers [who will be] defeated there among the companies [of disbelievers].' },
  { surahId: 38, ayahNumber: 12, text: 'The people of Noah denied before them, and [the tribe of] \'Aad and Pharaoh, the owner of stakes,' },
  { surahId: 38, ayahNumber: 13, text: 'And [the tribe of] Thamud and the people of Lot and the companions of the thicket. Those are the companies.' },
  { surahId: 38, ayahNumber: 14, text: 'Each of them denied the messengers, so My penalty was justified.' },
  { surahId: 38, ayahNumber: 15, text: 'And these [disbelievers] await not but one blast [of the Horn]; for it there will be no delay.' },
  { surahId: 38, ayahNumber: 16, text: 'And they say, "Our Lord, hasten for us our share [of the punishment] before the Day of Account"' },
  { surahId: 38, ayahNumber: 17, text: 'Be patient over what they say and remember Our servant, David, the possessor of strength; indeed, he was one who repeatedly turned back [to Allah].' },
  { surahId: 38, ayahNumber: 18, text: 'Indeed, We subjected the mountains [to praise] with him, exalting [Allah] in the [late] afternoon and [after] sunrise.' },
  { surahId: 38, ayahNumber: 19, text: 'And the birds were assembled, all with him repeating [praises].' },
  { surahId: 38, ayahNumber: 20, text: 'And We strengthened his kingdom and gave him wisdom and discernment in speech.' },
  { surahId: 38, ayahNumber: 21, text: 'And has there come to you the news of the adversaries, when they climbed over the wall of [his] prayer chamber -' },
  { surahId: 38, ayahNumber: 22, text: 'When they entered upon David and he was alarmed by them? They said, "Fear not. [We are] two adversaries, one of whom has wronged the other, so judge between us with truth and do not exceed [it] and guide us to the sound path.' },
  { surahId: 38, ayahNumber: 23, text: 'Indeed this, my brother, has ninety-nine ewes, and I have one ewe; so he said, \'Entrust her to me,\' and he overpowered me in speech."' },
  { surahId: 38, ayahNumber: 24, text: '[David] said, "He has certainly wronged you in demanding your ewe [in addition] to his ewes. And indeed, many associates oppress one another, except for those who believe and do righteous deeds - and few are they." And David became certain that We had tried him, and he asked forgiveness of his Lord and fell down bowing [in prostration] and turned in repentance [to Allah].' },
  { surahId: 38, ayahNumber: 25, text: 'So We forgave him that; and indeed, for him is nearness to Us and a good place of return.' },
  { surahId: 38, ayahNumber: 26, text: '[We said], "O David, indeed We have made you a successor upon the earth, so judge between the people in truth and do not follow [your own] desire, as it will lead you astray from the way of Allah." Indeed, those who go astray from the way of Allah will have a severe punishment for having forgotten the Day of Account.' },
  { surahId: 38, ayahNumber: 27, text: 'And We did not create the heaven and the earth and that between them aimlessly. That is the assumption of those who disbelieve, so woe to those who disbelieve from the Fire.' },
  { surahId: 38, ayahNumber: 28, text: 'Or should we treat those who believe and do righteous deeds like corrupters in the land? Or should We treat those who fear Allah like the wicked?' },
  { surahId: 38, ayahNumber: 29, text: '[This is] a blessed Book which We have revealed to you, [O Muhammad], that they might reflect upon its verses and that those of understanding would be reminded.' },
  { surahId: 38, ayahNumber: 30, text: 'And to David We gave Solomon. An excellent servant, indeed he was one repeatedly turning back [to Allah].' },
  { surahId: 38, ayahNumber: 31, text: '[Mention] when there were exhibited before him in the afternoon the poised [standing] racehorses.' },
  { surahId: 38, ayahNumber: 32, text: 'And he said, "Indeed, I gave preference to the love of good [things] over the remembrance of my Lord until the sun disappeared into the curtain [of darkness]."' },
  { surahId: 38, ayahNumber: 33, text: '[He said], "Return them to me," and set about striking [their] legs and necks.' },
  { surahId: 38, ayahNumber: 34, text: 'And We certainly tried Solomon and placed on his throne a body; then he returned.' },
  { surahId: 38, ayahNumber: 35, text: 'He said, "My Lord, forgive me and grant me a kingdom such as will not belong to anyone after me. Indeed, You are the Bestower."' },
  { surahId: 38, ayahNumber: 36, text: 'So We subjected to him the wind blowing by his command, gently, wherever he directed,' },
  { surahId: 38, ayahNumber: 37, text: 'And [also] the devils [of jinn] - every builder and diver' },
  { surahId: 38, ayahNumber: 38, text: 'And others bound together in shackles.' },
  { surahId: 38, ayahNumber: 39, text: '[We said], "This is Our gift, so grant or withhold without account."' },
  { surahId: 38, ayahNumber: 40, text: 'And indeed, for him is nearness to Us and a good place of return.' },
  { surahId: 38, ayahNumber: 41, text: 'And remember Our servant Job, when he called to his Lord, "Indeed, Satan has touched me with hardship and torment."' },
  { surahId: 38, ayahNumber: 42, text: '[So he was told], "Strike [the ground] with your foot; this is a [spring for] a cool bath and drink."' },
  { surahId: 38, ayahNumber: 43, text: 'And We granted him his family and a like [number] with them as mercy from Us and a reminder for those of understanding.' },
  { surahId: 38, ayahNumber: 44, text: '[We said], "And take in your hand a bunch [of grass] and strike with it and do not break your oath." Indeed, We found him patient, an excellent servant. Indeed, he was one repeatedly turning back [to Allah].' },
  { surahId: 38, ayahNumber: 45, text: 'And remember Our servants, Abraham, Isaac and Jacob - those of strength and [religious] vision.' },
  { surahId: 38, ayahNumber: 46, text: 'Indeed, We chose them for an exclusive quality: remembrance of the home [of the Hereafter].' },
  { surahId: 38, ayahNumber: 47, text: 'And indeed they are, to Us, among the chosen and outstanding.' },
  { surahId: 38, ayahNumber: 48, text: 'And remember Ishmael, Elisha and Dhul-Kifl, and all are among the outstanding.' },
  { surahId: 38, ayahNumber: 49, text: 'This is a reminder. And indeed, for the righteous is a good place of return' },
  { surahId: 38, ayahNumber: 50, text: 'Gardens of perpetual residence, whose doors will be opened to them.' },
  { surahId: 38, ayahNumber: 51, text: 'Reclining within them, they will call therein for abundant fruit and drink.' },
  { surahId: 38, ayahNumber: 52, text: 'And with them will be women limiting [their] glances and of equal age.' },
  { surahId: 38, ayahNumber: 53, text: 'This is what you, [the righteous], are promised for the Day of Account.' },
  { surahId: 38, ayahNumber: 54, text: 'Indeed, this is Our provision; for it there is no depletion.' },
  { surahId: 38, ayahNumber: 55, text: 'This [is so]. But indeed, for the transgressors is an evil place of return -' },
  { surahId: 38, ayahNumber: 56, text: 'Hell, which they will [enter to] burn, and wretched is the resting place.' },
  { surahId: 38, ayahNumber: 57, text: 'This - so let them taste it - is scalding water and [foul] purulence.' },
  { surahId: 38, ayahNumber: 58, text: 'And other [punishments] of its type [in various] kinds.' },
  { surahId: 38, ayahNumber: 59, text: '[Its inhabitants will say], "This is a company bursting in with you. No welcome for them. Indeed, they will burn in the Fire."' },
  { surahId: 38, ayahNumber: 60, text: 'They will say, "Nor you! No welcome for you. You, [our leaders], brought this upon us, and wretched is the settlement."' },
  { surahId: 38, ayahNumber: 61, text: 'They will say, "Our Lord, whoever brought this upon us - increase for him double punishment in the Fire."' },
  { surahId: 38, ayahNumber: 62, text: 'And they will say, "Why do we not see men whom we used to count among the worst?' },
  { surahId: 38, ayahNumber: 63, text: 'Is it [because] we took them in ridicule, or has [our] vision turned away from them?"' },
  { surahId: 38, ayahNumber: 64, text: 'Indeed, that is truth - the quarreling of the people of the Fire.' },
  { surahId: 38, ayahNumber: 65, text: 'Say, [O Muhammad], "I am only a warner, and there is not any deity except Allah, the One, the Prevailing.' },
  { surahId: 38, ayahNumber: 66, text: 'Lord of the heavens and the earth and whatever is between them, the Exalted in Might, the Perpetual Forgiver."' },
  { surahId: 38, ayahNumber: 67, text: 'Say, "It is great news' },
  { surahId: 38, ayahNumber: 68, text: 'From which you turn away.' },
  { surahId: 38, ayahNumber: 69, text: 'I had no knowledge of the exalted assembly [of angels] when they were disputing [the creation of Adam].' },
  { surahId: 38, ayahNumber: 70, text: 'It has not been revealed to me except that I am a clear warner."' },
  { surahId: 38, ayahNumber: 71, text: '[So mention] when your Lord said to the angels, "Indeed, I am going to create a human being from clay.' },
  { surahId: 38, ayahNumber: 72, text: 'So when I have proportioned him and breathed into him of My [created] soul, then fall down to him in prostration."' },
  { surahId: 38, ayahNumber: 73, text: 'So the angels prostrated - all of them entirely.' },
  { surahId: 38, ayahNumber: 74, text: 'Except Iblees; he was arrogant and became among the disbelievers.' },
  { surahId: 38, ayahNumber: 75, text: '[Allah] said, "O Iblees, what prevented you from prostrating to that which I created with My hands? Were you arrogant [then], or were you [already] among the haughty?"' },
  { surahId: 38, ayahNumber: 76, text: 'He said, "I am better than him. You created me from fire and created him from clay."' },
  { surahId: 38, ayahNumber: 77, text: '[Allah] said, "Then get out of Paradise, for indeed, you are expelled.' },
  { surahId: 38, ayahNumber: 78, text: 'And indeed, upon you is My curse until the Day of Recompense."' },
  { surahId: 38, ayahNumber: 79, text: 'He said, "My Lord, then reprieve me until the Day they are resurrected."' },
  { surahId: 38, ayahNumber: 80, text: '[Allah] said, "So indeed, you are of those reprieved' },
  { surahId: 38, ayahNumber: 81, text: 'Until the Day of the time well-known."' },
  { surahId: 38, ayahNumber: 82, text: '[Iblees] said, "By your might, I will surely mislead them all' },
  { surahId: 38, ayahNumber: 83, text: 'Except, among them, Your chosen servants."' },
  { surahId: 38, ayahNumber: 84, text: '[Allah] said, "The truth [is My oath], and the truth I say -' },
  { surahId: 38, ayahNumber: 85, text: '[That] I will surely fill Hell with you and those of them that follow you all together."' },
  { surahId: 38, ayahNumber: 86, text: 'Say, [O Muhammad], "I do not ask you for the Qur\'an any payment, and I am not of the pretentious' },
  { surahId: 38, ayahNumber: 87, text: 'It is but a reminder to the worlds.' },
  { surahId: 38, ayahNumber: 88, text: 'And you will surely know [the truth of] its information after a time."' },
  { surahId: 39, ayahNumber: 1, text: 'The revelation of the Qur\'an is from Allah, the Exalted in Might, the Wise.' },
  { surahId: 39, ayahNumber: 2, text: 'Indeed, We have sent down to you the Book, [O Muhammad], in truth. So worship Allah, [being] sincere to Him in religion.' },
  { surahId: 39, ayahNumber: 3, text: 'Unquestionably, for Allah is the pure religion. And those who take protectors besides Him [say], "We only worship them that they may bring us nearer to Allah in position." Indeed, Allah will judge between them concerning that over which they differ. Indeed, Allah does not guide he who is a liar and [confirmed] disbeliever.' },
  { surahId: 39, ayahNumber: 4, text: 'If Allah had intended to take a son, He could have chosen from what He creates whatever He willed. Exalted is He; He is Allah, the One, the Prevailing.' },
  { surahId: 39, ayahNumber: 5, text: 'He created the heavens and earth in truth. He wraps the night over the day and wraps the day over the night and has subjected the sun and the moon, each running [its course] for a specified term. Unquestionably, He is the Exalted in Might, the Perpetual Forgiver.' },
  { surahId: 39, ayahNumber: 6, text: 'He created you from one soul. Then He made from it its mate, and He produced for you from the grazing livestock eight mates. He creates you in the wombs of your mothers, creation after creation, within three darknesses. That is Allah, your Lord; to Him belongs dominion. There is no deity except Him, so how are you averted?' },
  { surahId: 39, ayahNumber: 7, text: 'If you disbelieve - indeed, Allah is Free from need of you. And He does not approve for His servants disbelief. And if you are grateful, He approves it for you; and no bearer of burdens will bear the burden of another. Then to your Lord is your return, and He will inform you about what you used to do. Indeed, He is Knowing of that within the breasts.' },
  { surahId: 39, ayahNumber: 8, text: 'And when adversity touches man, he calls upon his Lord, turning to Him [alone]; then when He bestows on him a favor from Himself, he forgets Him whom he called upon before, and he attributes to Allah equals to mislead [people] from His way. Say, "Enjoy your disbelief for a little; indeed, you are of the companions of the Fire."' },
  { surahId: 39, ayahNumber: 9, text: 'Is one who is devoutly obedient during periods of the night, prostrating and standing [in prayer], fearing the Hereafter and hoping for the mercy of his Lord, [like one who does not]? Say, "Are those who know equal to those who do not know?" Only they will remember [who are] people of understanding.' },
  { surahId: 39, ayahNumber: 10, text: 'Say, "O My servants who have believed, fear your Lord. For those who do good in this world is good, and the earth of Allah is spacious. Indeed, the patient will be given their reward without account."' },
  { surahId: 39, ayahNumber: 11, text: 'Say, [O Muhammad], "Indeed, I have been commanded to worship Allah, [being] sincere to Him in religion.' },
  { surahId: 39, ayahNumber: 12, text: 'And I have been commanded to be the first [among you] of the Muslims."' },
  { surahId: 39, ayahNumber: 13, text: 'Say, "Indeed I fear, if I should disobey my Lord, the punishment of a tremendous Day."' },
  { surahId: 39, ayahNumber: 14, text: 'Say, "Allah [alone] do I worship, sincere to Him in my religion,' },
  { surahId: 39, ayahNumber: 15, text: 'So worship what you will besides Him." Say, "Indeed, the losers are the ones who will lose themselves and their families on the Day of Resurrection. Unquestionably, that is the manifest loss."' },
  { surahId: 39, ayahNumber: 16, text: 'They will have canopies of fire above them and below them, canopies. By that Allah threatens His servants. O My servants, then fear Me.' },
  { surahId: 39, ayahNumber: 17, text: 'But those who have avoided Taghut, lest they worship it, and turned back to Allah - for them are good tidings. So give good tidings to My servants' },
  { surahId: 39, ayahNumber: 18, text: 'Who listen to speech and follow the best of it. Those are the ones Allah has guided, and those are people of understanding.' },
  { surahId: 39, ayahNumber: 19, text: 'Then, is one who has deserved the decree of punishment [to be guided]? Then, can you save one who is in the Fire?' },
  { surahId: 39, ayahNumber: 20, text: 'But those who have feared their Lord - for them are chambers, above them chambers built high, beneath which rivers flow. [This is] the promise of Allah. Allah does not fail in [His] promise.' },
  { surahId: 39, ayahNumber: 21, text: 'Do you not see that Allah sends down rain from the sky and makes it flow as springs [and rivers] in the earth; then He produces thereby crops of varying colors; then they dry and you see them turned yellow; then He makes them [scattered] debris. Indeed in that is a reminder for those of understanding.' },
  { surahId: 39, ayahNumber: 22, text: 'So is one whose breast Allah has expanded to [accept] Islam and he is upon a light from his Lord [like one whose heart rejects it]? Then woe to those whose hearts are hardened against the remembrance of Allah. Those are in manifest error.' },
  { surahId: 39, ayahNumber: 23, text: 'Allah has sent down the best statement: a consistent Book wherein is reiteration. The skins shiver therefrom of those who fear their Lord; then their skins and their hearts relax at the remembrance of Allah. That is the guidance of Allah by which He guides whom He wills. And one whom Allah leaves astray - for him there is no guide.' },
  { surahId: 39, ayahNumber: 24, text: 'Then is he who will shield with his face the worst of the punishment on the Day of Resurrection [like one secure from it]? And it will be said to the wrongdoers, "Taste what you used to earn."' },
  { surahId: 39, ayahNumber: 25, text: 'Those before them denied, and punishment came upon them from where they did not perceive.' },
  { surahId: 39, ayahNumber: 26, text: 'So Allah made them taste disgrace in worldly life. But the punishment of the Hereafter is greater, if they only knew.' },
  { surahId: 39, ayahNumber: 27, text: 'And We have certainly presented for the people in this Qur\'an from every [kind of] example - that they might remember.' },
  { surahId: 39, ayahNumber: 28, text: '[It is] an Arabic Qur\'an, without any deviance that they might become righteous.' },
  { surahId: 39, ayahNumber: 29, text: 'Allah presents an example: a slave owned by quarreling partners and another belonging exclusively to one man - are they equal in comparison? Praise be to Allah! But most of them do not know.' },
  { surahId: 39, ayahNumber: 30, text: 'Indeed, you are to die, and indeed, they are to die.' },
  { surahId: 39, ayahNumber: 31, text: 'Then indeed you, on the Day of Resurrection, before your Lord, will dispute.' },
  { surahId: 39, ayahNumber: 32, text: 'So who is more unjust than one who lies about Allah and denies the truth when it has come to him? Is there not in Hell a residence for the disbelievers?' },
  { surahId: 39, ayahNumber: 33, text: 'And the one who has brought the truth and [they who] believed in it - those are the righteous.' },
  { surahId: 39, ayahNumber: 34, text: 'They will have whatever they desire with their Lord. That is the reward of the doers of good -' },
  { surahId: 39, ayahNumber: 35, text: 'That Allah may remove from them the worst of what they did and reward them their due for the best of what they used to do.' },
  { surahId: 39, ayahNumber: 36, text: 'Is not Allah sufficient for His Servant [Prophet Muhammad]? And [yet], they threaten you with those [they worship] other than Him. And whoever Allah leaves astray - for him there is no guide.' },
  { surahId: 39, ayahNumber: 37, text: 'And whoever Allah guides - for him there is no misleader. Is not Allah Exalted in Might and Owner of Retribution?' },
  { surahId: 39, ayahNumber: 38, text: 'And if you asked them, "Who created the heavens and the earth?" they would surely say, "Allah." Say, "Then have you considered what you invoke besides Allah? If Allah intended me harm, are they removers of His harm; or if He intended me mercy, are they withholders of His mercy?" Say, "Sufficient for me is Allah; upon Him [alone] rely the [wise] reliers."' },
  { surahId: 39, ayahNumber: 39, text: 'Say, "O my people, work according to your position, [for] indeed, I am working; and you are going to know' },
  { surahId: 39, ayahNumber: 40, text: 'To whom will come a torment disgracing him and on whom will descend an enduring punishment."' },
  { surahId: 39, ayahNumber: 41, text: 'Indeed, We sent down to you the Book for the people in truth. So whoever is guided - it is for [the benefit of] his soul; and whoever goes astray only goes astray to its detriment. And you are not a manager over them.' },
  { surahId: 39, ayahNumber: 42, text: 'Allah takes the souls at the time of their death, and those that do not die [He takes] during their sleep. Then He keeps those for which He has decreed death and releases the others for a specified term. Indeed in that are signs for a people who give thought.' },
  { surahId: 39, ayahNumber: 43, text: 'Or have they taken other than Allah as intercessors? Say, "Even though they do not possess [power over] anything, nor do they reason?"' },
  { surahId: 39, ayahNumber: 44, text: 'Say, "To Allah belongs [the right to allow] intercession entirely. To Him belongs the dominion of the heavens and the earth. Then to Him you will be returned."' },
  { surahId: 39, ayahNumber: 45, text: 'And when Allah is mentioned alone, the hearts of those who do not believe in the Hereafter shrink with aversion, but when those [worshipped] other than Him are mentioned, immediately they rejoice.' },
  { surahId: 39, ayahNumber: 46, text: 'Say, "O Allah, Creator of the heavens and the earth, Knower of the unseen and the witnessed, You will judge between your servants concerning that over which they used to differ."' },
  { surahId: 39, ayahNumber: 47, text: 'And if those who did wrong had all that is in the earth entirely and the like of it with it, they would [attempt to] ransom themselves thereby from the worst of the punishment on the Day of Resurrection. And there will appear to them from Allah that which they had not taken into account.' },
  { surahId: 39, ayahNumber: 48, text: 'And there will appear to them the evils they had earned, and they will be enveloped by what they used to ridicule.' },
  { surahId: 39, ayahNumber: 49, text: 'And when adversity touches man, he calls upon Us; then when We bestow on him a favor from Us, he says, "I have only been given it because of [my] knowledge." Rather, it is a trial, but most of them do not know.' },
  { surahId: 39, ayahNumber: 50, text: 'Those before them had already said it, but they were not availed by what they used to earn.' },
  { surahId: 39, ayahNumber: 51, text: 'And the evil consequences of what they earned struck them. And those who have wronged of these [people] will be afflicted by the evil consequences of what they earned; and they will not cause failure.' },
  { surahId: 39, ayahNumber: 52, text: 'Do they not know that Allah extends provision for whom He wills and restricts [it]? Indeed in that are signs for a people who believe.' },
  { surahId: 39, ayahNumber: 53, text: 'Say, "O My servants who have transgressed against themselves [by sinning], do not despair of the mercy of Allah. Indeed, Allah forgives all sins. Indeed, it is He who is the Forgiving, the Merciful."' },
  { surahId: 39, ayahNumber: 54, text: 'And return [in repentance] to your Lord and submit to Him before the punishment comes upon you; then you will not be helped.' },
  { surahId: 39, ayahNumber: 55, text: 'And follow the best of what was revealed to you from your Lord before the punishment comes upon you suddenly while you do not perceive,' },
  { surahId: 39, ayahNumber: 56, text: 'Lest a soul should say, "Oh [how great is] my regret over what I neglected in regard to Allah and that I was among the mockers."' },
  { surahId: 39, ayahNumber: 57, text: 'Or [lest] it say, "If only Allah had guided me, I would have been among the righteous."' },
  { surahId: 39, ayahNumber: 58, text: 'Or [lest] it say when it sees the punishment, "If only I had another turn so I could be among the doers of good."' },
  { surahId: 39, ayahNumber: 59, text: 'But yes, there had come to you My verses, but you denied them and were arrogant, and you were among the disbelievers.' },
  { surahId: 39, ayahNumber: 60, text: 'And on the Day of Resurrection you will see those who lied about Allah [with] their faces blackened. Is there not in Hell a residence for the arrogant?' },
  { surahId: 39, ayahNumber: 61, text: 'And Allah will save those who feared Him by their attainment; no evil will touch them, nor will they grieve.' },
  { surahId: 39, ayahNumber: 62, text: 'Allah is the Creator of all things, and He is, over all things, Disposer of affairs.' },
  { surahId: 39, ayahNumber: 63, text: 'To Him belong the keys of the heavens and the earth. And they who disbelieve in the verses of Allah - it is those who are the losers.' },
  { surahId: 39, ayahNumber: 64, text: 'Say, [O Muhammad], "Is it other than Allah that you order me to worship, O ignorant ones?"' },
  { surahId: 39, ayahNumber: 65, text: 'And it was already revealed to you and to those before you that if you should associate [anything] with Allah, your work would surely become worthless, and you would surely be among the losers."' },
  { surahId: 39, ayahNumber: 66, text: 'Rather, worship [only] Allah and be among the grateful.' },
  { surahId: 39, ayahNumber: 67, text: 'They have not appraised Allah with true appraisal, while the earth entirely will be [within] His grip on the Day of Resurrection, and the heavens will be folded in His right hand. Exalted is He and high above what they associate with Him.' },
  { surahId: 39, ayahNumber: 68, text: 'And the Horn will be blown, and whoever is in the heavens and whoever is on the earth will fall dead except whom Allah wills. Then it will be blown again, and at once they will be standing, looking on.' },
  { surahId: 39, ayahNumber: 69, text: 'And the earth will shine with the light of its Lord, and the record [of deeds] will be placed, and the prophets and the witnesses will be brought, and it will be judged between them in truth, and they will not be wronged.' },
  { surahId: 39, ayahNumber: 70, text: 'And every soul will be fully compensated [for] what it did; and He is most knowing of what they do.' },
  { surahId: 39, ayahNumber: 71, text: 'And those who disbelieved will be driven to Hell in groups until, when they reach it, its gates are opened and its keepers will say, "Did there not come to you messengers from yourselves, reciting to you the verses of your Lord and warning you of the meeting of this Day of yours?" They will say, "Yes, but the word of punishment has come into effect upon the disbelievers.' },
  { surahId: 39, ayahNumber: 72, text: '[To them] it will be said, "Enter the gates of Hell to abide eternally therein, and wretched is the residence of the arrogant."' },
  { surahId: 39, ayahNumber: 73, text: 'But those who feared their Lord will be driven to Paradise in groups until, when they reach it while its gates have been opened and its keepers say, "Peace be upon you; you have become pure; so enter it to abide eternally therein," [they will enter].' },
  { surahId: 39, ayahNumber: 74, text: 'And they will say, "Praise to Allah, who has fulfilled for us His promise and made us inherit the earth [so] we may settle in Paradise wherever we will. And excellent is the reward of [righteous] workers."' },
  { surahId: 39, ayahNumber: 75, text: 'And you will see the angels surrounding the Throne, exalting [Allah] with praise of their Lord. And it will be judged between them in truth, and it will be said, "[All] praise to Allah, Lord of the worlds."' },
  { surahId: 40, ayahNumber: 1, text: 'Ha, Meem.' },
  { surahId: 40, ayahNumber: 2, text: 'The revelation of the Book is from Allah, the Exalted in Might, the Knowing.' },
  { surahId: 40, ayahNumber: 3, text: 'The forgiver of sin, acceptor of repentance, severe in punishment, owner of abundance. There is no deity except Him; to Him is the destination.' },
  { surahId: 40, ayahNumber: 4, text: 'No one disputes concerning the signs of Allah except those who disbelieve, so be not deceived by their [uninhibited] movement throughout the land.' },
  { surahId: 40, ayahNumber: 5, text: 'The people of Noah denied before them and the [disbelieving] factions after them, and every nation intended [a plot] for their messenger to seize him, and they disputed by [using] falsehood to [attempt to] invalidate thereby the truth. So I seized them, and how [terrible] was My penalty.' },
  { surahId: 40, ayahNumber: 6, text: 'And thus has the word of your Lord come into effect upon those who disbelieved that they are companions of the Fire.' },
  { surahId: 40, ayahNumber: 7, text: 'Those [angels] who carry the Throne and those around it exalt [Allah] with praise of their Lord and believe in Him and ask forgiveness for those who have believed, [saying], "Our Lord, You have encompassed all things in mercy and knowledge, so forgive those who have repented and followed Your way and protect them from the punishment of Hellfire.' },
  { surahId: 40, ayahNumber: 8, text: 'Our Lord, and admit them to gardens of perpetual residence which You have promised them and whoever was righteous among their fathers, their spouses and their offspring. Indeed, it is You who is the Exalted in Might, the Wise.' },
  { surahId: 40, ayahNumber: 9, text: 'And protect them from the evil consequences [of their deeds]. And he whom You protect from evil consequences that Day - You will have given him mercy. And that is the great attainment."' },
  { surahId: 40, ayahNumber: 10, text: 'Indeed, those who disbelieve will be addressed, "The hatred of Allah for you was [even] greater than your hatred of yourselves [this Day in Hell] when you were invited to faith, but you refused."' },
  { surahId: 40, ayahNumber: 11, text: 'They will say, "Our Lord, You made us lifeless twice and gave us life twice, and we have confessed our sins. So is there to an exit any way?"' },
  { surahId: 40, ayahNumber: 12, text: '[They will be told], "That is because, when Allah was called upon alone, you disbelieved; but if others were associated with Him, you believed. So the judgement is with Allah, the Most High, the Grand."' },
  { surahId: 40, ayahNumber: 13, text: 'It is He who shows you His signs and sends down to you from the sky, provision. But none will remember except he who turns back [in repentance].' },
  { surahId: 40, ayahNumber: 14, text: 'So invoke Allah, [being] sincere to Him in religion, although the disbelievers dislike it.' },
  { surahId: 40, ayahNumber: 15, text: '[He is] the Exalted above [all] degrees, Owner of the Throne; He places the inspiration of His command upon whom He wills of His servants to warn of the Day of Meeting.' },
  { surahId: 40, ayahNumber: 16, text: 'The Day they come forth nothing concerning them will be concealed from Allah. To whom belongs [all] sovereignty this Day? To Allah, the One, the Prevailing.' },
  { surahId: 40, ayahNumber: 17, text: 'This Day every soul will be recompensed for what it earned. No injustice today! Indeed, Allah is swift in account.' },
  { surahId: 40, ayahNumber: 18, text: 'And warn them, [O Muhammad], of the Approaching Day, when hearts are at the throats, filled [with distress]. For the wrongdoers there will be no devoted friend and no intercessor [who is] obeyed.' },
  { surahId: 40, ayahNumber: 19, text: 'He knows that which deceives the eyes and what the breasts conceal.' },
  { surahId: 40, ayahNumber: 20, text: 'And Allah judges with truth, while those they invoke besides Him judge not with anything. Indeed, Allah - He is the Hearing, the Seeing.' },
  { surahId: 40, ayahNumber: 21, text: 'Have they not traveled through the land and observed how was the end of those who were before them? They were greater than them in strength and in impression on the land, but Allah seized them for their sins. And they had not from Allah any protector.' },
  { surahId: 40, ayahNumber: 22, text: 'That was because their messengers were coming to them with clear proofs, but they disbelieved, so Allah seized them. Indeed, He is Powerful and severe in punishment.' },
  { surahId: 40, ayahNumber: 23, text: 'And We did certainly send Moses with Our signs and a clear authority' },
  { surahId: 40, ayahNumber: 24, text: 'To Pharaoh, Haman and Qarun; but they said, "[He is] a magician and a liar."' },
  { surahId: 40, ayahNumber: 25, text: 'And when he brought them the truth from Us, they said, "Kill the sons of those who have believed with him and keep their women alive." But the plan of the disbelievers is not except in error.' },
  { surahId: 40, ayahNumber: 26, text: 'And Pharaoh said, "Let me kill Moses and let him call upon his Lord. Indeed, I fear that he will change your religion or that he will cause corruption in the land."' },
  { surahId: 40, ayahNumber: 27, text: 'But Moses said, "Indeed, I have sought refuge in my Lord and your Lord from every arrogant one who does not believe in the Day of Account."' },
  { surahId: 40, ayahNumber: 28, text: 'And a believing man from the family of Pharaoh who concealed his faith said, "Do you kill a man [merely] because he says, \'My Lord is Allah\' while he has brought you clear proofs from your Lord? And if he should be lying, then upon him is [the consequence of] his lie; but if he should be truthful, there will strike you some of what he promises you. Indeed, Allah does not guide one who is a transgressor and a liar.' },
  { surahId: 40, ayahNumber: 29, text: 'O my people, sovereignty is yours today, [your being] dominant in the land. But who would protect us from the punishment of Allah if it came to us?" Pharaoh said, "I do not show you except what I see, and I do not guide you except to the way of right conduct."' },
  { surahId: 40, ayahNumber: 30, text: 'And he who believed said, "O my people, indeed I fear for you [a fate] like the day of the companies -' },
  { surahId: 40, ayahNumber: 31, text: 'Like the custom of the people of Noah and of \'Aad and Thamud and those after them. And Allah wants no injustice for [His] servants.' },
  { surahId: 40, ayahNumber: 32, text: 'And O my people, indeed I fear for you the Day of Calling -' },
  { surahId: 40, ayahNumber: 33, text: 'The Day you will turn your backs fleeing; there is not for you from Allah any protector. And whoever Allah leaves astray - there is not for him any guide.' },
  { surahId: 40, ayahNumber: 34, text: 'And Joseph had already come to you before with clear proofs, but you remained in doubt of that which he brought to you, until when he died, you said, \'Never will Allah send a messenger after him.\' Thus does Allah leave astray he who is a transgressor and skeptic."' },
  { surahId: 40, ayahNumber: 35, text: 'Those who dispute concerning the signs of Allah without an authority having come to them - great is hatred [of them] in the sight of Allah and in the sight of those who have believed. Thus does Allah seal over every heart [belonging to] an arrogant tyrant.' },
  { surahId: 40, ayahNumber: 36, text: 'And Pharaoh said, "O Haman, construct for me a tower that I might reach the ways -' },
  { surahId: 40, ayahNumber: 37, text: 'The ways into the heavens - so that I may look at the deity of Moses; but indeed, I think he is a liar." And thus was made attractive to Pharaoh the evil of his deed, and he was averted from the [right] way. And the plan of Pharaoh was not except in ruin.' },
  { surahId: 40, ayahNumber: 38, text: 'And he who believed said, "O my people, follow me, I will guide you to the way of right conduct.' },
  { surahId: 40, ayahNumber: 39, text: 'O my people, this worldly life is only [temporary] enjoyment, and indeed, the Hereafter - that is the home of [permanent] settlement.' },
  { surahId: 40, ayahNumber: 40, text: 'Whoever does an evil deed will not be recompensed except by the like thereof; but whoever does righteousness, whether male or female, while he is a believer - those will enter Paradise, being given provision therein without account.' },
  { surahId: 40, ayahNumber: 41, text: 'And O my people, how is it that I invite you to salvation while you invite me to the Fire?' },
  { surahId: 40, ayahNumber: 42, text: 'You invite me to disbelieve in Allah and associate with Him that of which I have no knowledge, and I invite you to the Exalted in Might, the Perpetual Forgiver.' },
  { surahId: 40, ayahNumber: 43, text: 'Assuredly, that to which you invite me has no [response to a] supplication in this world or in the Hereafter; and indeed, our return is to Allah, and indeed, the transgressors will be companions of the Fire.' },
  { surahId: 40, ayahNumber: 44, text: 'And you will remember what I [now] say to you, and I entrust my affair to Allah. Indeed, Allah is Seeing of [His] servants."' },
  { surahId: 40, ayahNumber: 45, text: 'So Allah protected him from the evils they plotted, and the people of Pharaoh were enveloped by the worst of punishment -' },
  { surahId: 40, ayahNumber: 46, text: 'The Fire, they are exposed to it morning and evening. And the Day the Hour appears [it will be said], "Make the people of Pharaoh enter the severest punishment."' },
  { surahId: 40, ayahNumber: 47, text: 'And [mention] when they will argue within the Fire, and the weak will say to those who had been arrogant, "Indeed, we were [only] your followers, so will you relieve us of a share of the Fire?"' },
  { surahId: 40, ayahNumber: 48, text: 'Those who had been arrogant will say, "Indeed, all [of us] are in it. Indeed, Allah has judged between the servants."' },
  { surahId: 40, ayahNumber: 49, text: 'And those in the Fire will say to the keepers of Hell, "Supplicate your Lord to lighten for us a day from the punishment."' },
  { surahId: 40, ayahNumber: 50, text: 'They will say, "Did there not come to you your messengers with clear proofs?" They will say, "Yes." They will reply, "Then supplicate [yourselves], but the supplication of the disbelievers is not except in error."' },
  { surahId: 40, ayahNumber: 51, text: 'Indeed, We will support Our messengers and those who believe during the life of this world and on the Day when the witnesses will stand -' },
  { surahId: 40, ayahNumber: 52, text: 'The Day their excuse will not benefit the wrongdoers, and they will have the curse, and they will have the worst home.' },
  { surahId: 40, ayahNumber: 53, text: 'And We had certainly given Moses guidance, and We caused the Children of Israel to inherit the Scripture' },
  { surahId: 40, ayahNumber: 54, text: 'As guidance and a reminder for those of understanding.' },
  { surahId: 40, ayahNumber: 55, text: 'So be patient, [O Muhammad]. Indeed, the promise of Allah is truth. And ask forgiveness for your sin and exalt [Allah] with praise of your Lord in the evening and the morning.' },
  { surahId: 40, ayahNumber: 56, text: 'Indeed, those who dispute concerning the signs of Allah without [any] authority having come to them - there is not within their breasts except pride, [the extent of] which they cannot reach. So seek refuge in Allah. Indeed, it is He who is the Hearing, the Seeing.' },
  { surahId: 40, ayahNumber: 57, text: 'The creation of the heavens and earth is greater than the creation of mankind, but most of the people do not know.' },
  { surahId: 40, ayahNumber: 58, text: 'And not equal are the blind and the seeing, nor are those who believe and do righteous deeds and the evildoer. Little do you remember.' },
  { surahId: 40, ayahNumber: 59, text: 'Indeed, the Hour is coming - no doubt about it - but most of the people do not believe.' },
  { surahId: 40, ayahNumber: 60, text: 'And your Lord says, "Call upon Me; I will respond to you." Indeed, those who disdain My worship will enter Hell [rendered] contemptible.' },
  { surahId: 40, ayahNumber: 61, text: 'It is Allah who made for you the night that you may rest therein and the day giving sight. Indeed, Allah is full of bounty to the people, but most of the people are not grateful.' },
  { surahId: 40, ayahNumber: 62, text: 'That is Allah, your Lord, Creator of all things; there is no deity except Him, so how are you deluded?' },
  { surahId: 40, ayahNumber: 63, text: 'Thus were those [before you] deluded who were rejecting the signs of Allah.' },
  { surahId: 40, ayahNumber: 64, text: 'It is Allah who made for you the earth a place of settlement and the sky a ceiling and formed you and perfected your forms and provided you with good things. That is Allah, your Lord; then blessed is Allah, Lord of the worlds.' },
  { surahId: 40, ayahNumber: 65, text: 'He is the Ever-Living; there is no deity except Him, so call upon Him, [being] sincere to Him in religion. [All] praise is [due] to Allah, Lord of the worlds.' },
  { surahId: 40, ayahNumber: 66, text: 'Say, [O Muhammad], "Indeed, I have been forbidden to worship those you call upon besides Allah once the clear proofs have come to me from my Lord, and I have been commanded to submit to the Lord of the worlds."' },
  { surahId: 40, ayahNumber: 67, text: 'It is He who created you from dust, then from a sperm-drop, then from a clinging clot; then He brings you out as a child; then [He develops you] that you reach your [time of] maturity, then [further] that you become elders. And among you is he who is taken in death before [that], so that you reach a specified term; and perhaps you will use reason.' },
  { surahId: 40, ayahNumber: 68, text: 'He it is who gives life and causes death; and when He decrees a matter, He but says to it, "Be," and it is.' },
  { surahId: 40, ayahNumber: 69, text: 'Do you not consider those who dispute concerning the signs of Allah - how are they averted?' },
  { surahId: 40, ayahNumber: 70, text: 'Those who deny the Book and that with which We sent Our messengers - they are going to know,' },
  { surahId: 40, ayahNumber: 71, text: 'When the shackles are around their necks and the chains; they will be dragged' },
  { surahId: 40, ayahNumber: 72, text: 'In boiling water; then in the Fire they will be filled [with flame].' },
  { surahId: 40, ayahNumber: 73, text: 'Then it will be said to them, "Where is that which you used to associate [with Him in worship]' },
  { surahId: 40, ayahNumber: 74, text: 'Other than Allah?" They will say, "They have departed from us; rather, we did not used to invoke previously anything." Thus does Allah put astray the disbelievers.' },
  { surahId: 40, ayahNumber: 75, text: '[The angels will say], "That was because you used to exult upon the earth without right and you used to behave insolently.' },
  { surahId: 40, ayahNumber: 76, text: 'Enter the gates of Hell to abide eternally therein, and wretched is the residence of the arrogant."' },
  { surahId: 40, ayahNumber: 77, text: 'So be patient, [O Muhammad]; indeed, the promise of Allah is truth. And whether We show you some of what We have promised them or We take you in death, it is to Us they will be returned.' },
  { surahId: 40, ayahNumber: 78, text: 'And We have already sent messengers before you. Among them are those [whose stories] We have related to you, and among them are those [whose stories] We have not related to you. And it was not for any messenger to bring a sign [or verse] except by permission of Allah. So when the command of Allah comes, it will be concluded in truth, and the falsifiers will thereupon lose [all].' },
  { surahId: 40, ayahNumber: 79, text: 'It is Allah who made for you the grazing animals upon which you ride, and some of them you eat.' },
  { surahId: 40, ayahNumber: 80, text: 'And for you therein are [other] benefits and that you may realize upon them a need which is in your breasts; and upon them and upon ships you are carried.' },
  { surahId: 40, ayahNumber: 81, text: 'And He shows you His signs. So which of the signs of Allah do you deny?' },
  { surahId: 40, ayahNumber: 82, text: 'Have they not traveled through the land and observed how was the end of those before them? They were more numerous than themselves and greater in strength and in impression on the land, but they were not availed by what they used to earn.' },
  { surahId: 40, ayahNumber: 83, text: 'And when their messengers came to them with clear proofs, they [merely] rejoiced in what they had of knowledge, but they were enveloped by what they used to ridicule.' },
  { surahId: 40, ayahNumber: 84, text: 'And when they saw Our punishment, they said," We believe in Allah alone and disbelieve in that which we used to associate with Him."' },
  { surahId: 40, ayahNumber: 85, text: 'But never did their faith benefit them once they saw Our punishment. [It is] the established way of Allah which has preceded among His servants. And the disbelievers thereupon lost [all].' },
];
